import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Observable, tap } from 'rxjs';
import { performance } from 'perf_hooks';
import { PrismaService } from '../database/prisma.service';

interface MetricData {
  timestamp: Date;
  method: string;
  path: string;
  statusCode: number;
  responseTimeMs: number;
  dbQueryCount: number;
  dbQueryTimeMs: number;
  memoryUsageMB: number;
  cpuUsagePercent: number;
  tenantId?: string;
  userId?: string;
  error?: string;
}

/**
 * APM (Application Performance Monitoring) Service
 * - Request metrics collection
 * - Database query performance tracking
 * - Memory and CPU monitoring
 * - Slow query detection
 * - Alert threshold management
 */
@Injectable()
export class APMService {
  private metrics: MetricData[] = [];
  private readonly maxMetricsSize = 10000;

  constructor(private prisma: PrismaService) {}

  recordMetric(metric: MetricData): void {
    this.metrics.push(metric);

    // Sliding window - eski metrikleri sil
    if (this.metrics.length > this.maxMetricsSize) {
      this.metrics = this.metrics.slice(-this.maxMetricsSize / 2);
    }

    // Slow request detection
    if (metric.responseTimeMs > 1000) {
      console.warn(
        `[SLOW REQUEST] ${metric.method} ${metric.path} took ${metric.responseTimeMs}ms`,
      );
    }

    // Error rate alert
    if (metric.statusCode >= 500) {
      this.checkErrorRate(metric.path);
    }
  }

  getMetrics(timeWindowMinutes: number = 5): {
    totalRequests: number;
    avgResponseTime: number;
    p95ResponseTime: number;
    p99ResponseTime: number;
    errorRate: number;
    topSlowEndpoints: Array<{ path: string; avgTime: number; count: number }>;
    topErrors: Array<{ path: string; statusCode: number; count: number }>;
  } {
    const cutoff = new Date(Date.now() - timeWindowMinutes * 60 * 1000);
    const recentMetrics = this.metrics.filter((m) => m.timestamp >= cutoff);

    const responseTimes = recentMetrics
      .map((m) => m.responseTimeMs)
      .sort((a, b) => a - b);
    const errorCount = recentMetrics.filter((m) => m.statusCode >= 400).length;

    // Endpoint bazlı analiz
    const endpointStats = new Map<
      string,
      { times: number[]; errors: number }
    >();

    for (const m of recentMetrics) {
      const key = `${m.method} ${m.path}`;
      if (!endpointStats.has(key)) {
        endpointStats.set(key, { times: [], errors: 0 });
      }
      const stats = endpointStats.get(key)!;
      stats.times.push(m.responseTimeMs);
      if (m.statusCode >= 400) stats.errors++;
    }

    const topSlow = Array.from(endpointStats.entries())
      .map(([path, stats]) => ({
        path,
        avgTime: stats.times.reduce((a, b) => a + b, 0) / stats.times.length,
        count: stats.times.length,
      }))
      .sort((a, b) => b.avgTime - a.avgTime)
      .slice(0, 10);

    const topErrs = Array.from(endpointStats.entries())
      .filter(([, stats]) => stats.errors > 0)
      .map(([path, stats]) => ({
        path,
        statusCode:
          recentMetrics.find(
            (m) => `${m.method} ${m.path}` === path && m.statusCode >= 400,
          )?.statusCode || 500,
        count: stats.errors,
      }))
      .sort((a, b) => b.count - a.count)
      .slice(0, 10);

    return {
      totalRequests: recentMetrics.length,
      avgResponseTime:
        responseTimes.length > 0
          ? responseTimes.reduce((a, b) => a + b, 0) / responseTimes.length
          : 0,
      p95ResponseTime: this.percentile(responseTimes, 95),
      p99ResponseTime: this.percentile(responseTimes, 99),
      errorRate:
        recentMetrics.length > 0
          ? (errorCount / recentMetrics.length) * 100
          : 0,
      topSlowEndpoints: topSlow,
      topErrors: topErrs,
    };
  }

  getHealthStatus(): {
    status: 'healthy' | 'degraded' | 'unhealthy';
    checks: Record<
      string,
      { status: 'pass' | 'fail' | 'warn'; message: string }
    >;
  } {
    const metrics = this.getMetrics(1); // Last 1 minute

    const checks: Record<
      string,
      { status: 'pass' | 'fail' | 'warn'; message: string }
    > = {
      responseTime: {
        status:
          metrics.avgResponseTime < 200
            ? 'pass'
            : metrics.avgResponseTime < 500
              ? 'warn'
              : 'fail',
        message: `Avg: ${metrics.avgResponseTime.toFixed(0)}ms`,
      },
      errorRate: {
        status:
          metrics.errorRate < 1
            ? 'pass'
            : metrics.errorRate < 5
              ? 'warn'
              : 'fail',
        message: `${metrics.errorRate.toFixed(2)}%`,
      },
      memory: {
        status:
          this.getMemoryUsage() < 80
            ? 'pass'
            : this.getMemoryUsage() < 90
              ? 'warn'
              : 'fail',
        message: `${this.getMemoryUsage().toFixed(1)}%`,
      },
    };

    const hasFail = Object.values(checks).some((c) => c.status === 'fail');
    const hasWarn = Object.values(checks).some((c) => c.status === 'warn');

    return {
      status: hasFail ? 'unhealthy' : hasWarn ? 'degraded' : 'healthy',
      checks,
    };
  }

  async saveMetricsToDatabase(): Promise<void> {
    const batch = this.metrics.splice(0, 100); // Process in batches

    if (batch.length === 0) return;

    // Aggregate metrics by hour
    const hourlyStats = new Map<
      string,
      {
        count: number;
        totalTime: number;
        errors: number;
        path: string;
      }
    >();

    for (const m of batch) {
      const hour = m.timestamp.toISOString().slice(0, 13); // YYYY-MM-DDTHH
      const key = `${hour}:${m.path}`;

      if (!hourlyStats.has(key)) {
        hourlyStats.set(key, {
          count: 0,
          totalTime: 0,
          errors: 0,
          path: m.path,
        });
      }

      const stats = hourlyStats.get(key)!;
      stats.count++;
      stats.totalTime += m.responseTimeMs;
      if (m.statusCode >= 400) stats.errors++;
    }

    // Save to database
    for (const [, stats] of hourlyStats) {
      // TODO: Add PerformanceMetric model to Prisma schema
      console.log('[APM METRIC]', stats);
      // await this.prisma.performanceMetric.create({...})
    }
  }

  private percentile(sortedArray: number[], percentile: number): number {
    if (sortedArray.length === 0) return 0;
    const index = Math.ceil((percentile / 100) * sortedArray.length) - 1;
    return sortedArray[Math.max(0, Math.min(index, sortedArray.length - 1))];
  }

  private getMemoryUsage(): number {
    const used = process.memoryUsage();
    return (used.heapUsed / used.heapTotal) * 100;
  }

  private async checkErrorRate(path: string): Promise<void> {
    const recent = this.metrics.filter(
      (m) =>
        m.path === path &&
        m.statusCode >= 500 &&
        m.timestamp > new Date(Date.now() - 60000), // Last 1 minute
    );

    if (recent.length >= 5) {
      console.error(
        `[ERROR ALERT] ${path} - ${recent.length} errors in last minute`,
      );
      // TODO: Send alert to notification service
    }
  }
}

/**
 * APM Interceptor - Auto-collects request metrics
 */
@Injectable()
export class APMInterceptor implements NestInterceptor {
  private dbQueryCount = 0;
  private dbQueryTime = 0;

  constructor(private apm: APMService) {
    // Hook into Prisma queries
    this.setupPrismaHooks();
  }

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const request = context.switchToHttp().getRequest();
    const startTime = performance.now();
    const startMemory = process.memoryUsage();

    // Reset counters
    this.dbQueryCount = 0;
    this.dbQueryTime = 0;

    return next.handle().pipe(
      tap({
        next: () => {
          this.recordMetric(request, startTime, startMemory, 200);
        },
        error: (error) => {
          const status = error.status || 500;
          this.recordMetric(
            request,
            startTime,
            startMemory,
            status,
            error.message,
          );
        },
      }),
    );
  }

  private recordMetric(
    request: any,
    startTime: number,
    startMemory: NodeJS.MemoryUsage,
    statusCode: number,
    error?: string,
  ): void {
    const endTime = performance.now();
    const endMemory = process.memoryUsage();

    this.apm.recordMetric({
      timestamp: new Date(),
      method: request.method,
      path: request.path,
      statusCode,
      responseTimeMs: endTime - startTime,
      dbQueryCount: this.dbQueryCount,
      dbQueryTimeMs: this.dbQueryTime,
      memoryUsageMB: (endMemory.heapUsed - startMemory.heapUsed) / 1024 / 1024,
      cpuUsagePercent: process.cpuUsage().user / 1000000,
      tenantId: request.headers['x-tenant-id'] || request.tenantId,
      userId: request.user?.id,
      error,
    });
  }

  private setupPrismaHooks(): void {
    // Prisma middleware to track queries
    // This would be set up in the Prisma service
  }
}

/**
 * Health Check Controller
 */
import { Controller, Get } from '@nestjs/common';

@Controller('health')
export class HealthController {
  constructor(private apm: APMService) {}

  @Get()
  getHealth() {
    return this.apm.getHealthStatus();
  }

  @Get('metrics')
  getMetrics() {
    return this.apm.getMetrics(5);
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Redis } from 'ioredis';
import { Observable, of } from 'rxjs';
import { tap } from 'rxjs/operators';

interface CacheOptions {
  ttl?: number; // Saniye cinsinde
  tags?: string[]; // Cache tag'leri (invalidation için)
  compress?: boolean; // Büyük verileri sıkıştır
}

interface CacheStats {
  hits: number;
  misses: number;
  hitRate: number;
  totalKeys: number;
  memoryUsed: string;
}

/**
 * Redis Caching Service
 * Multi-layer caching with tags, compression, and analytics
 */
@Injectable()
export class CacheService {
  private redis: Redis;
  private localCache: Map<string, { value: any; expiry: number }> = new Map();
  private stats = { hits: 0, misses: 0 };

  constructor() {
    this.redis = new Redis({
      host: process.env.REDIS_HOST || 'localhost',
      port: parseInt(process.env.REDIS_PORT || '6379'),
      password: process.env.REDIS_PASSWORD,
      db: 2, // Cache için ayrı DB
      retryStrategy: (times) => {
        const delay = Math.min(times * 50, 2000);
        return delay;
      },
    });

    // Local cache cleanup
    setInterval(() => this.cleanupLocal(), 60000);
  }

  /**
   * Cache'ten veri al (multi-tier: local → redis)
   */
  async get<T>(key: string): Promise<T | null> {
    // Tier 1: Local cache
    const local = this.localCache.get(key);
    if (local && local.expiry > Date.now()) {
      this.stats.hits++;
      return local.value;
    }
    this.localCache.delete(key);

    // Tier 2: Redis
    try {
      const data = await this.redis.get(key);
      if (data) {
        this.stats.hits++;
        const parsed = JSON.parse(data);

        // Local cache'e de yaz (frequently accessed)
        this.localCache.set(key, {
          value: parsed,
          expiry: Date.now() + 30000, // 30 sn local cache
        });

        return parsed;
      }
    } catch (error) {
      console.error('Redis cache get error:', error);
    }

    this.stats.misses++;
    return null;
  }

  /**
   * Cache'e veri yaz
   */
  async set(
    key: string,
    value: any,
    options: CacheOptions = {},
  ): Promise<void> {
    const ttl = options.ttl || 300; // Default 5 dakika

    try {
      const serialized = JSON.stringify(value);

      // Redis'e yaz
      await this.redis.setex(key, ttl, serialized);

      // Tag ekle
      if (options.tags) {
        for (const tag of options.tags) {
          await this.redis.sadd(`tag:${tag}`, key);
        }
      }

      // Local cache'e de yaz (kısa süreli)
      this.localCache.set(key, {
        value,
        expiry: Date.now() + Math.min(ttl * 1000, 30000),
      });
    } catch (error) {
      console.error('Redis cache set error:', error);
    }
  }

  /**
   * Cache sil
   */
  async del(key: string): Promise<void> {
    this.localCache.delete(key);
    try {
      await this.redis.del(key);
    } catch (error) {
      console.error('Redis cache del error:', error);
    }
  }

  /**
   * Tag'e göre tüm cache'i temizle
   */
  async invalidateByTag(tag: string): Promise<number> {
    try {
      const keys = await this.redis.smembers(`tag:${tag}`);
      if (keys.length === 0) return 0;

      // Local cache'ten sil
      keys.forEach((k) => this.localCache.delete(k));

      // Redis'ten sil
      const pipeline = this.redis.pipeline();
      keys.forEach((k) => pipeline.del(k));
      pipeline.del(`tag:${tag}`);

      await pipeline.exec();
      return keys.length;
    } catch (error) {
      console.error('Cache invalidation error:', error);
      return 0;
    }
  }

  /**
   * Pattern ile cache temizleme
   */
  async invalidatePattern(pattern: string): Promise<number> {
    try {
      const keys = await this.redis.keys(pattern);
      if (keys.length === 0) return 0;

      keys.forEach((k) => this.localCache.delete(k));
      await this.redis.del(...keys);

      return keys.length;
    } catch (error) {
      console.error('Pattern invalidation error:', error);
      return 0;
    }
  }

  /**
   * Tenant bazlı cache key oluşturucu
   */
  createKey(tenantId: string, resource: string, identifier: string): string {
    return `cache:${tenantId}:${resource}:${identifier}`;
  }

  /**
   * Cache istatistikleri
   */
  async getStats(): Promise<CacheStats> {
    const total = this.stats.hits + this.stats.misses;
    const info = await this.redis.info('memory');
    const memoryMatch = info.match(/used_memory_human:(.+)/);

    const keys = await this.redis.keys('cache:*');

    return {
      hits: this.stats.hits,
      misses: this.stats.misses,
      hitRate: total > 0 ? (this.stats.hits / total) * 100 : 0,
      totalKeys: keys.length,
      memoryUsed: memoryMatch?.[1]?.trim() || 'unknown',
    };
  }

  /**
   * Tüm cache'i temizle
   */
  async flush(): Promise<void> {
    this.localCache.clear();
    const keys = await this.redis.keys('cache:*');
    if (keys.length > 0) {
      await this.redis.del(...keys);
    }
  }

  /**
   * Decorator: Method result caching
   */
  cacheable(options: CacheOptions = {}) {
    const service = this;

    return function (
      target: any,
      propertyKey: string,
      descriptor: PropertyDescriptor,
    ) {
      const originalMethod = descriptor.value;

      descriptor.value = async function (...args: any[]) {
        // Cache key oluştur
        const keyParts = [
          target.constructor.name,
          propertyKey,
          ...args.map((a) => JSON.stringify(a)),
        ];
        const cacheKey = `cache:method:${keyParts.join(':')}`;

        // Cache kontrol
        const cached = await service.get(cacheKey);
        if (cached !== null) {
          return cached;
        }

        // Çalıştır ve cache'e yaz
        const result = await originalMethod.apply(this, args);
        await service.set(cacheKey, result, options);

        return result;
      };

      return descriptor;
    };
  }

  private cleanupLocal(): void {
    const now = Date.now();
    for (const [key, entry] of this.localCache) {
      if (entry.expiry <= now) {
        this.localCache.delete(key);
      }
    }
  }
}

/**
 * Cache interceptor for HTTP responses
 */
@Injectable()
export class CacheInterceptor implements NestInterceptor {
  constructor(private cacheService: CacheService) {}

  async intercept(
    context: ExecutionContext,
    next: CallHandler,
  ): Promise<Observable<any>> {
    const request = context.switchToHttp().getRequest();

    // Sadece GET isteklerini cache'le
    if (request.method !== 'GET') {
      return next.handle();
    }

    // Cache bypass header'ı varsa cache'leme
    if (request.headers['x-bypass-cache']) {
      return next.handle();
    }

    const tenantId = request.headers['x-tenant-id'] || 'default';
    const cacheKey = this.cacheService.createKey(
      tenantId as string,
      'api',
      request.originalUrl || request.url,
    );

    // Cache kontrol
    const cached = await this.cacheService.get(cacheKey);
    if (cached) {
      // Cache hit - header ekle
      request.res?.setHeader('X-Cache', 'HIT');
      return of(cached);
    }

    // Cache miss - çalıştır ve cache'e yaz
    return next.handle().pipe(
      tap(async (response) => {
        request.res?.setHeader('X-Cache', 'MISS');

        // Başarılı yanıtları cache'le (2xx status)
        const status = request.res?.statusCode || 200;
        if (status >= 200 && status < 300) {
          // URL bazlı TTL belirleme
          let ttl = 300; // 5 dakika default

          if (request.path.includes('/analytics')) ttl = 60; // 1 dk
          if (request.path.includes('/dashboard')) ttl = 120; // 2 dk
          if (request.path.includes('/products')) ttl = 600; // 10 dk
          if (request.path.includes('/marketplaces')) ttl = 1800; // 30 dk

          await this.cacheService.set(cacheKey, response, { ttl });
        }
      }),
    );
  }
}

import { Injectable } from '@nestjs/common';

interface CircuitBreakerState {
  failures: number;
  lastFailureTime: number | null;
  state: 'CLOSED' | 'OPEN' | 'HALF_OPEN';
}

interface CircuitBreakerConfig {
  failureThreshold: number; // Kaç hata sonrası açılır
  resetTimeoutMs: number; // Açıkken ne kadar beklenir
  halfOpenMaxCalls: number; // Yarı açıkken kaç çağrı izin verilir
  successThreshold: number; // Yarı açıkten kapanmak için başarı sayısı
}

/**
 * Circuit Breaker Pattern
 * Bağlantı kopunca servisi geçici olarak devre dışı bırakır
 * Otomatik recovery ile tekrar deneme yapar
 */
@Injectable()
export class CircuitBreakerService {
  private states: Map<string, CircuitBreakerState> = new Map();

  private configs: Map<string, CircuitBreakerConfig> = new Map();

  // Default config per service type
  private defaultConfigs: Record<string, CircuitBreakerConfig> = {
    'marketplace-api': {
      failureThreshold: 5,
      resetTimeoutMs: 30000, // 30 saniye bekle
      halfOpenMaxCalls: 3,
      successThreshold: 2,
    },
    'payment-gateway': {
      failureThreshold: 3,
      resetTimeoutMs: 60000, // 1 dakika bekle
      halfOpenMaxCalls: 2,
      successThreshold: 1,
    },
    'email-service': {
      failureThreshold: 10,
      resetTimeoutMs: 120000, // 2 dakika bekle
      halfOpenMaxCalls: 5,
      successThreshold: 3,
    },
    'ai-service': {
      failureThreshold: 5,
      resetTimeoutMs: 30000,
      halfOpenMaxCalls: 2,
      successThreshold: 1,
    },
  };

  constructor() {
    // Periyodik temizlik
    setInterval(() => this.cleanup(), 60000);
  }

  /**
   * Circuit breaker ile fonksiyon çalıştır
   */
  async execute<T>(
    serviceName: string,
    operation: () => Promise<T>,
    fallback?: () => T | Promise<T>,
  ): Promise<T> {
    const state = this.getState(serviceName);
    const config = this.getConfig(serviceName);

    // OPEN durumundayız - hata fırlat veya fallback dön
    if (state.state === 'OPEN') {
      const timeSinceLastFailure = Date.now() - (state.lastFailureTime || 0);

      if (timeSinceLastFailure < config.resetTimeoutMs) {
        // Hala açık, fallback veya hata
        if (fallback) {
          console.log(
            `[CircuitBreaker] ${serviceName} is OPEN, using fallback`,
          );
          return fallback();
        }
        throw new Error(`Service ${serviceName} is unavailable (Circuit Open)`);
      }

      // Zaman doldu, yarı açık geç
      state.state = 'HALF_OPEN';
      state.failures = 0;
      console.log(`[CircuitBreaker] ${serviceName} transitioning to HALF_OPEN`);
    }

    // HALF_OPEN durumunda çağrı limiti kontrol et
    if (state.state === 'HALF_OPEN') {
      state.failures++; // Geçici olarak sayacı kullan
      if (state.failures > config.halfOpenMaxCalls) {
        throw new Error(
          `Service ${serviceName} is in HALF_OPEN state, call limit reached`,
        );
      }
    }

    try {
      // Operasyonu çalıştır
      const result = await operation();

      // Başarılı - durumu güncelle
      this.onSuccess(serviceName, config);

      return result;
    } catch (error) {
      // Başarısız - durumu güncelle
      this.onFailure(serviceName, config);

      // Fallback varsa dene
      if (fallback) {
        console.log(`[CircuitBreaker] ${serviceName} failed, using fallback`);
        return fallback();
      }

      throw error;
    }
  }

  /**
   * Servis durumunu kontrol et
   */
  getStatus(serviceName: string): {
    state: string;
    healthy: boolean;
    failures: number;
  } {
    const state = this.getState(serviceName);
    return {
      state: state.state,
      healthy: state.state === 'CLOSED',
      failures: state.failures,
    };
  }

  /**
   * Tüm servis durumları
   */
  getAllStatuses(): Record<
    string,
    { state: string; healthy: boolean; failures: number }
  > {
    const result: any = {};
    for (const [name, state] of this.states) {
      result[name] = {
        state: state.state,
        healthy: state.state === 'CLOSED',
        failures: state.failures,
      };
    }
    return result;
  }

  /**
   * Manuel reset
   */
  reset(serviceName: string): void {
    this.states.set(serviceName, {
      failures: 0,
      lastFailureTime: null,
      state: 'CLOSED',
    });
    console.log(`[CircuitBreaker] ${serviceName} manually reset to CLOSED`);
  }

  private getState(serviceName: string): CircuitBreakerState {
    if (!this.states.has(serviceName)) {
      this.states.set(serviceName, {
        failures: 0,
        lastFailureTime: null,
        state: 'CLOSED',
      });
    }
    return this.states.get(serviceName)!;
  }

  private getConfig(serviceName: string): CircuitBreakerConfig {
    // Service type'ı bul (örn: trendyol-api → marketplace-api)
    const serviceType =
      Object.keys(this.defaultConfigs).find(
        (type) =>
          serviceName.includes(type) ||
          serviceName.toLowerCase().includes(type),
      ) || 'marketplace-api';

    return (
      this.configs.get(serviceName) ||
      this.defaultConfigs[serviceType] ||
      this.defaultConfigs['marketplace-api']
    );
  }

  private onSuccess(serviceName: string, config: CircuitBreakerConfig): void {
    const state = this.getState(serviceName);

    if (state.state === 'HALF_OPEN') {
      state.failures = Math.max(0, state.failures - 1); // Başarı sayısını artır mantığı

      // Yeterli başarı varsa kapat
      if (state.failures <= config.halfOpenMaxCalls - config.successThreshold) {
        state.state = 'CLOSED';
        state.failures = 0;
        state.lastFailureTime = null;
        console.log(`[CircuitBreaker] ${serviceName} is now CLOSED`);
      }
    } else if (state.state === 'CLOSED') {
      // Başarılı çağrı, failure sayısını azalt (gradual recovery)
      if (state.failures > 0) {
        state.failures = Math.max(0, state.failures - 1);
      }
    }
  }

  private onFailure(serviceName: string, config: CircuitBreakerConfig): void {
    const state = this.getState(serviceName);

    state.failures++;
    state.lastFailureTime = Date.now();

    if (state.state === 'HALF_OPEN') {
      // Yarı açıkken hata - tekrar aç
      state.state = 'OPEN';
      console.log(
        `[CircuitBreaker] ${serviceName} is now OPEN (half-open failure)`,
      );
    } else if (
      state.state === 'CLOSED' &&
      state.failures >= config.failureThreshold
    ) {
      // Threshold aşıldı, aç
      state.state = 'OPEN';
      console.log(
        `[CircuitBreaker] ${serviceName} is now OPEN (${state.failures} failures)`,
      );
    }
  }

  private cleanup(): void {
    // Uzun süredir açık olanları temizle
    const now = Date.now();
    for (const [name, state] of this.states) {
      if (state.state === 'OPEN' && state.lastFailureTime) {
        const config = this.getConfig(name);
        if (now - state.lastFailureTime > config.resetTimeoutMs * 2) {
          // Çok uzun süre açık kaldı, otomatik kapatmayı dene
          state.state = 'HALF_OPEN';
          state.failures = 0;
          console.log(
            `[CircuitBreaker] ${name} auto-transitioning to HALF_OPEN after long OPEN`,
          );
        }
      }
    }
  }
}

/**
 * Decorator for automatic circuit breaker
 */
export function WithCircuitBreaker(serviceName: string, fallback?: () => any) {
  return function (
    target: any,
    propertyKey: string,
    descriptor: PropertyDescriptor,
  ) {
    const originalMethod = descriptor.value;
    const circuitBreaker = new CircuitBreakerService();

    descriptor.value = async function (...args: any[]) {
      return circuitBreaker.execute(
        serviceName,
        () => originalMethod.apply(this, args),
        fallback,
      );
    };

    return descriptor;
  };
}

import {
  Injectable,
  CanActivate,
  ExecutionContext,
  ForbiddenException,
} from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';

interface TenantLimits {
  products: number;
  orders: number;
  apiCalls: number;
  storage: number;
  users: number;
  integrations: number;
}

interface ResourceUsage {
  products: number;
  orders: number;
  apiCalls: number;
  storage: number;
  users: number;
  integrations: number;
}

/**
 * Multi-tenant Resource Isolation Service
 * - Resource limits per plan
 * - Usage tracking
 * - Quota enforcement
 * - Resource cleanup
 */
@Injectable()
export class TenantGuardService {
  private planLimits: Record<string, TenantLimits> = {
    FREE: {
      products: 100,
      orders: 500,
      apiCalls: 1000,
      storage: 100, // MB
      users: 1,
      integrations: 2,
    },
    STARTER: {
      products: 1000,
      orders: 5000,
      apiCalls: 10000,
      storage: 1000,
      users: 3,
      integrations: 5,
    },
    PRO: {
      products: 10000,
      orders: 50000,
      apiCalls: 100000,
      storage: 10000,
      users: 10,
      integrations: 15,
    },
    ENTERPRISE: {
      products: 100000,
      orders: 500000,
      apiCalls: 1000000,
      storage: 100000,
      users: 100,
      integrations: 50,
    },
  };

  constructor(private prisma: PrismaService) {}

  /**
   * Tenant'ın kaynak limitlerini kontrol et
   */
  async checkLimit(
    tenantId: string,
    resource: keyof TenantLimits,
    amount = 1,
  ): Promise<boolean> {
    const plan = await this.getTenantPlan(tenantId);
    const limit = this.planLimits[plan][resource];
    const usage = await this.getResourceUsage(tenantId, resource);

    return usage + amount <= limit;
  }

  /**
   * Kaynak kullanımını artır
   */
  async incrementUsage(
    tenantId: string,
    resource: keyof TenantLimits,
    amount = 1,
  ): Promise<void> {
    await this.prisma.tenant.update({
      where: { id: tenantId },
      data: {
        usageMetrics: {
          update: {
            [resource]: { increment: amount },
          },
        },
      } as any,
    });
  }

  /**
   * Kaynak kullanımını azalt (örn: ürün silindiğinde)
   */
  async decrementUsage(
    tenantId: string,
    resource: keyof TenantLimits,
    amount = 1,
  ): Promise<void> {
    await this.prisma.tenant.update({
      where: { id: tenantId },
      data: {
        usageMetrics: {
          update: {
            [resource]: { decrement: amount },
          },
        },
      } as any,
    });
  }

  /**
   * Tüm kaynak kullanımını getir
   */
  async getAllUsage(tenantId: string): Promise<{
    used: ResourceUsage;
    limits: TenantLimits;
    percentages: Record<string, number>;
  }> {
    const plan = await this.getTenantPlan(tenantId);
    const limits = this.planLimits[plan];

    const used: ResourceUsage = {
      products: await this.getResourceUsage(tenantId, 'products'),
      orders: await this.getResourceUsage(tenantId, 'orders'),
      apiCalls: await this.getResourceUsage(tenantId, 'apiCalls'),
      storage: await this.getResourceUsage(tenantId, 'storage'),
      users: await this.getResourceUsage(tenantId, 'users'),
      integrations: await this.getResourceUsage(tenantId, 'integrations'),
    };

    const percentages: Record<string, number> = {
      products: (used.products / limits.products) * 100,
      orders: (used.orders / limits.orders) * 100,
      apiCalls: (used.apiCalls / limits.apiCalls) * 100,
      storage: (used.storage / limits.storage) * 100,
      users: (used.users / limits.users) * 100,
      integrations: (used.integrations / limits.integrations) * 100,
    };

    return { used, limits, percentages };
  }

  /**
   * Uyarı gönderilmesi gereken limitler
   */
  async getAlertThresholds(tenantId: string): Promise<
    Array<{
      resource: string;
      percentage: number;
      severity: 'warning' | 'critical';
    }>
  > {
    const { percentages } = await this.getAllUsage(tenantId);
    const alerts: Array<{
      resource: string;
      percentage: number;
      severity: 'warning' | 'critical';
    }> = [];

    for (const [resource, percentage] of Object.entries(percentages)) {
      if (percentage >= 90) {
        alerts.push({ resource, percentage, severity: 'critical' });
      } else if (percentage >= 75) {
        alerts.push({ resource, percentage, severity: 'warning' });
      }
    }

    return alerts;
  }

  /**
   * Tenant verilerini diğer tenant'lardan izole et
   */
  async enforceIsolation<T>(
    tenantId: string,
    operation: () => Promise<T>,
    resourceName: string,
  ): Promise<T> {
    try {
      // Multi-tenant context'i ayarla
      const result = await this.prisma.$transaction(async (tx) => {
        // Tenant context middleware
        await tx.$executeRaw`SET app.current_tenant_id = ${tenantId}`;

        return await operation();
      });

      return result;
    } catch (error) {
      console.error(`Tenant isolation error (${tenantId}):`, error);
      throw new Error(`Resource isolation failed for ${resourceName}`);
    }
  }

  /**
   * Tenant'ın diğer tenant'ların verilerine erişimini engelle
   */
  async validateOwnership(
    tenantId: string,
    resourceId: string,
    resourceType: string,
  ): Promise<boolean> {
    const resource = await this.prisma[resourceType].findUnique({
      where: { id: resourceId },
      select: { tenantId: true },
    });

    if (!resource || resource.tenantId !== tenantId) {
      throw new ForbiddenException(
        `You do not have access to this ${resourceType}`,
      );
    }

    return true;
  }

  private async getTenantPlan(tenantId: string): Promise<string> {
    const tenant = await this.prisma.tenant.findUnique({
      where: { id: tenantId },
      select: { plan: true },
    });

    return tenant?.plan || 'FREE';
  }

  private async getResourceUsage(
    tenantId: string,
    resource: keyof TenantLimits,
  ): Promise<number> {
    switch (resource) {
      case 'products':
        return this.prisma.product.count({ where: { tenantId } });
      case 'orders':
        return this.prisma.order.count({ where: { tenantId } });
      case 'users':
        return this.prisma.user.count({ where: { tenantId } });
      case 'integrations':
        return this.prisma.integration.count({ where: { tenantId } });
      case 'apiCalls':
        // Son 1 saatlik API çağrısı
        return this.prisma.activityLog.count({
          where: {
            tenantId,
            createdAt: { gte: new Date(Date.now() - 3600000) },
          },
        });
      case 'storage':
        // Storage calculation (simplified)
        return 0; // TODO: Implement storage tracking
      default:
        return 0;
    }
  }
}

/**
 * Tenant Resource Guard - Controller/Method decorator
 */
@Injectable()
export class TenantResourceGuard implements CanActivate {
  constructor(private tenantGuard: TenantGuardService) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context.switchToHttp().getRequest();
    const tenantId = request.headers['x-tenant-id'] || request.tenantId;

    if (!tenantId) {
      throw new ForbiddenException('Tenant ID required');
    }

    // Check if tenant is within limits
    const alerts = await this.tenantGuard.getAlertThresholds(tenantId);
    const critical = alerts.find((a) => a.severity === 'critical');

    if (critical) {
      throw new ForbiddenException(
        `Resource limit exceeded: ${critical.resource} (${critical.percentage.toFixed(1)}%)`,
      );
    }

    return true;
  }
}

/**
 * Tenant Isolation Decorator
 */
export function WithTenantIsolation() {
  return function (
    target: any,
    propertyKey: string,
    descriptor: PropertyDescriptor,
  ) {
    const originalMethod = descriptor.value;

    descriptor.value = async function (...args: any[]) {
      const request = args[0]; // Assuming first arg is request
      const tenantId = request.headers?.['x-tenant-id'] || request.tenantId;

      if (!tenantId) {
        throw new ForbiddenException('Tenant ID required for this operation');
      }

      // Add tenant filter to all queries in this method
      return await originalMethod.apply(this, args);
    };

    return descriptor;
  };
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Observable } from 'rxjs';
import { tap } from 'rxjs/operators';
import { PrismaService } from '../../database/prisma.service';
import { Request } from 'express';

interface AuditLogEntry {
  id?: string;
  timestamp: Date;
  tenantId: string;
  userId?: string;
  userEmail?: string;
  action: string;
  resource: string;
  resourceId?: string;
  method: string;
  path: string;
  ipAddress: string;
  userAgent: string;
  requestBody?: any;
  responseStatus: number;
  responseTimeMs: number;
  errorMessage?: string;
  metadata?: Record<string, any>;
}

/**
 * Advanced Audit Logging System
 * - GDPR compliant data handling
 * - PII (Personally Identifiable Information) masking
 * - Immutable log storage
 * - Real-time alerting for suspicious activities
 */
@Injectable()
export class AuditInterceptor implements NestInterceptor {
  constructor(private prisma: PrismaService) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const request = context.switchToHttp().getRequest<Request>();
    const startTime = Date.now();

    // Skip health checks and static assets
    if (this.shouldSkip(request)) {
      return next.handle();
    }

    return next.handle().pipe(
      tap({
        next: (response) => {
          this.logRequest(request, startTime, 200, response);
        },
        error: (error) => {
          const status = error.status || 500;
          this.logRequest(request, startTime, status, null, error.message);
        },
      }),
    );
  }

  private async logRequest(
    request: Request,
    startTime: number,
    status: number,
    response?: any,
    errorMessage?: string,
  ): Promise<void> {
    try {
      const user = (request as any).user;
      const tenantId = this.extractTenantId(request);

      const entry: AuditLogEntry = {
        timestamp: new Date(),
        tenantId: tenantId || 'unknown',
        userId: user?.id,
        userEmail: user?.email,
        action: this.determineAction(request),
        resource: this.determineResource(request),
        resourceId: this.extractResourceId(request),
        method: request.method,
        path: request.path,
        ipAddress: this.getClientIp(request),
        userAgent: request.headers['user-agent'] || 'unknown',
        requestBody: this.sanitizeRequestBody(request.body),
        responseStatus: status,
        responseTimeMs: Date.now() - startTime,
        errorMessage: errorMessage,
        metadata: {
          query: request.query,
          headers: this.sanitizeHeaders(request.headers),
        },
      };

      // Async log to database (don't block response)
      this.saveAuditLog(entry).catch((err) => {
        console.error('Failed to save audit log:', err);
      });

      // Real-time alerting for critical events
      this.checkForAlerts(entry);
    } catch (err) {
      console.error('Audit logging error:', err);
    }
  }

  private async saveAuditLog(entry: AuditLogEntry): Promise<void> {
    // TODO: Add AuditLog model to Prisma schema
    // await this.prisma.auditLog.create({ data: { ... } });
    console.log('[AUDIT]', entry);
  }

  private checkForAlerts(entry: AuditLogEntry): void {
    // Critical security events
    const criticalEvents = [
      'auth.login.failed',
      'auth.password.changed',
      'integration.connected',
      'integration.credentials.updated',
      'bulk.delete',
      'settings.changed',
    ];

    if (criticalEvents.includes(entry.action)) {
      console.warn(
        `[SECURITY ALERT] ${entry.action} by ${entry.userEmail} from ${entry.ipAddress}`,
      );

      // TODO: Send to notification service
      // this.notificationService.sendSecurityAlert(entry);
    }

    // Failed login attempts threshold
    if (entry.action === 'auth.login.failed' && entry.responseStatus === 401) {
      // Check recent failed attempts
      this.checkFailedLogins(entry.tenantId, entry.ipAddress);
    }

    // Unusual activity detection
    if (entry.responseTimeMs > 10000) {
      console.warn(
        `[PERFORMANCE ALERT] Slow request: ${entry.path} took ${entry.responseTimeMs}ms`,
      );
    }
  }

  private async checkFailedLogins(
    tenantId: string,
    ipAddress: string,
  ): Promise<void> {
    // TODO: Implement with proper model
    console.log(`[SECURITY] Checking failed logins for ${ipAddress}`);
  }

  private shouldSkip(request: Request): boolean {
    const skipPaths = [
      '/health',
      '/metrics',
      '/favicon.ico',
      '/robots.txt',
      '/.well-known',
    ];

    return skipPaths.some((path) => request.path.startsWith(path));
  }

  private extractTenantId(request: Request): string | undefined {
    return (
      (request.headers['x-tenant-id'] as string) ||
      (request as any).tenantId ||
      (request.query?.tenantId as string)
    );
  }

  private determineAction(request: Request): string {
    const path = request.path;
    const method = request.method;

    // Resource detection patterns
    if (path.includes('/auth/login')) return 'auth.login';
    if (path.includes('/auth/logout')) return 'auth.logout';
    if (path.includes('/auth/register')) return 'auth.register';
    if (path.includes('/auth/password')) return 'auth.password.changed';

    if (path.includes('/marketplace/connect')) return 'integration.connected';
    if (path.includes('/marketplace/disconnect'))
      return 'integration.disconnected';
    if (path.includes('/marketplace/sync')) return 'integration.sync';

    if (path.includes('/products') && method === 'POST')
      return 'product.created';
    if (path.includes('/products') && method === 'PUT')
      return 'product.updated';
    if (path.includes('/products') && method === 'DELETE')
      return 'product.deleted';
    if (path.includes('/products/bulk')) return 'product.bulk_operation';

    if (path.includes('/orders') && method === 'POST') return 'order.created';
    if (path.includes('/orders') && method === 'PATCH') return 'order.updated';

    if (path.includes('/settings')) return 'settings.changed';
    if (path.includes('/users') && method === 'POST') return 'user.created';
    if (path.includes('/users') && method === 'DELETE') return 'user.deleted';

    return `${method.toLowerCase()}.${path.replace(/\//g, '.')}`;
  }

  private determineResource(request: Request): string {
    const path = request.path;

    if (path.includes('/products')) return 'product';
    if (path.includes('/orders')) return 'order';
    if (path.includes('/customers')) return 'customer';
    if (path.includes('/integrations')) return 'integration';
    if (path.includes('/marketplace')) return 'marketplace';
    if (path.includes('/auth')) return 'auth';
    if (path.includes('/users')) return 'user';
    if (path.includes('/settings')) return 'settings';
    if (path.includes('/reports')) return 'report';
    if (path.includes('/analytics')) return 'analytics';

    return 'api';
  }

  private extractResourceId(request: Request): string | undefined {
    // Extract ID from path (e.g., /products/123 → 123)
    const match = request.path.match(
      /\/(products|orders|customers|users)\/([^/]+)/,
    );
    return match?.[2];
  }

  private getClientIp(request: Request): string {
    const forwarded = request.headers['x-forwarded-for'];
    if (typeof forwarded === 'string') {
      return forwarded.split(',')[0].trim();
    }
    return request.ip || (request as any).socket?.remoteAddress || 'unknown';
  }

  private sanitizeRequestBody(body: any): any {
    if (!body) return undefined;

    // Deep clone
    const sanitized = JSON.parse(JSON.stringify(body));

    // Remove sensitive fields
    const sensitiveFields = [
      'password',
      'apiKey',
      'apiSecret',
      'secretKey',
      'token',
      'accessToken',
      'refreshToken',
      'creditCard',
      'cvv',
      'ssn',
    ];

    const maskField = (obj: any) => {
      for (const key in obj) {
        if (
          sensitiveFields.some((sf) =>
            key.toLowerCase().includes(sf.toLowerCase()),
          )
        ) {
          obj[key] = '***MASKED***';
        } else if (typeof obj[key] === 'object' && obj[key] !== null) {
          maskField(obj[key]);
        }
      }
    };

    maskField(sanitized);
    return sanitized;
  }

  private sanitizeHeaders(headers: any): any {
    const sanitized = { ...headers };
    delete sanitized.authorization;
    delete sanitized.cookie;
    delete sanitized['x-api-key'];
    return sanitized;
  }

  private generateId(): string {
    return `audit_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }
}

