/**
 * Example Versioned Controller
 */
@Controller({
  path: 'products',
  version: ['1', '2'],
})
export class VersionedProductsController {
  // Default version (neutral)
  @Get()
  findAllV1() {
    return {
      version: '1',
      products: [],
      links: { self: '/v1/products' },
    };
  }

  // Explicit V2 with new features
  @Version('2')
  @Get()
  findAllV2() {
    return {
      version: '2',
