        latest: '/v2/products',
        docs: 'https://docs.example.com/v2/products',
      },
      deprecated: false,
    };
  }

  // Deprecated V1 endpoint
  @ApiVersion('1', true, '2024-12-31')
  @Get(':id')
  findOneV1(@Param('id') id: string) {
    return {
      product: { id },
      warning: 'This endpoint is deprecated. Use /v2/products/:id',
    };
  }

  // Latest V2 endpoint
  @Version('2')
  @Get(':id')
  findOneV2(@Param('id') id: string) {
    return {
      version: '2',
      data: { id },
      included: [],
    };
  }
}

/**
 * Version Interceptor - Adds version headers
 */
import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
} from '@nestjs/common';
import { Observable, map } from 'rxjs';

@Injectable()
export class VersionInterceptor implements NestInterceptor {
  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const request = context.switchToHttp().getRequest();
    const version = request.headers['x-api-version'] || '1';

    return next.handle().pipe(
      map((data) => ({
        ...data,
        _meta: {
          apiVersion: version,
          latestVersion: '2',
          deprecationWarning:
            version !== '2'
              ? 'You are using an outdated API version. Please migrate to v2.'
              : undefined,
        },
      })),
    );
  }
}

import {
  Injectable,
  OnModuleInit,
  OnModuleDestroy,
  Logger,
} from '@nestjs/common';
import { PrismaClient } from '@prisma/client';
import { Pool } from 'pg';
import { PrismaPg } from '@prisma/adapter-pg';

@Injectable()
export class PrismaService
  extends PrismaClient
  implements OnModuleInit, OnModuleDestroy
{
  currentTenantId?: string; // Added for tenant context
  private pool: Pool | null = null;
  private logger = new Logger(PrismaService.name);

  constructor() {
    const connectionString = process.env.DATABASE_URL;

    let adapter;
    let pool: Pool | null = null;

    if (connectionString) {
      try {
        pool = new Pool({ connectionString });
        adapter = new PrismaPg(pool as any);
      } catch (error: any) {
        // Log after super() is called
        pool = null;
      }
    }

    super({
      ...(adapter ? { adapter } : {}),
      log: ['error', 'warn'],
    });

    this.pool = pool;
  }

  async onModuleInit() {
    try {
      await this.$connect();
      this.logger.log('Database connected successfully');
    } catch (error) {
      this.logger.error(`Failed to connect to database: ${error.message}`);
      throw error;
    }
  }

  async onModuleDestroy() {
    try {
      await this.$disconnect();
      if (this.pool) {
        await this.pool.end();
      }
    } catch (error) {
      this.logger.error(`Error during disconnect: ${error.message}`);
    }
  }
}

