import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  OnGatewayConnection,
  OnGatewayDisconnect,
  MessageBody,
  ConnectedSocket,
} from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Logger, UseGuards } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';

interface ConnectedUser {
  socketId: string;
  tenantId: string;
  userId: string;
  connectedAt: Date;
}

@WebSocketGateway({
  namespace: '/ai-assistant',
  cors: {
    origin: '*',
    credentials: true,
  },
  transports: ['websocket', 'polling'],
})
export class AIAssistantGateway
  implements OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer()
  server: Server;

  private readonly logger = new Logger(AIAssistantGateway.name);
  private connectedUsers: Map<string, ConnectedUser> = new Map();

  constructor(private configService: ConfigService) {}

  // ==================== CONNECTION HANDLING ====================

  async handleConnection(client: Socket): Promise<void> {
    try {
      const { tenantId, userId, token } = client.handshake.query;

      if (!tenantId || !userId) {
        this.logger.warn(`Connection rejected: Missing tenantId or userId`);
        client.disconnect();
        return;
      }

      // Store connection
      this.connectedUsers.set(client.id, {
        socketId: client.id,
        tenantId: tenantId as string,
        userId: userId as string,
        connectedAt: new Date(),
      });

      // Join user-specific room
      client.join(`user:${userId}`);
      client.join(`tenant:${tenantId}`);

      this.logger.log(`Client connected: ${client.id} - User: ${userId}`);

      // Send welcome message
      client.emit('connected', {
        socketId: client.id,
        timestamp: new Date(),
        message: 'AI Assistant real-time connection established',
      });
    } catch (error) {
      this.logger.error('Connection error:', error);
      client.disconnect();
    }
  }

  handleDisconnect(client: Socket): void {
    const user = this.connectedUsers.get(client.id);
    if (user) {
      this.logger.log(
        `Client disconnected: ${client.id} - User: ${user.userId}`,
      );
      this.connectedUsers.delete(client.id);
    }
  }

  // ==================== INCOMING MESSAGES ====================

  @SubscribeMessage('chat:message')
  async handleChatMessage(
    @MessageBody()
    data: {
      conversationId: string;
      content: string;
      tenantId: string;
      userId: string;
    },
    @ConnectedSocket() client: Socket,
  ): Promise<void> {
    this.logger.debug(
      `Received message from ${data.userId}: ${data.content.substring(0, 50)}...`,
    );

    // Broadcast typing indicator
    client.to(`user:${data.userId}`).emit('assistant:typing', {
      conversationId: data.conversationId,
      isTyping: true,
    });

    // Acknowledge receipt
    client.emit('message:received', {
      conversationId: data.conversationId,
      timestamp: new Date(),
    });
  }

  @SubscribeMessage('user:typing')
  handleUserTyping(
    @MessageBody() data: { conversationId: string; isTyping: boolean },
    @ConnectedSocket() client: Socket,
  ): void {
    const user = this.connectedUsers.get(client.id);
    if (user) {
      client.to(`user:${user.userId}`).emit('user:typing', {
        ...data,
        userId: user.userId,
      });
    }
  }

  @SubscribeMessage('conversation:join')
  handleJoinConversation(
    @MessageBody() data: { conversationId: string },
    @ConnectedSocket() client: Socket,
  ): void {
    client.join(`conversation:${data.conversationId}`);
    this.logger.debug(
      `Client ${client.id} joined conversation ${data.conversationId}`,
    );

    client.emit('conversation:joined', {
      conversationId: data.conversationId,
      timestamp: new Date(),
    });
  }

  @SubscribeMessage('conversation:leave')
  handleLeaveConversation(
    @MessageBody() data: { conversationId: string },
    @ConnectedSocket() client: Socket,
  ): void {
    client.leave(`conversation:${data.conversationId}`);
    this.logger.debug(
      `Client ${client.id} left conversation ${data.conversationId}`,
    );
  }

  // ==================== BROADCAST METHODS ====================

  /**
   * Send message to specific user
   */
  sendToUser(userId: string, event: string, data: any): void {
    this.server.to(`user:${userId}`).emit(event, data);
  }

  /**
   * Send message to all users in a tenant
   */
  sendToTenant(tenantId: string, event: string, data: any): void {
    this.server.to(`tenant:${tenantId}`).emit(event, data);
  }

  /**
   * Send message to specific conversation participants
   */
  sendToConversation(conversationId: string, event: string, data: any): void {
    this.server.to(`conversation:${conversationId}`).emit(event, data);
  }

  /**
   * Broadcast to all connected clients
   */
  broadcast(event: string, data: any): void {
    this.server.emit(event, data);
  }

  // ==================== AI ASSISTANT SPECIFIC EVENTS ====================

  /**
   * Notify user that AI is processing their request
   */
  notifyProcessing(
    userId: string,
    data: {
      conversationId: string;
      action: string;
      message?: string;
    },
  ): void {
    this.sendToUser(userId, 'assistant:processing', {
      ...data,
      timestamp: new Date(),
    });
  }

  /**
   * Send AI response to user
   */
  sendAIResponse(
    userId: string,
    data: {
      conversationId: string;
      message: any;
      suggestions?: any[];
    },
  ): void {
    this.sendToUser(userId, 'assistant:response', {
      ...data,
      timestamp: new Date(),
    });

    // Also send to conversation room for multi-device sync
    if (data.conversationId) {
      this.sendToConversation(data.conversationId, 'conversation:new_message', {
        ...data,
        timestamp: new Date(),
      });
    }
  }

  /**
   * Notify about sync job progress
   */
  notifySyncProgress(
    userId: string,
    data: {
      jobId: string;
      type: string;
      platform: string;
      progress: number;
      status: 'pending' | 'processing' | 'completed' | 'failed';
      message?: string;
      details?: any;
    },
  ): void {
    this.sendToUser(userId, 'sync:progress', {
      ...data,
      timestamp: new Date(),
    });
  }

  /**
   * Notify about completed sync job
   */
  notifySyncCompleted(
    userId: string,
    data: {
      jobId: string;
      type: string;
      platform: string;
      success: boolean;
      message: string;
      stats?: {
        total: number;
        processed: number;
        failed: number;
      };
    },
  ): void {
    this.sendToUser(userId, 'sync:completed', {
      ...data,
      timestamp: new Date(),
    });

    // Also send notification
    this.sendToUser(userId, 'notification', {
      type: data.success ? 'success' : 'error',
      title: data.success ? 'Eşitleme Tamamlandı' : 'Eşitleme Başarısız',
      message: data.message,
      data: { jobId: data.jobId, type: data.type, platform: data.platform },
      timestamp: new Date(),
    });
  }

  /**
   * Send predictive suggestion proactively
   */
  sendProactiveSuggestion(
    userId: string,
    data: {
      suggestionId: string;
      title: string;
      description: string;
      type: string;
      confidence: number;
      action?: any;
    },
  ): void {
    this.sendToUser(userId, 'assistant:suggestion', {
      ...data,
      timestamp: new Date(),
    });
  }

  /**
   * Notify about errors
   */
  notifyError(
    userId: string,
    data: {
      type: string;
      message: string;
      details?: any;
      recoverable?: boolean;
    },
  ): void {
    this.sendToUser(userId, 'assistant:error', {
      ...data,
      timestamp: new Date(),
    });
  }

  /**
   * Update conversation list in real-time
   */
  updateConversationList(
    userId: string,
    data: {
      conversations: any[];
      total: number;
    },
  ): void {
    this.sendToUser(userId, 'conversations:update', {
      ...data,
      timestamp: new Date(),
    });
  }

  /**
   * Notify about learning insights
   */
  notifyLearningInsight(
    userId: string,
    data: {
      type: 'pattern_detected' | 'preference_learned' | 'optimization_found';
      title: string;
      description: string;
      action?: any;
    },
  ): void {
    this.sendToUser(userId, 'learning:insight', {
      ...data,
      timestamp: new Date(),
    });
  }

  // ==================== UTILITIES ====================

  /**
   * Get online users count
   */
  getOnlineUsersCount(): number {
    return this.connectedUsers.size;
  }

  /**
   * Get users by tenant
   */
  getUsersByTenant(tenantId: string): ConnectedUser[] {
    return Array.from(this.connectedUsers.values()).filter(
      (user) => user.tenantId === tenantId,
    );
  }

  /**
   * Check if user is online
   */
  isUserOnline(userId: string): boolean {
    return Array.from(this.connectedUsers.values()).some(
      (user) => user.userId === userId,
    );
  }

  /**
   * Get socket ID for user
   */
  getSocketIdForUser(userId: string): string | undefined {
    const user = Array.from(this.connectedUsers.values()).find(
      (u) => u.userId === userId,
    );
    return user?.socketId;
  }
}

/* eslint-disable @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-assignment */
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import {
  MarketplaceService,
  Platform,
} from '../marketplace/marketplace.service';
import { AIAssistantGateway } from './ai-assistant.gateway';
import { AiService } from '../ai/ai.service';
import { AIContextMemoryService } from './services/ai-context-memory.service';
import { AISmartIntentService } from './services/ai-smart-intent.service';
import { AILearningService } from './services/ai-learning.service';
import { AIPredictiveService } from './services/ai-predictive.service';
import { AIAssistantMarketplaceIntegrationService } from './services/ai-marketplace-integration.service';

export interface AIAssistantContext {
  tenantId: string;
  userId: string;
  platform?: string;
  conversationId?: string;
}

export interface AIAssistantMessage {
  role: 'user' | 'assistant' | 'system';
  content: string;
  timestamp: Date;
  metadata?: {
    action?: string;
    data?: any;
    status?: 'pending' | 'completed' | 'failed';
    suggestions?: any[];
    insights?: string[];
    followUpSuggestions?: string[];
  };
}

export interface AIAssistantConversation {
  id: string;
  tenantId: string;
  userId: string;
  title?: string;
  messages: AIAssistantMessage[];
  status: 'active' | 'archived';
  createdAt: Date;
  updatedAt: Date;
}

export interface AssistantAction {
  type:
    | 'BRAND_SYNC'
    | 'CATEGORY_SYNC'
    | 'ATTRIBUTE_SYNC'
    | 'PRODUCT_UPLOAD'
    | 'VARIANT_MANAGE'
    | 'BULK_UPLOAD'
    | 'GENERAL';
  payload: any;
  platform?: string;
}

export interface SyncResult {
  success: boolean;
  message: string;
  data?: any;
  errors?: string[];
}

@Injectable()
export class AIAssistantService {
  private readonly logger = new Logger(AIAssistantService.name);

  constructor(
    private prisma: PrismaService,
    private marketplaceService: MarketplaceService,
    private aiService: AiService,
    private contextMemory: AIContextMemoryService,
    private smartIntent: AISmartIntentService,
    private learningService: AILearningService,
    private predictiveService: AIPredictiveService,
    private marketplaceIntegration: AIAssistantMarketplaceIntegrationService,
  ) {}

  // ==================== CONVERSATION MANAGEMENT ====================

  async createConversation(
    tenantId: string,
    userId: string,
    title?: string,
  ): Promise<AIAssistantConversation> {
    const conversation = await this.prisma.aIAssistantConversation.create({
      data: {
        tenantId,
        userId,
        title: title || 'Yeni Konuşma',
        status: 'active',
      },
    });

    return {
      id: conversation.id,
      tenantId: conversation.tenantId,
      userId: conversation.userId,
      title: conversation.title || undefined,
      messages: [],
      status: conversation.status as 'active' | 'archived',
      createdAt: conversation.createdAt,
      updatedAt: conversation.updatedAt,
    };
  }

  async getConversation(
    conversationId: string,
    tenantId: string,
  ): Promise<AIAssistantConversation | null> {
    const conversation = await this.prisma.aIAssistantConversation.findFirst({
      where: { id: conversationId, tenantId },
      include: { messages: { orderBy: { createdAt: 'asc' } } },
    });

    if (!conversation) return null;

    return {
      id: conversation.id,
      tenantId: conversation.tenantId,
      userId: conversation.userId,
      title: conversation.title || undefined,
      messages: conversation.messages.map((m) => ({
        role: m.role as 'user' | 'assistant' | 'system',
        content: m.content,
        timestamp: m.createdAt,
        metadata: m.metadata as any,
      })),
      status: conversation.status as 'active' | 'archived',
      createdAt: conversation.createdAt,
      updatedAt: conversation.updatedAt,
    };
  }

  async getConversations(
    tenantId: string,
    userId: string,
    limit = 20,
  ): Promise<AIAssistantConversation[]> {
    const conversations = await this.prisma.aIAssistantConversation.findMany({
      where: { tenantId, userId },
      orderBy: { updatedAt: 'desc' },
      take: limit,
      include: { messages: { take: 1, orderBy: { createdAt: 'desc' } } },
    });

    return conversations.map((c) => ({
      id: c.id,
      tenantId: c.tenantId,
      userId: c.userId,
      title: c.title || undefined,
      messages: [],
      status: c.status as 'active' | 'archived',
      createdAt: c.createdAt,
      updatedAt: c.updatedAt,
    }));
  }

  // ==================== MESSAGE PROCESSING ====================

  async sendMessage(
    conversationId: string,
    tenantId: string,
    userId: string,
    content: string,
  ): Promise<AIAssistantMessage> {
    // Save user message
    await this.prisma.aIAssistantMessage.create({
      data: {
        conversationId,
        role: 'user',
        content,
      },
    });

    // Get conversation history for context
    const history = await this.prisma.aIAssistantMessage.findMany({
      where: { conversationId },
      orderBy: { createdAt: 'asc' },
      take: 10,
    });

    // Build conversation context for smart intent detection
    const conversationContext = {
      previousMessages: history.map((h) => ({
        role: h.role,
        content: h.content,
      })),
      activeWorkflow: undefined, // Could be retrieved from context memory
      userGoals: [], // Could be populated from context memory
      recentErrors: [], // Could be populated from error history
    };

    // Use smart intent detection with context
    const intentResult = await this.smartIntent.detectIntent(
      content,
      tenantId,
      userId,
      conversationContext,
    );

    // Get predictive suggestions
    const predictiveSuggestions =
      await this.predictiveService.predictNextActions(tenantId, userId);

    // Get personalized recommendations
    const personalizedRecs =
      await this.predictiveService.getPersonalizedRecommendations(
        tenantId,
        userId,
        { platform: intentResult.platform },
      );

    // Process action
    let response: AIAssistantMessage;

    if (intentResult.confidence > 0.6 && intentResult.type !== 'GENERAL') {
      // High confidence intent - execute action
      response = await this.executeSmartAction(intentResult, {
        tenantId,
        userId,
        platform: intentResult.platform,
        conversationId,
      });

      // Learn from this interaction
      await this.learningService.processEvent(tenantId, userId, {
        type: 'action_completed',
        data: {
          actionType: intentResult.type,
          platform: intentResult.platform,
          confidence: intentResult.confidence,
        },
      });
    } else {
      // Low confidence or general intent - use AI response
      const systemPrompt = await this.getEnhancedSystemPrompt(tenantId, userId);
      const aiResponse = await this.aiService.generateAssistantResponse(
        systemPrompt,
        content,
        history.map((h) => ({ role: h.role, content: h.content })),
      );

      response = {
        role: 'assistant',
        content: aiResponse.text,
        timestamp: new Date(),
        metadata: {
          suggestions: [
            ...predictiveSuggestions.slice(0, 3),
            ...personalizedRecs.slice(0, 2),
          ].map((s) => ({
            title: s.title,
            type: s.type,
          })),
        },
      };
    }

    // Save assistant response
    const savedMessage = await this.prisma.aIAssistantMessage.create({
      data: {
        conversationId,
        role: response.role,
        content: response.content,
        metadata: response.metadata as any,
      },
    });

    // Update conversation timestamp
    await this.prisma.aIAssistantConversation.update({
      where: { id: conversationId },
      data: { updatedAt: new Date() },
    });

    // Store conversation context for future reference
    await this.contextMemory.storeMemory(tenantId, userId, {
      key: `conversation_${conversationId}_last_intent`,
      memoryType: 'product_context',
      value: {
        intent: intentResult.type,
        platform: intentResult.platform,
        timestamp: new Date(),
      },
      expiresIn: 60,
    });

    return {
      role: savedMessage.role as 'assistant',
      content: savedMessage.content,
      timestamp: savedMessage.createdAt,
      metadata: savedMessage.metadata as any,
    };
  }

  private async executeSmartAction(
    intentResult: any,
    context: AIAssistantContext,
  ): Promise<AIAssistantMessage> {
    // Convert smart intent result to old action format for compatibility
    const action: AssistantAction = {
      type: intentResult.type,
      payload: intentResult.payload,
      platform: intentResult.platform,
    };

    // Get context-aware enhancements
    const contextSnapshot = await this.contextMemory.buildContextSnapshot(
      context.tenantId,
      context.userId,
    );

    // Add context hints to the action execution
    const response = await this.executeAction(
      action.type,
      action.payload,
      context,
    );

    // Enhance response with smart insights
    if (
      intentResult.suggestedFollowUp &&
      intentResult.suggestedFollowUp.length > 0
    ) {
      response.metadata = {
        ...response.metadata,
        followUpSuggestions: intentResult.suggestedFollowUp,
      };
    }

    if (intentResult.contextHints && intentResult.contextHints.length > 0) {
      response.metadata = {
        ...response.metadata,
        insights: intentResult.contextHints,
      };
    }

    return response;
  }

  private async getEnhancedSystemPrompt(
