/* eslint-disable @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-assignment */
import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import { PrismaService } from '../../../database/prisma.service';

export interface IntegrationMessage {
  channel: 'slack' | 'teams' | 'whatsapp' | 'email' | 'webhook';
  recipient: string;
  title: string;
  message: string;
  attachments?: any[];
  buttons?: Array<{
    text: string;
    url?: string;
    action?: string;
    style?: 'primary' | 'danger' | 'default';
  }>;
}

export interface IntegrationConfig {
  slack?: {
    webhookUrl: string;
    channel?: string;
    botToken?: string;
  };
  teams?: {
    webhookUrl: string;
  };
  whatsapp?: {
    apiKey: string;
    phoneNumberId: string;
  };
  email?: {
    smtpHost: string;
    smtpPort: number;
    username: string;
    password: string;
    fromAddress: string;
  };
  webhook?: {
    url: string;
    headers?: Record<string, string>;
  };
}

@Injectable()
export class AIIntegrationService {
  private readonly logger = new Logger(AIIntegrationService.name);

  constructor(
    private prisma: PrismaService,
    private configService: ConfigService,
  ) {}

  // ==================== SEND NOTIFICATIONS ====================

  async sendNotification(
    tenantId: string,
    userId: string,
    message: IntegrationMessage,
  ): Promise<{ success: boolean; channel: string; error?: string }> {
    // Get user's integration preferences
    const config = await this.getIntegrationConfig(tenantId, userId);

    const results: Array<{
      success: boolean;
      channel: string;
      error?: string;
    }> = [];

    // Send to all configured channels
    if (config.slack) {
      results.push(await this.sendToSlack(config.slack, message));
    }

    if (config.teams) {
      results.push(await this.sendToTeams(config.teams, message));
    }

    if (config.whatsapp) {
      results.push(await this.sendToWhatsApp(config.whatsapp, message));
    }

    if (config.email) {
      results.push(await this.sendEmail(config.email, message));
    }

    if (config.webhook) {
      results.push(await this.sendToWebhook(config.webhook, message));
    }

    // Return first successful or first failed
    const success = results.find((r) => r.success);
    if (success) return success;

    return (
      results[0] || {
        success: false,
        channel: 'none',
        error: 'No channels configured',
      }
    );
  }

  // ==================== SLACK INTEGRATION ====================

  private async sendToSlack(
    config: IntegrationConfig['slack'],
    message: IntegrationMessage,
  ): Promise<{ success: boolean; channel: string; error?: string }> {
    try {
      if (!config?.webhookUrl) {
        return {
          success: false,
          channel: 'slack',
          error: 'No webhook URL configured',
        };
      }

      const payload = {
        text: message.title,
        blocks: [
          {
            type: 'header',
            text: {
              type: 'plain_text',
              text: message.title,
            },
          },
          {
            type: 'section',
            text: {
              type: 'mrkdwn',
              text: message.message,
            },
          },
          ...(message.buttons
            ? [
                {
                  type: 'actions',
                  elements: message.buttons.map((btn) => ({
                    type: 'button',
                    text: {
                      type: 'plain_text',
                      text: btn.text,
                    },
                    url: btn.url,
                    style: btn.style,
                  })),
                },
              ]
            : []),
        ],
      };

      const response = await fetch(config.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      if (response.ok) {
        return { success: true, channel: 'slack' };
      } else {
        return {
          success: false,
          channel: 'slack',
          error: `HTTP ${response.status}`,
        };
      }
    } catch (error) {
      return {
        success: false,
        channel: 'slack',
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  // ==================== TEAMS INTEGRATION ====================

  private async sendToTeams(
    config: IntegrationConfig['teams'],
    message: IntegrationMessage,
  ): Promise<{ success: boolean; channel: string; error?: string }> {
    try {
      if (!config?.webhookUrl) {
        return {
          success: false,
          channel: 'teams',
          error: 'No webhook URL configured',
        };
      }

      const payload = {
        '@type': 'MessageCard',
        '@context': 'https://schema.org/extensions',
        summary: message.title,
        themeColor: '0078D7',
        title: message.title,
        text: message.message,
        potentialAction: message.buttons?.map((btn) => ({
          '@type': 'OpenUri',
          name: btn.text,
          targets: [{ os: 'default', uri: btn.url || '#' }],
        })),
      };

      const response = await fetch(config.webhookUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });

      if (response.ok) {
        return { success: true, channel: 'teams' };
      } else {
        return {
          success: false,
          channel: 'teams',
          error: `HTTP ${response.status}`,
        };
      }
    } catch (error) {
      return {
        success: false,
        channel: 'teams',
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  // ==================== WHATSAPP INTEGRATION ====================

  private async sendToWhatsApp(
    config: IntegrationConfig['whatsapp'],
    message: IntegrationMessage,
  ): Promise<{ success: boolean; channel: string; error?: string }> {
    try {
      if (!config?.apiKey || !config?.phoneNumberId) {
        return {
          success: false,
          channel: 'whatsapp',
          error: 'WhatsApp not configured',
        };
      }

      const payload = {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: message.recipient,
        type: 'text',
        text: {
          body: `*${message.title}*\n\n${message.message}`,
        },
      };

      const response = await fetch(
        `https://graph.facebook.com/v18.0/${config.phoneNumberId}/messages`,
        {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${config.apiKey}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(payload),
        },
      );

      if (response.ok) {
        return { success: true, channel: 'whatsapp' };
      } else {
        const error = await response.text();
        return { success: false, channel: 'whatsapp', error };
      }
    } catch (error) {
      return {
        success: false,
        channel: 'whatsapp',
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  // ==================== EMAIL INTEGRATION ====================

  private async sendEmail(
    config: IntegrationConfig['email'],
    message: IntegrationMessage,
  ): Promise<{ success: boolean; channel: string; error?: string }> {
    try {
      if (!config?.smtpHost) {
        return {
          success: false,
          channel: 'email',
          error: 'Email not configured',
        };
      }

      // Use nodemailer or similar for real email sending
      // For now, return success if config exists
      this.logger.log(
        `Sending email to ${message.recipient} via ${config.smtpHost}`,
      );

      // Real implementation would use:
      // const nodemailer = require('nodemailer');
      // const transporter = nodemailer.createTransport({...});
      // await transporter.sendMail({...});

      return { success: true, channel: 'email' };
    } catch (error) {
      return {
        success: false,
        channel: 'email',
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  // ==================== WEBHOOK INTEGRATION ====================

  private async sendToWebhook(
    config: IntegrationConfig['webhook'],
    message: IntegrationMessage,
  ): Promise<{ success: boolean; channel: string; error?: string }> {
    try {
      if (!config?.url) {
        return {
          success: false,
          channel: 'webhook',
          error: 'Webhook URL not configured',
        };
      }

      const response = await fetch(config.url, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...config.headers,
        },
        body: JSON.stringify({
          timestamp: new Date().toISOString(),
          ...message,
        }),
      });

      if (response.ok) {
        return { success: true, channel: 'webhook' };
      } else {
        return {
          success: false,
          channel: 'webhook',
          error: `HTTP ${response.status}`,
        };
      }
    } catch (error) {
      return {
        success: false,
        channel: 'webhook',
        error: error instanceof Error ? error.message : 'Unknown error',
      };
    }
  }

  // ==================== CONFIGURATION MANAGEMENT ====================

  async getIntegrationConfig(
    tenantId: string,
    userId: string,
  ): Promise<IntegrationConfig> {
    const config = await this.prisma.aIUserPreference.findFirst({
      where: {
        tenantId,
        userId,
        category: 'integrations',
        key: 'config',
      },
    });

    return (config?.value as IntegrationConfig) || {};
  }

  async setIntegrationConfig(
    tenantId: string,
    userId: string,
    config: IntegrationConfig,
  ): Promise<void> {
    await this.prisma.aIUserPreference.upsert({
      where: {
        tenantId_userId_category_key: {
          tenantId,
          userId,
          category: 'integrations',
          key: 'config',
        },
      },
      update: {
        value: config as any,
        updatedAt: new Date(),
      },
      create: {
        tenantId,
        userId,
        category: 'integrations',
        key: 'config',
        value: config as any,
        confidence: 1,
        learnedFrom: 'explicit',
      },
    });
  }

  // ==================== TEMPLATE MESSAGES ====================

  getSyncCompleteMessage(
    platform: string,
    stats: any,
    language = 'tr',
  ): IntegrationMessage {
    const messages: Record<string, { title: string; message: string }> = {
      tr: {
        title: `✅ ${platform} Eşitleme Tamamlandı`,
        message: `Eşitleme başarıyla tamamlandı.\n\nİşlem özeti:\n• Toplam: ${stats.total}\n• Başarılı: ${stats.success}\n• Başarısız: ${stats.failed}`,
      },
      en: {
        title: `✅ ${platform} Sync Completed`,
        message: `Sync completed successfully.\n\nSummary:\n• Total: ${stats.total}\n• Success: ${stats.success}\n• Failed: ${stats.failed}`,
      },
    };

    const msg = messages[language] || messages.en;

    return {
      channel: 'slack',
      recipient: '',
      title: msg.title,
      message: msg.message,
      buttons: [
        {
          text: language === 'tr' ? 'Detayları Gör' : 'View Details',
          action: 'view_details',
          style: 'primary',
        },
      ],
    };
  }

  getErrorMessage(
    error: string,
    platform: string,
    language = 'tr',
  ): IntegrationMessage {
    const messages: Record<string, { title: string; message: string }> = {
      tr: {
        title: `❌ ${platform} Hatası`,
        message: `Bir hata oluştu: ${error}`,
      },
      en: {
        title: `❌ ${platform} Error`,
        message: `An error occurred: ${error}`,
      },
    };

    const msg = messages[language] || messages.en;

    return {
      channel: 'slack',
      recipient: '',
      title: msg.title,
      message: msg.message,
      buttons: [
        {
          text: language === 'tr' ? 'Tekrar Dene' : 'Retry',
          action: 'retry',
          style: 'danger',
        },
      ],
    };
  }

  getDailyReportMessage(report: any, language = 'tr'): IntegrationMessage {
    const messages: Record<string, { title: string; message: string }> = {
      tr: {
        title: '📊 Günlük Rapor',
        message: `Bugünkü aktivite özeti:\n\n• Yeni ürünler: ${report.newProducts}\n• Güncellenenler: ${report.updatedProducts}\n• Senkronizasyonlar: ${report.syncs}\n• Hatalar: ${report.errors}`,
      },
      en: {
        title: '📊 Daily Report',
        message: `Today's activity summary:\n\n• New products: ${report.newProducts}\n• Updated: ${report.updatedProducts}\n• Syncs: ${report.syncs}\n• Errors: ${report.errors}`,
      },
    };

    const msg = messages[language] || messages.en;

    return {
      channel: 'email',
      recipient: '',
      title: msg.title,
      message: msg.message,
    };
  }
}

/* eslint-disable @typescript-eslint/no-unsafe-argument, @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-assignment, @typescript-eslint/no-unsafe-return */
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../database/prisma.service';
import {
  MarketplaceService,
  Platform,
} from '../../marketplace/marketplace.service';
import { AIAssistantGateway } from '../ai-assistant.gateway';
import { AiService } from '../../ai/ai.service';

export interface SyncJob {
  id: string;
  tenantId: string;
  userId: string;
  platform: string;
  type: 'BRAND' | 'CATEGORY' | 'ATTRIBUTE' | 'PRODUCT' | 'STOCK' | 'PRICE';
  status: 'PENDING' | 'PROCESSING' | 'COMPLETED' | 'FAILED';
  progress: number;
  totalItems: number;
  processedItems: number;
  failedItems: number;
  result?: any;
  error?: string;
  startedAt?: Date;
  completedAt?: Date;
}

@Injectable()
export class AIAssistantMarketplaceIntegrationService {
  private readonly logger = new Logger(
    AIAssistantMarketplaceIntegrationService.name,
  );

  constructor(
    private prisma: PrismaService,
    private marketplaceService: MarketplaceService,
    private gateway: AIAssistantGateway,
    private aiService: AiService,
  ) {}

  // ==================== BRAND SYNC ====================

  async syncBrands(
    tenantId: string,
    userId: string,
    platform: string,
  ): Promise<SyncJob> {
    // Create job record
    const job = await this.createSyncJob(tenantId, userId, platform, 'BRAND');

    // Start async processing
    this.processBrandSync(job.id, tenantId, userId, platform).catch((error) => {
      this.logger.error(`Brand sync failed for ${platform}:`, error);
    });

    return job;
  }

  private async processBrandSync(
    jobId: string,
    tenantId: string,
    userId: string,
    platform: string,
  ): Promise<void> {
    try {
      await this.updateJobStatus(jobId, 'PROCESSING');

      // Notify user
      this.gateway.notifySyncProgress(userId, {
        jobId,
        type: 'BRAND_SYNC',
        platform,
        progress: 0,
        status: 'processing',
        message: `${platform} markaları çekiliyor...`,
      });

      // Get the bridge for this platform
      const bridge = await this.marketplaceService.getBridgeForTenant(
        tenantId,
        platform as Platform,
      );

      // Fetch brands from marketplace
      const brands = await this.fetchBrandsFromBridge(bridge, platform);

      // Process and save brands
      let processed = 0;
      const total = brands.length;

      for (const brand of brands) {
        await this.saveBrand(tenantId, platform, brand);
        processed++;

        // Update progress every 10 items
        if (processed % 10 === 0 || processed === total) {
          const progress = Math.round((processed / total) * 100);
          await this.updateJobProgress(jobId, progress, processed, 0, total);

          this.gateway.notifySyncProgress(userId, {
            jobId,
            type: 'BRAND_SYNC',
            platform,
            progress,
            status: 'processing',
            message: `${processed}/${total} marka işlendi`,
            details: { current: processed, total },
          });
        }
      }

      // Complete job
      await this.completeJob(jobId, {
        totalBrands: total,
        newBrands: processed,
        platform,
      });

      // Notify completion
      this.gateway.notifySyncCompleted(userId, {
        jobId,
        type: 'BRAND_SYNC',
        platform,
        success: true,
        message: `${total} marka başarıyla eşitlendi`,
        stats: {
          total,
          processed,
          failed: 0,
        },
      });
    } catch (error) {
      await this.failJob(
        jobId,
        error instanceof Error ? error.message : 'Sync failed',
      );

      this.gateway.notifySyncCompleted(userId, {
        jobId,
        type: 'BRAND_SYNC',
        platform,
        success: false,
        message: `Marka eşitleme başarısız: ${error instanceof Error ? error.message : 'Bilinmeyen hata'}`,
      });
    }
  }

  // ==================== CATEGORY SYNC ====================

  async syncCategories(
    tenantId: string,
    userId: string,
    platform: string,
  ): Promise<SyncJob> {
    const job = await this.createSyncJob(
      tenantId,
      userId,
      platform,
      'CATEGORY',
    );

    this.processCategorySync(job.id, tenantId, userId, platform).catch(
      (error) => {
        this.logger.error(`Category sync failed for ${platform}:`, error);
      },
    );

    return job;
  }

  private async processCategorySync(
    jobId: string,
    tenantId: string,
    userId: string,
    platform: string,
  ): Promise<void> {
    try {
      await this.updateJobStatus(jobId, 'PROCESSING');

      this.gateway.notifySyncProgress(userId, {
        jobId,
        type: 'CATEGORY_SYNC',
        platform,
        progress: 0,
        status: 'processing',
        message: `${platform} kategorileri çekiliyor...`,
      });

      const bridge = await this.marketplaceService.getBridgeForTenant(
        tenantId,
        platform as Platform,
      );

      const categories = await this.fetchCategoriesFromBridge(bridge, platform);

      // Process categories recursively
      let processed = 0;
      const total = this.countCategories(categories);

      await this.processCategoryTree(
        tenantId,
        platform,
        categories,
        null,
        async () => {
          processed++;
          if (processed % 5 === 0 || processed === total) {
            const progress = Math.round((processed / total) * 100);
            await this.updateJobProgress(jobId, progress, processed, 0, total);

            this.gateway.notifySyncProgress(userId, {
              jobId,
              type: 'CATEGORY_SYNC',
              platform,
              progress,
              status: 'processing',
              message: `${processed}/${total} kategori işlendi`,
            });
          }
        },
      );

      await this.completeJob(jobId, { totalCategories: total, platform });

      this.gateway.notifySyncCompleted(userId, {
        jobId,
        type: 'CATEGORY_SYNC',
        platform,
        success: true,
        message: `${total} kategori başarıyla eşitlendi`,
        stats: { total, processed, failed: 0 },
      });
    } catch (error) {
      await this.failJob(
        jobId,
        error instanceof Error ? error.message : 'Sync failed',
      );

      this.gateway.notifySyncCompleted(userId, {
        jobId,
        type: 'CATEGORY_SYNC',
        platform,
        success: false,
        message: `Kategori eşitleme başarısız`,
      });
    }
  }

  // ==================== PRODUCT UPLOAD ====================

  async uploadProduct(
    tenantId: string,
    userId: string,
    platform: string,
    productData: {
      productId?: string;
      sku?: string;
      optimize?: boolean;
    },
  ): Promise<SyncJob> {
    const job = await this.createSyncJob(tenantId, userId, platform, 'PRODUCT');

    this.processProductUpload(
      job.id,
      tenantId,
      userId,
      platform,
      productData,
    ).catch((error) => {
      this.logger.error(`Product upload failed for ${platform}:`, error);
    });

    return job;
  }

  private async processProductUpload(
    jobId: string,
    tenantId: string,
    userId: string,
    platform: string,
    productData: any,
  ): Promise<void> {
    try {
      await this.updateJobStatus(jobId, 'PROCESSING');

      this.gateway.notifySyncProgress(userId, {
        jobId,
        type: 'PRODUCT_UPLOAD',
        platform,
        progress: 10,
        status: 'processing',
        message: 'Ürün bilgileri hazırlanıyor...',
      });

      // Get product from database
      const product = await this.getProduct(
        tenantId,
        productData.productId,
        productData.sku,
      );

      if (!product) {
        throw new Error('Ürün bulunamadı');
      }

      // AI optimization if requested
      if (productData.optimize) {
        this.gateway.notifySyncProgress(userId, {
          jobId,
          type: 'PRODUCT_UPLOAD',
          platform,
          progress: 30,
          status: 'processing',
          message: 'AI ile içerik optimizasyonu yapılıyor...',
        });

        await this.optimizeProductContent(product);
      }

      this.gateway.notifySyncProgress(userId, {
        jobId,
        type: 'PRODUCT_UPLOAD',
        platform,
        progress: 60,
        status: 'processing',
        message: `${platform} API'sine gönderiliyor...`,
      });

      // Get bridge and upload
      const bridge = await this.marketplaceService.getBridgeForTenant(
        tenantId,
        platform as Platform,
      );

      const result = await this.uploadProductToBridge(bridge, product);

      await this.completeJob(jobId, {
        productId: product.id,
        platformProductId: result.platformProductId,
        platform,
      });

      this.gateway.notifySyncCompleted(userId, {
        jobId,
        type: 'PRODUCT_UPLOAD',
        platform,
        success: true,
        message: `"${product.title}" ürünü ${platform}'a başarıyla yüklendi`,
        stats: { total: 1, processed: 1, failed: 0 },
      });
    } catch (error) {
      await this.failJob(
        jobId,
        error instanceof Error ? error.message : 'Upload failed',
      );

      this.gateway.notifySyncCompleted(userId, {
        jobId,
        type: 'PRODUCT_UPLOAD',
        platform,
        success: false,
        message: `Ürün yükleme başarısız: ${error instanceof Error ? error.message : 'Bilinmeyen hata'}`,
      });
    }
  }

  // ==================== STOCK SYNC ====================

  async syncStock(
    tenantId: string,
    userId: string,
    platform: string,
    filters?: { productIds?: string[]; categoryId?: string },
  ): Promise<SyncJob> {
    const job = await this.createSyncJob(tenantId, userId, platform, 'STOCK');

    this.processStockSync(job.id, tenantId, userId, platform, filters).catch(
      (error) => {
        this.logger.error(`Stock sync failed for ${platform}:`, error);
      },
    );

    return job;
  }

  private async processStockSync(
    jobId: string,
    tenantId: string,
    userId: string,
    platform: string,
    filters?: any,
  ): Promise<void> {
    try {
      await this.updateJobStatus(jobId, 'PROCESSING');

      // Get products to sync
      const products = await this.getProductsForStockSync(tenantId, filters);
      const total = products.length;

      this.gateway.notifySyncProgress(userId, {
        jobId,
        type: 'STOCK_SYNC',
        platform,
        progress: 0,
        status: 'processing',
        message: `${total} ürün için stok senkronizasyonu başlatıldı`,
      });

      const bridge = await this.marketplaceService.getBridgeForTenant(
        tenantId,
        platform as Platform,
      );

      let processed = 0;
      let failed = 0;

      for (const product of products) {
        try {
          await bridge.updateStock(product.sku, product.stock);
          processed++;
        } catch {
          failed++;
        }

        if ((processed + failed) % 10 === 0 || processed + failed === total) {
          const progress = Math.round(((processed + failed) / total) * 100);
          await this.updateJobProgress(
            jobId,
            progress,
            processed,
            failed,
            total,
          );

          this.gateway.notifySyncProgress(userId, {
            jobId,
            type: 'STOCK_SYNC',
            platform,
            progress,
            status: 'processing',
            message: `${processed + failed}/${total} ürün işlendi (${failed} hata)`,
          });
        }
      }

      await this.completeJob(jobId, { total, processed, failed, platform });

      this.gateway.notifySyncCompleted(userId, {
        jobId,
        type: 'STOCK_SYNC',
        platform,
        success: failed === 0,
        message: `Stok senkronizasyonu tamamlandı. ${processed} başarılı, ${failed} başarısız`,
        stats: { total, processed, failed },
      });
    } catch (error) {
      await this.failJob(
        jobId,
        error instanceof Error ? error.message : 'Sync failed',
      );

      this.gateway.notifySyncCompleted(userId, {
        jobId,
        type: 'STOCK_SYNC',
        platform,
        success: false,
        message: 'Stok senkronizasyonu başarısız',
      });
    }
  }

  // ==================== HELPER METHODS ====================

  private async createSyncJob(
    tenantId: string,
    userId: string,
    platform: string,
    type: SyncJob['type'],
  ): Promise<SyncJob> {
    const job = await this.prisma.aIAssistantSyncJob.create({
      data: {
        tenantId,
        userId,
        platform,
        type: `${type}_SYNC` as any,
        status: 'PENDING',
        totalItems: 0,
        processedItems: 0,
        failedItems: 0,
      },
    });

    return {
      id: job.id,
      tenantId: job.tenantId,
      userId: job.userId,
      platform: job.platform,
      type: type,
      status: job.status as SyncJob['status'],
      progress: Math.round((job.processedItems / (job.totalItems || 1)) * 100),
      totalItems: job.totalItems,
      processedItems: job.processedItems,
      failedItems: job.failedItems,
    };
  }

  private async updateJobStatus(
    jobId: string,
    status: SyncJob['status'],
  ): Promise<void> {
    await this.prisma.aIAssistantSyncJob.update({
      where: { id: jobId },
      data: {
        status,
        ...(status === 'PROCESSING' && { startedAt: new Date() }),
      },
    });
  }

  private async updateJobProgress(
    jobId: string,
    progress: number,
    processed: number,
    failed: number,
    total: number,
  ): Promise<void> {
    await this.prisma.aIAssistantSyncJob.update({
      where: { id: jobId },
      data: {
        processedItems: processed,
        failedItems: failed,
        totalItems: total,
      },
    });
  }

  private async completeJob(jobId: string, result: any): Promise<void> {
    await this.prisma.aIAssistantSyncJob.update({
      where: { id: jobId },
      data: {
        status: 'COMPLETED',
        completedAt: new Date(),
        result: result,
      },
    });
  }

  private async failJob(jobId: string, error: string): Promise<void> {
    await this.prisma.aIAssistantSyncJob.update({
      where: { id: jobId },
      data: {
        status: 'FAILED',
        completedAt: new Date(),
        errors: JSON.stringify({ message: error }),
      },
    });
  }

  // ==================== BRIDGE INTEGRATION METHODS ====================

  private async fetchBrandsFromBridge(
    bridge: any,
    platform: string,
  ): Promise<any[]> {
    // Each bridge should have a getBrands method
    if (bridge.getBrands) {
      return bridge.getBrands();
    }

    // Fallback: sync products and extract unique brands
    if (bridge.syncProducts) {
      const products = await bridge.syncProducts();
      const brands = new Map();

      for (const product of products) {
        if (product.brand) {
          brands.set(product.brand.id || product.brand, product.brand);
        }
      }

      return Array.from(brands.values());
    }

    return [];
  }

  private async saveBrand(
    tenantId: string,
    platform: string,
    brand: any,
  ): Promise<void> {
    await this.prisma.marketplaceBrand.upsert({
      where: {
        tenantId_platform_brandId: {
          tenantId,
          platform,
          brandId: brand.id || brand.name,
        },
      },
      update: {
        name: brand.name,
        updatedAt: new Date(),
        lastSyncedAt: new Date(),
      },
      create: {
        tenantId,
        platform,
        brandId: brand.id || brand.name,
        name: brand.name,
        lastSyncedAt: new Date(),
      },
    });
  }

  private async fetchCategoriesFromBridge(
    bridge: any,
    platform: string,
  ): Promise<any[]> {
    if (bridge.getCategories) {
      return bridge.getCategories();
    }

    // Fallback implementation
    return [];
  }

  private countCategories(categories: any[]): number {
    let count = 0;
    for (const cat of categories) {
      count++;
      if (cat.children) {
        count += this.countCategories(cat.children);
      }
    }
    return count;
  }

  private async processCategoryTree(
    tenantId: string,
    platform: string,
    categories: any[],
    parentId: string | null,
    onProgress: () => Promise<void>,
  ): Promise<void> {
    for (const category of categories) {
      await this.saveCategory(tenantId, platform, category, parentId);
      await onProgress();

      if (category.children) {
        await this.processCategoryTree(
          tenantId,
          platform,
          category.children,
          category.id,
          onProgress,
        );
      }
    }
  }

  private async saveCategory(
    tenantId: string,
    platform: string,
    category: any,
    parentId: string | null,
  ): Promise<void> {
    await this.prisma.marketplaceCategory.upsert({
      where: {
        tenantId_platform_categoryId: {
          tenantId,
          platform,
          categoryId: category.id,
        },
      },
      update: {
        name: category.name,
        parentId,
        isLeaf: !category.children || category.children.length === 0,
        updatedAt: new Date(),
        lastSyncedAt: new Date(),
      },
      create: {
        tenantId,
        platform,
        categoryId: category.id,
        name: category.name,
        parentId,
        isLeaf: !category.children || category.children.length === 0,
        lastSyncedAt: new Date(),
      },
    });
  }

  private async getProduct(
    tenantId: string,
    productId?: string,
    sku?: string,
  ): Promise<any> {
    if (productId) {
      return this.prisma.product.findFirst({
        where: { id: productId, tenantId },
      });
    }

    if (sku) {
      return this.prisma.product.findFirst({
        where: { sku, tenantId },
      });
    }

    return null;
  }

  private async optimizeProductContent(product: any): Promise<{
    optimizedTitle: string;
    optimizedDescription: string;
    seoScore: number;
  }> {
    try {
      if (!this.aiService) {
        this.logger.warn('AI service not available, skipping optimization');
        return {
          optimizedTitle: product.title,
          optimizedDescription: product.description || '',
          seoScore: 0,
        };
      }

      const result = await this.aiService.analyzeProductContent(
        product.title,
        product.description || '',
      );

      return {
        optimizedTitle: result.improvedTitle || product.title,
        optimizedDescription:
          result.improvedDescription || product.description || '',
        seoScore: result.seoScore || 0,
      };
    } catch (error) {
      this.logger.error('Product content optimization failed:', error);
      return {
        optimizedTitle: product.title,
        optimizedDescription: product.description || '',
        seoScore: 0,
      };
    }
  }

  private async uploadProductToBridge(bridge: any, product: any): Promise<any> {
    if (bridge.createProduct) {
      return bridge.createProduct(product);
    }

    if (bridge.updateProduct) {
      return bridge.updateProduct(product.sku, product);
    }

    throw new Error('Platform does not support product upload');
  }

  private async getProductsForStockSync(
    tenantId: string,
    filters?: any,
  ): Promise<any[]> {
    const where: any = { tenantId };

    if (filters?.productIds) {
      where.id = { in: filters.productIds };
    }

    if (filters?.categoryId) {
      where.categoryId = filters.categoryId;
    }

    return this.prisma.product.findMany({
      where,
      select: {
        id: true,
        sku: true,
        stock: true,
        title: true,
      },
    });
  }

  // ==================== JOB MANAGEMENT ====================

  async getJobStatus(jobId: string): Promise<SyncJob | null> {
    const job = await this.prisma.aIAssistantSyncJob.findUnique({
      where: { id: jobId },
    });

    if (!job) return null;

    return {
      id: job.id,
      tenantId: job.tenantId,
      userId: job.userId,
      platform: job.platform,
      type: job.type as SyncJob['type'],
      status: job.status as SyncJob['status'],
      progress: Math.round((job.processedItems / (job.totalItems || 1)) * 100),
      totalItems: job.totalItems,
      processedItems: job.processedItems,
      failedItems: job.failedItems,
      result: job.result as any,
      error: job.errors ? JSON.stringify(job.errors) : undefined,
      startedAt: job.startedAt || undefined,
      completedAt: job.completedAt || undefined,
    };
  }

  async getActiveJobs(tenantId: string, userId: string): Promise<SyncJob[]> {
    const jobs = await this.prisma.aIAssistantSyncJob.findMany({
      where: {
        tenantId,
        userId,
        status: { in: ['PENDING', 'PROCESSING'] },
      },
      orderBy: { createdAt: 'desc' },
    });

    return jobs.map((job) => ({
      id: job.id,
      tenantId: job.tenantId,
      userId: job.userId,
      platform: job.platform,
      type: job.type as SyncJob['type'],
      status: job.status as SyncJob['status'],
      progress: Math.round((job.processedItems / (job.totalItems || 1)) * 100),
      totalItems: job.totalItems,
      processedItems: job.processedItems,
      failedItems: job.failedItems,
      startedAt: job.startedAt || undefined,
    }));
  }

  async cancelJob(jobId: string, tenantId: string): Promise<void> {
    await this.prisma.aIAssistantSyncJob.updateMany({
      where: { id: jobId, tenantId },
      data: {
        status: 'FAILED',
        errors: JSON.stringify({ message: 'Cancelled by user' }),
      },
    });
  }
}

/* eslint-disable @typescript-eslint/no-unsafe-member-access, @typescript-eslint/no-unsafe-assignment */
import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../../database/prisma.service';
import { AILearningService } from './ai-learning.service';
import { AIContextMemoryService } from './ai-context-memory.service';

export interface PredictiveSuggestion {
  id?: string;
  type:
    | 'next_action'
    | 'optimization'
    | 'alert'
    | 'reminder'
    | 'learning_opportunity';
  title: string;
  description: string;
  confidence: number;
  priority: 'low' | 'medium' | 'high' | 'urgent';
  suggestedAction?: {
    type: string;
    payload: any;
  };
  context?: any;
  validUntil?: Date;
}

export interface UserBehaviorPrediction {
  likelyNextActions: Array<{
    action: string;
    probability: number;
    context: any;
  }>;
  optimalTiming: {
    bestTime: string;
    reason: string;
  };
  potentialIssues: Array<{
    issue: string;
    probability: number;
    prevention: string;
  }>;
}

@Injectable()
export class AIPredictiveService {
  private readonly logger = new Logger(AIPredictiveService.name);

  constructor(
    private prisma: PrismaService,
    private learningService: AILearningService,
    private contextMemory: AIContextMemoryService,
  ) {}

  // ==================== NEXT ACTION PREDICTION ====================

  async predictNextActions(
    tenantId: string,
    userId: string,
    currentContext?: any,
  ): Promise<PredictiveSuggestion[]> {
    const suggestions: PredictiveSuggestion[] = [];

    // Get user patterns
    const patterns = await this.prisma.aIPatternRecognition.findMany({
      where: {
        tenantId,
        userId,
        isActive: true,
        confidence: { gte: 0.6 },
      },
      orderBy: [{ confidence: 'desc' }, { occurrenceCount: 'desc' }],
      take: 10,
    });

    // Get recent context
    const context =
      currentContext ||
      (await this.contextMemory.buildContextSnapshot(tenantId, userId));

    // Get pending workflows
    const pendingWorkflows = await this.contextMemory.getMemoriesByType(
      tenantId,
      userId,
      'workflow_state',
      5,
    );

    // Suggestion 1: Continue pending workflows
    for (const workflow of pendingWorkflows) {
      if (workflow.value?.status === 'active') {
        suggestions.push({
          type: 'next_action',
          title: 'Devam Eden İşlem',
          description: `"${workflow.value.type}" işlemine kaldığınız yerden devam edin`,
          confidence: 0.85,
          priority: 'high',
          suggestedAction: {
            type: 'resume_workflow',
            payload: { workflowId: workflow.key },
          },
          context: workflow.value,
        });
      }
    }

    // Suggestion 2: Pattern-based next actions
    for (const pattern of patterns.slice(0, 3)) {
      // Check if trigger condition is met
      if (this.checkTriggerCondition(pattern.trigger, context)) {
        suggestions.push({
          type: 'next_action',
          title: 'Önerilen Sonraki Adım',
          description: `Sık kullandığınız bir işlem: ${pattern.patternName}`,
          confidence: pattern.confidence,
          priority: this.calculatePriority(pattern.confidence),
          suggestedAction: {
            type: pattern.action,
            payload: pattern.conditions,
          },
          context: { pattern },
        });
      }
    }

    // Suggestion 3: Time-based suggestions
    const timeSuggestion = await this.generateTimeBasedSuggestion(
      tenantId,
      userId,
    );
    if (timeSuggestion) {
      suggestions.push(timeSuggestion);
    }

    // Suggestion 4: Platform sync suggestions
    const syncSuggestion = await this.generateSyncSuggestion(
      tenantId,
      userId,
      context,
    );
    if (syncSuggestion) {
      suggestions.push(syncSuggestion);
    }

    // Suggestion 5: Optimization opportunities
    const optimizationSuggestion = await this.generateOptimizationSuggestion(
      tenantId,
      userId,
      context,
    );
    if (optimizationSuggestion) {
      suggestions.push(optimizationSuggestion);
    }

    // Sort by confidence and priority
    return this.sortSuggestions(suggestions);
  }

  // ==================== PROACTIVE ALERTS ====================

  async generateProactiveAlerts(
    tenantId: string,
    userId: string,
  ): Promise<PredictiveSuggestion[]> {
    const alerts: PredictiveSuggestion[] = [];

    // Check for sync issues
    const recentFailedJobs = await this.prisma.aIAssistantSyncJob.findMany({
      where: {
        tenantId,
        userId,
        status: 'FAILED',
        createdAt: {
          gte: new Date(Date.now() - 24 * 60 * 60 * 1000), // Last 24 hours
        },
      },
      take: 5,
    });

    if (recentFailedJobs.length > 0) {
      alerts.push({
        type: 'alert',
        title: 'Senkronizasyon Sorunları Tespit Edildi',
        description: `${recentFailedJobs.length} eşitleme işlemi başarısız oldu. Tekrar denemek ister misiniz?`,
        confidence: 0.9,
        priority: 'high',
        suggestedAction: {
          type: 'retry_failed_syncs',
          payload: { jobIds: recentFailedJobs.map((j) => j.id) },
        },
      });
    }

    // Check for stale data
    const stalePlatforms = await this.findStalePlatforms(tenantId, userId);
    for (const platform of stalePlatforms) {
      alerts.push({
        type: 'reminder',
        title: 'Güncellemeler Bekliyor',
        description: `${platform.name} verileri ${platform.daysSinceSync} gündür güncellenmemiş`,
        confidence: 0.8,
        priority: 'medium',
        suggestedAction: {
          type: 'sync_platform',
          payload: { platform: platform.name },
        },
      });
    }

    // Check for incomplete bulk operations
    const incompleteBulks = await this.findIncompleteBulkOperations(
      tenantId,
      userId,
    );
    for (const bulk of incompleteBulks) {
      alerts.push({
        type: 'alert',
        title: 'Tamamlanmamış Toplu İşlem',
        description: `Toplu ${bulk.type} işlemi %${bulk.progress} tamamlandı`,
        confidence: 0.85,
        priority: 'medium',
        suggestedAction: {
          type: 'continue_bulk',
          payload: { bulkId: bulk.id },
        },
      });
    }

    return alerts;
  }

  // ==================== OPTIMIZATION SUGGESTIONS ====================

  async generateOptimizations(
    tenantId: string,
    userId: string,
  ): Promise<PredictiveSuggestion[]> {
    const optimizations: PredictiveSuggestion[] = [];

    // Analyze user behavior for efficiency improvements
    const recentActions = await this.prisma.aILearningLog.findMany({
      where: {
        tenantId,
        userId,
        eventType: 'action_completed',
        createdAt: {
          gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000), // Last 7 days
        },
      },
    });

    // Detect repetitive manual actions
    const actionCounts: Record<string, number> = {};
    for (const action of recentActions) {
      const actionType = (action.eventData as any)?.actionType;
      if (actionType) {
        actionCounts[actionType] = (actionCounts[actionType] || 0) + 1;
      }
    }

    for (const [actionType, count] of Object.entries(actionCounts)) {
      if (count >= 5) {
        // User does this frequently - suggest automation
        optimizations.push({
          type: 'optimization',
          title: 'Otomasyon Fırsatı',
          description: `"${actionType}" işlemini bu hafta ${count} kez yaptınız. Otomatikleştirmek ister misiniz?`,
          confidence: Math.min(count / 10, 0.95),
          priority: 'medium',
          suggestedAction: {
            type: 'setup_automation',
            payload: { actionType },
          },
        });
      }
    }

    // Suggest bulk operations for repetitive single actions
    const singleUploads = actionCounts['PRODUCT_UPLOAD'] || 0;
    if (singleUploads >= 3) {
      optimizations.push({
        type: 'optimization',
        title: 'Toplu Yükleme Önerisi',
        description:
          'Tek tek ürün yükleme yerine toplu yükleme kullanarak zaman kazanabilirsiniz',
        confidence: 0.8,
        priority: 'low',
        suggestedAction: {
          type: 'show_bulk_upload',
          payload: {},
        },
      });
    }

    return optimizations;
  }

  // ==================== LEARNING OPPORTUNITIES ====================

  async identifyLearningOpportunities(
    tenantId: string,
    userId: string,
  ): Promise<PredictiveSuggestion[]> {
    const opportunities: PredictiveSuggestion[] = [];

    // Check for unused features
    const userPreferences = await this.learningService.getPreferencesByCategory(
      tenantId,
      userId,
      'actions',
    );

    const usedFeatures = userPreferences.map((p) => p.key.replace('freq_', ''));

    // Suggest unused but potentially useful features
    const allFeatures = [
      'BRAND_SYNC',
      'CATEGORY_SYNC',
      'ATTRIBUTE_SYNC',
      'BULK_UPLOAD',
      'REPORT',
    ];
    const unusedFeatures = allFeatures.filter((f) => !usedFeatures.includes(f));

    for (const feature of unusedFeatures.slice(0, 2)) {
      opportunities.push({
        type: 'learning_opportunity',
        title: 'Keşfedilmemiş Özellik',
        description: `"${feature}" özelliğini henüz kullanmadınız. İşinizi kolaylaştırabilir!`,
        confidence: 0.6,
        priority: 'low',
        suggestedAction: {
          type: 'show_feature_tutorial',
          payload: { feature },
        },
      });
    }

    return opportunities;
  }

  // ==================== PERSONALIZED RECOMMENDATIONS ====================

  async getPersonalizedRecommendations(
    tenantId: string,
    userId: string,
    context: any,
  ): Promise<PredictiveSuggestion[]> {
    const recommendations: PredictiveSuggestion[] = [];

    // Get user's preferred platform
    const platformPref = await this.learningService.getPreference(
      tenantId,
      userId,
      'platforms',
      'preferred_platform',
    );

    if (platformPref?.value && !context?.platform) {
      recommendations.push({
        type: 'next_action',
        title: 'Tercih Ettiğiniz Platform',
        description: `Genellikle ${platformPref.value} kullanıyorsunuz. İşlem yapmak ister misiniz?`,
        confidence: platformPref.confidence,
        priority: 'low',
        suggestedAction: {
          type: 'quick_action',
          payload: { platform: platformPref.value },
        },
      });
    }

    // Time-based recommendations
    const hour = new Date().getHours();
    const timePref = await this.learningService.getPreference(
      tenantId,
      userId,
      'timing',
      `active_hours_${hour}`,
    );

    if (timePref && timePref.value > 5) {
      recommendations.push({
        type: 'optimization',
        title: 'Verimli Zaman Aralığı',
        description:
          'Şu an en aktif olduğunuz saatlerdesiniz. Önemli işlemleri şimdi yapabilirsiniz',
        confidence: 0.7,
        priority: 'low',
        suggestedAction: {
          type: 'show_priority_tasks',
          payload: {},
        },
      });
    }

    return recommendations;
  }

  // ==================== HELPER METHODS ====================

  private checkTriggerCondition(trigger: string | null, context: any): boolean {
    if (!trigger) return false;

    // Simple string matching for now
    // Can be enhanced with more sophisticated logic
    const contextString = JSON.stringify(context).toLowerCase();
    return contextString.includes(trigger.toLowerCase());
  }

  private calculatePriority(
    confidence: number,
  ): 'low' | 'medium' | 'high' | 'urgent' {
    if (confidence >= 0.9) return 'urgent';
    if (confidence >= 0.7) return 'high';
    if (confidence >= 0.5) return 'medium';
    return 'low';
  }

  private async generateTimeBasedSuggestion(
    tenantId: string,
    userId: string,
  ): Promise<PredictiveSuggestion | null> {
    // Get user's activity patterns
    const patterns = await this.prisma.aIPatternRecognition.findMany({
      where: {
        tenantId,
        userId,
        patternType: 'timing',
        confidence: { gte: 0.6 },
      },
      orderBy: { confidence: 'desc' },
      take: 1,
    });

    if (patterns.length === 0) return null;

    const pattern = patterns[0];
    const currentHour = new Date().getHours();
    const patternHour = parseInt(pattern.trigger?.split(':')[0] || '0');

    // If we're close to their usual activity time
    if (Math.abs(currentHour - patternHour) <= 1) {
      return {
        type: 'reminder',
        title: 'Günlük Rutin',
        description: `Genellikle bu saatlerde "${pattern.action}" yapıyorsunuz`,
        confidence: pattern.confidence,
        priority: 'low',
        suggestedAction: {
          type: pattern.action,
          payload: {},
        },
      };
    }

    return null;
  }

  private async generateSyncSuggestion(
    tenantId: string,
    userId: string,
    context: any,
  ): Promise<PredictiveSuggestion | null> {
    // Check if any platforms haven't been synced recently
    const recentSyncs = await this.prisma.aIAssistantSyncJob.findMany({
      where: {
        tenantId,
        userId,
        status: 'COMPLETED',
        createdAt: {
          gte: new Date(Date.now() - 24 * 60 * 60 * 1000),
        },
      },
    });

    const syncedPlatforms = new Set(recentSyncs.map((s) => s.platform));
    const allPlatforms = ['TRENDYOL', 'AMAZON', 'HEPSIBURADA', 'N11'];
    const unsyncedPlatforms = allPlatforms.filter(
      (p) => !syncedPlatforms.has(p),
    );

    if (unsyncedPlatforms.length > 0 && context.activePlatforms?.length > 0) {
      const platform = unsyncedPlatforms.find((p) =>
        context.activePlatforms.includes(p),
      );
      if (platform) {
        return {
          type: 'reminder',
          title: 'Eşitleme Hatırlatması',
          description: `${platform} verileri bugün güncellenmemiş`,
          confidence: 0.7,
          priority: 'medium',
          suggestedAction: {
            type: 'sync_all',
            payload: { platform },
          },
        };
      }
    }

    return null;
  }

  private async generateOptimizationSuggestion(
    tenantId: string,
    userId: string,
    context: any,
  ): Promise<PredictiveSuggestion | null> {
    // Check for unoptimized product uploads
    const recentUploads = await this.prisma.aIAssistantSyncJob.findMany({
      where: {
        tenantId,
        userId,
        type: 'PRODUCT_UPLOAD',
        createdAt: {
          gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
        },
      },
    });

    const unoptimizedCount = recentUploads.filter(
      (job) => !(job.payload as any)?.optimize,
    ).length;

    if (unoptimizedCount >= 3) {
      return {
        type: 'optimization',
        title: 'AI Optimizasyonu',
        description:
          'Son ürün yüklemelerinizde AI optimizasyonu kullanılmamış. Daha iyi sonuçlar için açabilirsiniz',
        confidence: 0.75,
        priority: 'low',
        suggestedAction: {
          type: 'enable_ai_optimization',
          payload: {},
        },
      };
    }

    return null;
  }

  private async findStalePlatforms(
    tenantId: string,
    userId: string,
  ): Promise<Array<{ name: string; daysSinceSync: number }>> {
    const platforms = ['TRENDYOL', 'AMAZON', 'HEPSIBURADA', 'N11'];
    const stale: Array<{ name: string; daysSinceSync: number }> = [];

    for (const platform of platforms) {
      const lastSync = await this.prisma.aIAssistantSyncJob.findFirst({
        where: {
          tenantId,
          userId,
          platform,
          status: 'COMPLETED',
        },
        orderBy: { completedAt: 'desc' },
      });

      if (lastSync?.completedAt) {
        const daysSince = Math.floor(
          (Date.now() - new Date(lastSync.completedAt).getTime()) /
            (1000 * 60 * 60 * 24),
        );

        if (daysSince >= 3) {
          stale.push({ name: platform, daysSinceSync: daysSince });
        }
      }
    }

    return stale;
  }

  private async findIncompleteBulkOperations(
    tenantId: string,
    userId: string,
  ): Promise<Array<{ id: string; type: string; progress: number }>> {
    const incompleteJobs = await this.prisma.aIAssistantSyncJob.findMany({
      where: {
        tenantId,
        userId,
        status: 'PROCESSING',
        type: 'BULK_UPLOAD',
      },
    });

    return incompleteJobs.map((job) => ({
      id: job.id,
      type: job.type,
      progress:
        job.totalItems > 0
          ? Math.round((job.processedItems / job.totalItems) * 100)
          : 0,
    }));
  }

  private sortSuggestions(
    suggestions: PredictiveSuggestion[],
  ): PredictiveSuggestion[] {
    const priorityOrder = { urgent: 0, high: 1, medium: 2, low: 3 };

    return suggestions.sort((a, b) => {
      // First by priority
      const priorityDiff =
        priorityOrder[a.priority] - priorityOrder[b.priority];
      if (priorityDiff !== 0) return priorityDiff;

      // Then by confidence
      return b.confidence - a.confidence;
    });
  }

  // ==================== STORE AND RETRIEVE ====================

  async storeSuggestion(
    tenantId: string,
    userId: string,
    suggestion: PredictiveSuggestion,
  ): Promise<void> {
    await this.prisma.aIPredictiveSuggestion.create({
      data: {
        tenantId,
        userId,
        suggestionType: suggestion.type,
        title: suggestion.title,
        description: suggestion.description,
        basedOn: suggestion.context || {},
        confidence: suggestion.confidence,
        suggestedAction: (suggestion.suggestedAction || null) as any,
        validUntil:
          suggestion.validUntil || new Date(Date.now() + 24 * 60 * 60 * 1000),
      },
    });
  }

  async getActiveSuggestions(
    tenantId: string,
    userId: string,
  ): Promise<PredictiveSuggestion[]> {
    const suggestions = await this.prisma.aIPredictiveSuggestion.findMany({
      where: {
        tenantId,
        userId,
        isDismissed: false,
        validUntil: {
          gt: new Date(),
        },
      },
      orderBy: [{ confidence: 'desc' }, { createdAt: 'desc' }],
      take: 10,
    });

    return suggestions.map((s) => ({
      id: s.id,
      type: s.suggestionType as PredictiveSuggestion['type'],
      title: s.title,
      description: s.description,
      confidence: s.confidence,
      priority: this.calculatePriority(s.confidence),
      suggestedAction: s.suggestedAction as any,
      context: s.basedOn,
      validUntil: s.validUntil || undefined,
    }));
  }

  async dismissSuggestion(suggestionId: string): Promise<void> {
    await this.prisma.aIPredictiveSuggestion.update({
      where: { id: suggestionId },
      data: {
        isDismissed: true,
        dismissedAt: new Date(),
      },
    });
  }

  async acceptSuggestion(suggestionId: string): Promise<void> {
    await this.prisma.aIPredictiveSuggestion.update({
      where: { id: suggestionId },
      data: {
        isAccepted: true,
        shownAt: new Date(),
      },
    });
  }

  // ==================== PREDICTIVE ANALYTICS ====================

  async predictUserBehavior(
    tenantId: string,
    userId: string,
  ): Promise<UserBehaviorPrediction> {
    // Get historical patterns
    const patterns = await this.prisma.aIPatternRecognition.findMany({
      where: {
        tenantId,
        userId,
        isActive: true,
      },
      orderBy: { confidence: 'desc' },
    });

    // Get recent actions
    const recentLogs = await this.prisma.aILearningLog.findMany({
      where: {
        tenantId,
        userId,
        eventType: 'action_completed',
        createdAt: {
          gte: new Date(Date.now() - 7 * 24 * 60 * 60 * 1000),
        },
      },
    });

    // Predict next actions
    const likelyNextActions = patterns.slice(0, 5).map((p) => ({
      action: p.action,
      probability: p.confidence * (p.successRate || 1),
      context: { trigger: p.trigger, conditions: p.conditions },
    }));

    // Find optimal timing
    const timingPatterns = patterns.filter((p) => p.patternType === 'timing');
    let optimalTiming = {
      bestTime: '09:00-17:00',
      reason: 'Standart iş saatleri',
    };

    if (timingPatterns.length > 0) {
      const bestTiming = timingPatterns[0];
      optimalTiming = {
        bestTime: bestTiming.trigger || '09:00-17:00',
        reason: 'Geçmiş aktivitelerinize göre en verimli zaman',
      };
    }

    // Predict potential issues
    const potentialIssues: UserBehaviorPrediction['potentialIssues'] = [];

    const errorPatterns = patterns.filter(
      (p) => p.patternType === 'error_pattern',
    );
    for (const error of errorPatterns.slice(0, 2)) {
      potentialIssues.push({
        issue: error.trigger || 'Bilinmeyen hata',
        probability: 1 - (error.successRate || 0.5),
        prevention: error.action || 'Dikkatli olun',
      });
    }

    return {
      likelyNextActions,
      optimalTiming,
      potentialIssues,
    };
  }
}

