import { Injectable, Logger } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import OpenAI from 'openai';

@Injectable()
export class AiImageGenerationService {
  private readonly logger = new Logger(AiImageGenerationService.name);
  private openai: OpenAI | null = null;
  private isAvailable: boolean = false;

  constructor(private configService: ConfigService) {
    const apiKey = this.configService.get<string>('OPENAI_API_KEY');
    if (apiKey) {
      try {
        this.openai = new OpenAI({ apiKey });
        this.isAvailable = true;
        this.logger.log('OpenAI service initialized successfully');
      } catch (error) {
        this.logger.warn('Failed to initialize OpenAI service');
      }
    } else {
      this.logger.warn(
        'OPENAI_API_KEY not configured - AI image generation disabled',
      );
    }
  }

  async generateImage(
    prompt: string,
    size: '256x256' | '512x512' | '1024x1024' = '1024x1024',
  ): Promise<string> {
    if (!this.isAvailable || !this.openai) {
      this.logger.warn('OpenAI service is not available');
      throw new Error(
        'AI image generation is not configured. Please set OPENAI_API_KEY environment variable.',
      );
    }

    this.logger.log(`Generating image for prompt: ${prompt}`);
    try {
      const response = await this.openai.images.generate({
        model: 'dall-e-3',
        prompt: prompt,
        n: 1,
        size: size,
      });

      return response.data?.[0]?.url || '';
    } catch (error) {
      this.logger.error('DALL-E Generation Error:', error);
      throw new Error('AI image generation failed');
    }
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import axios from 'axios';

@Injectable()
export class AiImageService {
  private readonly logger = new Logger(AiImageService.name);
  private readonly replicateApiKey: string | undefined;
  private readonly removeBgApiKey: string | undefined;

  constructor(private configService: ConfigService) {
    this.replicateApiKey = this.configService.get('REPLICATE_API_KEY');
    this.removeBgApiKey = this.configService.get('REMOVEBG_API_KEY');
  }

  async removeBackground(imageUrl: string): Promise<string> {
    this.logger.log(`Removing background for image: ${imageUrl}`);

    if (!this.removeBgApiKey) {
      this.logger.warn(
        'REMOVEBG_API_KEY not configured, returning original image',
      );
      return imageUrl;
    }

    try {
      // Use Remove.bg API for background removal
      const response = await axios.post(
        'https://api.remove.bg/v1.0/removebg',
        { image_url: imageUrl },
        {
          headers: {
            'X-Api-Key': this.removeBgApiKey,
            'Content-Type': 'application/json',
          },
          responseType: 'arraybuffer',
        },
      );

      // Upload result to storage and return URL
      const processedUrl = await this.uploadToStorage(
        Buffer.from(response.data),
      );
      return processedUrl;
    } catch (error) {
      this.logger.error(
        `Background removal failed: ${(error as Error).message}`,
      );
      throw new BadRequestException('Arka plan kaldırma işlemi başarısız oldu');
    }
  }

  async upscale(imageUrl: string): Promise<string> {
    this.logger.log(`Upscaling image: ${imageUrl}`);

    if (!this.replicateApiKey) {
      this.logger.warn(
        'REPLICATE_API_KEY not configured, returning original image',
      );
      return imageUrl;
    }

    try {
      // Use Replicate API for upscaling
      const prediction = await this.createReplicatePrediction(
        'nightmareai/real-esrgan',
        { image: imageUrl, scale: 4 },
      );

      return prediction.output || imageUrl;
    } catch (error) {
      this.logger.error(`Upscaling failed: ${(error as Error).message}`);
      throw new BadRequestException('Görüntü büyütme işlemi başarısız oldu');
    }
  }

  private async createReplicatePrediction(
    model: string,
    input: Record<string, any>,
  ): Promise<any> {
    const response = await axios.post(
      'https://api.replicate.com/v1/predictions',
      { version: model, input },
      {
        headers: {
          Authorization: `Token ${this.replicateApiKey}`,
          'Content-Type': 'application/json',
        },
      },
    );

    // Poll for completion
    let prediction = response.data;
    const maxAttempts = 30;
    let attempts = 0;

    while (
      prediction.status !== 'succeeded' &&
      prediction.status !== 'failed' &&
      attempts < maxAttempts
    ) {
      await new Promise((resolve) => setTimeout(resolve, 1000));
      const pollResponse = await axios.get(
        `https://api.replicate.com/v1/predictions/${prediction.id}`,
        { headers: { Authorization: `Token ${this.replicateApiKey}` } },
      );
      prediction = pollResponse.data;
      attempts++;
    }

    if (prediction.status === 'failed') {
      throw new Error('Prediction failed');
    }

    return prediction;
  }

  private async uploadToStorage(buffer: Buffer): Promise<string> {
    // In real implementation, upload to S3/Cloudflare R2/etc
    // For now, return data URL as placeholder
    return `data:image/png;base64,${buffer.toString('base64')}`;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import { GoogleGenerativeAI } from '@google/generative-ai';
import { ConfigService } from '@nestjs/config';

@Injectable()
export class UserBriefingService {
  private readonly logger = new Logger(UserBriefingService.name);
  private genAI: GoogleGenerativeAI;
  private model: any;

  constructor(
    private prisma: PrismaService,
    private configService: ConfigService,
  ) {
    const apiKey = this.configService.get<string>('GEMINI_API_KEY');
    if (apiKey) {
      this.genAI = new GoogleGenerativeAI(apiKey);
      this.model = this.genAI.getGenerativeModel({ model: 'gemini-1.5-flash' });
    }
  }

  async generateDailyBriefing(tenantId: string) {
    this.logger.log(`Generating daily briefing for tenant: ${tenantId}`);

    // 1. Get key data points
    const today = new Date();
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);

    const orders = await this.prisma.order.findMany({
      where: { tenantId, orderDate: { gte: yesterday } },
    });

    const totalRevenue = orders.reduce(
      (sum, o) => sum + Number(o.totalAmount || 0),
      0,
    );
    const orderCount = orders.length;

    const lowStockProducts = await this.prisma.product.count({
      where: { tenantId, stock: { lt: 10 } },
    });

    // 2. Construct Prompt for Gemini
    const prompt = `
            Sen "PazarAI" adında bir e-ticaret danışmanısın. Satıcıyı sabah karşılayan bir özet hazırla.
            
            DÜNÜN VERİLERİ:
            - Ciro: ₺${totalRevenue}
            - Sipariş Adedi: ${orderCount}
            - Stok Uyarısı: ${lowStockProducts} ürün kritik seviyede.
            
            TALİMAT:
            - Samimi, profesyonel ve heyecan verici bir dil kullan.
            - "Günaydın Erdem!" diye başla (veya kullanıcı adı yoksa Genel başla).
            - En önemli fırsat veya uyarıyı vurgula.
            - Maksimum 3 cümle olsun.
            - Yanıtı sadece metin olarak ver.
        `;

    try {
      const result = await this.model.generateContent(prompt);
      const response = await result.response;
      const text = response.text();

      return {
        message: text,
        stats: {
          revenue: totalRevenue,
          orders: orderCount,
          stockAlerts: lowStockProducts,
        },
        generatedAt: new Date(),
      };
    } catch (error) {
      this.logger.error(`Briefing generation failed: ${error.message}`);
      return {
        message:
          'Günaydın! Sistemleriniz aktif, verilerinizi analiz ediyoruz. Harika bir gün dileriz!',
        stats: {
          revenue: totalRevenue,
          orders: orderCount,
          stockAlerts: lowStockProducts,
        },
        generatedAt: new Date(),
      };
    }
  }
}

