import {
  Injectable,
  UnauthorizedException,
  ConflictException,
  Logger,
} from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { PrismaService } from '../../database/prisma.service';
import * as bcrypt from 'bcryptjs';

export interface JwtPayload {
  sub: string; // userId
  email: string;
  tenantId: string;
  type: string; // SUPERADMIN | ADMIN | USER
}

export interface TokenResponse {
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
  user: {
    id: string;
    email: string;
    firstName: string | null;
    lastName: string | null;
    type: string;
    tenantId: string | null;
  };
}

@Injectable()
export class AuthService {
  private readonly logger = new Logger(AuthService.name);

  constructor(
    private readonly prisma: PrismaService,
    private readonly jwtService: JwtService,
  ) {}

  async login(email: string, password: string): Promise<TokenResponse> {
    const cleanEmail = email.toLowerCase().trim();
    this.logger.debug(`Login attempt for email: ${cleanEmail}`);

    const user = await this.prisma.user.findUnique({
      where: { email: cleanEmail },
      select: {
        id: true,
        email: true,
        password: true,
        firstName: true,
        lastName: true,
        type: true,
        tenantId: true,
      },
    });

    if (!user) {
      this.logger.warn(`Login failed: User not found for ${cleanEmail}`);
      throw new UnauthorizedException('Geçersiz e-posta veya şifre');
    }

    if (!user.password) {
      this.logger.warn(`Login failed: No password set for ${cleanEmail}`);
      throw new UnauthorizedException(
        'Bu hesap için şifre ayarlanmamış. OAuth ile giriş yapın.',
      );
    }

    const isPasswordValid = await bcrypt.compare(password, user.password);
    if (!isPasswordValid) {
      this.logger.warn(`Login failed: Invalid password for ${cleanEmail}`);
      throw new UnauthorizedException('Geçersiz e-posta veya şifre');
    }

    const tokens = await this.generateTokens(user);

    this.logger.log(`User logged in successfully: ${user.email}`);
    return tokens;
  }

  async register(data: {
    email: string;
    password: string;
    firstName?: string;
    lastName?: string;
    company?: string;
  }): Promise<TokenResponse> {
    const existing = await this.prisma.user.findUnique({
      where: { email: data.email.toLowerCase().trim() },
    });

    if (existing) {
      throw new ConflictException('Bu e-posta adresi zaten kayıtlı');
    }

    const hashedPassword = await bcrypt.hash(data.password, 12);

    // Create a new tenant for each registered user (multi-tenant SaaS)
    const tenantName =
      data.company ||
      `${data.firstName || data.email.split('@')[0]}'in Mağazası`;
    const baseSlug = tenantName
      .toLowerCase()
      .replace(/[çÇ]/g, 'c')
      .replace(/[ğĞ]/g, 'g')
      .replace(/[ıİ]/g, 'i')
      .replace(/[öÖ]/g, 'o')
      .replace(/[şŞ]/g, 's')
      .replace(/[üÜ]/g, 'u')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .substring(0, 60);

    let slug = baseSlug;
    const slugExists = await this.prisma.tenant.findFirst({ where: { slug } });
    if (slugExists) {
      slug = `${baseSlug}-${Date.now().toString(36)}`;
    }

    try {
      const result = await this.prisma.$transaction(async (tx) => {
        const tenant = await tx.tenant.create({
          data: {
            name: tenantName,
            slug,
            plan: 'FREE',
            isOnboarded: false,
          },
        });

        const adminRole = await tx.role.create({
          data: {
            name: 'Admin',
            description: 'Mağaza Yöneticisi - Tam Yetki',
            tenantId: tenant.id,
            isSystem: true,
            permissions: {
              create: [{ action: 'manage', resource: 'all' }],
            },
          },
        });

        const user = await tx.user.create({
          data: {
            email: data.email.toLowerCase().trim(),
            password: hashedPassword,
            firstName: data.firstName || null,
            lastName: data.lastName || null,
            tenantId: tenant.id,
            roleId: adminRole.id,
            type: 'ADMIN',
          },
          select: {
            id: true,
            email: true,
            firstName: true,
            lastName: true,
            type: true,
            tenantId: true,
          },
        });

        return user;
      });

      const tokens = await this.generateTokens({
        id: result.id,
        email: result.email,
        firstName: result.firstName,
        lastName: result.lastName,
        type: result.type,
        tenantId: result.tenantId,
      });
      this.logger.log(
        `User registered with new tenant: ${result.email} (tenant: ${slug})`,
      );
      return tokens;
    } catch (error) {
      this.logger.error(
        `Registration failed for ${data.email}: ${error.message}`,
        error.stack,
      );
      if (error instanceof ConflictException) throw error;
      throw new Error(
        `Kayıt işlemi sırasında bir hata oluştu: ${error.message}`,
      );
    }
  }

  async refreshToken(refreshToken: string): Promise<TokenResponse> {
    try {
      const payload = this.jwtService.verify<
        JwtPayload & { tokenType: string }
      >(refreshToken);

      if (payload.tokenType !== 'refresh') {
        throw new UnauthorizedException('Geçersiz refresh token');
      }

      const user = await this.prisma.user.findUnique({
        where: { id: payload.sub },
        select: {
          id: true,
          email: true,
          firstName: true,
          lastName: true,
          type: true,
          tenantId: true,
        },
      });

      if (!user) {
        throw new UnauthorizedException('Kullanıcı bulunamadı');
      }

      return this.generateTokens({
        id: user.id,
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        type: user.type,
        tenantId: user.tenantId,
      });
    } catch {
      throw new UnauthorizedException(
        'Geçersiz veya süresi dolmuş refresh token',
      );
    }
  }

  async validateUser(payload: JwtPayload) {
    const user = await this.prisma.user.findUnique({
      where: { id: payload.sub },
      select: {
        id: true,
        email: true,
        firstName: true,
        lastName: true,
        type: true,
        tenantId: true,
      },
    });

    if (!user) {
      throw new UnauthorizedException('Geçersiz token');
    }

    return user;
  }

  async changePassword(
    userId: string,
    oldPassword: string,
    newPassword: string,
  ): Promise<void> {
    const user = await this.prisma.user.findUnique({
      where: { id: userId },
      select: { password: true },
    });

    if (!user?.password) {
      throw new UnauthorizedException('Mevcut şifre bulunamadı');
    }

    const isOldPasswordValid = await bcrypt.compare(oldPassword, user.password);
    if (!isOldPasswordValid) {
      throw new UnauthorizedException('Mevcut şifre yanlış');
    }

    if (newPassword.length < 8) {
      throw new UnauthorizedException('Yeni şifre en az 8 karakter olmalıdır');
    }

    const hashedPassword = await bcrypt.hash(newPassword, 12);
    await this.prisma.user.update({
      where: { id: userId },
      data: { password: hashedPassword },
    });

    this.logger.log(`Password changed for user: ${userId}`);
  }

  private async generateTokens(user: {
    id: string;
    email: string;
    firstName: string | null;
    lastName: string | null;
    type: string;
    tenantId: string | null;
  }): Promise<TokenResponse> {
    const payload: JwtPayload = {
      sub: user.id,
      email: user.email,
      tenantId: user.tenantId || '',
      type: user.type,
    };

    const accessToken = this.jwtService.sign(payload, { expiresIn: '24h' });
    const refreshToken = this.jwtService.sign(
      { ...payload, tokenType: 'refresh' },
      { expiresIn: '7d' },
    );

    return {
      accessToken,
      refreshToken,
      expiresIn: 86400, // 24h in seconds
      user: {
        id: user.id,
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        type: user.type,
        tenantId: user.tenantId,
      },
    };
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Body,
  Param,
  Query,
  Request,
  BadRequestException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse } from '@nestjs/swagger';
import {
  BackupService,
  BackupType,
  BackupStatus,
  BackupSchedule,
} from './backup.service';

// DTOs
export class CreateBackupScheduleDto {
  name: string;
  type: 'full' | 'incremental' | 'differential';
  frequency: 'hourly' | 'daily' | 'weekly' | 'monthly';
  databases: string[];
  retentionDays?: number;
}

export class UpdateScheduleDto {
  name?: string;
  frequency?: string;
  isActive?: boolean;
  retentionDays?: number;
}

export class StartBackupDto {
  name: string;
  type: 'full' | 'incremental';
  databases: string[];
  retentionDays?: number;
}

export class StartRestoreDto {
  backupId: string;
  targetDatabase: string;
  dryRun?: boolean;
}

export class UpdateDRSettingsDto {
  rtoMinutes?: number;
  rpoMinutes?: number;
  replicationEnabled?: boolean;
  geoRedundancyEnabled?: boolean;
  backupEncryption?: boolean;
  encryptionAlgorithm?: string;
  dataRetentionYears?: number;
  complianceLevel?: string;
}

@ApiTags('Backup & Disaster Recovery')
@Controller('api/backup')
export class BackupController {
  constructor(private backupService: BackupService) {}

  /**
   * Create backup schedule
   */
  @Post('schedules')
  @ApiOperation({ summary: 'Create new backup schedule' })
  @ApiResponse({
    status: 201,
    description: 'Schedule created',
  })
  async createSchedule(@Body() dto: CreateBackupScheduleDto) {
    return this.backupService.createSchedule(
      dto.name,
      dto.type as BackupType,
      dto.frequency,
      dto.databases,
      dto.retentionDays || 30,
    );
  }

  /**
   * Get all schedules
   */
  @Get('schedules')
  @ApiOperation({ summary: 'Get all backup schedules' })
  @ApiResponse({
    status: 200,
    description: 'List of schedules',
  })
  async getSchedules() {
    return this.backupService.getSchedules();
  }

  /**
   * Get schedule by ID
   */
  @Get('schedules/:id')
  @ApiOperation({ summary: 'Get backup schedule by ID' })
  @ApiResponse({
    status: 200,
    description: 'Schedule details',
  })
  async getSchedule(@Param('id') id: string) {
    const schedule = await this.backupService.getScheduleById(id);
    if (!schedule) {
      throw new BadRequestException('Schedule not found');
    }
    return schedule;
  }

  /**
   * Update schedule
   */
  @Put('schedules/:id')
  @ApiOperation({ summary: 'Update backup schedule' })
  @ApiResponse({
    status: 200,
    description: 'Schedule updated',
  })
  async updateSchedule(
    @Param('id') id: string,
    @Body() dto: UpdateScheduleDto,
  ) {
    return this.backupService.updateSchedule(
      id,
      dto as Partial<BackupSchedule>,
    );
  }

  /**
   * Delete schedule
   */
  @Delete('schedules/:id')
  @ApiOperation({ summary: 'Delete backup schedule' })
  @ApiResponse({
    status: 200,
    description: 'Schedule deleted',
  })
  async deleteSchedule(@Param('id') id: string) {
    await this.backupService.deleteSchedule(id);
    return { success: true };
  }

  /**
   * Start manual backup
   */
  @Post('create')
  @ApiOperation({ summary: 'Start manual backup immediately' })
  @ApiResponse({
    status: 200,
    description: 'Backup started',
  })
  async startBackup(@Body() dto: StartBackupDto) {
    return this.backupService.startBackup(
      dto.name,
      dto.type as BackupType,
      dto.databases,
      dto.retentionDays || 30,
    );
  }

  /**
   * Get all backups
   */
  @Get('jobs')
  @ApiOperation({ summary: 'Get all backup jobs' })
  @ApiResponse({
    status: 200,
    description: 'List of backup jobs',
  })
  async getBackups(
    @Query('limit') limit: string = '50',
    @Query('offset') offset: string = '0',
    @Query('status') status?: BackupStatus,
  ) {
    return this.backupService.getBackups(
      parseInt(limit),
      parseInt(offset),
      status,
    );
  }

  /**
   * Get backup by ID
   */
  @Get('jobs/:id')
  @ApiOperation({ summary: 'Get backup job by ID' })
  @ApiResponse({
    status: 200,
    description: 'Backup job details',
  })
  async getBackup(@Param('id') id: string) {
    const backup = await this.backupService.getBackupById(id);
    if (!backup) {
      throw new BadRequestException('Backup not found');
    }
    return backup;
  }

  /**
   * Get backup statistics
   */
  @Get('statistics')
  @ApiOperation({ summary: 'Get backup statistics' })
  @ApiResponse({
    status: 200,
    description: 'Backup statistics',
  })
  async getStatistics() {
