import { Injectable, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import * as cron from 'node-cron';

export enum BackupType {
  FULL = 'full',
  INCREMENTAL = 'incremental',
  DIFFERENTIAL = 'differential',
}

export enum BackupStatus {
  SCHEDULED = 'scheduled',
  IN_PROGRESS = 'in_progress',
  COMPLETED = 'completed',
  FAILED = 'failed',
  ARCHIVED = 'archived',
}

export enum VerificationStatus {
  PENDING = 'pending',
  VERIFIED = 'verified',
  FAILED = 'failed',
}

export interface BackupJob {
  id: string;
  name: string;
  type: BackupType;
  status: BackupStatus;
  scheduleId?: string;
  startTime: Date;
  endTime?: Date;
  duration?: number;
  uncompressedSize: number;
  compressedSize: number;
  compressionRatio: number;
  location: string;
  storageType: string;
  databases: string[];
  tables: number;
  rows: number;
  verificationStatus: VerificationStatus;
  verifiedAt?: Date;
  retentionDays: number;
  expiresAt: Date;
  estimatedRestoreTimeMs: number;
  createdAt: Date;
  updatedAt: Date;
}

export interface BackupSchedule {
  id: string;
  name?: string | null;
  type: string;
  frequency: 'hourly' | 'daily' | 'weekly' | 'monthly';
  cronExpression?: string | null;
  isActive: boolean;
  retentionDays: number;
  databases: string[];
  lastRunAt?: Date | null;
  nextRunAt: Date;
  failureCount: number;
  lastFailureMessage?: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface DisasterRecoverySettings {
  rtoMinutes: number;
  rpoMinutes: number;
  replicationEnabled: boolean;
  geoRedundancyEnabled: boolean;
  testRestoreFrequencyDays: number;
  lastTestRestoreDate?: Date;
  backupEncryption: boolean;
  encryptionAlgorithm: string;
  dataRetentionYears: number;
  complianceLevel: string;
}

@Injectable()
export class BackupService {
  private backupSchedules = new Map<string, NodeJS.Timeout>();

  constructor(private prisma: PrismaService) {
    void this.initializeSchedules();
  }

  /**
   * Initialize backup schedules from database
   */
  private async initializeSchedules() {
    try {
      const schedules = await this.getActiveSchedules();
      for (const schedule of schedules) {
        this.scheduleBackup(schedule);
      }
    } catch (error) {
      console.error('Failed to initialize backup schedules:', error);
    }
  }

  /**
   * Create a new backup schedule
   */
  async createSchedule(
    name: string,
    type: BackupType,
    frequency: 'hourly' | 'daily' | 'weekly' | 'monthly',
    databases: string[],
    retentionDays: number = 30,
  ): Promise<BackupSchedule> {
    const cronExpression = this.frequencyToCron(frequency);

    const schedule = await (this.prisma as any).backupSchedule.create({
      data: {
        tenant: {
          connect: {
            id: (this.prisma as any).currentTenantId || 'default-tenant-id',
          },
        }, // Assuming tenantId context or similar
        name,
        type,
        frequency,
        cronExpression,
        isActive: true,
        databases,
        retentionDays,
        nextRunAt: this.getNextRunTime(frequency),
        failureCount: 0,
      },
    });

    void this.scheduleBackup(schedule as unknown as BackupSchedule);
    return schedule as unknown as BackupSchedule;
  }

  /**
   * Get all backup schedules
   */
  async getSchedules(): Promise<BackupSchedule[]> {
    return (this.prisma as any).backupSchedule.findMany({
      orderBy: { createdAt: 'desc' },
    }) as unknown as BackupSchedule[];
  }

  /**
   * Get active schedules only
   */
  async getActiveSchedules(): Promise<BackupSchedule[]> {
    return (this.prisma as any).backupSchedule.findMany({
      where: { isActive: true },
    }) as unknown as BackupSchedule[];
  }

  /**
   * Get backup schedule by ID
   */
  async getScheduleById(id: string): Promise<BackupSchedule | null> {
    return this.prisma.backupSchedule.findUnique({
      where: { id },
    }) as unknown as BackupSchedule | null;
  }

  /**
   * Update backup schedule
   */
  async updateSchedule(
    id: string,
    data: Partial<BackupSchedule>,
  ): Promise<BackupSchedule> {
    const schedule = await this.prisma.backupSchedule.update({
      where: { id },
      data: {
        ...data,
        updatedAt: new Date(),
      },
    });

    // Reschedule if active
    if (schedule.isActive) {
      void this.scheduleBackup(schedule as unknown as BackupSchedule);
    }

    return schedule as unknown as BackupSchedule;
  }

  /**
   * Delete backup schedule
   */
  async deleteSchedule(id: string): Promise<void> {
    const timeout = this.backupSchedules.get(id);
    if (timeout) {
      clearTimeout(timeout);
      this.backupSchedules.delete(id);
    }

    await this.prisma.backupSchedule.delete({
      where: { id },
    });
  }

  /**
   * Start a manual backup
   */
  async startBackup(
    name: string,
    type: BackupType,
    databases: string[],
    retentionDays: number = 30,
  ): Promise<BackupJob> {
    const backup = await this.prisma.backupJob.create({
      data: {
        name,
        type,
        status: BackupStatus.IN_PROGRESS,
        startTime: new Date(),
        uncompressedSize: 0,
        compressedSize: 0,
        compressionRatio: 0,
        location: this.generateBackupLocation(),
        storageType: 'aws-s3',
        databases,
        tables: 0,
        rows: 0,
        verificationStatus: VerificationStatus.PENDING,
        retentionDays,
        expiresAt: new Date(Date.now() + retentionDays * 24 * 60 * 60 * 1000),
        estimatedRestoreTimeMs: this.estimateRestoreTime(type, databases),
        tenant: {
          connect: {
            id: (this.prisma as any).currentTenantId || 'default-tenant-id',
          },
        },
      },
    });

    // Simulate backup process
    void this.performBackup(backup.id);

    return backup as unknown as BackupJob;
  }

  /**
   * Get backup job by ID
   */
  async getBackupById(id: string): Promise<BackupJob | null> {
    return this.prisma.backupJob.findUnique({
      where: { id },
    }) as unknown as BackupJob | null;
  }

  /**
   * Get all backups
   */
  async getBackups(
    limit: number = 50,
    offset: number = 0,
    status?: BackupStatus,
  ): Promise<BackupJob[]> {
    return this.prisma.backupJob.findMany({
      where: status ? { status } : undefined,
      orderBy: { startTime: 'desc' },
      take: limit,
      skip: offset,
    }) as unknown as BackupJob[];
  }

  /**
   * Get backup statistics
   */
  async getBackupStatistics() {
    const totalBackups = await this.prisma.backupJob.count();
    const successfulBackups = await this.prisma.backupJob.count({
      where: { status: BackupStatus.COMPLETED },
    });
    const failedBackups = await this.prisma.backupJob.count({
      where: { status: BackupStatus.FAILED },
    });

    const allBackups = await this.prisma.backupJob.findMany({
      orderBy: { startTime: 'desc' },
      take: 100,
    });

    const totalSize = allBackups.reduce(
      (sum, b) => sum + (Number(b.compressedSize) || 0),
      0,
    );
    const avgDuration =
      allBackups
        .filter((b) => b.duration)
        .reduce((sum, b) => sum + (b.duration || 0), 0) / allBackups.length;

    return {
      totalBackups,
      successfulBackups,
      failedBackups,
      successRate: (successfulBackups / totalBackups) * 100,
      totalSize,
      averageDurationMs: avgDuration,
      totalCompressedSize: totalSize,
      averageCompressionRatio:
        allBackups.reduce(
          (sum, b) => sum + (Number(b.compressionRatio) || 0),
          0,
        ) / allBackups.length,
    };
  }

  /**
   * Verify backup integrity
   */
  async verifyBackup(backupId: string): Promise<boolean> {
    const backup = await this.getBackupById(backupId);
    if (!backup) {
      throw new BadRequestException('Backup not found');
    }

    // Verify based on metadata completeness and status
    const isValid =
      backup.status === BackupStatus.COMPLETED &&
      backup.compressedSize > 0 &&
      backup.uncompressedSize > 0 &&
      backup.tables > 0;

    const status = isValid
      ? VerificationStatus.VERIFIED
      : VerificationStatus.FAILED;

    await this.prisma.backupJob.update({
      where: { id: backupId },
      data: {
        verificationStatus: status,
        verifiedAt: new Date(),
      },
    });

    return isValid;
  }

  /**
   * List restore points
   */
  async getRestorePoints(limit: number = 20): Promise<BackupJob[]> {
    return this.prisma.backupJob.findMany({
      where: {
        status: BackupStatus.COMPLETED,
        verificationStatus: VerificationStatus.VERIFIED,
      },
      orderBy: { startTime: 'desc' },
      take: limit,
    }) as unknown as BackupJob[];
  }

  /**
   * Start restore from backup
   */
  async startRestore(
    backupId: string,
    targetDatabase: string,
    dryRun: boolean = false,
  ): Promise<any> {
    const backup = await this.getBackupById(backupId);
    if (!backup) {
      throw new BadRequestException('Backup not found');
    }

    if (backup.verificationStatus !== VerificationStatus.VERIFIED) {
      throw new BadRequestException('Backup is not verified');
    }

    const restore = await this.prisma.restoreJob.create({
      data: {
        backupId,
        targetDatabase,
        sourceDatabase: backup.databases[0],
        status: 'in_progress',
        startedAt: new Date(),
        dryRun,
        estimatedDurationMs: backup.estimatedRestoreTimeMs,
        tenant: {
          connect: {
            id: (this.prisma as any).currentTenantId || 'default-tenant-id',
          },
        },
      },
    });

    // Simulate restore process
    void this.performRestore(restore.id);

    return restore;
  }

  /**
   * Get restore job
   */
  async getRestoreJob(id: string): Promise<any> {
    return this.prisma.restoreJob.findUnique({
      where: { id },
      include: { backup: true } as any,
    });
  }

  /**
   * Get DR settings
   */
  async getDRSettings(): Promise<DisasterRecoverySettings> {
    const settings = await this.prisma.drSettings.findFirst();

    if (!settings) {
      return {
        rtoMinutes: 240,
        rpoMinutes: 60,
        replicationEnabled: true,
        geoRedundancyEnabled: true,
        testRestoreFrequencyDays: 30,
        backupEncryption: true,
        encryptionAlgorithm: 'AES-256',
        dataRetentionYears: 7,
        complianceLevel: 'GDPR',
      };
    }

    return {
      ...settings,
      rtoMinutes: settings.rtoMinutes || 240,
      rpoMinutes: settings.rpoMinutes || 60,
      replicationEnabled: settings.replicationEnabled ?? true,
      geoRedundancyEnabled: settings.geoRedundancyEnabled ?? true,
      testRestoreFrequencyDays: settings.testRestoreFrequencyDays || 30,
      backupEncryption: settings.backupEncryption ?? true,
      encryptionAlgorithm: settings.encryptionAlgorithm || 'AES-256',
      dataRetentionYears: settings.dataRetentionYears || 7,
      complianceLevel: settings.complianceLevel || 'GDPR',
    };
  }

  /**
   * Update DR settings
   */
  async updateDRSettings(data: Partial<DisasterRecoverySettings>) {
    const existing = await this.prisma.drSettings.findFirst();

    if (existing) {
      return this.prisma.drSettings.update({
        where: { id: existing.id },
        data,
      });
    }

    return this.prisma.drSettings.create({
      data: {
        ...data,
        rtoMinutes: data.rtoMinutes || 240,
        rpoMinutes: data.rpoMinutes || 60,
        replicationEnabled: data.replicationEnabled !== false,
        geoRedundancyEnabled: data.geoRedundancyEnabled !== false,
        testRestoreFrequencyDays: data.testRestoreFrequencyDays || 30,
        backupEncryption: data.backupEncryption !== false,
        encryptionAlgorithm: data.encryptionAlgorithm || 'AES-256',
        dataRetentionYears: data.dataRetentionYears || 7,
        complianceLevel: data.complianceLevel || 'GDPR',
        tenant: {
          connect: {
            id: (this.prisma as any).currentTenantId || 'default-tenant-id',
          },
        },
      },
    });
  }

  /**
   * Test restore (dry-run)
   */
  async testRestore(backupId: string): Promise<any> {
    return this.startRestore(backupId, 'test-db', true);
  }

  // Private helper methods

  /**
   * Schedule backup to run at specified frequency
   */
  private scheduleBackup(schedule: BackupSchedule) {
    if (!schedule.isActive) {
      return;
    }

    // Clear existing timeout if present
    const existing = this.backupSchedules.get(schedule.id);
    if (existing) {
      clearTimeout(existing);
    }

    // Schedule new backup
    const timeout = setTimeout(() => {
      void this.runScheduledBackup(schedule);
    }, this.getTimeUntilNextRun(schedule.frequency));

    this.backupSchedules.set(schedule.id, timeout);
  }

  /**
   * Convert frequency to cron expression
   */
  private frequencyToCron(frequency: string): string {
    const cronMap: Record<string, string> = {
      hourly: '0 * * * *',
      daily: '0 2 * * *',
      weekly: '0 2 * * 0',
      monthly: '0 2 1 * *',
    };
    return cronMap[frequency] || '0 2 * * *';
  }

  /**
   * Get next run time based on frequency
   */
  private getNextRunTime(frequency: string): Date {
    const now = new Date();
    const next = new Date(now);

    switch (frequency) {
      case 'hourly':
        next.setHours(next.getHours() + 1, 0, 0, 0);
        break;
      case 'daily':
        next.setDate(next.getDate() + 1);
        next.setHours(2, 0, 0, 0);
        break;
      case 'weekly':
        next.setDate(next.getDate() + (7 - next.getDay()));
        next.setHours(2, 0, 0, 0);
        break;
      case 'monthly':
        next.setMonth(next.getMonth() + 1);
        next.setDate(1);
        next.setHours(2, 0, 0, 0);
        break;
    }

    return next;
  }

  /**
   * Get time until next run in milliseconds
   */
  private getTimeUntilNextRun(frequency: string): number {
    return this.getNextRunTime(frequency).getTime() - Date.now();
  }

  /**
   * Generate backup location path
   */
  private generateBackupLocation(): string {
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    return `aws-s3://backups/prod/${timestamp}`;
  }

  /**
   * Estimate restore time based on backup type and size
   */
  private estimateRestoreTime(type: BackupType, databases: string[]): number {
    const baseTime = 60000; // 1 minute
    const dbMultiplier = databases.length * 2000;
    const typeMultiplier = type === BackupType.FULL ? 8 : 2;

    return baseTime + dbMultiplier + baseTime * typeMultiplier;
  }

  /**
   * Execute backup process
   */
  private async performBackup(backupId: string) {
    const startTime = Date.now();
    try {
      const backup = await this.getBackupById(backupId);
      if (!backup) return;

      // Get actual table count and row count from database
      const tableCountResult = await this.prisma
        .$queryRawUnsafe<
          { count: bigint }[]
        >(`SELECT count(*) as count FROM information_schema.tables WHERE table_schema = 'public'`)
        .catch(() => [{ count: BigInt(0) }]);

      const tables = Number(tableCountResult[0]?.count || 0);

      // Estimate size based on DB stats
      const dbSizeResult = await this.prisma
        .$queryRawUnsafe<
          { size: string }[]
        >(`SELECT pg_database_size(current_database())::text as size`)
        .catch(() => [{ size: '0' }]);

      const uncompressedSize = parseInt(dbSizeResult[0]?.size || '0', 10);
      const compressionRatio = 0.3; // typical gzip compression
      const compressedSize = Math.floor(uncompressedSize * compressionRatio);

      const duration = Date.now() - startTime;

      await this.prisma.backupJob.update({
        where: { id: backupId },
        data: {
          status: BackupStatus.COMPLETED,
          endTime: new Date(),
          duration,
          uncompressedSize: uncompressedSize || 1,
          compressedSize: compressedSize || 1,
          compressionRatio:
            uncompressedSize > 0 ? compressedSize / uncompressedSize : 0,
          tables,
          rows: 0, // will be filled on verification
          verificationStatus: VerificationStatus.PENDING,
        },
      });
    } catch (error) {
      await this.prisma.backupJob
        .update({
          where: { id: backupId },
          data: {
            status: BackupStatus.FAILED,
            endTime: new Date(),
            duration: Date.now() - startTime,
          },
        })
        .catch(() => {});
    }
  }

  /**
   * Execute restore process
   */
  private async performRestore(restoreId: string) {
    const startTime = Date.now();
    try {
      const restore = await this.prisma.restoreJob.findUnique({
        where: { id: restoreId },
      });

      if (restore) {
        await this.prisma.restoreJob.update({
          where: { id: restoreId },
          data: {
            status: 'completed',
            endTime: new Date(),
            duration: Date.now() - startTime,
          },
        });
      }
    } catch {
      await this.prisma.restoreJob
        .update({
          where: { id: restoreId },
          data: {
            status: 'failed',
            endTime: new Date(),
            duration: Date.now() - startTime,
          },
        })
        .catch(() => {});
    }
  }

  /**
   * Run scheduled backup
   */
  private async runScheduledBackup(schedule: BackupSchedule) {
    try {
      await this.startBackup(
        `${schedule.type.toUpperCase()} - ${new Date().toISOString()}`,
        schedule.type as BackupType,
        schedule.databases,
        schedule.retentionDays,
      );

      // Update schedule
      await this.updateSchedule(schedule.id, {
        lastRunAt: new Date(),
        nextRunAt: this.getNextRunTime(schedule.frequency),
        failureCount: 0,
      });
    } catch (error) {
      console.error(`Backup schedule ${schedule.id} failed:`, error);

      // Update schedule with failure info
      await this.updateSchedule(schedule.id, {
        failureCount: (schedule.failureCount || 0) + 1,
        lastFailureMessage: (error as Error).message,
      });
    }

    // Reschedule
    void this.scheduleBackup(schedule as unknown as BackupSchedule);
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import { ConvertCurrencyDto, SetExchangeRateDto } from './dto/currency.dto';

const SUPPORTED_CURRENCIES = ['TRY', 'USD', 'EUR', 'GBP'] as const;

@Injectable()
export class CurrencyService {
  private readonly logger = new Logger(CurrencyService.name);
  // In-memory cache for fast lookups
  private rateCache = new Map<string, { rate: number; updatedAt: Date }>();

  constructor(private readonly prisma: PrismaService) {
    this.loadLatestRates().catch(() => {
      this.logger.warn(
        'Başlangıç kurları yüklenemedi, varsayılan kurlar kullanılacak',
      );
    });
  }

  /** Döviz çevirme */
  async convert(dto: ConvertCurrencyDto): Promise<{
    amount: number;
    rate: number;
    from: string;
    to: string;
    result: number;
    date: Date;
  }> {
    if (dto.from === dto.to) {
      return {
        amount: dto.amount,
        rate: 1,
        from: dto.from,
        to: dto.to,
        result: dto.amount,
        date: new Date(),
      };
    }

    const rate = await this.getRate(dto.from, dto.to);
    const result = Math.round(dto.amount * rate * 100) / 100;

    return {
      amount: dto.amount,
      rate,
      from: dto.from,
      to: dto.to,
      result,
      date: new Date(),
    };
  }

  /** İki para birimi arasındaki güncel kuru getir */
  async getRate(from: string, to: string): Promise<number> {
    if (from === to) return 1;

    // Önce cache'e bak
    const cacheKey = `${from}_${to}`;
    const cached = this.rateCache.get(cacheKey);
    if (cached && Date.now() - cached.updatedAt.getTime() < 3600000) {
      // 1 saat
      return cached.rate;
    }

    // DB'den al
    const dbRate = await this.prisma.exchangeRate.findFirst({
      where: { baseCurrency: from, targetCurrency: to },
      orderBy: { date: 'desc' },
    });

    if (dbRate) {
      const rate = Number(dbRate.rate);
      this.rateCache.set(cacheKey, { rate, updatedAt: new Date() });
      return rate;
    }

    // Ters kur dene
    const reverseRate = await this.prisma.exchangeRate.findFirst({
      where: { baseCurrency: to, targetCurrency: from },
      orderBy: { date: 'desc' },
    });

    if (reverseRate) {
      const rate = 1 / Number(reverseRate.rate);
      this.rateCache.set(cacheKey, { rate, updatedAt: new Date() });
      return rate;
    }

    // TRY üzerinden cross-rate dene
    if (from !== 'TRY' && to !== 'TRY') {
      const fromToTry = await this.getRate(from, 'TRY');
      const toToTry = await this.getRate(to, 'TRY');
      if (fromToTry && toToTry) {
        return fromToTry / toToTry;
      }
    }

    // Varsayılan kurlar (fallback)
    const fallbackRates: Record<string, number> = {
      USD_TRY: 38.5,
      EUR_TRY: 40.8,
      GBP_TRY: 48.5,
    };

    const fallbackRate = fallbackRates[cacheKey];
    if (fallbackRate) {
      this.logger.warn(
        `Kur bulunamadı: ${from}→${to}, varsayılan kullanılıyor: ${fallbackRate}`,
      );
      return fallbackRate;
    }

    const reverseFallback = fallbackRates[`${to}_${from}`];
    if (reverseFallback) {
      return 1 / reverseFallback;
    }

    throw new BadRequestException(`Kur bulunamadı: ${from} → ${to}`);
  }

  /** Manuel kur girişi */
  async setRate(dto: SetExchangeRateDto) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const rate = await this.prisma.exchangeRate.upsert({
      where: {
        baseCurrency_targetCurrency_date: {
          baseCurrency: dto.baseCurrency,
          targetCurrency: dto.targetCurrency,
          date: today,
        },
      },
      update: { rate: dto.rate, source: dto.source || 'manual' },
      create: {
        baseCurrency: dto.baseCurrency,
        targetCurrency: dto.targetCurrency,
        rate: dto.rate,
        source: dto.source || 'manual',
        date: today,
      },
    });

    // Cache güncelle
    const cacheKey = `${dto.baseCurrency}_${dto.targetCurrency}`;
    this.rateCache.set(cacheKey, { rate: dto.rate, updatedAt: new Date() });

    this.logger.log(
      `Kur güncellendi: ${dto.baseCurrency}/${dto.targetCurrency} = ${dto.rate}`,
    );
    return rate;
  }

  /** Tüm güncel kurları getir */
  async getLatestRates(baseCurrency: string = 'TRY') {
    const rates: { currency: string; rate: number; baseCurrency: string }[] =
      [];

    for (const currency of SUPPORTED_CURRENCIES) {
      if (currency === baseCurrency) continue;

      try {
        const rate = await this.getRate(currency, baseCurrency);
        rates.push({
          currency,
          rate,
          baseCurrency,
        });
      } catch {
        // Bu para birimi için kur yok, atla
      }
    }

    return { baseCurrency, rates, date: new Date() };
  }

  /** Kur geçmişi */
  async getRateHistory(
    baseCurrency: string,
    targetCurrency: string,
    days: number = 30,
  ) {
    const startDate = new Date();
    startDate.setDate(startDate.getDate() - days);

    return this.prisma.exchangeRate.findMany({
      where: {
        baseCurrency,
        targetCurrency,
        date: { gte: startDate },
      },
      orderBy: { date: 'asc' },
    });
  }

  /** TCMB'den kurları çek (her gün 15:30'da) */
  // @Cron('30 15 * * 1-5') // Hafta içi her gün 15:30
  async fetchRatesFromTCMB() {
    this.logger.log('TCMB kurları çekiliyor...');

    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const rates: { base: string; target: string; rate: number }[] = [];

    try {
      const response = await fetch('https://www.tcmb.gov.tr/kurlar/today.xml');
      if (!response.ok) throw new Error(`TCMB HTTP ${response.status}`);
      const xml = await response.text();

      // Parse USD, EUR, GBP from TCMB XML
      const currencyMap: Record<string, string> = {
        'US DOLLAR': 'USD',
        EURO: 'EUR',
        'POUND STERLING': 'GBP',
      };
      const currencyRegex =
        /<Currency[^>]*CurrencyCode="(\w+)"[^>]*>[\s\S]*?<ForexBuying>([\d.]+)<\/ForexBuying>[\s\S]*?<ForexSelling>([\d.]+)<\/ForexSelling>[\s\S]*?<\/Currency>/g;

      let match: RegExpExecArray | null;
      while ((match = currencyRegex.exec(xml)) !== null) {
        const code = match[1];
        if (['USD', 'EUR', 'GBP'].includes(code)) {
          const buying = parseFloat(match[2]);
          const selling = parseFloat(match[3]);
          const midRate = Math.round(((buying + selling) / 2) * 10000) / 10000;
          if (!isNaN(midRate) && midRate > 0) {
            rates.push({ base: code, target: 'TRY', rate: midRate });
          }
        }
      }

      if (rates.length === 0) {
        this.logger.warn('TCMB XML parse edildi ancak kur verisi bulunamadı');
      }
    } catch (error) {
      this.logger.error(`TCMB API hatası: ${(error as Error).message}`);
      this.logger.warn('TCMB kurları çekilemedi, mevcut kurlar korunuyor');
      return { success: false, error: (error as Error).message };
    }

    for (const r of rates) {
      await this.prisma.exchangeRate.upsert({
        where: {
          baseCurrency_targetCurrency_date: {
            baseCurrency: r.base,
            targetCurrency: r.target,
            date: today,
          },
        },
        update: { rate: r.rate, source: 'TCMB' },
        create: {
          baseCurrency: r.base,
          targetCurrency: r.target,
          rate: r.rate,
          source: 'TCMB',
          date: today,
        },
      });
    }

    // Cache'i güncelle
    await this.loadLatestRates();

    this.logger.log(
      `TCMB kurları güncellendi: ${rates.map((r) => `${r.base}/${r.target}=${r.rate}`).join(', ')}`,
    );
    return { success: true, rates };
  }

  /** Cache'e en güncel kurları yükle */
  private async loadLatestRates() {
    for (const base of SUPPORTED_CURRENCIES) {
      for (const target of SUPPORTED_CURRENCIES) {
        if (base === target) continue;
        const rate = await this.prisma.exchangeRate.findFirst({
          where: { baseCurrency: base, targetCurrency: target },
          orderBy: { date: 'desc' },
        });
        if (rate) {
          this.rateCache.set(`${base}_${target}`, {
            rate: Number(rate.rate),
            updatedAt: rate.createdAt,
          });
        }
      }
    }
  }
}

