import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import type { Platform, Integration } from '@prisma/client';
import {
  ALL_MARKETPLACES,
  MarketplaceConfig,
  getMarketplaceById,
  getMarketplacesByRegion,
  getMarketplacesByPlan,
  canAccessMarketplace,
  getActiveMarketplaces,
  PlatformRegion,
  SubscriptionPlan,
  REGION_NAMES,
  CATEGORY_NAMES,
  PLAN_NAMES,
} from './marketplace-registry';
import { EncryptionService } from '../../common/encryption.service';

export interface IntegrationCredentials {
  [key: string]: string;
}

export interface UserIntegration {
  id: string;
  tenantId: string;
  marketplaceId: string;
  marketplace: MarketplaceConfig;
  credentials: IntegrationCredentials;
  isActive: boolean;
  status: 'connected' | 'disconnected' | 'error' | 'pending';
  lastSync?: Date;
  errorMessage?: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface ConnectionTestResult {
  success: boolean;
  message: string;
  details?: any;
}

// Platform enum değerlerine marketplaceId eşleştirmesi
const PLATFORM_MAP: Record<string, Platform> = {
  trendyol: 'TRENDYOL',
  hepsiburada: 'HEPSIBURADA',
  'amazon-tr': 'AMAZON',
  'amazon-us': 'AMAZON',
  'amazon-de': 'AMAZON',
  'amazon-uk': 'AMAZON',
  n11: 'N11',
} as const;

// Desteklenen platformlar
const SUPPORTED_PLATFORMS = [
  'trendyol',
  'hepsiburada',
  'amazon-tr',
  'amazon-us',
  'amazon-de',
  'amazon-uk',
  'n11',
];

function getPlatformEnum(marketplaceId: string): Platform | null {
  return PLATFORM_MAP[marketplaceId] || null;
}

function getMarketplaceIdFromPlatform(
  platform: Platform,
  apiExtra?: any,
): string {
  // apiExtra içinde marketplaceId varsa kullan
  if (apiExtra && typeof apiExtra === 'object' && 'marketplaceId' in apiExtra) {
    return apiExtra.marketplaceId as string;
  }
  // Varsayılan eşleştirme
  const platformMap: Partial<Record<Platform, string>> = {
    TRENDYOL: 'trendyol',
    HEPSIBURADA: 'hepsiburada',
    AMAZON: 'amazon-tr',
    N11: 'n11',
    CICEKSEPETI: 'ciceksepeti',
    GITTIGIDIYOR: 'gittigidiyor',
    PTTAVM: 'pttavm',
    MORHIPO: 'morhipo',
    AMAZON_US: 'amazon-us',
    AMAZON_UK: 'amazon-uk',
    AMAZON_DE: 'amazon-de',
    AMAZON_FR: 'amazon-fr',
    EBAY: 'ebay',
    ETSY: 'etsy',
    ALIEXPRESS: 'aliexpress',
    SHOPEE: 'shopee',
    LAZADA: 'lazada',
    WALMART: 'walmart',
    SHOPIFY: 'shopify',
    WOOCOMMERCE: 'woocommerce',
    WEBSITE: 'website',
    OTHER: 'other',
  };
  return platformMap[platform] || platform.toLowerCase();
}

@Injectable()
export class IntegrationsService {
  constructor(
    private prisma: PrismaService,
    private encryption: EncryptionService,
  ) {}

  private encrypt(text: string): string {
    return this.encryption.encrypt(text);
  }

  private decrypt(encryptedText: string): string {
    return this.encryption.decrypt(encryptedText);
  }

  // Tüm pazaryerlerini listele
  async getAllMarketplaces(
    tenantId: string,
    filters?: {
      region?: PlatformRegion;
      category?: string;
      status?: string;
      search?: string;
    },
  ): Promise<{
    marketplaces: (MarketplaceConfig & { userIntegration?: UserIntegration })[];
    regions: typeof REGION_NAMES;
    categories: typeof CATEGORY_NAMES;
  }> {
    // Kullanıcının mevcut entegrasyonlarını al
    const userIntegrations = await this.prisma.integration.findMany({
      where: { tenantId },
    });

    let marketplaces = getActiveMarketplaces();

    // Filtreleme
    if (filters?.region) {
      marketplaces = marketplaces.filter((m) => m.region === filters.region);
    }
    if (filters?.category) {
      marketplaces = marketplaces.filter(
        (m) => m.category === filters.category,
      );
    }
    if (filters?.status) {
      marketplaces = marketplaces.filter((m) => m.status === filters.status);
    }
    if (filters?.search) {
      const search = filters.search.toLowerCase();
      marketplaces = marketplaces.filter(
        (m) =>
          m.name.toLowerCase().includes(search) ||
          m.country.toLowerCase().includes(search) ||
          m.description.toLowerCase().includes(search),
      );
    }

    // Kullanıcı entegrasyonlarını eşleştir
    const marketplacesWithIntegration = marketplaces.map((marketplace) => {
      // Platform enum veya marketplaceId ile eşleştir
      const integration = userIntegrations.find((i) => {
        const integrationMarketplaceId = getMarketplaceIdFromPlatform(
          i.platform,
          i.apiExtra,
        );
        return integrationMarketplaceId === marketplace.id;
      });

      if (integration) {
        return {
          ...marketplace,
          userIntegration: {
            id: integration.id,
            tenantId: integration.tenantId,
            marketplaceId: marketplace.id,
            marketplace,
            credentials: {}, // Güvenlik için credentials gizli
            isActive: integration.isActive,
            status: integration.isActive ? 'connected' : 'disconnected',
            lastSync: integration.updatedAt || undefined,
            createdAt: integration.createdAt,
            updatedAt: integration.updatedAt,
          } as UserIntegration,
        };
      }
      return marketplace;
    });

    // Popülerliğe göre sırala
    marketplacesWithIntegration.sort((a, b) => b.popularity - a.popularity);

    return {
      marketplaces: marketplacesWithIntegration,
      regions: REGION_NAMES,
      categories: CATEGORY_NAMES,
    };
  }

  // Kullanıcının entegrasyonlarını listele
  async getUserIntegrations(tenantId: string): Promise<UserIntegration[]> {
    const integrations = await this.prisma.integration.findMany({
      where: { tenantId },
      orderBy: { createdAt: 'desc' },
    });

    return integrations
      .map((integration) => {
        const marketplaceId = getMarketplaceIdFromPlatform(
          integration.platform,
          integration.apiExtra,
        );
        const marketplace = getMarketplaceById(marketplaceId);
        return {
          id: integration.id,
          tenantId: integration.tenantId,
          marketplaceId,
          marketplace: marketplace!,
          credentials: {}, // Güvenlik için boş
          isActive: integration.isActive,
          status: integration.isActive ? 'connected' : 'disconnected',
          lastSync: integration.updatedAt || undefined,
          createdAt: integration.createdAt,
          updatedAt: integration.updatedAt,
        } as UserIntegration;
      })
      .filter((i) => i.marketplace);
  }

  // Pazaryeri detayını getir
  async getMarketplaceDetails(
    marketplaceId: string,
    tenantId?: string,
  ): Promise<MarketplaceConfig & { userIntegration?: UserIntegration }> {
    const marketplace = getMarketplaceById(marketplaceId);
    if (!marketplace) {
      throw new NotFoundException('Pazaryeri bulunamadı');
    }

    if (tenantId) {
      // Platform enum'unu al
      const platformEnum = getPlatformEnum(marketplaceId);
      if (platformEnum) {
        const integration = await this.prisma.integration.findFirst({
          where: { tenantId, platform: platformEnum },
        });

        if (integration) {
          // apiExtra'da doğru marketplaceId var mı kontrol et
          const integrationMarketplaceId = getMarketplaceIdFromPlatform(
            integration.platform,
            integration.apiExtra,
          );
          if (integrationMarketplaceId === marketplaceId) {
            return {
              ...marketplace,
              userIntegration: {
                id: integration.id,
                tenantId: integration.tenantId,
                marketplaceId,
                marketplace,
                credentials: {},
                isActive: integration.isActive,
                status: integration.isActive ? 'connected' : 'disconnected',
                lastSync: integration.updatedAt || undefined,
                createdAt: integration.createdAt,
                updatedAt: integration.updatedAt,
              } as UserIntegration,
            };
          }
        }
      }
    }

    return marketplace;
  }

  // Entegrasyon oluştur/bağlan
  async connectMarketplace(
    tenantId: string,
    marketplaceId: string,
    credentials: IntegrationCredentials,
  ): Promise<{
    success: boolean;
    integration: UserIntegration;
    message: string;
  }> {
    const marketplace = getMarketplaceById(marketplaceId);
    if (!marketplace) {
      throw new NotFoundException('Pazaryeri bulunamadı');
    }

    // Kullanıcının planını kontrol et (şimdilik PROFESSIONAL varsayıyoruz)
    const userPlan: SubscriptionPlan = 'PROFESSIONAL';
    if (!canAccessMarketplace(marketplace, userPlan)) {
      throw new BadRequestException(
        `Bu pazaryerine erişmek için ${PLAN_NAMES[marketplace.minimumPlan]} planına sahip olmanız gerekiyor.`,
      );
    }

    // Zorunlu alanları kontrol et
    for (const field of marketplace.requiredFields) {
      if (field.required && !credentials[field.key]) {
        throw new BadRequestException(`${field.label} alanı zorunludur`);
      }
    }

    // Platform enum'unu kontrol et
    const platformEnum = getPlatformEnum(marketplaceId);
    if (!platformEnum) {
      throw new BadRequestException(
        `Bu pazaryeri henüz desteklenmiyor: ${marketplace.name}. Yakında eklenecek!`,
      );
    }

    // apiKey ve apiSecret'ı ayarla
    const apiKey =
      credentials['apiKey'] ||
      credentials['supplierId'] ||
      credentials['sellerId'] ||
      '';
    const apiSecret =
      credentials['apiSecret'] ||
      credentials['secretKey'] ||
      credentials['apiToken'] ||
      '';

    // Diğer credentials'ı apiExtra'ya kaydet
    const apiExtra = {
      ...credentials,
      marketplaceId, // Hangi marketplace olduğunu kaydet
    };

    // Mevcut entegrasyonu kontrol et
    const existing = await this.prisma.integration.findFirst({
      where: {
        tenantId,
        platform: platformEnum,
        apiExtra: { path: ['marketplaceId'], equals: marketplaceId } as any,
      },
    });

    let integration: Integration;
    if (existing) {
      // Güncelle
      integration = await this.prisma.integration.update({
        where: { id: existing.id },
        data: {
          apiKey: this.encrypt(apiKey),
          apiSecret: this.encrypt(apiSecret),
          apiExtra,
          isActive: true,
        },
      });
    } else {
      // Yeni oluştur
      integration = await this.prisma.integration.create({
        data: {
          tenantId,
          platform: platformEnum,
          apiKey: this.encrypt(apiKey),
          apiSecret: this.encrypt(apiSecret),
          apiExtra,
          isActive: true,
        },
      });
    }

    // Bağlantıyı test et
    const testResult = await this.testConnection(integration.id, tenantId);

    return {
      success: testResult.success,
      integration: {
        id: integration.id,
        tenantId: integration.tenantId,
        marketplaceId,
        marketplace,
        credentials: {},
        isActive: testResult.success,
        status: testResult.success ? 'connected' : 'error',
        errorMessage: testResult.success ? undefined : testResult.message,
        createdAt: integration.createdAt,
        updatedAt: integration.updatedAt,
      } as UserIntegration,
      message: testResult.message,
    };
  }

  // Bağlantıyı test et
  async testConnection(
    integrationId: string,
    tenantId: string,
  ): Promise<ConnectionTestResult> {
    const integration = await this.prisma.integration.findFirst({
      where: { id: integrationId, tenantId },
    });

    if (!integration) {
      throw new NotFoundException('Entegrasyon bulunamadı');
    }

    const marketplaceId = getMarketplaceIdFromPlatform(
      integration.platform,
      integration.apiExtra,
    );
    const marketplace = getMarketplaceById(marketplaceId);
    if (!marketplace) {
      return { success: false, message: 'Pazaryeri yapılandırması bulunamadı' };
    }

    // Credentials'ı çöz
    const credentials: Record<string, string> = {};
    // apiKey ve apiSecret'ı çöz
    if (integration.apiKey) {
      credentials['apiKey'] = this.decrypt(integration.apiKey);
    }
    if (integration.apiSecret) {
      credentials['apiSecret'] = this.decrypt(integration.apiSecret);
    }
    // apiExtra'dan diğer bilgileri al
    if (integration.apiExtra && typeof integration.apiExtra === 'object') {
      const extra = integration.apiExtra as Record<string, unknown>;
      for (const [key, value] of Object.entries(extra)) {
        if (typeof value === 'string' && key !== 'marketplaceId') {
          credentials[key] = value;
        }
      }
    }

    // Gerçek API bağlantısı burada yapılacak
    // Şimdilik simüle ediyoruz
    try {
      // Her marketplace için farklı test mantığı olabilir
      switch (marketplace.id) {
        case 'trendyol':
          return await this.testTrendyolConnection(credentials);
        case 'hepsiburada':
          return await this.testHepsiburadaConnection(credentials);
        case 'n11':
          return await this.testN11Connection(credentials);
        case 'amazon-tr':
        case 'amazon-us':
        case 'amazon-uk':
        case 'amazon-de':
          return await this.testAmazonConnection(credentials);
        default:
          // Generic test - sadece credentials'ın dolu olduğunu kontrol et
          const hasAllRequired = marketplace.requiredFields
            .filter((f) => f.required)
            .every((f) => credentials[f.key]);

          if (hasAllRequired) {
            return { success: true, message: 'Bağlantı başarılı' };
          }
          return { success: false, message: 'Eksik kimlik bilgileri' };
      }
    } catch (error: any) {
      return { success: false, message: error.message || 'Bağlantı hatası' };
    }
  }

  // Trendyol bağlantı testi
  private async testTrendyolConnection(
    credentials: Record<string, string>,
  ): Promise<ConnectionTestResult> {
    // Gerçek implementasyonda Trendyol API'ye istek atılacak
    if (credentials.supplierId && credentials.apiKey && credentials.apiSecret) {
      // Simüle edilmiş başarılı bağlantı
      return { success: true, message: 'Trendyol bağlantısı başarılı' };
    }
    return {
      success: false,
      message: 'Trendyol kimlik bilgileri eksik veya hatalı',
    };
  }

  // Hepsiburada bağlantı testi
  private async testHepsiburadaConnection(
    credentials: Record<string, string>,
  ): Promise<ConnectionTestResult> {
    if (
      credentials.merchantId &&
      credentials.username &&
      credentials.password
    ) {
      return { success: true, message: 'Hepsiburada bağlantısı başarılı' };
    }
    return {
      success: false,
      message: 'Hepsiburada kimlik bilgileri eksik veya hatalı',
    };
  }

  // N11 bağlantı testi
  private async testN11Connection(
    credentials: Record<string, string>,
  ): Promise<ConnectionTestResult> {
    if (credentials.apiKey && credentials.apiSecret) {
      return { success: true, message: 'N11 bağlantısı başarılı' };
    }
    return {
      success: false,
      message: 'N11 kimlik bilgileri eksik veya hatalı',
    };
  }

  // Amazon bağlantı testi
  private async testAmazonConnection(
    credentials: Record<string, string>,
  ): Promise<ConnectionTestResult> {
    if (
      credentials.sellerId &&
      (credentials.refreshToken || credentials.mwsAuthToken) &&
      credentials.clientId &&
      credentials.clientSecret
    ) {
      return { success: true, message: 'Amazon bağlantısı başarılı' };
    }
    return {
      success: false,
      message: 'Amazon kimlik bilgileri eksik veya hatalı',
    };
  }

  // Entegrasyonu devre dışı bırak
  async disconnectMarketplace(
    tenantId: string,
    marketplaceId: string,
  ): Promise<{ success: boolean; message: string }> {
    const platformEnum = getPlatformEnum(marketplaceId);
    if (!platformEnum) {
      throw new BadRequestException('Desteklenmeyen pazaryeri');
    }

    const integration = await this.prisma.integration.findFirst({
      where: { tenantId, platform: platformEnum },
    });

    if (!integration) {
      throw new NotFoundException('Entegrasyon bulunamadı');
    }

    await this.prisma.integration.update({
      where: { id: integration.id },
      data: { isActive: false },
    });

    return {
      success: true,
      message: 'Entegrasyon başarıyla devre dışı bırakıldı',
    };
  }

  // Entegrasyonu tamamen sil
  async deleteIntegration(
    tenantId: string,
    marketplaceId: string,
  ): Promise<{ success: boolean; message: string }> {
    const platformEnum = getPlatformEnum(marketplaceId);
    if (!platformEnum) {
      throw new BadRequestException('Desteklenmeyen pazaryeri');
    }

    const integration = await this.prisma.integration.findFirst({
      where: { tenantId, platform: platformEnum },
    });

    if (!integration) {
      throw new NotFoundException('Entegrasyon bulunamadı');
    }

    await this.prisma.integration.delete({
      where: { id: integration.id },
    });

    return { success: true, message: 'Entegrasyon başarıyla silindi' };
  }

  // Senkronizasyon başlat
  async syncMarketplace(
    tenantId: string,
    marketplaceId: string,
    syncType: 'products' | 'orders' | 'inventory' | 'all',
  ): Promise<{ success: boolean; message: string; jobId?: string }> {
    const platformEnum = getPlatformEnum(marketplaceId);
    if (!platformEnum) {
      throw new BadRequestException('Desteklenmeyen pazaryeri');
    }

    const integration = await this.prisma.integration.findFirst({
      where: { tenantId, platform: platformEnum, isActive: true },
    });

    if (!integration) {
      throw new NotFoundException('Aktif entegrasyon bulunamadı');
    }

    // Senkronizasyon işi başlat (gerçek implementasyonda queue kullanılacak)
    const jobId = `sync_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // Son senkronizasyon zamanını güncelle - updatedAt kullanıyoruz
    await this.prisma.integration.update({
      where: { id: integration.id },
      data: { updatedAt: new Date() },
    });

    return {
      success: true,
      message: `${syncType} senkronizasyonu başlatıldı`,
      jobId,
    };
  }

  // Bölgeye göre pazaryerlerini getir
  async getMarketplacesByRegion(
    region: PlatformRegion,
  ): Promise<MarketplaceConfig[]> {
    return getMarketplacesByRegion(region);
  }

  // Plana göre erişilebilir pazaryerlerini getir
  async getAccessibleMarketplaces(
    plan: SubscriptionPlan,
  ): Promise<MarketplaceConfig[]> {
    return getMarketplacesByPlan(plan);
  }

  // İstatistikler
  async getIntegrationStats(tenantId: string): Promise<{
    total: number;
    active: number;
    inactive: number;
    byRegion: Record<string, number>;
  }> {
    const integrations = await this.prisma.integration.findMany({
      where: { tenantId },
    });

    const byRegion: Record<string, number> = {};
    let active = 0;
    let inactive = 0;

    for (const integration of integrations) {
      const marketplace = getMarketplaceById(integration.platform);
      if (marketplace) {
        byRegion[marketplace.region] = (byRegion[marketplace.region] || 0) + 1;
        if (integration.isActive) {
          active++;
        } else {
          inactive++;
        }
      }
    }

    return {
      total: integrations.length,
      active,
      inactive,
      byRegion,
    };
  }
}

import {
  Controller,
  Get,
  Post,
  Query,
  Res,
  Body,
  Headers,
  Param,
} from '@nestjs/common';
import type { Response } from 'express';
import { PrismaService } from '../../database/prisma.service';
import { EncryptionService } from '../../common/encryption.service';
import { Public } from '../auth/public.decorator';

/**
 * OAuth Callback Handler
 * Amazon SP-API, Hepsiburada ve diğer OAuth gerektiren platformlar için callback endpoint'leri
 */
@Controller('oauth')
export class OAuthController {
  constructor(
    private prisma: PrismaService,
    private encryption: EncryptionService,
  ) {}

  /**
   * Amazon Selling Partner API OAuth Callback
   * GET /oauth/amazon/callback?state={tenantId}&selling_partner_id={sellerId}&spapi_oauth_code={code}
   */
  @Public()
  @Get('amazon/callback')
  async amazonCallback(
    @Query('state') tenantId: string,
    @Query('selling_partner_id') sellerId: string,
    @Query('spapi_oauth_code') authCode: string,
    @Query('error') error: string,
    @Query('error_description') errorDescription: string,
    @Res() res: Response,
  ) {
    try {
      if (error) {
        console.error(`Amazon OAuth Error: ${error} - ${errorDescription}`);
        return res.redirect(
          `/dashboard/stores?error=amazon_auth_failed&message=${encodeURIComponent(errorDescription)}`,
        );
      }

      if (!tenantId || !sellerId || !authCode) {
        return res.redirect('/dashboard/stores?error=missing_params');
      }

      // Amazon'dan refresh token al
      const tokenResponse = await this.exchangeAmazonCodeForToken(
        authCode,
        sellerId,
      );

      if (!tokenResponse.refresh_token) {
        throw new Error('Refresh token alınamadı');
      }

      // Integration'ı güncelle veya oluştur
      const existing = await this.prisma.integration.findFirst({
        where: {
          tenantId,
          platform: 'AMAZON',
        },
      });

      if (existing) {
        await this.prisma.integration.update({
          where: {
            id: existing.id,
          },
          data: {
            apiSecret: this.encryption.encrypt(tokenResponse.refresh_token),
            isActive: true,
            apiExtra: {
              ...(existing.apiExtra as object),
              sellerId,
              accessToken: tokenResponse.access_token,
              expiresAt: Date.now() + tokenResponse.expires_in * 1000,
            },
          },
        });
      } else {
        await this.prisma.integration.create({
          data: {
            tenantId,
            platform: 'AMAZON',
            apiKey: this.encryption.encrypt(sellerId),
            apiSecret: this.encryption.encrypt(tokenResponse.refresh_token),
            isActive: true,
            apiExtra: {
              sellerId,
              accessToken: tokenResponse.access_token,
              expiresAt: Date.now() + tokenResponse.expires_in * 1000,
              marketplaceId: 'amazon-tr',
            },
          },
        });
      }

      return res.redirect('/dashboard/stores?success=amazon_connected');
    } catch (err) {
      console.error('Amazon OAuth callback error:', err);
      return res.redirect(
        `/dashboard/stores?error=amazon_callback_failed&message=${encodeURIComponent(err.message)}`,
      );
    }
  }

  /**
   * Hepsiburada OAuth Callback
   * GET /oauth/hepsiburada/callback?code={code}&state={tenantId}
   */
  @Public()
  @Get('hepsiburada/callback')
  async hepsiburadaCallback(
    @Query('code') code: string,
    @Query('state') tenantId: string,
    @Query('error') error: string,
    @Res() res: Response,
  ) {
    try {
      if (error) {
        return res.redirect(`/dashboard/stores?error=hepsiburada_auth_failed`);
      }

      if (!code || !tenantId) {
        return res.redirect('/dashboard/stores?error=missing_params');
      }

      // Hepsiburada'dan token al
      const tokenResponse = await this.exchangeHepsiburadaCodeForToken(code);

      // Merchant ID bilgisini çek
      const merchantInfo = await this.getHepsiburadaMerchantInfo(
        tokenResponse.access_token,
      );

      const existing = await this.prisma.integration.findFirst({
        where: { tenantId, platform: 'HEPSIBURADA' },
      });

      if (existing) {
        await this.prisma.integration.update({
          where: { id: existing.id },
          data: {
            apiKey: this.encryption.encrypt(tokenResponse.access_token),
            apiSecret: this.encryption.encrypt(tokenResponse.refresh_token),
            isActive: true,
            apiExtra: {
              merchantId: merchantInfo.merchantId,
              expiresAt: Date.now() + tokenResponse.expires_in * 1000,
            },
          },
        });
      } else {
        await this.prisma.integration.create({
          data: {
            tenantId,
            platform: 'HEPSIBURADA',
            apiKey: this.encryption.encrypt(tokenResponse.access_token),
            apiSecret: this.encryption.encrypt(tokenResponse.refresh_token),
            isActive: true,
            apiExtra: {
              merchantId: merchantInfo.merchantId,
              expiresAt: Date.now() + tokenResponse.expires_in * 1000,
              marketplaceId: 'hepsiburada',
            },
          },
        });
      }

      return res.redirect('/dashboard/stores?success=hepsiburada_connected');
    } catch (err) {
      console.error('Hepsiburada OAuth callback error:', err);
      return res.redirect(
        `/dashboard/stores?error=hepsiburada_callback_failed`,
      );
    }
  }

  /**
   * OAuth başlatma endpoint'i
   * Kullanıcıyı platformun OAuth sayfasına yönlendirir
   */
  @Public()
  @Get('init/:platform')
  async initiateOAuth(
    @Param('platform') platform: string,
    @Query('tenantId') tenantId: string,
    @Query('redirectUri') redirectUri: string,
    @Res() res: Response,
  ) {
    if (!tenantId) {
      return res.status(400).json({ error: 'tenantId required' });
    }

    let authUrl: string;

    switch (platform.toLowerCase()) {
      case 'amazon':
      case 'amazon-tr':
        authUrl = this.buildAmazonAuthUrl(tenantId, redirectUri);
        break;
      case 'hepsiburada':
        authUrl = this.buildHepsiburadaAuthUrl(tenantId, redirectUri);
        break;
      default:
        return res.status(400).json({ error: 'Unsupported platform' });
    }

    return res.redirect(authUrl);
  }

  // Private helper methods
  private async exchangeAmazonCodeForToken(code: string, sellerId: string) {
    const clientId = process.env.AMAZON_CLIENT_ID;
    const clientSecret = process.env.AMAZON_CLIENT_SECRET;

    const response = await fetch('https://api.amazon.com/auth/o2/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'authorization_code',
        code,
        client_id: clientId!,
        client_secret: clientSecret!,
        redirect_uri: `${process.env.API_URL}/oauth/amazon/callback`,
      }),
    });

    if (!response.ok) {
      throw new Error(`Token exchange failed: ${response.status}`);
    }

    return response.json();
  }

  private async exchangeHepsiburadaCodeForToken(code: string) {
    const clientId = process.env.HEPSIBURADA_CLIENT_ID;
    const clientSecret = process.env.HEPSIBURADA_CLIENT_SECRET;

    const response = await fetch('https://api.hepsiburada.com/oauth/token', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({
        grant_type: 'authorization_code',
        code,
        client_id: clientId!,
        client_secret: clientSecret!,
        redirect_uri: `${process.env.API_URL}/oauth/hepsiburada/callback`,
      }),
    });

    if (!response.ok) {
      throw new Error(`Hepsiburada token exchange failed: ${response.status}`);
    }

    return response.json();
  }

  private async getHepsiburadaMerchantInfo(accessToken: string) {
    const response = await fetch('https://api.hepsiburada.com/user/merchant', {
      headers: { Authorization: `Bearer ${accessToken}` },
    });

    if (!response.ok) {
      throw new Error('Failed to get merchant info');
    }

    return response.json();
  }

  private buildAmazonAuthUrl(tenantId: string, redirectUri?: string): string {
    const clientId = process.env.AMAZON_CLIENT_ID;
    const redirect =
      redirectUri || `${process.env.API_URL}/oauth/amazon/callback`;

    const params = new URLSearchParams({
      application_id: clientId!,
      state: tenantId,
      redirect_uri: redirect,
    });

    return `https://sellercentral.amazon.com/apps/authorize/consent?${params.toString()}`;
  }

  private buildHepsiburadaAuthUrl(
    tenantId: string,
    redirectUri?: string,
  ): string {
    const clientId = process.env.HEPSIBURADA_CLIENT_ID;
    const redirect =
      redirectUri || `${process.env.API_URL}/oauth/hepsiburada/callback`;

    const params = new URLSearchParams({
      client_id: clientId!,
      response_type: 'code',
      state: tenantId,
      redirect_uri: redirect,
      scope: 'read write',
    });

    return `https://api.hepsiburada.com/oauth/authorize?${params.toString()}`;
  }
}

import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';

export interface InventoryFilters {
  tenantId: string;
  status?: 'critical' | 'low' | 'ok';
  category?: string;
  search?: string;
  sortBy?: 'stock' | 'name' | 'trend';
  sortOrder?: 'asc' | 'desc';
  page?: number;
  limit?: number;
}

export class StockUpdateDto {
  quantity: number;
  type: 'add' | 'remove' | 'set';
  reason?: string;
}

@Injectable()
export class InventoryService {
  constructor(private prisma: PrismaService) {}

  async findAll(filters: InventoryFilters) {
    const {
      tenantId,
      status,
      category,
      search,
      sortBy = 'stock',
      sortOrder = 'asc',
      page = 1,
      limit = 20,
    } = filters;

    const where: any = { tenantId };

    if (category && category !== 'Tümü') {
      where.category = category;
    }
    if (search) {
      where.OR = [
        { title: { contains: search, mode: 'insensitive' } },
        { sku: { contains: search, mode: 'insensitive' } },
      ];
    }
    // Handle low/critical stock status filtering
    if (status === 'critical') {
      where.stock = { lt: 5 };
    } else if (status === 'low') {
      where.stock = { lt: 20, gte: 5 };
    }

    const [items, total] = await Promise.all([
      this.prisma.product.findMany({
        where,
        orderBy: { [sortBy === 'name' ? 'title' : sortBy]: sortOrder },
        skip: (page - 1) * limit,
        take: limit,
      }),
      this.prisma.product.count({ where }),
    ]);

    return {
      items,
      pagination: {
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit),
      },
    };
  }

  async getStats(tenantId: string) {
    const products = await this.prisma.product.findMany({
      where: { tenantId },
      include: { inventoryLogs: { take: 10, orderBy: { createdAt: 'desc' } } },
    });

    const totalValue = products.reduce(
      (sum, p) => sum + Number(p.price) * p.stock,
      0,
    );
    const critical = products.filter((p) => p.stock < 5).length;
    const low = products.filter((p) => p.stock < 20 && p.stock >= 5).length;

    return {
      totalProducts: products.length,
      totalValue,
      critical,
      low,
      ok: products.length - critical - low,
      alerts: products
        .filter((p) => p.stock < 10)
        .map((p) => ({
          id: p.id,
          sku: p.sku,
          name: p.title,
          stock: p.stock,
          minStock: 10,
          status: p.stock < 5 ? 'critical' : 'low',
        }))
        .slice(0, 5),
    };
  }

  async updateStock(id: string, tenantId: string, dto: StockUpdateDto) {
    const product = await this.prisma.product.findFirst({
      where: { id, tenantId },
    });
    if (!product) throw new Error('Ürün bulunamadı');

    const previousStock = product.stock;
    let newStock: number;
    switch (dto.type) {
      case 'add':
        newStock = previousStock + dto.quantity;
        break;
      case 'remove':
        newStock = Math.max(0, previousStock - dto.quantity);
        break;
      case 'set':
        newStock = dto.quantity;
        break;
      default:
        newStock = dto.quantity;
    }

    await this.prisma.product.update({
      where: { id },
      data: { stock: newStock },
    });

    await this.prisma.inventoryLog.create({
      data: {
        productId: id,
        type:
          dto.type === 'add'
            ? 'PURCHASE'
            : dto.type === 'remove'
              ? 'ADJUSTMENT'
              : 'ADJUSTMENT',
        change: dto.type === 'remove' ? -dto.quantity : dto.quantity,
        previousStock,
        newStock,
        note:
          dto.reason ||
          `Stok ${dto.type === 'add' ? 'eklendi' : dto.type === 'remove' ? 'çıkarıldı' : 'ayarlandı'}`,
      },
    });

    return {
      id,
      previousStock,
      newStock,
      type: dto.type,
      quantity: dto.quantity,
      reason: dto.reason,
      updatedAt: new Date(),
    };
  }

  async getAIPredictions(tenantId: string) {
    return {
      predictions: [
        {
          sku: 'SKU-001',
          name: 'iPhone 15 Pro Max Kılıf',
          currentStock: 3,
          predictedDemand: 25,
          daysUntilStockout: 2,
          recommendedOrder: 50,
          confidence: 0.92,
        },
        {
          sku: 'SKU-002',
          name: 'Samsung Galaxy Buds3 Pro',
          currentStock: 8,
          predictedDemand: 15,
          daysUntilStockout: 5,
          recommendedOrder: 30,
          confidence: 0.87,
        },
        {
          sku: 'SKU-003',
          name: 'Apple AirPods Pro 2',
          currentStock: 12,
          predictedDemand: 20,
          daysUntilStockout: 6,
          recommendedOrder: 40,
          confidence: 0.85,
        },
      ],
      insights: [
        { type: 'warning', message: '3 ürün önümüzdeki hafta tükenebilir' },
        {
          type: 'info',
          message: 'Aksesuar kategorisinde satışlar %15 artış gösteriyor',
        },
        {
          type: 'success',
          message: 'Stok devir hızınız sektör ortalamasının %12 üzerinde',
        },
      ],
    };
  }

  async bulkUpdate(tenantId: string, updates: { id: string; stock: number }[]) {
    const results: { id: string; newStock: number; updatedAt: Date }[] = [];
    let failed = 0;

    // Pre-fetch all products in a single query
    const allIds = updates.map((u) => u.id);
    const existingProducts = await this.prisma.product.findMany({
      where: { id: { in: allIds }, tenantId },
    });
    const productMap = new Map(existingProducts.map((p) => [p.id, p]));

    for (const u of updates) {
      try {
        const product = productMap.get(u.id);
        if (!product) {
          failed++;
          continue;
        }

        await this.prisma.product.update({
          where: { id: u.id },
          data: { stock: u.stock },
        });

        await this.prisma.inventoryLog.create({
          data: {
            productId: u.id,
            type: 'ADJUSTMENT',
            change: u.stock - product.stock,
            previousStock: product.stock,
            newStock: u.stock,
            note: 'Toplu stok güncellemesi',
          },
        });

        results.push({ id: u.id, newStock: u.stock, updatedAt: new Date() });
      } catch {
        failed++;
      }
    }

    return { success: results.length, failed, updates: results };
  }

  async getStockHistory(id: string, tenantId: string) {
    const product = await this.prisma.product.findFirst({
      where: { id, tenantId },
      select: { sku: true, title: true },
    });

    const logs = await this.prisma.inventoryLog.findMany({
      where: { productId: id },
      orderBy: { createdAt: 'desc' },
      take: 30,
    });

    return {
      sku: product?.sku || 'N/A',
      name: product?.title || 'Bilinmeyen Ürün',
      history: logs.map((log) => ({
        date: log.createdAt,
        type: (log.change ?? 0) > 0 ? 'in' : 'out',
        quantity: Math.abs(log.change ?? 0),
        balance: log.newStock,
        note: log.note || log.description || log.type,
      })),
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { PrismaService } from '../../database/prisma.service';

interface ForecastEntry {
  forecastDate: Date;
  predictedSales: number;
  confidenceScore: number;
  metadata: Record<string, unknown>;
}

@Injectable()
export class ForecastingService {
  private readonly logger = new Logger(ForecastingService.name);

  constructor(private prisma: PrismaService) {}

  async generateProductForecast(productId: string) {
    const product = await this.prisma.product.findUnique({
      where: { id: productId },
      select: {
        id: true,
        tenantId: true,
        title: true,
        price: true,
        stock: true,
      },
    });

    if (!product) return null;

    // Gather historical order data for this product (last 90 days)
    const ninetyDaysAgo = new Date(Date.now() - 90 * 86400000);
    const orderItems = await this.prisma.orderItem.findMany({
      where: {
        productId,
        order: {
          tenantId: product.tenantId,
          createdAt: { gte: ninetyDaysAgo },
        },
      },
      include: { order: { select: { createdAt: true } } },
      orderBy: { order: { createdAt: 'asc' } },
    });

    // Build daily sales series
    const dailySales = this.buildDailySeries(orderItems, ninetyDaysAgo);

    // Get price history to detect price-sensitivity
    const priceHistory = await this.prisma.priceHistory.findMany({
      where: {
        tenantId: product.tenantId,
        productId,
        createdAt: { gte: ninetyDaysAgo },
      },
      orderBy: { createdAt: 'asc' },
    });

    // Calculate base metrics from historical data
    const totalDays = dailySales.length || 1;
    const totalSales = dailySales.reduce((s, d) => s + d.sales, 0);
    const avgDailySales = totalSales / totalDays;

    // Trend: linear regression slope over daily sales
    const trend = this.calculateTrend(dailySales.map((d) => d.sales));

    // Seasonality: day-of-week factor
    const dowFactors = this.calculateDayOfWeekFactors(dailySales);

    // Price sensitivity factor
    const priceSensitivity = this.estimatePriceSensitivity(
      dailySales,
      priceHistory,
    );

    // Generate 14-day forecast using exponential smoothing + trend + seasonality
    const alpha = 0.3; // smoothing
    let level = avgDailySales;
    const forecasts: ForecastEntry[] = [];

    for (let i = 1; i <= 14; i++) {
      const forecastDate = new Date();
      forecastDate.setDate(forecastDate.getDate() + i);

      const dow = forecastDate.getDay();
      const seasonFactor = dowFactors[dow] || 1;
      const trendEffect = trend * i;

      // Exponential smoothing forecast
      const predicted = Math.max(
        0,
        Math.round((level + trendEffect) * seasonFactor),
      );

      // Confidence decreases with horizon
      const baseConfidence = totalSales > 0 ? 0.85 : 0.4;
      const horizonDecay = i * 0.025;
      const dataBoost = Math.min(0.1, totalDays * 0.001);
      const confidence = Math.max(
        0.2,
        Math.min(0.95, baseConfidence - horizonDecay + dataBoost),
      );

      forecasts.push({
        forecastDate,
        predictedSales: predicted,
        confidenceScore: +confidence.toFixed(3),
        metadata: {
          method: totalSales > 0 ? 'exponential_smoothing' : 'cold_start',
          trend: +trend.toFixed(4),
          seasonFactor: +seasonFactor.toFixed(3),
          avgDailySales: +avgDailySales.toFixed(2),
          historicalDays: totalDays,
          priceSensitivity: +priceSensitivity.toFixed(3),
        },
      });

      // Update level with simple exponential smoothing
      level = alpha * predicted + (1 - alpha) * level;
    }

    // Replace old forecasts
    await this.prisma.salesForecast.deleteMany({ where: { productId } });

    await this.prisma.salesForecast.createMany({
      data: forecasts.map((f) => ({
        productId,
        tenantId: product.tenantId,
        forecastDate: f.forecastDate,
        predictedSales: f.predictedSales,
        confidenceScore: f.confidenceScore,
        metadata: f.metadata as Prisma.InputJsonValue,
      })),
    });

    return {
      productId,
      forecastDays: 14,
      avgDailySales: +avgDailySales.toFixed(2),
      trend: trend > 0 ? 'increasing' : trend < -0.1 ? 'decreasing' : 'stable',
      trendValue: +trend.toFixed(4),
      totalHistoricalSales: totalSales,
      historicalDays: totalDays,
      forecasts: forecasts.map((f) => ({
        date: f.forecastDate.toISOString().slice(0, 10),
        predictedSales: f.predictedSales,
        confidence: f.confidenceScore,
      })),
      stockWarning:
        product.stock > 0 && product.stock < avgDailySales * 7
          ? `Mevcut stok (${product.stock}) tahmini 7 gunluk satisi karsilamiyor`
          : null,
    };
  }

  async getForecast(productId: string) {
    return this.prisma.salesForecast.findMany({
      where: { productId },
      orderBy: { forecastDate: 'asc' },
    });
  }

  // ==================== PRIVATE HELPERS ====================

  private buildDailySeries(
    orderItems: Array<{ quantity: number; order: { createdAt: Date } }>,
    startDate: Date,
  ): Array<{ date: string; sales: number; dow: number }> {
    const map = new Map<string, number>();

    // Initialize all days with 0
    const now = new Date();
    const cursor = new Date(startDate);
    while (cursor <= now) {
      map.set(cursor.toISOString().slice(0, 10), 0);
      cursor.setDate(cursor.getDate() + 1);
    }

    // Fill actual sales
    for (const item of orderItems) {
      const day = item.order.createdAt.toISOString().slice(0, 10);
      map.set(day, (map.get(day) || 0) + item.quantity);
    }

    return Array.from(map.entries())
      .sort()
      .map(([date, sales]) => ({
        date,
        sales,
        dow: new Date(date).getDay(),
      }));
  }

  private calculateTrend(values: number[]): number {
    const n = values.length;
    if (n < 7) return 0;

    // Simple linear regression: y = a + bx
    let sumX = 0,
      sumY = 0,
      sumXY = 0,
      sumXX = 0;
    for (let i = 0; i < n; i++) {
      sumX += i;
      sumY += values[i];
      sumXY += i * values[i];
      sumXX += i * i;
    }

    const denom = n * sumXX - sumX * sumX;
    if (denom === 0) return 0;

    return (n * sumXY - sumX * sumY) / denom;
  }

  private calculateDayOfWeekFactors(
    series: Array<{ sales: number; dow: number }>,
  ): number[] {
    const sums = new Array(7).fill(0);
    const counts = new Array(7).fill(0);

    for (const entry of series) {
      sums[entry.dow] += entry.sales;
      counts[entry.dow] += 1;
    }

    const overallAvg =
      series.length > 0
        ? series.reduce((s, e) => s + e.sales, 0) / series.length
        : 1;

    if (overallAvg === 0) return new Array(7).fill(1);

    return sums.map((sum, i) => {
      if (counts[i] === 0) return 1;
      const dayAvg = sum / counts[i];
      return dayAvg / overallAvg;
    });
  }

  private estimatePriceSensitivity(
    salesSeries: Array<{ date: string; sales: number }>,
    priceHistory: Array<{ price: Prisma.Decimal | number; createdAt: Date }>,
  ): number {
    if (priceHistory.length < 2 || salesSeries.length < 14) return 0;

    // Simple: check if sales changed after a price change
    let totalElasticity = 0;
    let measurements = 0;

    for (let i = 1; i < priceHistory.length; i++) {
      const oldPrice = Number(priceHistory[i - 1].price);
      const newPrice = Number(priceHistory[i].price);
      if (oldPrice === 0 || newPrice === oldPrice) continue;

      const priceChangeDate = priceHistory[i].createdAt
        .toISOString()
        .slice(0, 10);
      const beforeIdx = salesSeries.findIndex(
        (s) => s.date === priceChangeDate,
      );
      if (beforeIdx < 7) continue;

      const beforeAvg = this.avgSlice(salesSeries, beforeIdx - 7, beforeIdx);
      const afterAvg = this.avgSlice(
        salesSeries,
        beforeIdx,
        Math.min(beforeIdx + 7, salesSeries.length),
      );

      if (beforeAvg === 0) continue;

      const pctPriceChange = (newPrice - oldPrice) / oldPrice;
      const pctSalesChange = (afterAvg - beforeAvg) / beforeAvg;

      if (pctPriceChange !== 0) {
        totalElasticity += Math.abs(pctSalesChange / pctPriceChange);
        measurements += 1;
      }
    }

    return measurements > 0 ? totalElasticity / measurements : 0;
  }

  private avgSlice(
    series: Array<{ sales: number }>,
    from: number,
    to: number,
  ): number {
    const slice = series.slice(from, to);
    if (slice.length === 0) return 0;
    return slice.reduce((s, e) => s + e.sales, 0) / slice.length;
  }
}

