      where: { competitorId, marketplaceId },
      select: { id: true },
    });

    if (existing) {
      return this.prisma.competitorProduct.update({
        where: { id: existing.id },
        data: {
          title: String(data.title || 'Isimsiz Urun'),
          url: data.url ? String(data.url) : null,
