  // ==================== PRICING ANALYSIS ====================
  async getPricingAnalysis(tenantId: string) {
    if (!tenantId) {
      throw new BadRequestException('tenantId zorunludur');
    }

    const products = await this.prisma.product.findMany({
      where: { tenantId },
      orderBy: { updatedAt: 'desc' },
      take: 200,
    });

    const productIds = products.map((p) => p.id);
    const competitorProducts = await this.prisma.competitorProduct.findMany({
      where: {
        productId: { in: productIds },
        competitor: { tenantId, isActive: true },
      },
      include: {
        competitor: { select: { id: true, name: true, platform: true } },
      },
      orderBy: { lastCheckedAt: 'desc' },
    });

    const byProduct = new Map<string, typeof competitorProducts>();
    for (const cp of competitorProducts) {
      if (!cp.productId) continue;
      const list = byProduct.get(cp.productId) || [];
      list.push(cp);
      byProduct.set(cp.productId, list);
    }

    const rows = products.map((product) => {
      const comps = byProduct.get(product.id) || [];
      const competitorPrices = comps
        .map((c) => Number(c.price))
        .filter((v) => Number.isFinite(v) && v > 0);
      const avgCompetitorPrice = competitorPrices.length
        ? competitorPrices.reduce((s, p) => s + p, 0) / competitorPrices.length
        : 0;
      const minCompetitorPrice = competitorPrices.length
        ? Math.min(...competitorPrices)
        : 0;
      const myPrice = Number(product.price);
      const pricePosition = this.getPricePosition(myPrice, avgCompetitorPrice);
      const recommended = this.calculateRecommendedPrice(
        myPrice,
        avgCompetitorPrice,
        minCompetitorPrice,
        Number(product.costPrice ?? 0),
      );

      return {
        id: product.id,
        name: product.title,
        currentPrice: myPrice,
        recommendedPrice: recommended,
        competitorAvgPrice: avgCompetitorPrice,
        minCompetitorPrice,
        competitorCount: comps.length,
        pricePosition,
        margin: this.calculateMargin(myPrice, Number(product.costPrice ?? 0)),
        demandElasticity: this.estimateElasticity(pricePosition, comps.length),
        lastUpdated: product.updatedAt.toISOString(),
      };
    });

    const covered = rows.filter((r) => r.competitorCount > 0);
    const optimized = covered.filter((r) => r.pricePosition === 'at').length;
    const needsAttention = covered.filter(
      (r) => r.pricePosition !== 'at',
    ).length;
    const competitive = covered.filter(
      (r) => r.pricePosition === 'below',
    ).length;

    const coverageRate =
      products.length > 0 ? covered.length / products.length : 0;
    const optimalRate = covered.length > 0 ? optimized / covered.length : 0;
    const overallScore = Math.round(
      (coverageRate * 40 + optimalRate * 60) * 100,
    );

    return {
      overallScore,
      totalProducts: products.length,
      coveredProducts: covered.length,
      optimized,
      needsAttention,
      competitive,
      products: rows.slice(0, 100),
      rules: [
        {
          id: 'rule-competitive-band',
          name: 'Rakip ortalamasina yakin fiyat',
          type: 'competitive',
          isActive: true,
          affectedProducts: covered.length,
        },
        {
          id: 'rule-floor-margin',
          name: 'Maliyet uzeri guvenli marj',
          type: 'margin',
          isActive: true,
          affectedProducts: rows.length,
        },
      ],
    };
  }

  async getCompetitorPrices(tenantId: string, productId: string) {
    if (!tenantId || !productId) {
      throw new BadRequestException('tenantId ve productId zorunludur');
    }

    const product = await this.prisma.product.findFirst({
      where: { id: productId, tenantId },
      select: { id: true, title: true, price: true, costPrice: true },
    });

    if (!product) {
      throw new NotFoundException('Urun bulunamadi');
    }

    const competitorProducts = await this.prisma.competitorProduct.findMany({
      where: {
        productId,
        competitor: { tenantId, isActive: true },
      },
      include: {
        competitor: {
          select: { id: true, name: true, platform: true },
        },
      },
      orderBy: { lastCheckedAt: 'desc' },
    });

    const cpIds = competitorProducts.map((cp) => cp.id);
    const history = await this.prisma.priceHistory.findMany({
      where: {
        tenantId,
        OR: [
          { productId },
          cpIds.length > 0 ? { competitorProductId: { in: cpIds } } : undefined,
        ].filter(Boolean) as Prisma.PriceHistoryWhereInput[],
      },
      orderBy: { createdAt: 'asc' },
      take: 90,
    });

    const competitorPrices = competitorProducts.map((cp) => Number(cp.price));
    const avg = competitorPrices.length
      ? competitorPrices.reduce((s, p) => s + p, 0) / competitorPrices.length
      : 0;
    const min = competitorPrices.length ? Math.min(...competitorPrices) : 0;
    const suggestedPrice = this.calculateRecommendedPrice(
      Number(product.price),
      avg,
      min,
      Number(product.costPrice ?? 0),
    );

    const groupedByDay = new Map<
      string,
      { myPrice: number[]; competitor: number[] }
    >();
    for (const item of history) {
      const day = item.createdAt.toISOString().slice(0, 10);
      const entry = groupedByDay.get(day) || { myPrice: [], competitor: [] };
      if (item.productId === productId) {
        entry.myPrice.push(Number(item.price));
      } else {
        entry.competitor.push(Number(item.price));
      }
      groupedByDay.set(day, entry);
    }

    const priceHistory = Array.from(groupedByDay.entries()).map(
      ([date, values]) => ({
        date,
        myPrice: values.myPrice.length
          ? this.avg(values.myPrice)
          : Number(product.price),
        avgCompetitorPrice: values.competitor.length
          ? this.avg(values.competitor)
          : avg,
        minCompetitorPrice: values.competitor.length
          ? Math.min(...values.competitor)
          : min,
      }),
    );

    return {
      productId,
      currentPrice: Number(product.price),
      competitors: competitorProducts.map((cp) => ({
        id: cp.id,
        name: cp.competitor.name,
        platform: cp.competitor.platform,
        price: Number(cp.price),
        lastChecked: cp.lastCheckedAt.toISOString(),
        inStock: (cp.stock ?? 0) > 0,
        rating: Number(cp.rating ?? 0),
        reviewCount: cp.reviewCount,
      })),
      priceHistory,
      recommendation: {
        suggestedPrice,
        reason:
          avg > 0
            ? `Rakip ortalama fiyati ${avg.toFixed(2)} TRY seviyesinde.`
            : 'Rakip ortalama fiyati henuz olusmadi.',
        expectedImpact: this.expectedImpact(
          Number(product.price),
          suggestedPrice,
        ),
        confidence: this.recommendationConfidence(
          competitorProducts.length,
          history.length,
        ),
      },
    };
  }

  async getCompetitorGap(tenantId: string, productId: string) {
    const detail = await this.getCompetitorPrices(tenantId, productId);
    const myPrice = detail.currentPrice;
    const competitorAvg = this.avg(detail.competitors.map((c) => c.price));
    const gapPercent =
      competitorAvg > 0 ? ((myPrice - competitorAvg) / competitorAvg) * 100 : 0;

    const stockAdvantageCount = detail.competitors.filter(
      (c) => !c.inStock,
    ).length;
    const trustAvg = detail.competitors.length
      ? this.avg(detail.competitors.map((c) => c.rating))
      : 0;

    return {
      productId,
      gap: {
        myPrice,
        competitorAvg,
        gapPercent: +gapPercent.toFixed(2),
        position: this.getPricePosition(myPrice, competitorAvg),
      },
      marketSignals: {
        competitorCount: detail.competitors.length,
        outOfStockCompetitors: stockAdvantageCount,
        competitorRatingAvg: +trustAvg.toFixed(2),
      },
      actionPlan: this.generateActionPlan(
        gapPercent,
        stockAdvantageCount,
        trustAvg,
      ),
    };
  }

  async getCompetitorRecommendations(tenantId: string, productId: string) {
    const gap = await this.getCompetitorGap(tenantId, productId);
    const actions = gap.actionPlan.map((text, index) => ({
      id: `rec-${index + 1}`,
      text,
      priority: index === 0 ? 'high' : 'medium',
    }));

    return {
      productId,
      score: this.recommendationScoreFromGap(gap.gap.gapPercent),
      actions,
      summary: {
        priceGapPercent: gap.gap.gapPercent,
        competitorCount: gap.marketSignals.competitorCount,
        outOfStockCompetitors: gap.marketSignals.outOfStockCompetitors,
      },
    };
  }

  async getCompetitorAlerts(tenantId: string, priceGapPercent = 5) {
    if (!tenantId) {
      throw new BadRequestException('tenantId zorunludur');
    }

    const products = await this.prisma.product.findMany({
      where: { tenantId },
      select: {
        id: true,
        title: true,
        price: true,
        stock: true,
        costPrice: true,
      },
      take: 300,
    });

    const productIds = products.map((p) => p.id);
    const competitorProducts = await this.prisma.competitorProduct.findMany({
      where: {
        productId: { in: productIds },
        competitor: { tenantId, isActive: true },
      },
      include: { competitor: { select: { name: true, platform: true } } },
      orderBy: { lastCheckedAt: 'desc' },
    });

    const byProduct = new Map<string, typeof competitorProducts>();
    for (const row of competitorProducts) {
      if (!row.productId) continue;
      const list = byProduct.get(row.productId) || [];
      list.push(row);
      byProduct.set(row.productId, list);
    }

    const alerts: Array<Record<string, unknown>> = [];

    for (const product of products) {
      const comps = byProduct.get(product.id) || [];
      if (!comps.length) continue;

      const compPrices = comps
        .map((c) => Number(c.price))
        .filter((n) => Number.isFinite(n) && n > 0);
      if (!compPrices.length) continue;

      const myPrice = Number(product.price);
      const avgPrice = this.avg(compPrices);
      const gapPct = avgPrice > 0 ? ((myPrice - avgPrice) / avgPrice) * 100 : 0;

      if (gapPct > priceGapPercent) {
        alerts.push({
          type: 'price_gap_high',
          severity: 'high',
          productId: product.id,
          productTitle: product.title,
          details: `Urun fiyati rakip ortalamasindan %${gapPct.toFixed(2)} yuksek`,
          myPrice,
          competitorAvgPrice: +avgPrice.toFixed(2),
        });
      }

      if (product.stock <= 0 && comps.some((c) => (c.stock ?? 0) > 0)) {
        alerts.push({
          type: 'stockout_vs_competitor',
          severity: 'high',
          productId: product.id,
          productTitle: product.title,
          details: 'Bizde stok yok, rakipte stok var',
        });
      }

      const costPrice = Number(product.costPrice ?? 0);
      if (costPrice > 0 && myPrice < costPrice * 1.05) {
        alerts.push({
          type: 'low_margin_risk',
          severity: 'medium',
          productId: product.id,
          productTitle: product.title,
          details: 'Fiyat maliyete cok yakin, marj riski var',
          myPrice,
          estimatedCost: costPrice,
        });
      }
    }

    if (alerts.length > 0) {
      await this.prisma.activityLog.create({
        data: {
          tenantId,
          action: 'competitor.alerts.generated',
          resource: 'competitor',
          details: {
            alertCount: alerts.length,
            highSeverityCount: alerts.filter((a) => a.severity === 'high')
              .length,
          } as Prisma.InputJsonValue,
        },
      });

      await this.dispatchAlertsWebhook(tenantId, alerts, priceGapPercent);
    }

    return {
      tenantId,
      generatedAt: new Date().toISOString(),
      threshold: priceGapPercent,
      alertCount: alerts.length,
      alerts,
    };
  }

  async generateCompetitorSummaryReport(tenantId: string, days = 7) {
    if (!tenantId) {
      throw new BadRequestException('tenantId zorunludur');
    }

    const safeDays = Math.max(1, Math.min(30, days));
    const startDate = new Date(Date.now() - safeDays * 86400000);

    const competitors = await this.prisma.competitor.findMany({
      where: { tenantId, isActive: true },
      include: {
        _count: { select: { products: true } },
      },
    });

    const history = await this.prisma.priceHistory.findMany({
      where: {
        tenantId,
        createdAt: { gte: startDate },
        competitorProductId: { not: null },
      },
      orderBy: { createdAt: 'asc' },
    });

    const avgCompetitorPrice = history.length
      ? this.avg(history.map((h) => Number(h.price)))
      : 0;

    const summary = {
      tenantId,
      periodDays: safeDays,
      totalCompetitors: competitors.length,
      totalTrackedProducts: competitors.reduce(
        (sum, c) => sum + c._count.products,
        0,
      ),
      totalPriceSamples: history.length,
      averageCompetitorPrice: +avgCompetitorPrice.toFixed(2),
      byPlatform: this.groupCompetitorByPlatform(
        competitors.map((c) => c.platform),
      ),
      generatedAt: new Date().toISOString(),
    };

    const report = await this.prisma.report.create({
      data: {
        tenantId,
        name: `Rakip Ozet Raporu (${safeDays} gun)`,
        type: 'competitor-summary',
        description: 'Rakip takip ozet metrikleri',
        parameters: { days: safeDays } as Prisma.InputJsonValue,
        data: summary as unknown as Prisma.InputJsonValue,
        status: 'completed',
        generatedAt: new Date(),
        format: 'json',
      },
    });

    return {
      success: true,
      reportId: report.id,
      summary,
    };
  }

  async applyPriceRecommendation(
    tenantId: string,
    productId: string,
    newPrice: number,
  ) {
    if (!tenantId || !productId) {
      throw new BadRequestException('tenantId ve productId zorunludur');
    }
    if (!Number.isFinite(newPrice) || newPrice <= 0) {
      throw new BadRequestException(
        'newPrice gecerli bir pozitif sayi olmalidir',
      );
    }

    const product = await this.prisma.product.findFirst({
      where: { id: productId, tenantId },
      select: { id: true, price: true },
    });

    if (!product) {
      throw new NotFoundException('Urun bulunamadi');
    }

    const updated = await this.prisma.product.update({
      where: { id: productId },
      data: { price: newPrice },
    });

    await this.prisma.priceHistory.create({
      data: {
        tenantId,
        productId,
        price: newPrice,
        platform: Platform.OTHER,
      },
    });

    await this.prisma.activityLog.create({
      data: {
        tenantId,
        action: 'pricing.recommendation.applied',
        resource: 'product',
        resourceId: productId,
        details: {
          oldPrice: Number(product.price),
          newPrice,
        } as Prisma.InputJsonValue,
      },
    });

    return {
      success: true,
      productId,
      newPrice: Number(updated.price),
      message: `Fiyat ${newPrice} olarak guncellendi`,
      updatedAt: new Date().toISOString(),
    };
  }

  async runCompetitorSnapshot(
    tenantId: string,
    options?: { platform?: Platform; limitPerStore?: number },
  ) {
    if (!tenantId) {
      throw new BadRequestException('tenantId zorunludur');
    }

    const limitPerStore = Math.max(
      1,
      Math.min(30, options?.limitPerStore ?? 10),
    );
    const supportedPlatforms: Platform[] = [
      Platform.TRENDYOL,
      Platform.HEPSIBURADA,
      Platform.N11,
      Platform.CICEKSEPETI,
    ];

    const competitors = await this.prisma.competitor.findMany({
      where: {
        tenantId,
        isActive: true,
        platform: options?.platform || undefined,
        storeUrl: { not: null },
      },
      orderBy: { updatedAt: 'desc' },
    });

    let scannedCompetitors = 0;
    let scannedProducts = 0;
    let createdProducts = 0;
    let updatedProducts = 0;
    let historyWrites = 0;
    const warnings: string[] = [];

    const tenantProducts = await this.prisma.product.findMany({
      where: { tenantId },
      select: { id: true, title: true, sku: true },
    });

    for (const competitor of competitors) {
      if (!supportedPlatforms.includes(competitor.platform)) {
        warnings.push(`${competitor.name}: platform su an desteklenmiyor`);
        continue;
      }
      if (!competitor.storeUrl) {
        warnings.push(`${competitor.name}: storeUrl eksik`);
        continue;
      }

      const storeId = this.extractStoreIdFromUrl(
        competitor.storeUrl,
        competitor.platform,
      );
      if (!storeId) {
        warnings.push(`${competitor.name}: storeId parse edilemedi`);
        continue;
      }

      scannedCompetitors += 1;

      let products: Array<Record<string, unknown>> = [];
      try {
        const raw = (await this.marketplaceService.getStoreProducts(
          competitor.platform as unknown as any,
          storeId,
          limitPerStore,
        )) as unknown;
        products = Array.isArray(raw)
          ? (raw as Array<Record<string, unknown>>)
          : [];
      } catch (error) {
        warnings.push(
          `${competitor.name}: urun cekilemedi (${(error as Error).message})`,
        );
        continue;
      }

      for (const item of products) {
        scannedProducts += 1;
        const marketplaceId = String(
          item.productId ?? item.id ?? item.merchantSku ?? '',
        ).trim();
        if (!marketplaceId) continue;

        const title = String(item.title ?? 'Isimsiz Urun');
        const productId = this.matchOurProduct(
          tenantProducts,
          title,
          String(item.sku ?? item.merchantSku ?? ''),
        );
        const price = this.safeNumber(item.salePrice ?? item.price);

        const existing = await this.prisma.competitorProduct.findFirst({
          where: {
            competitorId: competitor.id,
            marketplaceId,
          },
          select: { id: true },
        });

        if (existing) {
          await this.prisma.competitorProduct.update({
            where: { id: existing.id },
            data: {
              productId,
              title,
              price,
              stock: this.safeNullableInt(item.stockCount ?? item.stock),
              rating: this.safeDecimal(item.rating),
              reviewCount: this.safeInt(item.reviewCount, 0),
              url: item.url ? String(item.url) : null,
              lastCheckedAt: new Date(),
            },
          });
          updatedProducts += 1;

          await this.prisma.priceHistory.create({
            data: {
              tenantId,
              competitorProductId: existing.id,
              price,
              platform: competitor.platform,
            },
          });
          historyWrites += 1;
        } else {
          const created = await this.prisma.competitorProduct.create({
            data: {
              competitorId: competitor.id,
              productId,
              marketplaceId,
              title,
              price,
              stock: this.safeNullableInt(item.stockCount ?? item.stock),
              rating: this.safeDecimal(item.rating),
              reviewCount: this.safeInt(item.reviewCount, 0),
              url: item.url ? String(item.url) : null,
            },
          });
          createdProducts += 1;

          await this.prisma.priceHistory.create({
            data: {
              tenantId,
              competitorProductId: created.id,
              price,
              platform: competitor.platform,
            },
          });
          historyWrites += 1;
        }
      }
    }

    const summary = {
      tenantId,
      scannedCompetitors,
      scannedProducts,
      createdProducts,
      updatedProducts,
      historyWrites,
      warnings,
      completedAt: new Date().toISOString(),
    };

    await this.prisma.report.create({
      data: {
        tenantId,
        name: 'Rakip Snapshot Raporu',
        type: 'competitor',
        description: 'Gunluk rakip urun ve fiyat snapshot ozeti',
        parameters: {
          platform: options?.platform || null,
          limitPerStore,
        } as Prisma.InputJsonValue,
        data: summary as unknown as Prisma.InputJsonValue,
        status: 'completed',
        generatedAt: new Date(),
        format: 'json',
      },
    });

    await this.prisma.activityLog.create({
      data: {
        tenantId,
        action: 'competitor.snapshot.run',
        resource: 'competitor',
        details: summary as unknown as Prisma.InputJsonValue,
      },
    });

    return summary;
  }

  private safeInt(value: unknown, fallback = 0): number {
    const num = Number(value);
    if (!Number.isFinite(num)) return fallback;
    return Math.max(0, Math.round(num));
  }

  private safeNullableInt(value: unknown): number | null {
    if (value === null || value === undefined || value === '') {
      return null;
    }
    return this.safeInt(value, 0);
  }

  private safeNumber(value: unknown, fallback = 0): number {
    const num = Number(value);
    return Number.isFinite(num) ? num : fallback;
  }

  private safeDecimal(value: unknown, fallback?: number): Prisma.Decimal {
    const raw = this.safeNumber(
      value,
      Number.isFinite(fallback as number) ? (fallback as number) : 0,
    );
    return new Prisma.Decimal(raw);
  }

  private avg(values: number[]): number {
    if (!values.length) return 0;
    return values.reduce((sum, n) => sum + n, 0) / values.length;
  }

  private getPricePosition(
    myPrice: number,
    competitorAvg: number,
  ): PricePosition {
    if (competitorAvg <= 0) return 'at';
    const ratio = ((myPrice - competitorAvg) / competitorAvg) * 100;
    if (ratio <= -3) return 'below';
    if (ratio >= 3) return 'above';
    return 'at';
  }

  private calculateMargin(price: number, costPrice: number): number {
    if (costPrice <= 0 || price <= 0) return 0;
    return +(((price - costPrice) / price) * 100).toFixed(2);
  }

  private calculateRecommendedPrice(
    myPrice: number,
    competitorAvg: number,
    minCompetitorPrice: number,
    costPrice: number,
  ): number {
    if (competitorAvg <= 0) return +myPrice.toFixed(2);

    let candidate = competitorAvg * 0.98;
    if (minCompetitorPrice > 0) {
      candidate = Math.max(candidate, minCompetitorPrice * 0.995);
    }
    if (costPrice > 0) {
      candidate = Math.max(candidate, costPrice * 1.15);
    }

    return +candidate.toFixed(2);
  }

  private estimateElasticity(
    position: PricePosition,
    competitorCount: number,
  ): number {
    const base = position === 'above' ? 1.6 : position === 'at' ? 1.1 : 0.8;
    const marketPressure = Math.min(0.9, competitorCount * 0.08);
    return +(base + marketPressure).toFixed(2);
  }

  private expectedImpact(currentPrice: number, suggestedPrice: number): string {
    if (currentPrice <= 0) return 'N/A';
    const diffPct = ((suggestedPrice - currentPrice) / currentPrice) * 100;
    if (diffPct < -2) return 'Donusum artisi beklenir';
    if (diffPct > 2) return 'Marj artisi, donusum takibi onerilir';
    return 'Dengeli etki beklenir';
  }

  private recommendationConfidence(
    competitorCount: number,
    historyCount: number,
  ): number {
    const compScore = Math.min(60, competitorCount * 12);
    const histScore = Math.min(40, Math.floor(historyCount / 3));
    return Math.max(35, compScore + histScore);
  }

  private recommendationScoreFromGap(gapPercent: number): number {
    const normalized = Math.max(0, 100 - Math.abs(gapPercent) * 6);
    return Math.round(normalized);
  }

  private async dispatchAlertsWebhook(
    tenantId: string,
    alerts: Array<Record<string, unknown>>,
    threshold: number,
  ): Promise<void> {
    const webhookUrl = process.env.COMPETITOR_ALERT_WEBHOOK_URL;
    if (!webhookUrl) {
      return;
    }

    try {
      const generatedAt = new Date().toISOString();
      const payload = {
        tenantId,
        generatedAt,
        threshold,
        alertCount: alerts.length,
        alerts,
      };
      const body = JSON.stringify(payload);
      const timestamp = String(Date.now());
      const secret = process.env.COMPETITOR_ALERT_WEBHOOK_SECRET;

      const headers: Record<string, string> = {
        'Content-Type': 'application/json',
        'User-Agent': 'PazarYonetimi/1.0',
        'X-PazarYonetimi-Timestamp': timestamp,
      };

      if (secret) {
        headers['X-PazarYonetimi-Signature'] = this.buildWebhookSignature(
          body,
          timestamp,
          secret,
        );
        headers['X-PazarYonetimi-Signature-Alg'] = 'sha256';
      }

      const response = await fetch(webhookUrl, {
        method: 'POST',
        headers,
        body,
      });

      if (!response.ok) {
        this.logger.warn(
          `Competitor alert webhook failed (${response.status}) tenant=${tenantId}`,
        );
      }
    } catch (error) {
      this.logger.warn(
        `Competitor alert webhook error tenant=${tenantId}: ${(error as Error).message}`,
      );
    }
  }

  private buildWebhookSignature(
    body: string,
    timestamp: string,
    secret: string,
  ): string {
    const payload = `${timestamp}.${body}`;
    return createHmac('sha256', secret).update(payload).digest('hex');
  }

  private groupCompetitorByPlatform(platforms: Platform[]) {
    const map = new Map<string, number>();
    for (const p of platforms) {
      map.set(p, (map.get(p) || 0) + 1);
    }
    return Array.from(map.entries()).map(([platform, count]) => ({
      platform,
      count,
    }));
  }

  private generateActionPlan(
    gapPercent: number,
    outOfStockCompetitors: number,
    trustAvg: number,
  ): string[] {
    const actions: string[] = [];

    if (gapPercent > 5) {
      actions.push(
        'Fiyati rakip ortalamasina yaklastir ve 7 gun A/B test uygula.',
      );
    } else if (gapPercent < -8) {
      actions.push('Marj kontrolu yap; fiyatta kademeli artis firsati var.');
    } else {
      actions.push(
        'Mevcut fiyat bandi korunabilir, listeleme kalitesine odaklan.',
      );
    }

    if (outOfStockCompetitors > 0) {
      actions.push(
        'Rakip stok disi iken kampanya butcesini gecici olarak artir.',
      );
    }

    if (trustAvg > 0 && trustAvg < 4.2) {
      actions.push(
        'Yorum toplama ve satis sonrasi iletisim akisini guclendir.',
      );
    }

    if (actions.length === 0) {
      actions.push(
        'Haftalik rakip snapshot ve fiyat alarmi takibine devam et.',
      );
    }

    return actions;
  }

  private extractStoreIdFromUrl(
    url: string,
    platform: Platform,
  ): string | null {
    try {
      const urlObj = new URL(url.startsWith('http') ? url : `https://${url}`);
      const pathname = urlObj.pathname;

      if (platform === Platform.TRENDYOL) {
        const match = pathname.match(/\/magaza\/([^/]+)/);
        if (!match) return null;
        const parts = match[1].split('-m-');
        if (parts.length > 1) return parts[1];
        return match[1].split('-').pop() || null;
      }

      if (platform === Platform.HEPSIBURADA) {
        const match = pathname.match(/\/magaza\/([^/?]+)/);
        return match ? match[1] : null;
      }

      return null;
    } catch {
      return null;
    }
  }

  private matchOurProduct(
    products: Array<{ id: string; title: string; sku: string }>,
    competitorTitle: string,
    competitorSku: string,
  ): string | null {
    const normalizedSku = competitorSku.trim().toLowerCase();
    if (normalizedSku) {
      const skuMatch = products.find(
        (p) => p.sku.trim().toLowerCase() === normalizedSku,
      );
      if (skuMatch) return skuMatch.id;
    }

    const normalizedTitle = competitorTitle.trim().toLowerCase();
    if (!normalizedTitle) return null;

    const titleMatch = products.find((p) => {
      const own = p.title.trim().toLowerCase();
      return (
        own.includes(normalizedTitle.slice(0, 24)) ||
        normalizedTitle.includes(own.slice(0, 24))
      );
    });

    return titleMatch?.id || null;
  }

  // ==================== DELETE OPERATIONS ====================
  async deleteCompetitor(tenantId: string, competitorId: string) {
    if (!tenantId || !competitorId) {
      throw new BadRequestException('tenantId ve competitorId zorunludur');
    }

    const competitor = await this.prisma.competitor.findFirst({
      where: { id: competitorId, tenantId },
      select: { id: true, name: true },
    });
    if (!competitor) throw new NotFoundException('Rakip bulunamadi');

    // Delete related competitor products' price history first
    const cpIds = await this.prisma.competitorProduct.findMany({
      where: { competitorId },
      select: { id: true },
    });

    if (cpIds.length > 0) {
      await this.prisma.priceHistory.deleteMany({
        where: { competitorProductId: { in: cpIds.map((c) => c.id) } },
      });
      await this.prisma.competitorProduct.deleteMany({
        where: { competitorId },
      });
    }

    await this.prisma.competitor.delete({ where: { id: competitorId } });

    await this.prisma.activityLog.create({
      data: {
        tenantId,
        action: 'competitor.deleted',
        resource: 'competitor',
        resourceId: competitorId,
        details: {
          name: competitor.name,
          deletedProducts: cpIds.length,
        } as Prisma.InputJsonValue,
      },
    });

    return { success: true, deletedProducts: cpIds.length };
  }

  async deleteCompetitorProduct(tenantId: string, competitorProductId: string) {
    if (!tenantId || !competitorProductId) {
      throw new BadRequestException(
        'tenantId ve competitorProductId zorunludur',
      );
    }

    const cp = await this.prisma.competitorProduct.findFirst({
      where: { id: competitorProductId, competitor: { tenantId } },
      select: { id: true, title: true },
    });
    if (!cp) throw new NotFoundException('Rakip urun bulunamadi');

    await this.prisma.priceHistory.deleteMany({
      where: { competitorProductId },
    });
    await this.prisma.competitorProduct.delete({
      where: { id: competitorProductId },
    });

    return { success: true, deleted: cp.title };
  }

  // ==================== A/B EXPERIMENTS ====================
  async createExperiment(tenantId: string, data: Record<string, unknown>) {
    if (!tenantId) throw new BadRequestException('tenantId zorunludur');

    const productId = String(data.productId || '');
    if (!productId) throw new BadRequestException('productId zorunludur');

    const product = await this.prisma.product.findFirst({
      where: { id: productId, tenantId },
      select: { id: true, price: true },
    });
    if (!product) throw new NotFoundException('Urun bulunamadi');

    const controlPrice = Number(data.controlPrice ?? product.price);
    const testPrice = Number(data.testPrice);
    if (!Number.isFinite(testPrice) || testPrice <= 0) {
      throw new BadRequestException(
        'testPrice gecerli bir pozitif sayi olmalidir',
      );
    }

    const durationDays = Math.max(
      1,
      Math.min(30, Number(data.durationDays) || 7),
    );
    const endDate = new Date();
    endDate.setDate(endDate.getDate() + durationDays);

    const experiment = await this.prisma.priceExperiment.create({
      data: {
        tenantId,
        productId,
        name: String(data.name || `A/B Test - ${product.id.slice(0, 8)}`),
        controlPrice,
        testPrice,
        durationDays,
        endDate,
        metadata: {
          hypothesis: data.hypothesis || null,
        } as Prisma.InputJsonValue,
      },
    });

    // Set product to test price for the experiment
    await this.prisma.product.update({
      where: { id: productId },
      data: { price: testPrice },
    });

    await this.prisma.activityLog.create({
      data: {
        tenantId,
        action: 'experiment.created',
        resource: 'product',
        resourceId: productId,
        details: {
          experimentId: experiment.id,
          controlPrice,
          testPrice,
          durationDays,
        } as Prisma.InputJsonValue,
      },
    });

    return experiment;
  }

  async getExperiments(tenantId: string) {
    if (!tenantId) throw new BadRequestException('tenantId zorunludur');

    return this.prisma.priceExperiment.findMany({
      where: { tenantId },
      orderBy: { createdAt: 'desc' },
    });
  }

  async evaluateExperiment(tenantId: string, experimentId: string) {
    if (!tenantId || !experimentId)
      throw new BadRequestException('tenantId ve experimentId zorunludur');

    const experiment = await this.prisma.priceExperiment.findFirst({
      where: { id: experimentId, tenantId },
    });
    if (!experiment) throw new NotFoundException('Deney bulunamadi');

    const controlSales = experiment.controlSales;
    const testSales = experiment.testSales;
    const controlRevenue = Number(experiment.controlRevenue);
    const testRevenue = Number(experiment.testRevenue);
    const controlViews = experiment.controlViews || 1;
    const testViews = experiment.testViews || 1;

    const controlConversion = controlSales / controlViews;
    const testConversion = testSales / testViews;

    // Calculate lift
    const salesLift =
      controlSales > 0 ? ((testSales - controlSales) / controlSales) * 100 : 0;
    const revenueLift =
      controlRevenue > 0
        ? ((testRevenue - controlRevenue) / controlRevenue) * 100
        : 0;

    // Simple statistical significance: using normal approximation
    const totalSamples = controlViews + testViews;
    const significance = this.calculateSignificance(
      controlConversion,
      testConversion,
      controlViews,
      testViews,
    );

    const winner =
      revenueLift > 0 && significance >= 0.9
        ? 'test'
        : revenueLift < 0 && significance >= 0.9
          ? 'control'
          : 'inconclusive';

    const result = {
      winner,
      salesLift: +salesLift.toFixed(2),
      revenueLift: +revenueLift.toFixed(2),
      controlConversion: +(controlConversion * 100).toFixed(2),
      testConversion: +(testConversion * 100).toFixed(2),
      significance: +significance.toFixed(4),
      isSignificant: significance >= 0.9,
      recommendation:
        winner === 'test'
          ? `Test fiyati (${Number(experiment.testPrice).toFixed(2)} TRY) kazandi. Kalici olarak uygulayin.`
          : winner === 'control'
            ? `Kontrol fiyati (${Number(experiment.controlPrice).toFixed(2)} TRY) daha iyi. Eski fiyata donun.`
            : `Yeterli veri yok, deneyi devam ettirin veya fiyat farkini artirin.`,
    };

    await this.prisma.priceExperiment.update({
      where: { id: experimentId },
      data: { result: result as unknown as Prisma.InputJsonValue },
    });

    return { experimentId, ...result };
  }

  async stopExperiment(tenantId: string, experimentId: string) {
    if (!tenantId || !experimentId)
      throw new BadRequestException('tenantId ve experimentId zorunludur');

    const experiment = await this.prisma.priceExperiment.findFirst({
      where: { id: experimentId, tenantId, status: 'active' },
    });
    if (!experiment) throw new NotFoundException('Aktif deney bulunamadi');

    // Evaluate before stopping
    const evaluation = await this.evaluateExperiment(tenantId, experimentId);

    // Revert to control price if test lost or inconclusive
    if (evaluation.winner !== 'test') {
      await this.prisma.product.update({
        where: { id: experiment.productId },
        data: { price: experiment.controlPrice },
      });
    }

    await this.prisma.priceExperiment.update({
      where: { id: experimentId },
      data: { status: 'completed', endDate: new Date() },
    });

    await this.prisma.activityLog.create({
      data: {
        tenantId,
        action: 'experiment.stopped',
        resource: 'product',
        resourceId: experiment.productId,
        details: {
          experimentId,
          winner: evaluation.winner,
          revenueLift: evaluation.revenueLift,
        } as Prisma.InputJsonValue,
      },
    });

    return { success: true, winner: evaluation.winner, evaluation };
  }

  // ==================== AUTO-DISCOVERY ====================
  async autoDiscoverCompetitors(tenantId: string, platform?: Platform) {
    if (!tenantId) throw new BadRequestException('tenantId zorunludur');

    const products = await this.prisma.product.findMany({
      where: { tenantId },
      select: { id: true, title: true, sku: true, category: true },
      take: 50,
    });

    if (products.length === 0) {
      return { discovered: 0, message: 'Urun bulunamadi' };
    }

    const platforms: Platform[] = platform
      ? [platform]
      : [Platform.TRENDYOL, Platform.HEPSIBURADA];
    const discoveredStores = new Map<
      string,
      {
        name: string;
        platform: Platform;
        storeUrl: string;
        productCount: number;
      }
    >();

    for (const p of platforms) {
      for (const product of products.slice(0, 20)) {
        try {
          const searchResults = (await this.marketplaceService.searchProducts(
            p as unknown as any,
            product.title.slice(0, 60),
            5,
          )) as unknown as Array<Record<string, unknown>>;

          if (!Array.isArray(searchResults)) continue;

          for (const item of searchResults) {
            const storeName = String(
              item.storeName || item.merchantName || item.seller || '',
            ).trim();
            const storeUrl = String(
              item.storeUrl || item.merchantUrl || item.sellerUrl || '',
            ).trim();
            if (!storeName || !storeUrl) continue;

            const storeKey = `${p}:${storeName}`;
            const existing = discoveredStores.get(storeKey);
            if (existing) {
              existing.productCount += 1;
            } else {
              discoveredStores.set(storeKey, {
                name: storeName,
                platform: p,
                storeUrl,
                productCount: 1,
              });
            }
          }
        } catch {
          // Search may not be available for all platforms
        }
      }
    }

    // Filter stores with multiple product overlaps and not already tracked
    const existingCompetitors = await this.prisma.competitor.findMany({
      where: { tenantId },
      select: { storeUrl: true, name: true },
    });
    const existingUrls = new Set(
      existingCompetitors.map((c) => c.storeUrl?.toLowerCase()),
    );
    const existingNames = new Set(
      existingCompetitors.map((c) => c.name.toLowerCase()),
    );

    const candidates = Array.from(discoveredStores.values())
      .filter((s) => s.productCount >= 2)
      .filter(
        (s) =>
          !existingUrls.has(s.storeUrl.toLowerCase()) &&
          !existingNames.has(s.name.toLowerCase()),
      )
      .sort((a, b) => b.productCount - a.productCount)
      .slice(0, 10);

    const created: Array<{ id: string; name: string; platform: string }> = [];
    for (const cand of candidates) {
      const competitor = await this.prisma.competitor.create({
        data: {
          tenantId,
          name: cand.name,
          platform: cand.platform,
          storeUrl: cand.storeUrl,
          isActive: true,
        },
      });
      created.push({
        id: competitor.id,
        name: competitor.name,
        platform: competitor.platform,
      });
    }

    if (created.length > 0) {
      await this.prisma.activityLog.create({
        data: {
          tenantId,
          action: 'competitor.auto_discovered',
          resource: 'competitor',
          details: {
            count: created.length,
            names: created.map((c) => c.name),
          } as Prisma.InputJsonValue,
        },
      });
    }

    return {
      discovered: created.length,
      competitors: created,
      scannedProducts: products.length,
      scannedPlatforms: platforms,
    };
  }

  // ==================== PRIVATE HELPERS ====================
  private calculateSignificance(
    controlRate: number,
    testRate: number,
    controlN: number,
    testN: number,
  ): number {
    if (controlN < 10 || testN < 10) return 0;

    const pooledRate =
      (controlRate * controlN + testRate * testN) / (controlN + testN);
    if (pooledRate <= 0 || pooledRate >= 1) return 0;

    const se = Math.sqrt(
      pooledRate * (1 - pooledRate) * (1 / controlN + 1 / testN),
    );
    if (se <= 0) return 0;

    const z = Math.abs(controlRate - testRate) / se;

    // Approximate normal CDF for z-score
    // P(Z > z) ≈ erfc(z/sqrt(2))/2
    // significance = 1 - 2*P(Z > z)
    const t = 1 / (1 + 0.2316419 * z);
    const d = 0.3989422804014327;
    const p =
      d *
      Math.exp((-z * z) / 2) *
      (0.3193815 * t +
        -0.3565638 * t * t +
        1.781478 * t ** 3 +
        -1.821256 * t ** 4 +
        1.330274 * t ** 5);
    return Math.max(0, Math.min(1, 1 - 2 * p));
  }
}

import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { Platform, Prisma } from '@prisma/client';
import { PrismaService } from '../../database/prisma.service';

interface PricingContext {
  productId: string;
  tenantId: string;
  currentPrice: number;
  costPrice: number;
  stock: number;
  category: string | null;
  platform?: Platform;
  competitorPrices: number[];
  competitorAvg: number;
  competitorMin: number;
  competitorMax: number;
  competitorInStockPrices: number[];
}

export interface PricingResult {
  suggestedPrice: number;
  currentPrice: number;
  costPrice: number;
  margin: number;
  appliedRules: Array<{
    id: string;
    name: string;
    type: string;
    effect: number;
  }>;
  competitorSummary: {
    avg: number;
    min: number;
    max: number;
    count: number;
  };
  confidence: number;
  reasoning: string[];
}

interface RuleAction {
  type:
    | 'percentage'
    | 'fixed'
    | 'undercut'
    | 'match'
    | 'margin_floor'
    | 'margin_target';
  value: number;
  reference?:
    | 'competitor_avg'
    | 'competitor_min'
    | 'competitor_max'
    | 'cost_price';
}

interface RuleConditions {
  minPrice?: number;
  maxPrice?: number;
  minMargin?: number;
  maxMargin?: number;
  minStock?: number;
  maxStock?: number;
  categories?: string[];
  platforms?: string[];
  minCompetitorCount?: number;
}

@Injectable()
export class PricingEngineService {
  private readonly logger = new Logger(PricingEngineService.name);

  constructor(private prisma: PrismaService) {}

  async calculateOptimalPrice(
    productId: string,
    competitorProductId: string,
    rules: { minPrice?: number; maxPrice?: number; strategy?: string },
  ): Promise<PricingResult | null> {
    const product = await this.prisma.product.findUnique({
      where: { id: productId },
      select: {
        id: true,
        tenantId: true,
        price: true,
        costPrice: true,
        stock: true,
        category: true,
      },
    });
    if (!product) return null;

    const tenantId = product.tenantId;
    const ctx = await this.buildContext(product);

    // If a specific competitor product was requested, ensure its price is included
    if (competitorProductId) {
      const cp = await this.prisma.competitorProduct.findUnique({
        where: { id: competitorProductId },
        select: { price: true, stock: true },
      });
      if (cp) {
        const cpPrice = Number(cp.price);
        if (cpPrice > 0 && !ctx.competitorPrices.includes(cpPrice)) {
          ctx.competitorPrices.push(cpPrice);
          this.recalcAggregates(ctx);
        }
      }
    }

    // Load active pricing rules from DB, sorted by priority
    const dbRules = await this.prisma.pricingRule.findMany({
      where: { tenantId, isActive: true },
      orderBy: { priority: 'desc' },
    });

    const reasoning: string[] = [];
    const appliedRules: PricingResult['appliedRules'] = [];
    let targetPrice = ctx.currentPrice;

    if (dbRules.length > 0) {
      // Apply DB rules in priority order
      for (const rule of dbRules) {
        const conditions = (rule.conditions || {}) as unknown as RuleConditions;
        const action = (rule.action || {}) as unknown as RuleAction;

        if (!this.matchesConditions(ctx, conditions)) continue;

        const prevPrice = targetPrice;
        targetPrice = this.applyAction(targetPrice, ctx, action);

        const effect = +(targetPrice - prevPrice).toFixed(2);
        appliedRules.push({
          id: rule.id,
          name: rule.name,
          type: rule.type,
          effect,
        });
        reasoning.push(
          `Kural "${rule.name}" (${rule.type}): ${effect >= 0 ? '+' : ''}${effect} TRY`,
        );

        // Update applied stats (fire and forget)
        this.prisma.pricingRule
          .update({
            where: { id: rule.id },
            data: { appliedCount: { increment: 1 }, lastApplied: new Date() },
          })
          .catch(() => {});
      }
    } else {
      // Fallback: built-in competitive pricing strategy
      const result = this.builtInCompetitiveStrategy(ctx);
      targetPrice = result.price;
      reasoning.push(...result.reasoning);
    }

    // Enforce inline min/max overrides
    if (rules.minPrice && targetPrice < rules.minPrice) {
      reasoning.push(
        `Min fiyat korumasi: ${targetPrice.toFixed(2)} → ${rules.minPrice}`,
      );
      targetPrice = rules.minPrice;
    }
    if (rules.maxPrice && targetPrice > rules.maxPrice) {
      reasoning.push(
        `Max fiyat siniri: ${targetPrice.toFixed(2)} → ${rules.maxPrice}`,
      );
      targetPrice = rules.maxPrice;
    }

    // Final safety: never go below cost
    const costFloor = ctx.costPrice * 1.03; // 3% minimum margin
    if (ctx.costPrice > 0 && targetPrice < costFloor) {
      reasoning.push(
        `Maliyet koruma: fiyat ${targetPrice.toFixed(2)} olarak maliyetin altina dusuyordu, ${costFloor.toFixed(2)} olarak ayarlandi`,
      );
      targetPrice = costFloor;
    }

    targetPrice = +targetPrice.toFixed(2);
    const margin =
      ctx.costPrice > 0
        ? +((1 - ctx.costPrice / targetPrice) * 100).toFixed(2)
        : 0;
    const confidence = this.calculateConfidence(ctx, appliedRules.length);

    return {
      suggestedPrice: targetPrice,
      currentPrice: ctx.currentPrice,
      costPrice: ctx.costPrice,
      margin,
      appliedRules,
      competitorSummary: {
        avg: +ctx.competitorAvg.toFixed(2),
        min: +ctx.competitorMin.toFixed(2),
        max: +ctx.competitorMax.toFixed(2),
        count: ctx.competitorPrices.length,
      },
      confidence,
      reasoning,
    };
  }

  // ==================== RULE CRUD ====================

  async getRules(tenantId: string) {
    return this.prisma.pricingRule.findMany({
      where: { tenantId },
      orderBy: { priority: 'desc' },
    });
  }

  async createRule(tenantId: string, data: Record<string, unknown>) {
    return this.prisma.pricingRule.create({
      data: {
        tenantId,
        name: String(data.name || 'Yeni Kural'),
        description: data.description ? String(data.description) : null,
        type: String(data.type || 'competitor'),
        conditions: (data.conditions || {}) as Prisma.InputJsonValue,
        action: (data.action || {
          type: 'undercut',
          value: 1,
        }) as Prisma.InputJsonValue,
        platforms: data.platforms
          ? (data.platforms as Prisma.InputJsonValue)
          : undefined,
        categories: data.categories
          ? (data.categories as Prisma.InputJsonValue)
          : undefined,
        isActive: data.isActive !== false,
        priority: typeof data.priority === 'number' ? data.priority : 0,
      },
    });
  }

  async updateRule(
    ruleId: string,
    tenantId: string,
    data: Record<string, unknown>,
  ) {
    const rule = await this.prisma.pricingRule.findFirst({
      where: { id: ruleId, tenantId },
    });
    if (!rule) throw new NotFoundException('Kural bulunamadi');

    return this.prisma.pricingRule.update({
      where: { id: ruleId },
      data: {
        name: data.name !== undefined ? String(data.name) : undefined,
        description:
          data.description !== undefined ? String(data.description) : undefined,
        type: data.type !== undefined ? String(data.type) : undefined,
        conditions:
          data.conditions !== undefined
            ? (data.conditions as Prisma.InputJsonValue)
            : undefined,
        action:
          data.action !== undefined
            ? (data.action as Prisma.InputJsonValue)
            : undefined,
        isActive:
          data.isActive !== undefined ? Boolean(data.isActive) : undefined,
        priority: typeof data.priority === 'number' ? data.priority : undefined,
      },
    });
  }

  async deleteRule(ruleId: string, tenantId: string) {
    const rule = await this.prisma.pricingRule.findFirst({
      where: { id: ruleId, tenantId },
    });
    if (!rule) throw new NotFoundException('Kural bulunamadi');
    await this.prisma.pricingRule.delete({ where: { id: ruleId } });
    return { success: true };
  }

  async bulkReprice(tenantId: string, productIds?: string[]) {
    const where: Prisma.ProductWhereInput = { tenantId };
    if (productIds?.length) where.id = { in: productIds };

    const products = await this.prisma.product.findMany({
      where,
      select: {
        id: true,
        price: true,
        costPrice: true,
        stock: true,
        category: true,
        tenantId: true,
      },
      take: 500,
    });

    const results: Array<{
      productId: string;
      oldPrice: number;
      newPrice: number;
      applied: boolean;
    }> = [];

    for (const product of products) {
      const ctx = await this.buildContext(product);
      if (ctx.competitorPrices.length === 0) {
        results.push({
          productId: product.id,
          oldPrice: ctx.currentPrice,
          newPrice: ctx.currentPrice,
          applied: false,
        });
        continue;
      }

      const optimal = await this.calculateOptimalPrice(product.id, '', {});
      if (!optimal || optimal.suggestedPrice === ctx.currentPrice) {
        results.push({
          productId: product.id,
          oldPrice: ctx.currentPrice,
          newPrice: ctx.currentPrice,
          applied: false,
        });
        continue;
      }

      await this.prisma.product.update({
        where: { id: product.id },
        data: { price: optimal.suggestedPrice },
      });
      await this.prisma.priceHistory.create({
        data: {
          tenantId,
          productId: product.id,
          price: optimal.suggestedPrice,
          platform: Platform.OTHER,
        },
      });

      results.push({
        productId: product.id,
        oldPrice: ctx.currentPrice,
        newPrice: optimal.suggestedPrice,
        applied: true,
      });
    }

    const appliedCount = results.filter((r) => r.applied).length;
    await this.prisma.activityLog.create({
      data: {
        tenantId,
        action: 'pricing.bulk_reprice',
        resource: 'product',
        details: {
          total: results.length,
          applied: appliedCount,
        } as Prisma.InputJsonValue,
      },
    });

    return { total: results.length, applied: appliedCount, results };
  }

  // ==================== PRIVATE HELPERS ====================

  private async buildContext(product: {
    id: string;
    tenantId: string;
    price: Prisma.Decimal | number;
    costPrice?: Prisma.Decimal | number | null;
    stock: number;
    category?: string | null;
  }): Promise<PricingContext> {
    const competitorProducts = await this.prisma.competitorProduct.findMany({
      where: {
        productId: product.id,
        competitor: { tenantId: product.tenantId, isActive: true },
      },
      select: { price: true, stock: true },
    });

    const allPrices = competitorProducts
      .map((c) => Number(c.price))
      .filter((n) => Number.isFinite(n) && n > 0);
    const inStockPrices = competitorProducts
      .filter((c) => (c.stock ?? 0) > 0)
      .map((c) => Number(c.price))
      .filter((n) => Number.isFinite(n) && n > 0);

    return {
      productId: product.id,
      tenantId: product.tenantId,
      currentPrice: Number(product.price),
      costPrice: Number(product.costPrice ?? 0),
      stock: product.stock,
      category: product.category ?? null,
      competitorPrices: allPrices,
      competitorAvg: allPrices.length
        ? allPrices.reduce((s, p) => s + p, 0) / allPrices.length
        : 0,
      competitorMin: allPrices.length ? Math.min(...allPrices) : 0,
      competitorMax: allPrices.length ? Math.max(...allPrices) : 0,
      competitorInStockPrices: inStockPrices,
    };
  }

  private recalcAggregates(ctx: PricingContext) {
    ctx.competitorAvg =
      ctx.competitorPrices.reduce((s, p) => s + p, 0) /
      ctx.competitorPrices.length;
    ctx.competitorMin = Math.min(...ctx.competitorPrices);
    ctx.competitorMax = Math.max(...ctx.competitorPrices);
  }

  private matchesConditions(
    ctx: PricingContext,
    cond: RuleConditions,
  ): boolean {
    if (cond.minStock !== undefined && ctx.stock < cond.minStock) return false;
    if (cond.maxStock !== undefined && ctx.stock > cond.maxStock) return false;
    if (
      cond.minCompetitorCount !== undefined &&
      ctx.competitorPrices.length < cond.minCompetitorCount
    )
      return false;
    if (
      cond.categories?.length &&
      ctx.category &&
      !cond.categories.includes(ctx.category)
    )
      return false;

    if (cond.minMargin !== undefined || cond.maxMargin !== undefined) {
      const margin =
        ctx.costPrice > 0
          ? ((ctx.currentPrice - ctx.costPrice) / ctx.currentPrice) * 100
          : 100;
      if (cond.minMargin !== undefined && margin < cond.minMargin) return false;
      if (cond.maxMargin !== undefined && margin > cond.maxMargin) return false;
    }

    return true;
  }

  private applyAction(
    price: number,
    ctx: PricingContext,
    action: RuleAction,
  ): number {
    const ref = this.resolveReference(ctx, action.reference);

    switch (action.type) {
      case 'percentage':
        // action.value = -5 means 5% cheaper than reference
        return ref > 0 ? ref * (1 + action.value / 100) : price;

      case 'fixed':
        // action.value = -10 means 10 TRY below reference
        return ref > 0 ? ref + action.value : price;

      case 'undercut':
        // action.value = 1 means 1% below competitor min
        return ctx.competitorMin > 0
          ? ctx.competitorMin * (1 - action.value / 100)
          : price;

      case 'match':
        // Match reference price exactly
        return ref > 0 ? ref : price;

      case 'margin_floor':
        // Ensure minimum margin: action.value = 15 means 15% minimum
        if (ctx.costPrice > 0) {
          const floorPrice = ctx.costPrice / (1 - action.value / 100);
          return Math.max(price, floorPrice);
        }
        return price;

      case 'margin_target':
        // Set price to achieve target margin
        if (ctx.costPrice > 0) {
          return ctx.costPrice / (1 - action.value / 100);
        }
        return price;

      default:
        return price;
    }
  }

  private resolveReference(ctx: PricingContext, ref?: string): number {
    switch (ref) {
      case 'competitor_avg':
        return ctx.competitorAvg;
      case 'competitor_min':
        return ctx.competitorMin;
      case 'competitor_max':
        return ctx.competitorMax;
      case 'cost_price':
        return ctx.costPrice;
      default:
        return ctx.competitorAvg;
    }
  }

  private builtInCompetitiveStrategy(ctx: PricingContext): {
    price: number;
    reasoning: string[];
  } {
    const reasoning: string[] = [];

    if (ctx.competitorPrices.length === 0) {
      reasoning.push('Rakip verisi yok, mevcut fiyat korunuyor');
      return { price: ctx.currentPrice, reasoning };
    }

    // Strategy: be 2% below competitor average but above min competitor * 0.995
    let candidate = ctx.competitorAvg * 0.98;
    reasoning.push(
      `Rakip ortalama (${ctx.competitorAvg.toFixed(2)}) uzerine %2 alt: ${candidate.toFixed(2)}`,
    );

    if (ctx.competitorMin > 0) {
      const minFloor = ctx.competitorMin * 0.995;
      if (candidate < minFloor) {
        candidate = minFloor;
        reasoning.push(
          `Rakip min (${ctx.competitorMin.toFixed(2)}) alti koruma: ${candidate.toFixed(2)}`,
        );
      }
    }

    if (ctx.costPrice > 0) {
      const costFloor = ctx.costPrice * 1.15;
      if (candidate < costFloor) {
        candidate = costFloor;
        reasoning.push(
          `Maliyet ustu guvenli marj (%15): ${candidate.toFixed(2)}`,
        );
      }
    }

    return { price: candidate, reasoning };
  }

  private calculateConfidence(ctx: PricingContext, ruleCount: number): number {
    let score = 30;
    score += Math.min(30, ctx.competitorPrices.length * 6);
    score += ctx.costPrice > 0 ? 20 : 0;
    score += ruleCount > 0 ? 20 : 0;
    return Math.min(100, Math.max(25, score));
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';
import {
  MarketplaceAnalysisResponse,
  computeConfidenceFromSources,
} from './analysis.types';

interface AlibabaProduct {
  productId: string;
  title: string;
  price: number;
  salePrice: number;
  stockCount: number;
  rating: number;
  reviewCount: number;
  url: string;
  images: string[];
  supplierName: string;
  supplierUrl: string;
  minOrder: number;
  unit: string;
  shippingTerms: string;
  paymentTerms: string;
}

@Injectable()
export class AlibabaBridge implements MarketplaceBridge {
  private readonly logger = new Logger(AlibabaBridge.name);
  private readonly apiUrl = 'https://openapi.alibaba.com/gateway.do';

  constructor(
    private readonly appKey: string,
    private readonly appSecret: string,
    private readonly accessToken: string,
    private readonly scrapingService: ScrapingService,
  ) {}

  async syncProducts(): Promise<any> {
    this.logger.log('Syncing products from Alibaba');
    try {
      // Alibaba API uses signature-based authentication
      const timestamp = new Date().toISOString();
      const params = {
        app_key: this.appKey,
        timestamp: timestamp,
        method: 'alibaba.product.list',
        access_token: this.accessToken,
        format: 'json',
        v: '2.0',
        pageSize: '100',
      };

      const signature = this.generateSignature(params);

      const queryString = new URLSearchParams({
        ...params,
        sign: signature,
        sign_method: 'hmac-sha256',
      }).toString();

      const response = await fetch(`${this.apiUrl}?${queryString}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        this.logger.warn(`Alibaba syncProducts failed: ${response.status}`);
        return {
          success: false,
          platform: 'ALIBABA',
          error: `HTTP ${response.status}`,
        };
      }

      const data = await response.json();
      const products = data.productList || [];

      return {
        success: true,
        platform: 'ALIBABA',
        count: products.length,
        products: products.map(this.mapAlibabaProduct),
      };
    } catch (error) {
      this.logger.warn(
        `Alibaba syncProducts error: ${(error as Error).message}`,
      );
      return {
        success: false,
        platform: 'ALIBABA',
        error: (error as Error).message,
      };
    }
  }

  async syncOrders(): Promise<any> {
    try {
      const timestamp = new Date().toISOString();
      const params = {
        app_key: this.appKey,
        timestamp: timestamp,
        method: 'alibaba.trade.order.list',
        access_token: this.accessToken,
        format: 'json',
        v: '2.0',
      };

      const signature = this.generateSignature(params);

      const queryString = new URLSearchParams({
        ...params,
        sign: signature,
        sign_method: 'hmac-sha256',
      }).toString();

      const response = await fetch(`${this.apiUrl}?${queryString}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      return {
        success: true,
        platform: 'ALIBABA',
        orders: data.orderList || [],
      };
    } catch (error) {
      this.logger.warn(`Alibaba syncOrders error: ${(error as Error).message}`);
      return {
        success: false,
        platform: 'ALIBABA',
        error: (error as Error).message,
      };
    }
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    try {
      const timestamp = new Date().toISOString();
      const params = {
        app_key: this.appKey,
        timestamp: timestamp,
        method: 'alibaba.product.update',
        access_token: this.accessToken,
        format: 'json',
        v: '2.0',
        productId: sku,
        stockQuantity: stock.toString(),
      };

      const signature = this.generateSignature(params);

      const response = await fetch(this.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          ...params,
          sign: signature,
          sign_method: 'hmac-sha256',
        }).toString(),
      });

      if (response.status === 429 || response.status >= 500) {
        throw new Error(`Alibaba stock update failed: HTTP ${response.status}`);
      }

      return { success: response.ok, sku, stock, platform: 'ALIBABA' };
    } catch (error) {
      this.logger.warn(
        `Alibaba updateStock error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    try {
      const timestamp = new Date().toISOString();
      const params = {
        app_key: this.appKey,
        timestamp: timestamp,
        method: 'alibaba.product.update',
        access_token: this.accessToken,
        format: 'json',
        v: '2.0',
        productId: sku,
        price: price.toString(),
      };

      const signature = this.generateSignature(params);

      const response = await fetch(this.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          ...params,
          sign: signature,
          sign_method: 'hmac-sha256',
        }).toString(),
      });

      if (response.status === 429 || response.status >= 500) {
        throw new Error(`Alibaba price update failed: HTTP ${response.status}`);
      }

      return { success: response.ok, sku, price, platform: 'ALIBABA' };
    } catch (error) {
      this.logger.warn(
        `Alibaba updatePrice error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  async getStoreInfo(storeId: string): Promise<any> {
    try {
      // Alibaba supplier info via scraping fallback
      const url = `https://${storeId}.en.alibaba.com`;
      const scraped = await this.scrapingService.scrapeStore(url, 'ALIBABA');
      if (scraped) {
        return {
          storeId,
          storeName: scraped.storeName || storeId,
          totalProducts: scraped.productCount ?? 0,
          averageRating: scraped.rating ?? 0,
          totalReviews: scraped.totalReviews ?? 0,
          followersCount: scraped.followerCount ?? 0,
          platform: 'ALIBABA',
          isGoldSupplier: false,
          yearsInBusiness: 0,
        };
      }

      throw new Error('Alibaba supplier info could not be retrieved');
    } catch (error) {
      this.logger.error(
        `Alibaba getStoreInfo error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  async getStoreProducts(
    storeId?: string,
    limit: number = 10,
  ): Promise<AlibabaProduct[]> {
    try {
      const timestamp = new Date().toISOString();
      const params = {
        app_key: this.appKey,
        timestamp: timestamp,
        method: 'alibaba.product.search',
        access_token: this.accessToken,
        format: 'json',
        v: '2.0',
        sellerId: storeId || '',
        pageSize: limit.toString(),
      };

      const signature = this.generateSignature(params);

      const queryString = new URLSearchParams({
        ...params,
        sign: signature,
        sign_method: 'hmac-sha256',
      }).toString();

      const response = await fetch(`${this.apiUrl}?${queryString}`, {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      const items = data.productList || [];

      return items
        .slice(0, limit)
        .map((item: any, index: number) => this.mapAlibabaProduct(item, index));
    } catch (error) {
      this.logger.error(
        `Alibaba getStoreProducts error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  private generateSignature(params: Record<string, string>): string {
    // HMAC-SHA256 signature for Alibaba API
    const sortedParams = Object.keys(params)
      .sort()
      .reduce(
        (acc, key) => {
          acc[key] = params[key];
          return acc;
        },
        {} as Record<string, string>,
      );

    const signString = Object.entries(sortedParams)
      .map(([k, v]) => `${k}${v}`)
      .join('');

    // In production, use crypto library for HMAC
    return `hmac_sha256_${signString}`;
  }

  private mapAlibabaProduct(item: any, index: number = 0): AlibabaProduct {
    return {
      productId: item.productId || `ALIBABA-${index}`,
      title: item.subject || 'Unknown',
      price: parseFloat(item.fobPrice?.value) || 0,
      salePrice: parseFloat(item.fobPrice?.value) || 0,
      stockCount: item.stockQuantity || 0,
      rating: item.supplier?.rating || 0,
      reviewCount: 0,
      url: item.productUrl || '',
      images: item.imageUrls || [],
      supplierName: item.supplier?.name || '',
      supplierUrl: item.supplier?.url || '',
      minOrder: item.minOrderQuantity || 1,
      unit: item.unit || 'piece',
      shippingTerms: item.shippingTerms || '',
      paymentTerms: item.paymentTerms || '',
    };
  }
}

