  async syncOrders(): Promise<any> {
    try {
      const timestamp = Date.now().toString();
      const params = {
        app_key: this.appKey,
        timestamp: timestamp,
        method: 'aliexpress.trade.seller.order.list.get',
        access_token: this.accessToken,
        format: 'json',
        v: '2.0',
        page_size: '50',
      };

      const signature = this.generateSignature(params);

      const response = await fetch(this.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          ...params,
          sign: signature,
          sign_method: 'md5',
        }).toString(),
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      return {
        success: true,
        platform: 'ALIEXPRESS',
        orders: data.data?.order_list || [],
      };
    } catch (error) {
      this.logger.warn(
        `AliExpress syncOrders error: ${(error as Error).message}`,
      );
      return {
        success: false,
        platform: 'ALIEXPRESS',
        error: (error as Error).message,
      };
    }
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    try {
      const timestamp = Date.now().toString();
      const params = {
        app_key: this.appKey,
        timestamp: timestamp,
        method: 'aliexpress.solution.product.inventory.update',
        access_token: this.accessToken,
        format: 'json',
        v: '2.0',
        product_id: sku,
        inventory: stock.toString(),
      };

      const signature = this.generateSignature(params);

      const response = await fetch(this.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          ...params,
          sign: signature,
          sign_method: 'md5',
        }).toString(),
      });

      if (response.status === 429 || response.status >= 500) {
        throw new Error(
          `AliExpress stock update failed: HTTP ${response.status}`,
        );
      }

      return { success: response.ok, sku, stock, platform: 'ALIEXPRESS' };
    } catch (error) {
      this.logger.warn(
        `AliExpress updateStock error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    try {
      const timestamp = Date.now().toString();
      const params = {
        app_key: this.appKey,
        timestamp: timestamp,
        method: 'aliexpress.solution.product.price.update',
        access_token: this.accessToken,
        format: 'json',
        v: '2.0',
        product_id: sku,
        price: price.toString(),
      };

      const signature = this.generateSignature(params);

      const response = await fetch(this.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          ...params,
          sign: signature,
          sign_method: 'md5',
        }).toString(),
      });

      if (response.status === 429 || response.status >= 500) {
        throw new Error(
          `AliExpress price update failed: HTTP ${response.status}`,
        );
      }

      return { success: response.ok, sku, price, platform: 'ALIEXPRESS' };
    } catch (error) {
      this.logger.warn(
        `AliExpress updatePrice error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  async getStoreInfo(storeId: string): Promise<any> {
    try {
      // AliExpress store info via scraping fallback
      const url = `https://www.aliexpress.com/store/${storeId}`;
      const scraped = await this.scrapingService.scrapeStore(url, 'ALIEXPRESS');
      if (scraped) {
        return {
          storeId,
          storeName: scraped.storeName || storeId,
          totalProducts: scraped.productCount ?? 0,
          averageRating: scraped.rating ?? 0,
          totalReviews: scraped.totalReviews ?? 0,
          followersCount: scraped.followerCount ?? 0,
          platform: 'ALIEXPRESS',
          positiveFeedback: '0%',
          yearsActive: 0,
        };
      }

      throw new Error('AliExpress store info could not be retrieved');
    } catch (error) {
      this.logger.error(
        `AliExpress getStoreInfo error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  async getStoreProducts(
    storeId?: string,
    limit: number = 10,
  ): Promise<AliexpressProduct[]> {
    try {
      const timestamp = Date.now().toString();
      const params = {
        app_key: this.appKey,
        timestamp: timestamp,
        method: 'aliexpress.solution.store.products.get',
        access_token: this.accessToken,
        format: 'json',
        v: '2.0',
        store_id: storeId || '',
        page_size: limit.toString(),
      };

      const signature = this.generateSignature(params);

      const response = await fetch(this.apiUrl, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          ...params,
          sign: signature,
          sign_method: 'md5',
        }).toString(),
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      const items = data.data?.product_list || [];

      return items
        .slice(0, limit)
        .map((item: any, index: number) =>
          this.mapAliexpressProduct(item, index),
        );
    } catch (error) {
      this.logger.error(
        `AliExpress getStoreProducts error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  private generateSignature(params: Record<string, string>): string {
    // MD5 signature for AliExpress API
    const sortedParams = Object.keys(params)
      .sort()
      .reduce(
        (acc, key) => {
          acc[key] = params[key];
          return acc;
        },
        {} as Record<string, string>,
      );

    const signString =
      this.appSecret +
      Object.entries(sortedParams)
        .map(([k, v]) => `${k}${v}`)
        .join('') +
      this.appSecret;

    // In production, use crypto library for MD5
    return `md5_${signString}`;
  }

  private mapAliexpressProduct(
    item: any,
    index: number = 0,
  ): AliexpressProduct {
    return {
      productId: item.product_id || `ALIEXPRESS-${index}`,
      title: item.subject || 'Unknown',
      price: parseFloat(item.price) || 0,
      salePrice: parseFloat(item.sale_price) || parseFloat(item.price) || 0,
      stockCount: item.stock || 0,
      rating: item.avg_rating || 0,
      reviewCount: item.reviews_count || 0,
      url: item.product_url || '',
      images: item.image_urls || [],
      storeName: item.store_name || '',
      storeUrl: item.store_url || '',
      shippingCost: item.shipping_cost || 0,
      estimatedDelivery: item.estimated_delivery || '',
      ordersCount: item.orders_count || 0,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';

interface AllegroProduct {
  productId: string;
  title: string;
  price: number;
  salePrice: number;
  stockCount: number;
  rating: number;
  reviewCount: number;
  url: string;
  images: string[];
  sellerName: string;
  sellerId: string;
  shippingFrom: string;
  deliveryTime: string;
  freeShipping: boolean;
  category: string;
}

@Injectable()
export class AllegroBridge implements MarketplaceBridge {
  private readonly logger = new Logger(AllegroBridge.name);
  private readonly apiUrl = 'https://api.allegro.pl';

  constructor(
    private readonly clientId: string,
    private readonly clientSecret: string,
    private readonly accessToken: string,
    private readonly scrapingService: ScrapingService,
  ) {}

  private getAuthHeaders(): Record<string, string> {
    return {
      Authorization: `Bearer ${this.accessToken}`,
      Accept: 'application/vnd.allegro.public.v1+json',
      'Content-Type': 'application/vnd.allegro.public.v1+json',
    };
  }

  async syncProducts(): Promise<any> {
    try {
      const response = await fetch(`${this.apiUrl}/sale/offers?limit=100`, {
        headers: this.getAuthHeaders(),
      });

      if (!response.ok) {
        return {
          success: false,
          platform: 'ALLEGRO',
          error: `HTTP ${response.status}`,
        };
      }

      const data = await response.json();
      return {
        success: true,
        platform: 'ALLEGRO',
        count: data.items?.length || 0,
      };
    } catch (error) {
      return {
        success: false,
        platform: 'ALLEGRO',
        error: (error as Error).message,
      };
    }
  }

  async syncOrders(): Promise<any> {
    try {
      const response = await fetch(
        `${this.apiUrl}/order/checkout-forms?status=READY_FOR_PROCESSING`,
        {
          headers: this.getAuthHeaders(),
        },
      );
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();
      return {
        success: true,
        platform: 'ALLEGRO',
        orders: data.checkoutForms || [],
      };
    } catch (error) {
      return {
        success: false,
        platform: 'ALLEGRO',
        error: (error as Error).message,
      };
    }
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    try {
      // Get current offer
      const getResponse = await fetch(`${this.apiUrl}/sale/offers/${sku}`, {
        headers: this.getAuthHeaders(),
      });
      if (!getResponse.ok) throw new Error('Failed to get offer');
      const offer = await getResponse.json();

      // Update stock
      const response = await fetch(`${this.apiUrl}/sale/offers/${sku}`, {
        method: 'PUT',
        headers: this.getAuthHeaders(),
        body: JSON.stringify({
          ...offer,
          stock: {
            ...offer.stock,
            available: stock,
          },
        }),
      });
      return { success: response.ok, sku, stock, platform: 'ALLEGRO' };
    } catch (error) {
      throw error;
    }
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    try {
      const response = await fetch(
        `${this.apiUrl}/sale/offers/${sku}/change-price-commands/${Date.now()}`,
        {
          method: 'PUT',
          headers: this.getAuthHeaders(),
          body: JSON.stringify({
            input: {
              buyNowPrice: {
                amount: price.toString(),
                currency: 'PLN',
              },
            },
          }),
        },
      );
      return { success: response.ok, sku, price, platform: 'ALLEGRO' };
    } catch (error) {
      throw error;
    }
  }

  async getStoreInfo(storeId: string): Promise<any> {
    try {
      const response = await fetch(
        `${this.apiUrl}/users/${storeId}/ratings-summary`,
        {
          headers: this.getAuthHeaders(),
        },
      );
      if (response.ok) {
        const data = await response.json();
        return {
          storeId,
          storeName: storeId,
          platform: 'ALLEGRO',
          country: 'Poland',
          averageRating: data.averageRating || 0,
          totalReviews: data.totalReviews || 0,
        };
      }
      throw new Error('Failed to get store info');
    } catch (error) {
      throw error;
    }
  }

  async getStoreProducts(
    storeId?: string,
    limit: number = 10,
  ): Promise<AllegroProduct[]> {
    try {
      const response = await fetch(
        `${this.apiUrl}/users/${storeId}/offers?limit=${limit}`,
        { headers: this.getAuthHeaders() },
      );
      const data = await response.json();
      return (data.items || []).map((item: any) => ({
        productId: item.id,
        title: item.name,
        price: item.sellingMode?.price?.amount,
        salePrice: item.sellingMode?.price?.amount,
        stockCount: item.stock?.available || 0,
        rating: 0,
        reviewCount: 0,
        url: item.url,
        images: [item.images?.[0]?.url],
        sellerName: item.seller?.login,
        sellerId: item.seller?.id,
        shippingFrom: item.location?.city,
        deliveryTime: item.delivery?.shippingRates?.name,
        freeShipping: item.delivery?.shippingRates?.id === 'free',
        category: item.category?.name,
      }));
    } catch (error) {
      throw error;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';
import {
  MarketplaceAnalysisResponse,
  computeConfidenceFromSources,
} from './analysis.types';

@Injectable()
export class AmazonBridge implements MarketplaceBridge {
  private readonly logger = new Logger(AmazonBridge.name);

  constructor(
    private readonly sellerId: string,
    private readonly mwsAuthToken: string,
    private readonly scrapingService: ScrapingService,
  ) {}

  async syncProducts(): Promise<any> {
    const sellerId = this.sellerId?.trim();
    if (!sellerId || sellerId === 'public') {
      throw new Error('Amazon syncProducts için sellerId zorunludur');
    }

    this.logger.log(`Syncing products for Amazon Seller: ${sellerId}`);
    const storeUrl = sellerId.startsWith('http')
      ? sellerId
      : `https://www.amazon.com.tr/s?me=${encodeURIComponent(sellerId)}`;

    const products = await this.scrapingService.scrapeStoreProducts(
      storeUrl,
      'AMAZON',
      100,
    );
    if (!Array.isArray(products)) {
      throw new Error('Amazon ürün verisi alınamadı');
    }

    return {
      success: true,
      platform: 'AMAZON',
      count: products.length,
      products,
    };
  }

  async getStoreInfo(storeId?: string): Promise<any> {
    const resolvedStoreId = (storeId || this.sellerId || '').trim();
    if (!resolvedStoreId || resolvedStoreId === 'public') {
      throw new Error('Amazon getStoreInfo için sellerId zorunludur');
    }

    const storeUrl = resolvedStoreId.startsWith('http')
      ? resolvedStoreId
      : `https://www.amazon.com.tr/s?me=${encodeURIComponent(resolvedStoreId)}`;

    const scraped = await this.scrapingService.scrapeStore(storeUrl, 'AMAZON');
    return {
      storeId: resolvedStoreId,
      storeName: scraped?.storeName || resolvedStoreId,
      totalProducts: scraped?.productCount ?? 0,
      averageRating: scraped?.rating ?? 0,
      totalReviews: scraped?.totalReviews ?? 0,
      followersCount: scraped?.followerCount ?? 0,
      platform: 'AMAZON',
    };
  }

  async getStoreProducts(storeId?: string, limit: number = 10): Promise<any[]> {
    const resolvedStoreId = (storeId || this.sellerId || '').trim();
    if (!resolvedStoreId || resolvedStoreId === 'public') {
      throw new Error('Amazon getStoreProducts için sellerId zorunludur');
    }

    const storeUrl = resolvedStoreId.startsWith('http')
      ? resolvedStoreId
      : `https://www.amazon.com.tr/s?me=${encodeURIComponent(resolvedStoreId)}`;

    const scrapedProducts = await this.scrapingService.scrapeStoreProducts(
      storeUrl,
      'AMAZON',
      limit,
    );
    return (Array.isArray(scrapedProducts) ? scrapedProducts : []).map(
      (product, index) => {
        const entry = product as unknown as Record<string, unknown>;
        return {
          productId: String(entry.productId || entry.id || `AMZ-${index + 1}`),
          title: String(entry.title || entry.name || ''),
          salePrice: Number(entry.salePrice || entry.price || 0),
          price: Number(entry.price || entry.salePrice || 0),
          stockCount: Number(entry.stock ?? entry.stockCount ?? 0),
          rating: Number(entry.rating || 0),
          reviewCount: Number(entry.reviewCount || 0),
          images: Array.isArray(entry.images) ? entry.images : [],
          url: String(entry.url || ''),
        };
      },
    );
  }

  async syncOrders(): Promise<any> {
    throw new Error(
      'Amazon sipariş senkronizasyonu için SP-API entegrasyonu zorunludur',
    );
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    void sku;
    void stock;
    throw new Error(
      'Amazon stok güncelleme için SP-API entegrasyonu zorunludur',
    );
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    void sku;
    void price;
    throw new Error(
      'Amazon fiyat güncelleme için SP-API entegrasyonu zorunludur',
    );
  }

  // Amazon SP-API review entegrasyonu — henüz aktif değil
  async getReviews(
    _page: number = 0,
    _size: number = 100,
  ): Promise<MarketplaceReview[]> {
    this.logger.warn(
      'Amazon getReviews: SP-API entegrasyonu henüz aktif değil',
    );
    return [];
  }

  /**
   * SEO ve Performans analizi yap - Scraping tabanlı
   */
  async analyzeStoreSEO(
    storeId?: string,
  ): Promise<MarketplaceAnalysisResponse> {
    try {
      const resolvedStoreId = (storeId || this.sellerId || '').trim();
      if (!resolvedStoreId || resolvedStoreId === 'public') {
        throw new Error('Amazon analiz için sellerId zorunludur');
      }

      const storeInfo = await this.getStoreInfo(resolvedStoreId);
      const products = await this.getStoreProducts(resolvedStoreId, 20);

      // SEO Score hesabı
      const seoScore = this.calculateSEOScore(storeInfo, products);

      const metricSources = {
        storeName: 'scraped',
        rating: 'scraped',
        followers: 'not_available',
        totalProducts: 'scraped',
        responseTime: 'not_available',
        monthlyTraffic: 'not_available',
        monthlyTurnover: 'not_available',
        titleOptimization: 'calculated',
        imageOptimization: 'calculated',
        priceCompetitiveness: 'calculated',
        stockHealth: 'calculated',
        ratingTrend: 'scraped',
        reviewCount: 'scraped',
      } as const;

      return {
        platform: 'AMAZON',
        storeId: resolvedStoreId,
        storeName: storeInfo.storeName,
        seoScore,
        dataSources: {
          overall: 'scraped+calculated',
          seoScore: 'calculated',
          products: 'scraped',
          metrics: metricSources,
          reasons: {
            responseTime:
              'Amazon public source yanit suresi bilgisini acik olarak saglamiyor.',
            monthlyTraffic:
              'Aylik trafik verisi platform public endpointlerinde bulunmuyor.',
            monthlyTurnover:
              'Aylik ciro verisi platform public endpointlerinde bulunmuyor.',
            followers:
              'Amazon magaza takipcisi bilgisi public olarak saglanmiyor.',
          },
          evidence: {
            adapter: 'amazon.bridge',
            productSampleSize: products.length,
            hasCredentials: Boolean(
              this.sellerId && this.sellerId !== 'public',
            ),
          },
        },
        confidence: computeConfidenceFromSources(metricSources),
        metrics: {
          storeName: storeInfo.storeName,
          rating: storeInfo.averageRating,
          followers: 0,
          totalProducts: storeInfo.totalProducts,
          titleOptimization: this.analyzeTitles(products),
          imageOptimization: this.analyzeImages(products),
          priceCompetitiveness: this.analyzePrices(products),
          stockHealth: this.analyzeStock(products),
          ratingTrend: storeInfo.averageRating,
          reviewCount: storeInfo.totalReviews,
        },
        products: products.map((p) => ({
          name: p.title,
          price: p.salePrice,
          rating: p.rating,
          reviews: p.reviewCount,
          stock: p.stockCount,
        })),
        recommendations: this.generateRecommendations(storeInfo, products),
        timestamp: new Date(),
      };
    } catch (error) {
      this.logger.error(
        `Amazon SEO analysis error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  private calculateSEOScore(storeInfo: any, products: any[]): number {
    let score = 45; // Base score (lower than local platforms due to global competition)

    // Rating (max +20) - Amazon uses 5-star system
    score += (storeInfo.averageRating / 5) * 20;

    // Review count (max +15)
    const reviewBonus = Math.min(storeInfo.totalReviews / 500, 15);
    score += reviewBonus;

    // Stock health (max +15)
    const avgStock =
      products.length > 0
        ? products.reduce((sum, p) => sum + (p.stockCount > 0 ? 1 : 0), 0) /
          products.length
        : 0;
    score += avgStock * 15;

    // Product diversity (max +5)
    if (products.length >= 10) score += 5;

    return Math.min(Math.round(score), 100);
  }

  private analyzeTitles(products: any[]): number {
    if (!products.length) return 50;
    let validCount = 0;

    products.forEach((p) => {
      const title = p.title || '';
      // Amazon title optimization: 60-200 chars is ideal
      if (title.length >= 60 && title.length <= 200) validCount++;
    });

    return Math.round((validCount / products.length) * 100);
  }

  private analyzeImages(products: any[]): number {
    if (!products.length) return 50;
    let validCount = 0;
    products.forEach((p) => {
      // Amazon requires main image + 4+ additional images ideally
      if (p.images && p.images.length >= 1) validCount++;
    });
    return Math.round((validCount / products.length) * 100);
  }

  private analyzePrices(products: any[]): number {
    if (!products.length) return 50;
    const avgPrice =
      products.reduce((sum, p) => sum + (p.salePrice || 0), 0) /
      products.length;
    // Amazon competitive pricing analysis - variance indicates competition
    const variance =
      products.reduce(
        (sum, p) => sum + Math.abs((p.salePrice || 0) - avgPrice),
        0,
      ) / products.length;
    const normalizedVariance = Math.min(
      30,
      (variance / Math.max(avgPrice, 1)) * 100,
    );
    return Math.round(
      Math.min(100, Math.max(40, 70 + (30 - normalizedVariance))),
    );
  }

  private analyzeStock(products: any[]): number {
    if (!products.length) return 50;
    const stockedProducts = products.filter(
      (p) => (p.stockCount || 0) > 5,
    ).length;
    return Math.round((stockedProducts / products.length) * 100);
  }

  private generateRecommendations(storeInfo: any, products: any[]): string[] {
    const recommendations: string[] = [];

    if (storeInfo.averageRating < 4.0) {
      recommendations.push(
        'Amazon satıcı puanını artırmak için müşteri hizmetlerini iyileştir',
      );
    }

    if (storeInfo.totalReviews < 100) {
      recommendations.push(
        'Yorum sayısını artırmak için Amazon Early Reviewer programını kullan',
      );
    }

    const lowStockProducts = products.filter(
      (p) => (p.stockCount || 0) < 10,
    ).length;
    if (lowStockProducts > 0) {
      recommendations.push(
        `${lowStockProducts} ürün kritik stok seviyesinde - FBA kullanmayı düşün`,
      );
    }

    if (products.length < 10) {
      recommendations.push(
        'Amazon katalogunu genişlet - minimum 10+ ürün önerilir',
      );
    }

    // Check for Prime eligibility simulation
    const hasPrimeEligible = products.some((p) => (p.salePrice || 0) > 35);
    if (!hasPrimeEligible) {
      recommendations.push('Prime ücretsiz kargo için 35$+ ürünler ekle');
    }

    return recommendations;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
