      const scraped = await this.scrapingService.scrapeStore(url, 'CDISCOUNT');
      return {
        storeId,
        storeName: scraped?.storeName || storeId,
        platform: 'CDISCOUNT',
        country: 'France',
      };
    } catch (error) {
