        { headers: this.getAuthHeaders() },
      );
      const data = await response.json();
      return (data.products || []).map((item: any) => ({
        productId: item.id,
        title: item.name,
        price: item.price,
        salePrice: item.sale_price || item.price,
        stockCount: item.stock || 0,
