import { Injectable, Logger } from '@nestjs/common';
import {
  ScrapingService,
  ScrapedProductData,
} from '../scraping/scraping.service';
import { MarketplaceService, Platform } from './marketplace.service';

export interface CompetitorProduct {
  productId: string;
  title: string;
  price: number;
  originalPrice?: number;
  rating: number;
  reviewCount: number;
  platform: string;
  storeName: string;
  url: string;
  image?: string;
  stockStatus: boolean;
}

export interface PriceComparison {
  productName: string;
  ourPrice: number;
  competitorPrices: Array<{
    platform: string;
    storeName: string;
    price: number;
    difference: number;
    differencePercent: number;
    url: string;
  }>;
  cheapest: {
    platform: string;
    price: number;
  } | null;
  mostExpensive: {
    platform: string;
    price: number;
  } | null;
  averageMarketPrice: number;
  recommendation: string;
}

export interface CompetitorAnalysis {
  competitorStoreUrl: string;
  platform: Platform;
  storeInfo: {
    name: string;
    rating: number;
    followerCount: number;
    productCount: number;
  };
  products: CompetitorProduct[];
  commonProducts: Array<{
    ourProduct: { title: string; price: number };
    competitorProduct: CompetitorProduct;
    priceDifference: number;
    priceDifferencePercent: number;
  }>;
  strengths: string[];
  weaknesses: string[];
  opportunities: string[];
  threats: string[];
  analyzedAt: Date;
}

@Injectable()
export class CompetitorAnalysisService {
  private readonly logger = new Logger(CompetitorAnalysisService.name);

  constructor(
    private readonly scrapingService: ScrapingService,
    private readonly marketplaceService: MarketplaceService,
  ) {}

  /**
   * Rakip mağazayı analiz et
   */
  async analyzeCompetitor(
    competitorUrl: string,
    platform: Platform,
    ourTenantId: string,
  ): Promise<CompetitorAnalysis> {
    this.logger.log(`Analyzing competitor: ${competitorUrl} on ${platform}`);

    // Rakip mağaza bilgilerini çek
    const storeData = await this.scrapingService.scrapeStore(
      competitorUrl,
      platform,
    );
    if (!storeData) {
      throw new Error('Rakip mağaza verisi alınamadı');
    }

    // Rakip ürünlerini çek
    const products = await this.scrapingService.scrapeStoreProducts(
      competitorUrl,
      platform,
      50,
    );

    // Kendi ürünlerimizi çek
    const ourProducts = await this.getOurProducts(ourTenantId);

    // Ortak ürünleri bul ve karşılaştır
    const commonProducts = this.findCommonProducts(
      ourProducts,
      products,
      platform,
    );

    // SWOT analizi yap
    const { strengths, weaknesses, opportunities, threats } =
      this.performSwotAnalysis(
        storeData,
        products,
        ourProducts,
        commonProducts,
      );

    return {
      competitorStoreUrl: competitorUrl,
      platform,
      storeInfo: {
        name: storeData.storeName,
        rating: storeData.rating,
        followerCount: storeData.followerCount,
        productCount: storeData.productCount,
      },
      products: products.map((p) => ({
        productId: p.title, // Use title as ID for scraped products
        title: p.title,
        price: p.price,
        rating: p.rating,
        reviewCount: p.reviewCount,
        platform,
        storeName: storeData.storeName,
        url: competitorUrl,
        image: p.images?.[0],
        stockStatus: p.stockStatus,
      })),
      commonProducts,
      strengths,
      weaknesses,
      opportunities,
      threats,
      analyzedAt: new Date(),
    };
  }

  /**
   * Fiyat karşılaştırması yap
   */
  async comparePrices(
    productQuery: string,
    platforms: Platform[],
    ourProductPrice?: number,
  ): Promise<PriceComparison> {
    this.logger.log(`Comparing prices for: ${productQuery}`);

    const competitorPrices: PriceComparison['competitorPrices'] = [];

    for (const platform of platforms) {
      try {
        // Platformda ürün ara (bridge searchProducts varsa kullan)
        const results = await this.marketplaceService.searchProducts(
          platform,
          productQuery,
          5,
        );

        for (const result of results) {
          const price = Number(result.price || result.salePrice || 0);
          if (price > 0) {
            competitorPrices.push({
              platform,
              storeName: String(
                result.storeName || result.sellerName || platform,
              ),
              price,
              difference: ourProductPrice ? price - ourProductPrice : 0,
              differencePercent: ourProductPrice
                ? ((price - ourProductPrice) / ourProductPrice) * 100
                : 0,
              url: String(result.url || ''),
            });
          }
        }
      } catch (error) {
        this.logger.warn(
          `Price search failed for ${platform}: ${(error as Error).message}`,
        );
      }
    }

    // Fiyat istatistikleri
    const prices = competitorPrices.map((p) => p.price);
    const cheapest =
      prices.length > 0
        ? {
            platform:
              competitorPrices[prices.indexOf(Math.min(...prices))].platform,
            price: Math.min(...prices),
          }
        : null;
    const mostExpensive =
      prices.length > 0
        ? {
            platform:
              competitorPrices[prices.indexOf(Math.max(...prices))].platform,
            price: Math.max(...prices),
          }
        : null;
    const averageMarketPrice =
      prices.length > 0 ? prices.reduce((a, b) => a + b, 0) / prices.length : 0;

    // Öneri oluştur
    let recommendation = 'Pazar fiyatları analiz ediliyor';
    if (ourProductPrice && cheapest) {
      if (ourProductPrice <= cheapest.price * 1.05) {
        recommendation = 'Fiyatınız pazarda rekabetçi düzeyde';
      } else if (ourProductPrice > cheapest.price * 1.2) {
        recommendation =
          'Fiyatınız pazar ortalamasının üzerinde - indirim düşünün';
      } else {
        recommendation = 'Fiyatınız pazar ortalamasında';
      }
    }

    return {
      productName: productQuery,
      ourPrice: ourProductPrice || 0,
      competitorPrices,
      cheapest,
      mostExpensive,
      averageMarketPrice: Math.round(averageMarketPrice * 100) / 100,
      recommendation,
    };
  }

  /**
   * Çoklu rakip analizi
   */
  async analyzeMultipleCompetitors(
    competitorUrls: Array<{ url: string; platform: Platform }>,
    ourTenantId: string,
  ): Promise<{
    analyses: CompetitorAnalysis[];
    summary: {
      totalCompetitors: number;
      totalCompetitorProducts: number;
      averageCompetitorRating: number;
      priceGapAnalysis: string;
    };
  }> {
    const analyses: CompetitorAnalysis[] = [];

    for (const { url, platform } of competitorUrls) {
      try {
        const analysis = await this.analyzeCompetitor(
          url,
          platform,
          ourTenantId,
        );
        analyses.push(analysis);
      } catch (error) {
        this.logger.error(
          `Failed to analyze ${url}: ${(error as Error).message}`,
        );
      }
    }

    const totalCompetitorProducts = analyses.reduce(
      (sum, a) => sum + a.storeInfo.productCount,
      0,
    );
    const averageCompetitorRating =
      analyses.length > 0
        ? analyses.reduce((sum, a) => sum + a.storeInfo.rating, 0) /
          analyses.length
        : 0;

    return {
      analyses,
      summary: {
        totalCompetitors: analyses.length,
        totalCompetitorProducts,
        averageCompetitorRating:
          Math.round(averageCompetitorRating * 100) / 100,
        priceGapAnalysis: this.generatePriceGapSummary(analyses),
      },
    };
  }

  private async getOurProducts(
    tenantId: string,
  ): Promise<Array<{ title: string; price: number; sku: string }>> {
    // Prisma'dan ürünleri çek
    // Şimdilik basit bir implementasyon - gerçek implementasyonda PrismaService kullanılmalı
    return [];
  }

  private findCommonProducts(
    ourProducts: Array<{ title: string; price: number; sku: string }>,
    competitorProducts: ScrapedProductData[],
    platform: Platform,
  ): CompetitorAnalysis['commonProducts'] {
    const common: CompetitorAnalysis['commonProducts'] = [];

    for (const ourProduct of ourProducts) {
      // Başlık benzerliği kontrolü (basit string matching)
      const matchingProduct = competitorProducts.find((cp) => {
        const ourTitleLower = ourProduct.title.toLowerCase();
        const compTitleLower = cp.title.toLowerCase();
        return (
          ourTitleLower.includes(compTitleLower.substring(0, 20)) ||
          compTitleLower.includes(ourTitleLower.substring(0, 20))
        );
      });

      if (matchingProduct) {
        const priceDifference = matchingProduct.price - ourProduct.price;
        const priceDifferencePercent = ourProduct.price
          ? (priceDifference / ourProduct.price) * 100
          : 0;

        common.push({
          ourProduct,
          competitorProduct: {
            productId: matchingProduct.title,
            title: matchingProduct.title,
            price: matchingProduct.price,
            rating: matchingProduct.rating,
            reviewCount: matchingProduct.reviewCount,
            platform,
            storeName: 'Rakip Mağaza',
            url: '',
            stockStatus: matchingProduct.stockStatus,
          },
          priceDifference,
          priceDifferencePercent,
        });
      }
    }

    return common;
  }

  private performSwotAnalysis(
    storeData: any,
    products: ScrapedProductData[],
    ourProducts: Array<{ title: string; price: number }>,
    commonProducts: CompetitorAnalysis['commonProducts'],
  ): {
    strengths: string[];
    weaknesses: string[];
    opportunities: string[];
    threats: string[];
  } {
    const strengths: string[] = [];
    const weaknesses: string[] = [];
    const opportunities: string[] = [];
    const threats: string[] = [];

    // Güçlü yönler
    if (storeData.rating > 9.0) {
      strengths.push('Rakip yüksek müşteri memnuniyetine sahip');
    }
    if (storeData.followerCount > 5000) {
      strengths.push('Rakibin geniş müşteri kitlesi var');
    }
    if (products.length > 100) {
      strengths.push('Rakip geniş ürün yelpazesi sunuyor');
    }

    // Zayıf yönler
    if (storeData.rating < 8.0) {
      weaknesses.push('Rakip düşük müşteri memnuniyeti');
    }
    const lowStockProducts = products.filter((p) => !p.stockStatus).length;
    if (lowStockProducts > products.length * 0.3) {
      weaknesses.push('Rakip stok sorunları yaşıyor');
    }

    // Fırsatlar
    const ourCheaperProducts = commonProducts.filter(
      (cp) => cp.priceDifference < 0,
    );
    if (ourCheaperProducts.length > 0) {
      opportunities.push(
        `${ourCheaperProducts.length} üründe fiyat avantajına sahibiz`,
      );
    }
    if (products.length < ourProducts.length) {
      opportunities.push('Ürün çeşitliliğinde avantajlıyız');
    }

    // Tehditler
    const theirCheaperProducts = commonProducts.filter(
      (cp) => cp.priceDifference > 0,
    );
    if (theirCheaperProducts.length > 0) {
      threats.push(`${theirCheaperProducts.length} üründe rakip daha ucuz`);
    }
    if (storeData.followerCount > 10000) {
      threats.push('Rakip güçlü marka bilinirliğine sahip');
    }

    return { strengths, weaknesses, opportunities, threats };
  }

  private generatePriceGapSummary(analyses: CompetitorAnalysis[]): string {
    const allPriceGaps = analyses.flatMap((a) =>
      a.commonProducts.map((cp) => cp.priceDifferencePercent),
    );

    if (allPriceGaps.length === 0) {
      return 'Ortak ürün bulunamadı';
    }

    const avgGap =
      allPriceGaps.reduce((a, b) => a + b, 0) / allPriceGaps.length;

    if (avgGap < -10) {
      return 'Genel olarak rakiplerden daha ucuzsunuz (%10+ avantaj)';
    } else if (avgGap > 10) {
      return 'Rakipler genel olarak daha ucuz - fiyat stratejisi gözden geçirilmeli';
    } else {
      return 'Fiyatlar pazar ortalamasında';
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';

interface CoupangProduct {
  productId: string;
  title: string;
  price: number;
  salePrice: number;
  stockCount: number;
  rating: number;
  reviewCount: number;
  url: string;
  images: string[];
  vendorName: string;
  vendorId: string;
  rocketDelivery: boolean;
  freeShipping: boolean;
  category: string;
  salesCount: number;
}

@Injectable()
export class CoupangBridge implements MarketplaceBridge {
  private readonly logger = new Logger(CoupangBridge.name);
  private readonly apiUrl = 'https://api-gateway.coupang.com/v2/providers';

  constructor(
    private readonly accessKey: string,
    private readonly secretKey: string,
    private readonly vendorId: string,
    private readonly scrapingService: ScrapingService,
  ) {}

  private generateSignature(date: string): string {
    const message = date + '\n' + this.accessKey + '\n' + this.secretKey;
    return `HmacSHA256_${message}`;
  }

  private getHeaders(): Record<string, string> {
    const date = new Date().toISOString();
    return {
      Authorization: `${this.accessKey}:${this.generateSignature(date)}`,
      'X-Requested-By': this.vendorId,
      'Content-Type': 'application/json',
    };
  }

  async syncProducts(): Promise<any> {
    try {
      const response = await fetch(
        `${this.apiUrl}/marketplace_openapi/apis/api/v1/vendor/inventory`,
        { headers: this.getHeaders() },
      );

      if (!response.ok) {
        return {
          success: false,
          platform: 'COUPANG',
          error: `HTTP ${response.status}`,
        };
      }

      const data = await response.json();
      return {
        success: true,
        platform: 'COUPANG',
        count: data.data?.length || 0,
      };
    } catch (error) {
      return {
        success: false,
        platform: 'COUPANG',
        error: (error as Error).message,
      };
    }
  }

  async syncOrders(): Promise<any> {
    try {
      const response = await fetch(
        `${this.apiUrl}/marketplace_openapi/apis/api/v1/vendor/orders`,
        { headers: this.getHeaders() },
      );
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();
      return { success: true, platform: 'COUPANG', orders: data.data || [] };
    } catch (error) {
      return {
        success: false,
        platform: 'COUPANG',
        error: (error as Error).message,
      };
    }
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    try {
      const response = await fetch(
        `${this.apiUrl}/marketplace_openapi/apis/api/v1/vendor/inventory/${sku}`,
        {
          method: 'PUT',
          headers: this.getHeaders(),
          body: JSON.stringify({ quantity: stock }),
        },
      );
      return { success: response.ok, sku, stock, platform: 'COUPANG' };
    } catch (error) {
      throw error;
    }
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    try {
      const response = await fetch(
        `${this.apiUrl}/marketplace_openapi/apis/api/v1/vendor/products/${sku}/price`,
        {
          method: 'PUT',
          headers: this.getHeaders(),
          body: JSON.stringify({ price }),
        },
      );
      return { success: response.ok, sku, price, platform: 'COUPANG' };
    } catch (error) {
      throw error;
    }
  }

  async getStoreInfo(storeId: string): Promise<any> {
    try {
      const url = `https://www.coupang.com/vp/products?vendorItemId=${storeId}`;
      const scraped = await this.scrapingService.scrapeStore(url, 'COUPANG');
      return {
        storeId,
        storeName: scraped?.storeName || storeId,
        platform: 'COUPANG',
        country: 'South Korea',
        rocketDelivery: true,
      };
    } catch (error) {
      throw error;
    }
  }

  async getStoreProducts(
    storeId?: string,
    limit: number = 10,
  ): Promise<CoupangProduct[]> {
    try {
      const response = await fetch(
        `${this.apiUrl}/marketplace_openapi/apis/api/v1/vendor/products?limit=${limit}`,
        { headers: this.getHeaders() },
      );
      const data = await response.json();
      return (data.data || []).map((item: any) => ({
        productId: item.productId,
        title: item.productName,
        price: item.originalPrice,
        salePrice: item.salePrice || item.originalPrice,
        stockCount: item.quantity || 0,
        rating: item.rating || 0,
        reviewCount: item.reviewCount || 0,
        url: item.productUrl,
        images: [item.imageUrl],
        vendorName: item.vendorName,
        vendorId: item.vendorId,
        rocketDelivery: item.rocketDelivery || false,
        freeShipping: item.freeShipping || false,
        category: item.categoryName,
        salesCount: item.salesCount || 0,
      }));
    } catch (error) {
      throw error;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';
import {
  MarketplaceAnalysisResponse,
  computeConfidenceFromSources,
} from './analysis.types';

interface EbayProduct {
  productId: string;
  title: string;
  price: number;
  salePrice: number;
  stockCount: number;
  rating: number;
  reviewCount: number;
  url: string;
  images: string[];
  sellerName: string;
  sellerUrl: string;
  condition: string;
  listingStatus: string;
}

@Injectable()
export class EbayBridge implements MarketplaceBridge {
  private readonly logger = new Logger(EbayBridge.name);
  private readonly apiUrl = 'https://api.ebay.com/sell/inventory/v1';
  private readonly tradingApiUrl = 'https://api.ebay.com/wsapi';

  constructor(
    private readonly appId: string,
    private readonly certId: string,
    private readonly devId: string,
    private readonly authToken: string,
    private readonly scrapingService: ScrapingService,
    private readonly isSandbox: boolean = false,
  ) {}

  private getBaseUrl(): string {
    return this.isSandbox
      ? 'https://api.sandbox.ebay.com/sell/inventory/v1'
      : this.apiUrl;
  }

  async syncProducts(): Promise<any> {
    this.logger.log('Syncing products from eBay');
    try {
      const token = await this.getOAuthToken();

      const response = await fetch(`${this.getBaseUrl()}/inventory_item`, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
          'X-EBAY-C-MARKETPLACE-ID': 'EBAY_US',
        },
      });

      if (!response.ok) {
        this.logger.warn(`eBay syncProducts failed: ${response.status}`);
        return {
          success: false,
          platform: 'EBAY',
          error: `HTTP ${response.status}`,
        };
      }

      const data = await response.json();
      const products = data.inventoryItems || [];

      return {
        success: true,
        platform: 'EBAY',
        count: products.length,
        products: products.map(this.mapEbayProduct),
      };
    } catch (error) {
      this.logger.warn(`eBay syncProducts error: ${(error as Error).message}`);
      return {
        success: false,
        platform: 'EBAY',
        error: (error as Error).message,
      };
    }
  }

  async syncOrders(): Promise<any> {
    try {
      const token = await this.getOAuthToken();

      const response = await fetch(
        `https://api.ebay.com/sell/fulfillment/v1/order`,
        {
          method: 'GET',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
            'X-EBAY-C-MARKETPLACE-ID': 'EBAY_US',
          },
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      return {
        success: true,
        platform: 'EBAY',
        orders: data.orders || [],
      };
    } catch (error) {
      this.logger.warn(`eBay syncOrders error: ${(error as Error).message}`);
      return {
        success: false,
        platform: 'EBAY',
        error: (error as Error).message,
      };
    }
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    try {
      const token = await this.getOAuthToken();

      const response = await fetch(
        `${this.getBaseUrl()}/inventory_item/${sku}`,
        {
          method: 'PUT',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
            'X-EBAY-C-MARKETPLACE-ID': 'EBAY_US',
          },
          body: JSON.stringify({
            availability: {
              shipToLocationAvailability: {
                quantity: stock,
              },
            },
          }),
        },
      );

      if (response.status === 429 || response.status >= 500) {
        throw new Error(`eBay stock update failed: HTTP ${response.status}`);
      }

      return { success: response.ok, sku, stock, platform: 'EBAY' };
    } catch (error) {
      this.logger.warn(`eBay updateStock error: ${(error as Error).message}`);
      throw error;
    }
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    try {
      const token = await this.getOAuthToken();

      // Get current listing
      const getResponse = await fetch(
        `${this.getBaseUrl()}/inventory_item/${sku}`,
        {
          method: 'GET',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
        },
      );

      if (!getResponse.ok) {
        throw new Error(`Failed to get item: HTTP ${getResponse.status}`);
      }

      const item = await getResponse.json();

      // Update with new price
      const response = await fetch(
        `${this.getBaseUrl()}/inventory_item/${sku}`,
        {
          method: 'PUT',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
            'X-EBAY-C-MARKETPLACE-ID': 'EBAY_US',
          },
          body: JSON.stringify({
            ...item,
            pricingSummary: {
              ...item.pricingSummary,
              price: {
                currency: 'USD',
                value: price.toString(),
              },
            },
          }),
        },
      );

      if (response.status === 429 || response.status >= 500) {
        throw new Error(`eBay price update failed: HTTP ${response.status}`);
      }

      return { success: response.ok, sku, price, platform: 'EBAY' };
    } catch (error) {
      this.logger.warn(`eBay updatePrice error: ${(error as Error).message}`);
      throw error;
    }
  }

  async getStoreInfo(storeId: string): Promise<any> {
    try {
      const token = await this.getOAuthToken();

      const response = await fetch(`https://api.ebay.com/ws/api.dll`, {
        method: 'POST',
        headers: {
          'X-EBAY-API-COMPATIBILITY-LEVEL': '967',
          'X-EBAY-API-CALL-NAME': 'GetSellerDashboard',
          'X-EBAY-API-SITEID': '0',
          'Content-Type': 'text/xml',
        },
        body: this.buildTradingApiRequest('GetSellerDashboard'),
      });

      if (!response.ok) {
        // Fallback to scraping
        const url = `https://www.ebay.com/str/${storeId}`;
        const scraped = await this.scrapingService.scrapeStore(url, 'EBAY');
        if (scraped) {
          return {
            storeId,
            storeName: scraped.storeName || storeId,
            totalProducts: scraped.productCount ?? 0,
            averageRating: scraped.rating ?? 0,
            totalReviews: scraped.totalReviews ?? 0,
            platform: 'EBAY',
          };
        }
        throw new Error('eBay store info could not be retrieved');
      }

      const xmlText = await response.text();
      // Parse XML response (simplified)
      return {
        storeId,
        platform: 'EBAY',
        rawData: xmlText,
      };
    } catch (error) {
      this.logger.error(`eBay getStoreInfo error: ${(error as Error).message}`);
      throw error;
    }
  }

  async getStoreProducts(
    storeId?: string,
    limit: number = 10,
  ): Promise<EbayProduct[]> {
    try {
      const token = await this.getOAuthToken();

      const response = await fetch(
        `${this.getBaseUrl()}/inventory_item?limit=${limit}`,
        {
          method: 'GET',
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
            'X-EBAY-C-MARKETPLACE-ID': 'EBAY_US',
          },
        },
      );

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      const items = data.inventoryItems || [];

      return items
        .slice(0, limit)
        .map((item: any, index: number) => this.mapEbayProduct(item, index));
    } catch (error) {
      this.logger.error(
        `eBay getStoreProducts error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  private async getOAuthToken(): Promise<string> {
    // OAuth token implementation
    // In production, this should use proper OAuth flow with refresh tokens
    return this.authToken;
  }

  private buildTradingApiRequest(callName: string): string {
    return `<?xml version="1.0" encoding="utf-8"?>
<eBayCredentials xmlns="urn:ebay:apis:eBLBaseComponents">
    <RequesterCredentials>
        <eBayAuthToken>${this.authToken}</eBayAuthToken>
    </RequesterCredentials>
</eBayCredentials>`;
  }

  private mapEbayProduct(item: any, index: number = 0): EbayProduct {
    return {
      productId: item.sku || `EBAY-${index}`,
      title: item.product?.title || 'Unknown',
      price: parseFloat(item.pricingSummary?.price?.value) || 0,
      salePrice: parseFloat(item.pricingSummary?.price?.value) || 0,
      stockCount: item.availability?.shipToLocationAvailability?.quantity || 0,
      rating: 0,
      reviewCount: 0,
      url: item.product?.imageUrls?.[0] || '',
      images: item.product?.imageUrls || [],
      sellerName: '',
      sellerUrl: '',
      condition: item.condition || 'NEW',
      listingStatus: item.status || 'ACTIVE',
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';

interface EtsyProduct {
  productId: string;
  title: string;
  price: number;
  salePrice: number;
  stockCount: number;
  rating: number;
  reviewCount: number;
  url: string;
  images: string[];
  shopName: string;
  shopUrl: string;
  materials: string[];
  tags: string[];
  processingTime: string;
  shippingFrom: string;
  isCustomizable: boolean;
}

@Injectable()
export class EtsyBridge implements MarketplaceBridge {
  private readonly logger = new Logger(EtsyBridge.name);
  private readonly apiUrl = 'https://openapi.etsy.com/v3';

  constructor(
    private readonly apiKey: string,
    private readonly apiSecret: string,
    private readonly accessToken: string,
    private readonly scrapingService: ScrapingService,
  ) {}

  private async makeAuthenticatedRequest(
    url: string,
    options: RequestInit = {},
  ): Promise<Response> {
    return fetch(url, {
      ...options,
      headers: {
        ...options.headers,
        'x-api-key': this.apiKey,
        Authorization: `Bearer ${this.accessToken}`,
      },
    });
  }

  async syncProducts(): Promise<any> {
    this.logger.log('Syncing products from Etsy');
    try {
      // Get shop listings
      const response = await this.makeAuthenticatedRequest(
        `${this.apiUrl}/application/shops/me/listings/active`,
      );

      if (!response.ok) {
        this.logger.warn(`Etsy syncProducts failed: ${response.status}`);
        return {
          success: false,
          platform: 'ETSY',
          error: `HTTP ${response.status}`,
        };
      }

      const data = await response.json();
      const listings = data.results || [];

      return {
        success: true,
        platform: 'ETSY',
        count: listings.length,
        products: listings.map(this.mapEtsyProduct),
      };
    } catch (error) {
      this.logger.warn(`Etsy syncProducts error: ${(error as Error).message}`);
      return {
        success: false,
        platform: 'ETSY',
        error: (error as Error).message,
      };
    }
  }

  async syncOrders(): Promise<any> {
    try {
      const response = await this.makeAuthenticatedRequest(
        `${this.apiUrl}/application/shops/me/receipts/open`,
      );

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      return {
        success: true,
        platform: 'ETSY',
        orders: data.results || [],
      };
    } catch (error) {
      this.logger.warn(`Etsy syncOrders error: ${(error as Error).message}`);
      return {
        success: false,
        platform: 'ETSY',
        error: (error as Error).message,
      };
    }
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    try {
      const response = await this.makeAuthenticatedRequest(
        `${this.apiUrl}/application/listings/${sku}/inventory`,
        {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            products: [
              {
                sku: sku,
                offerings: [
                  {
                    quantity: stock,
                    is_enabled: stock > 0,
                  },
                ],
              },
            ],
          }),
        },
      );

      if (response.status === 429 || response.status >= 500) {
        throw new Error(`Etsy stock update failed: HTTP ${response.status}`);
      }

      return { success: response.ok, sku, stock, platform: 'ETSY' };
    } catch (error) {
      this.logger.warn(`Etsy updateStock error: ${(error as Error).message}`);
      throw error;
    }
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    try {
      const response = await this.makeAuthenticatedRequest(
        `${this.apiUrl}/application/listings/${sku}`,
        {
          method: 'PUT',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            price: price,
          }),
        },
      );

      if (response.status === 429 || response.status >= 500) {
        throw new Error(`Etsy price update failed: HTTP ${response.status}`);
      }

      return { success: response.ok, sku, price, platform: 'ETSY' };
    } catch (error) {
      this.logger.warn(`Etsy updatePrice error: ${(error as Error).message}`);
      throw error;
    }
  }

  async getStoreInfo(storeId: string): Promise<any> {
    try {
      // Try API first
      const response = await this.makeAuthenticatedRequest(
        `${this.apiUrl}/application/shops/${storeId}`,
      );

      if (response.ok) {
        const data = await response.json();
        return {
          storeId: data.shop_id?.toString() || storeId,
          storeName: data.shop_name || storeId,
          totalProducts: data.listing_active_count || 0,
          averageRating: data.review_average || 0,
          totalReviews: data.review_count || 0,
          platform: 'ETSY',
          shopUrl: data.url,
          location: data.location_formatted_address || '',
          isVacation: data.is_vacation || false,
        };
      }

      // Fallback to scraping
      const url = `https://www.etsy.com/shop/${storeId}`;
      const scraped = await this.scrapingService.scrapeStore(url, 'ETSY');
      if (scraped) {
        return {
          storeId,
          storeName: scraped.storeName || storeId,
          totalProducts: scraped.productCount ?? 0,
          averageRating: scraped.rating ?? 0,
          totalReviews: scraped.totalReviews ?? 0,
          platform: 'ETSY',
        };
      }

      throw new Error('Etsy shop info could not be retrieved');
    } catch (error) {
      this.logger.error(`Etsy getStoreInfo error: ${(error as Error).message}`);
      throw error;
    }
  }

  async getStoreProducts(
    storeId?: string,
    limit: number = 10,
  ): Promise<EtsyProduct[]> {
    try {
      const response = await this.makeAuthenticatedRequest(
        `${this.apiUrl}/application/shops/${storeId}/listings/active?limit=${limit}`,
      );

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      const data = await response.json();
      const listings = data.results || [];

      return listings
        .slice(0, limit)
        .map((item: any, index: number) => this.mapEtsyProduct(item, index));
    } catch (error) {
      this.logger.error(
        `Etsy getStoreProducts error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  private mapEtsyProduct(item: any, index: number = 0): EtsyProduct {
    return {
      productId: item.listing_id?.toString() || `ETSY-${index}`,
      title: item.title || 'Unknown',
      price: parseFloat(item.price?.amount) || 0,
      salePrice: parseFloat(item.price?.amount) || 0,
      stockCount: item.quantity || 0,
      rating: item.review_average || 0,
      reviewCount: item.num_favorers || 0,
      url: item.url || '',
      images: item.images?.map((img: any) => img.url_570xN) || [],
      shopName: item.shop_name || '',
      shopUrl: item.shop_url || '',
      materials: item.materials || [],
      tags: item.tags || [],
      processingTime: item.processing_min_display_days
        ? `${item.processing_min_display_days}-${item.processing_max_display_days} days`
        : '',
      shippingFrom: item.shipping_profile?.origin_country_iso || '',
      isCustomizable: item.is_customizable || false,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';
import {
  MarketplaceAnalysisResponse,
  computeConfidenceFromSources,
} from './analysis.types';

interface HepsiburadaStoreData {
  storeId: string;
  storeName: string;
  categoryCount: number;
  totalProducts: number;
  averageRating: number;
  totalReviews: number;
  followersCount: number;
  establishedDate: string;
  responseTimeHours: number | null;
}

interface HepsiburadaProduct {
  productId: string;
  title: string;
  salePrice: number;
  currencyCode: string;
  listingStatus: string;
  stockCount: number;
  categoryId: string;
  categoryName: string;
  images: string[];
  rating: number;
  reviewCount: number;
  hasFreeCargo: boolean;
  merchantSku: string;
}

@Injectable()
export class HepsiburadaBridge implements MarketplaceBridge {
  private readonly logger = new Logger(HepsiburadaBridge.name);
  private readonly baseUrl = 'https://listing-external-sit.hepsiburada.com';
  private readonly requestDelayMs = 300;
  private readonly maxApiPages = 5;

  constructor(
    private readonly apiKey: string,
    private readonly merchantId: string,
    private readonly scrapingService: ScrapingService,
  ) {}

  /**
   * Mağaza bilgilerini Hepsiburada API'sinden çek
   */
  async getStoreInfo(storeId?: string): Promise<HepsiburadaStoreData> {
    try {
      // Use ScrapingService
      const url = `https://www.hepsiburada.com/magaza/${(storeId || this.merchantId).toLowerCase()}`;
      const scrapedData = await this.scrapingService.scrapeStore(
        url,
        'HEPSIBURADA',
      );

      if (scrapedData) {
        return {
          storeId: storeId || this.merchantId,
          storeName: scrapedData.storeName,
          categoryCount: Math.ceil(scrapedData.productCount / 15),
          totalProducts: scrapedData.productCount,
          averageRating: scrapedData.rating,
          totalReviews: scrapedData.totalReviews ?? 0,
          followersCount: scrapedData.followerCount,
          establishedDate: scrapedData.establishedDate || '',
          responseTimeHours: null,
        };
      }

      throw new Error('Hepsiburada mağaza verisi alınamadı');
    } catch (error) {
      this.logger.error(
        `Hepsiburada store info error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  /**
   * Mağazanın ürünlerini çek
   */
  async getStoreProducts(
    storeId?: string,
    limit: number = 10,
  ): Promise<HepsiburadaProduct[]> {
    try {
      const resolvedStoreId = storeId || this.merchantId;

      // Prefer official API when credentials exist.
      const apiProducts = await this.getStoreProductsFromApi(
        resolvedStoreId,
        limit,
      );
      if (apiProducts.length > 0) {
        return apiProducts;
      }

      this.logger.warn(
        `Hepsiburada API ürün çekimi boş döndü, scraping fallback çalışacak. storeId=${resolvedStoreId}`,
      );
      const url = `https://www.hepsiburada.com/magaza/${resolvedStoreId.toLowerCase()}`;
      const scrapedProducts = await this.scrapingService.scrapeStoreProducts(
        url,
        'HEPSIBURADA',
        limit,
      );

      return scrapedProducts.map((product, index) => ({
        productId: `HB-${resolvedStoreId}-${index + 1}`,
        title: product.title,
        salePrice: product.price,
        currencyCode: 'TRY',
        listingStatus: product.stockStatus ? 'ACTIVE' : 'OUT_OF_STOCK',
        stockCount: product.stockStatus ? 40 : 0,
        categoryId: 'UNKNOWN',
        categoryName: 'Genel',
        images: product.images,
        rating: product.rating,
        reviewCount: product.reviewCount,
        hasFreeCargo: false,
        merchantSku: `HB-SKU-${index + 1}`,
      }));
    } catch (error) {
      this.logger.error(
        `Hepsiburada products error: ${(error as Error).message}`,
      );
      throw error;
    }
  }

  private async getStoreProductsFromApi(
    storeId: string,
    limit: number,
  ): Promise<HepsiburadaProduct[]> {
    if (!this.apiKey || this.apiKey === 'public') {
      return [];
    }

    const pageSize = Math.min(100, Math.max(10, limit));
    const results: HepsiburadaProduct[] = [];

    for (
      let page = 1;
      page <= this.maxApiPages && results.length < limit;
      page++
    ) {
      const payload = await this.requestHepsiburada(storeId, page, pageSize);
      if (!payload) break;

      const items = this.extractProductArray(payload);
      if (!items.length) break;

      for (const item of items) {
        if (results.length >= limit) break;
        results.push(this.mapApiProduct(item, storeId));
      }

      if (items.length < pageSize) {
        break;
      }

      await this.delay(this.requestDelayMs);
    }

    return results;
  }

  private async requestHepsiburada(
    storeId: string,
    page: number,
    size: number,
  ): Promise<Record<string, unknown> | null> {
    const endpoints = [
      `${this.baseUrl}/ListingExternalService/v1/Listings/merchantid/${encodeURIComponent(storeId)}?page=${page}&size=${size}`,
      `${this.baseUrl}/ListingExternalService/v1/Listings?merchantId=${encodeURIComponent(storeId)}&page=${page}&size=${size}`,
    ];

    for (const url of endpoints) {
      try {
        const response = await fetch(url, {
          headers: {
            Authorization: `Basic ${this.apiKey}`,
            'Content-Type': 'application/json',
            Accept: 'application/json',
            'User-Agent': 'PazarYonetimi/1.0',
          },
        });

        if (response.status === 429) {
          this.logger.warn(`Hepsiburada rate limit: ${url}`);
          await this.delay(1200);
          return null;
        }

        if (!response.ok) {
          continue;
        }

        return (await response.json()) as Record<string, unknown>;
      } catch (error) {
        this.logger.warn(
          `Hepsiburada API request error: ${(error as Error).message}`,
        );
      }
    }

    return null;
  }

  private extractProductArray(
    payload: Record<string, unknown>,
  ): Record<string, unknown>[] {
    const data = payload.data;
    if (Array.isArray(data)) return data as Record<string, unknown>[];

    if (data && typeof data === 'object') {
      const listings = (data as { listings?: unknown }).listings;
      if (Array.isArray(listings)) return listings as Record<string, unknown>[];
    }

    const items = payload.items;
    if (Array.isArray(items)) return items as Record<string, unknown>[];

    return [];
  }

  private mapApiProduct(
    item: Record<string, unknown>,
    storeId: string,
  ): HepsiburadaProduct {
    const imagesRaw = item.images;
    const images = Array.isArray(imagesRaw)
      ? imagesRaw
          .map((img) => {
            if (typeof img === 'string') return img;
            if (
              img &&
              typeof img === 'object' &&
              'url' in img &&
              typeof img.url === 'string'
            )
              return img.url;
            return '';
          })
          .filter((v): v is string => Boolean(v))
      : [];

    const stock = Number(item.availableStock ?? item.stock ?? 0);
    const price = Number(item.price ?? item.salePrice ?? 0);

    return {
      productId: String(
        item.listingId ?? item.id ?? `HB-${storeId}-${Date.now()}`,
      ),
      title: String(item.title ?? item.productName ?? 'İsimsiz Ürün'),
      salePrice: Number.isFinite(price) ? price : 0,
      currencyCode: String(item.currency ?? 'TRY'),
      listingStatus: String(
        item.status ?? (stock > 0 ? 'ACTIVE' : 'OUT_OF_STOCK'),
      ),
      stockCount: Number.isFinite(stock) ? stock : 0,
      categoryId: String(item.categoryId ?? 'UNKNOWN'),
      categoryName: String(item.categoryName ?? 'Genel'),
      images,
      rating: 0,
      reviewCount: 0,
      hasFreeCargo: Boolean(item.freeShipping),
      merchantSku: String(
        item.merchantSku ??
          item.stockCode ??
          item.sku ??
          `HB-SKU-${Date.now()}`,
      ),
    };
  }

  private async delay(ms: number): Promise<void> {
    await new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * SEO ve Performans analizi yap
   */
  async analyzeStoreSEO(
    storeId?: string,
  ): Promise<MarketplaceAnalysisResponse> {
    try {
      const storeInfo = await this.getStoreInfo(storeId);
      const products = await this.getStoreProducts(storeId, 20);

      // SEO Score hesabı
      const seoScore = this.calculateSEOScore(storeInfo, products);

      const metricSources = {
        storeName: 'scraped',
        rating: 'scraped',
        followers: 'scraped',
        totalProducts: 'scraped',
        responseTime: 'not_available',
        monthlyTraffic: 'not_available',
        monthlyTurnover: 'not_available',
        titleOptimization: 'calculated',
        imageOptimization: 'calculated',
        priceCompetitiveness: 'calculated',
        stockHealth: 'calculated',
        ratingTrend: 'scraped',
        reviewCount: 'scraped',
      } as const;

      return {
        platform: 'HEPSIBURADA',
        storeId: storeInfo.storeId,
        storeName: storeInfo.storeName,
        seoScore,
        dataSources: {
          overall: 'scraped+calculated',
          seoScore: 'calculated',
          products: 'api_or_scraped',
          metrics: metricSources,
          reasons: {
            responseTime:
              'Hepsiburada public source yanit suresi bilgisini acik olarak saglamiyor.',
            monthlyTraffic:
              'Aylik trafik verisi platform public endpointlerinde bulunmuyor.',
            monthlyTurnover:
              'Aylik ciro verisi platform public endpointlerinde bulunmuyor.',
          },
          evidence: {
            adapter: 'hepsiburada.bridge',
            productSampleSize: products.length,
            hasCredentials: Boolean(this.apiKey && this.apiKey !== 'public'),
          },
        },
        confidence: computeConfidenceFromSources(metricSources),
        metrics: {
          storeName: storeInfo.storeName,
          rating: storeInfo.averageRating / 2, // Convert 10-scale to 5-scale for frontend
          followers: storeInfo.followersCount,
          totalProducts: storeInfo.totalProducts,
          responseTime:
            storeInfo.responseTimeHours !== null
              ? `${storeInfo.responseTimeHours} saat`
              : undefined,
          titleOptimization: this.analyzeTitles(products),
          imageOptimization: this.analyzeImages(products),
          priceCompetitiveness: this.analyzePrices(products),
          stockHealth: this.analyzeStock(products),
          ratingTrend: storeInfo.averageRating / 2,
          reviewCount: storeInfo.totalReviews,
        },
        products: products.map((p) => ({
          name: p.title,
          price: p.salePrice,
          rating: p.rating,
          reviews: p.reviewCount,
          stock: p.stockCount,
          hasFreeCargo: p.hasFreeCargo,
        })),
        recommendations: this.generateRecommendations(storeInfo, products),
        timestamp: new Date(),
      };
    } catch (error) {
      this.logger.error(`SEO analysis error: ${(error as Error).message}`);
      throw error;
    }
  }

  private calculateSEOScore(
    storeInfo: HepsiburadaStoreData,
    products: HepsiburadaProduct[],
  ): number {
    let score = 50; // Base score

    // Rating (max +15) - normalized from 10
    score += (storeInfo.averageRating / 10) * 15;

    // Review count (max +10)
    const reviewBonus = Math.min(storeInfo.totalReviews / 1000, 10);
    score += reviewBonus;

    // Followers (max +10)
    const followerBonus = Math.min(storeInfo.followersCount / 2000, 10);
    score += followerBonus;

    // Stock health (max +10)
    const avgStock =
      products.reduce((sum, p) => sum + (p.stockCount > 0 ? 1 : 0), 0) /
      products.length;
    score += avgStock * 10;

    // Response time (max +5)
    if (storeInfo.responseTimeHours !== null) {
      if (storeInfo.responseTimeHours < 4) score += 5;
      else if (storeInfo.responseTimeHours < 12) score += 3;
    }

    return Math.min(Math.round(score), 100);
  }

  private analyzeTitles(products: HepsiburadaProduct[]): number {
    const score = 0;
    let validCount = 0;

    products.forEach((p) => {
      const title = p.title;
      // Hepsiburada specific simple checks
      if (title.length >= 20 && title.length <= 150) validCount++;
      if (title.includes(p.categoryName)) validCount++;
    });

    return Math.round((validCount / (products.length * 2)) * 100);
  }

  private analyzeImages(products: HepsiburadaProduct[]): number {
    let validCount = 0;
    products.forEach((p) => {
      if (p.images && p.images.length >= 2) validCount++;
    });
    return Math.round((validCount / products.length) * 100);
  }

  private analyzePrices(products: HepsiburadaProduct[]): number {
    if (!products.length) return 50;
    const avgPrice =
      products.reduce((sum, p) => sum + p.salePrice, 0) / products.length;
    const variance =
      products.reduce((sum, p) => sum + Math.abs(p.salePrice - avgPrice), 0) /
      products.length;
    const normalizedVariance = Math.min(
      20,
      (variance / Math.max(avgPrice, 1)) * 100,
    );
    return Math.round(
      Math.min(
        100,
        Math.max(50, (avgPrice > 200 ? 72 : 62) + (20 - normalizedVariance)),
      ),
    );
  }

  private analyzeStock(products: HepsiburadaProduct[]): number {
    const stockedProducts = products.filter((p) => p.stockCount > 5).length;
    return Math.round((stockedProducts / products.length) * 100);
  }

  private generateRecommendations(
    storeInfo: HepsiburadaStoreData,
    products: HepsiburadaProduct[],
  ): string[] {
    const recommendations: string[] = [];

    if (storeInfo.averageRating < 8.5) {
      recommendations.push(
        'Satıcı puanını artırmak için kargolama hızına dikkat et',
      );
    }

    if (storeInfo.totalReviews < 500) {
      recommendations.push(
        'Yorum sayısını artırmak için müşteri notları kullan',
      );
    }

    const lowStockProducts = products.filter((p) => p.stockCount < 10).length;
    if (lowStockProducts > 0) {
      recommendations.push(`${lowStockProducts} ürün kritik stok seviyesinde`);
    }

    if (
      storeInfo.responseTimeHours !== null &&
      storeInfo.responseTimeHours > 4
    ) {
      recommendations.push(
        'Müşteri sorularına yanıt süresini düşür (hedef < 4 saat)',
      );
    }

    return recommendations;
  }

  async syncProducts(): Promise<any> {
    this.logger.log(
      `Syncing products for Hepsiburada Merchant: ${this.merchantId}`,
    );
    const products = await this.getStoreProducts(this.merchantId);
    return {
      success: true,
      platform: 'HEPSIBURADA',
      count: products.length,
      products,
    };
  }

  async syncOrders(): Promise<any> {
    this.logger.log(
      `Syncing orders for Hepsiburada Merchant: ${this.merchantId}`,
    );
    if (!this.apiKey || this.apiKey === 'public') {
      throw new Error(
        'Hepsiburada sipariş senkronizasyonu için API kimlik bilgileri zorunludur',
      );
    }

    const endpoints = [
      `${this.baseUrl}/OrderService/v1/orders/merchantid/${encodeURIComponent(this.merchantId)}?page=1&size=50`,
      `${this.baseUrl}/OrderService/v1/orders?merchantId=${encodeURIComponent(this.merchantId)}&page=1&size=50`,
    ];

    for (const url of endpoints) {
      try {
        const response = await fetch(url, {
          headers: {
            Authorization: `Basic ${this.apiKey}`,
            'Content-Type': 'application/json',
            Accept: 'application/json',
            'User-Agent': 'PazarYonetimi/1.0',
          },
        });

        if (!response.ok) continue;
        const data = (await response.json()) as Record<string, unknown>;
        const orders = this.extractOrderArray(data);

        return {
          success: true,
          platform: 'HEPSIBURADA',
          orders,
          source: 'api',
        };
      } catch (error) {
        this.logger.warn(
          `Hepsiburada syncOrders request error: ${(error as Error).message}`,
        );
      }
    }

    throw new Error('Hepsiburada sipariş verisi alınamadı');
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    this.logger.log(`Updating Hepsiburada stock for ${sku}: ${stock}`);
    if (!this.apiKey || this.apiKey === 'public') {
      throw new Error(
        'Hepsiburada stok güncelleme için API kimlik bilgileri zorunludur',
      );
    }

    return this.sendListingMutation(
      '/ListingExternalService/v1/Listings/stock-uploads',
      [{ merchantSku: sku, availableStock: stock }],
      { sku, stock },
      'stock',
    );
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    this.logger.log(`Updating Hepsiburada price for ${sku}: ${price}`);
    if (!this.apiKey || this.apiKey === 'public') {
      throw new Error(
        'Hepsiburada fiyat güncelleme için API kimlik bilgileri zorunludur',
      );
    }

    return this.sendListingMutation(
      '/ListingExternalService/v1/Listings/price-uploads',
      [{ merchantSku: sku, price }],
      { sku, price },
      'price',
    );
  }

  private extractOrderArray(payload: Record<string, unknown>): unknown[] {
    if (Array.isArray(payload.data)) return payload.data;

    if (payload.data && typeof payload.data === 'object') {
      const data = payload.data as {
        items?: unknown;
        orders?: unknown;
        content?: unknown;
      };
      if (Array.isArray(data.items)) return data.items;
      if (Array.isArray(data.orders)) return data.orders;
      if (Array.isArray(data.content)) return data.content;
    }

    if (Array.isArray(payload.items)) return payload.items;
    if (Array.isArray(payload.orders)) return payload.orders;
    return [];
  }

  private async sendListingMutation(
    endpoint: string,
    items: Array<Record<string, unknown>>,
    responseMeta: { sku: string; stock?: number; price?: number },
    operation: 'stock' | 'price',
  ): Promise<any> {
    const response = await fetch(`${this.baseUrl}${endpoint}`, {
      method: 'POST',
      headers: {
        Authorization: `Basic ${this.apiKey}`,
        'Content-Type': 'application/json',
        Accept: 'application/json',
        'User-Agent': 'PazarYonetimi/1.0',
      },
      body: JSON.stringify({
        merchantId: this.merchantId,
        items,
      }),
    });

    if (response.status === 429 || response.status >= 500) {
      throw new Error(
        `Hepsiburada ${operation} transient error: ${response.status}`,
      );
    }

    if (!response.ok) {
      const errorBody = await this.parseApiErrorBody(response);
      this.logger.warn(
        `Hepsiburada update${operation === 'stock' ? 'Stock' : 'Price'} failed (${response.status}) for sku=${responseMeta.sku}`,
      );
      return {
        success: false,
        ...responseMeta,
        source: 'api',
        status: response.status,
        error: errorBody,
      };
    }

    return {
      success: true,
      ...responseMeta,
      source: 'api',
      status: response.status,
    };
  }

  private async parseApiErrorBody(response: Response): Promise<string | null> {
    try {
      const text = await response.text();
      if (!text) return null;
      return text.length > 500 ? `${text.slice(0, 500)}...` : text;
    } catch {
      return null;
    }
  }

  /**
   * Hepsiburada'dan ürün yorumlarını çek
   * API: GET /ReviewService/v1/reviews?merchantId={id}&page=1&pageSize=100
   */
  async getReviews(
    page: number = 1,
    size: number = 100,
  ): Promise<MarketplaceReview[]> {
    if (!this.apiKey || this.apiKey === 'public') {
      this.logger.warn('Hepsiburada getReviews: API anahtarı eksik');
      return [];
    }
    const endpoints = [
      `${this.baseUrl}/ReviewService/v1/reviews?merchantId=${encodeURIComponent(this.merchantId)}&page=${page}&pageSize=${size}`,
      `${this.baseUrl}/ReviewService/v1/reviews/merchantid/${encodeURIComponent(this.merchantId)}?page=${page}&pageSize=${size}`,
    ];
    for (const url of endpoints) {
      try {
        const response = await fetch(url, {
          headers: {
            Authorization: `Basic ${this.apiKey}`,
            'Content-Type': 'application/json',
            Accept: 'application/json',
            'User-Agent': 'PazarYonetimi/1.0',
          },
        });
        if (!response.ok) continue;
        const data = (await response.json()) as Record<string, unknown>;
        const reviews: Record<string, unknown>[] = Array.isArray(data.data)
          ? (data.data as Record<string, unknown>[])
          : Array.isArray(data.reviews)
            ? (data.reviews as Record<string, unknown>[])
            : Array.isArray(data.items)
              ? (data.items as Record<string, unknown>[])
              : [];
        return reviews
          .map((r) => ({
            externalId: String(r.id ?? r.reviewId ?? ''),
            productId: r.productId ? String(r.productId) : undefined,
            productName: String(r.productName ?? r.sku ?? 'Ürün'),
            customerName: String(
              r.userName ?? r.customerName ?? r.user ?? 'Müşteri',
            ),
            rating: Math.round(Number(r.rating ?? r.rate ?? r.score ?? 0)),
            title: r.title ? String(r.title) : undefined,
            comment: String(r.comment ?? r.description ?? r.text ?? ''),
            reviewDate: r.reviewDate
              ? new Date(r.reviewDate as string)
              : new Date(),
            helpful: Number(r.helpfulCount ?? 0),
            verified: Boolean(r.isVerified ?? false),
          }))
          .filter((r) => r.externalId && r.comment);
      } catch (error) {
        this.logger.warn(
          `Hepsiburada getReviews ${url} hatası: ${(error as Error).message}`,
        );
      }
    }
    return [];
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';

interface LazadaProduct {
  productId: string;
  title: string;
  price: number;
  salePrice: number;
  stockCount: number;
  rating: number;
  reviewCount: number;
  url: string;
  images: string[];
  shopName: string;
  shopId: string;
  soldCount: number;
  isPreOrder: boolean;
  brand: string;
  category: string;
}

@Injectable()
export class LazadaBridge implements MarketplaceBridge {
  private readonly logger = new Logger(LazadaBridge.name);
  private readonly apiUrl = 'https://api.lazada.com/rest';

  constructor(
    private readonly appKey: string,
    private readonly appSecret: string,
    private readonly accessToken: string,
    private readonly scrapingService: ScrapingService,
    private readonly countryCode: string = 'MY',
  ) {}

  private generateSignature(params: Record<string, string>): string {
    const sortedKeys = Object.keys(params).sort();
    const strToSign = sortedKeys.map((k) => `${k}${params[k]}`).join('');
    return `hmac_${this.appSecret}_${strToSign}`;
  }

  async syncProducts(): Promise<any> {
    try {
      const timestamp = Date.now().toString();
      const params = {
        app_key: this.appKey,
        timestamp,
        sign_method: 'sha256',
        access_token: this.accessToken,
      };
      const sign = this.generateSignature(params);

      const response = await fetch(
        `${this.apiUrl}/products/get?app_key=${this.appKey}&timestamp=${timestamp}&sign_method=sha256&sign=${sign}&access_token=${this.accessToken}`,
        { headers: { 'Content-Type': 'application/json' } },
      );

      if (!response.ok) {
        return {
          success: false,
          platform: 'LAZADA',
          error: `HTTP ${response.status}`,
        };
      }

      const data = await response.json();
      return {
        success: true,
        platform: 'LAZADA',
        count: data.data?.products?.length || 0,
      };
    } catch (error) {
      return {
        success: false,
        platform: 'LAZADA',
        error: (error as Error).message,
      };
    }
  }

  async syncOrders(): Promise<any> {
    try {
      const timestamp = Date.now().toString();
      const params = {
        app_key: this.appKey,
        timestamp,
        status: 'pending',
        access_token: this.accessToken,
      };
      const sign = this.generateSignature(params);

      const response = await fetch(
        `${this.apiUrl}/orders/get?app_key=${this.appKey}&timestamp=${timestamp}&sign=${sign}&access_token=${this.accessToken}&status=pending`,
        { headers: { 'Content-Type': 'application/json' } },
      );
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();
      return {
        success: true,
        platform: 'LAZADA',
        orders: data.data?.orders || [],
      };
    } catch (error) {
      return {
        success: false,
        platform: 'LAZADA',
        error: (error as Error).message,
      };
    }
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    try {
      const timestamp = Date.now().toString();
      const params = {
        app_key: this.appKey,
        timestamp,
        item_id: sku,
        quantity: stock.toString(),
        access_token: this.accessToken,
      };
      const sign = this.generateSignature(params);

      const response = await fetch(`${this.apiUrl}/product/stock/update`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...params, sign }),
      });
      return { success: response.ok, sku, stock, platform: 'LAZADA' };
    } catch (error) {
      throw error;
    }
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    try {
      const timestamp = Date.now().toString();
      const params = {
        app_key: this.appKey,
        timestamp,
        item_id: sku,
        price: price.toString(),
        access_token: this.accessToken,
      };
      const sign = this.generateSignature(params);

      const response = await fetch(`${this.apiUrl}/product/price/update`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...params, sign }),
      });
      return { success: response.ok, sku, price, platform: 'LAZADA' };
    } catch (error) {
      throw error;
    }
  }

  async getStoreInfo(storeId: string): Promise<any> {
    try {
      const url = `https://www.lazada.com.my/shop/${storeId}`;
      const scraped = await this.scrapingService.scrapeStore(url, 'LAZADA');
      return {
        storeId,
        storeName: scraped?.storeName || storeId,
        platform: 'LAZADA',
        country: this.countryCode,
      };
    } catch (error) {
      throw error;
    }
  }

  async getStoreProducts(
    storeId?: string,
    limit: number = 10,
  ): Promise<LazadaProduct[]> {
    try {
      const timestamp = Date.now().toString();
      const params = {
        app_key: this.appKey,
        timestamp,
        shop_id: storeId || '',
        limit: limit.toString(),
        access_token: this.accessToken,
      };
      const sign = this.generateSignature(params);

      const response = await fetch(
        `${this.apiUrl}/products/get?app_key=${this.appKey}&timestamp=${timestamp}&sign=${sign}&shop_id=${storeId}&limit=${limit}&access_token=${this.accessToken}`,
      );
      const data = await response.json();
      return (data.data?.products || []).map((item: any) => ({
        productId: item.item_id,
        title: item.attributes?.name,
        price: item.skus?.[0]?.price,
        salePrice: item.skus?.[0]?.sale_price || item.skus?.[0]?.price,
        stockCount: item.skus?.[0]?.quantity || 0,
        rating: item.rating || 0,
        reviewCount: item.review_count || 0,
        url: `https://www.lazada.${this.countryCode.toLowerCase()}/products/${item.item_id}`,
        images: item.images || [],
        shopName: item.shop_name,
        shopId: item.shop_id,
        soldCount: item.sold_count || 0,
        isPreOrder: item.pre_order || false,
        brand: item.attributes?.brand,
        category: item.primary_category,
      }));
    } catch (error) {
      throw error;
    }
  }
}

import {
  Controller,
  Post,
  Get,
  Param,
  Headers,
  Query,
  Body,
} from '@nestjs/common';
import { MarketplaceService, Platform } from './marketplace.service';
import { Public } from '../auth/public.decorator';

@Controller('marketplace')
export class MarketplaceController {
  constructor(private readonly marketplaceService: MarketplaceService) {}

  private resolveTenantId(
    headerTenantId?: string,
    queryTenantId?: string,
    bodyTenantId?: string,
  ): string {
    return headerTenantId || queryTenantId || bodyTenantId || '';
  }

  @Post('sync-all')
  async syncAll(
    @Headers('x-tenant-id') headerTenantId: string,
    @Query('tenantId') queryTenantId?: string,
    @Body() body?: { tenantId?: string },
  ) {
    const tenantId = this.resolveTenantId(
      headerTenantId,
      queryTenantId,
      body?.tenantId,
    );
    return this.marketplaceService.syncAllPlatformsForTenant(tenantId);
  }

  @Post('sync/:platform')
  async syncPlatform(
    @Headers('x-tenant-id') headerTenantId: string,
    @Param('platform') platform: string,
    @Query('tenantId') queryTenantId?: string,
    @Body() body?: { tenantId?: string },
  ) {
    const tenantId = this.resolveTenantId(
      headerTenantId,
      queryTenantId,
      body?.tenantId,
    );
    const bridge = await this.marketplaceService.getBridgeForTenant(
      tenantId,
      platform.toUpperCase() as Platform,
    );
    return bridge.syncProducts();
  }

  @Post('sync-store/:storeId')
  async syncStore(
    @Headers('x-tenant-id') headerTenantId: string,
    @Param('storeId') storeId: string,
    @Query('tenantId') queryTenantId?: string,
    @Body() body?: { tenantId?: string },
  ) {
    const tenantId = this.resolveTenantId(
      headerTenantId,
      queryTenantId,
      body?.tenantId,
    );
    return this.marketplaceService.syncIntegrationByStoreId(tenantId, storeId);
  }

  @Post('sync-orders/:platform')
  async syncPlatformOrders(
    @Headers('x-tenant-id') headerTenantId: string,
    @Param('platform') platform: string,
    @Query('tenantId') queryTenantId?: string,
    @Body() body?: { tenantId?: string },
  ) {
    const tenantId = this.resolveTenantId(
      headerTenantId,
      queryTenantId,
      body?.tenantId,
    );
    return this.marketplaceService.syncPlatformOrdersForTenant(
      tenantId,
      platform.toUpperCase() as Platform,
    );
  }

  @Post('stock/:platform')
  async updateStock(
    @Headers('x-tenant-id') headerTenantId: string,
    @Param('platform') platform: string,
    @Query('tenantId') queryTenantId: string | undefined,
    @Body() body: { sku: string; stock: number; requestKey?: string },
  ) {
    const tenantId = this.resolveTenantId(headerTenantId, queryTenantId);
    return this.marketplaceService.updateMarketplaceStock(
      tenantId,
      platform.toUpperCase() as Platform,
      body.sku,
      body.stock,
      body.requestKey,
    );
  }

  @Post('price/:platform')
  async updatePrice(
    @Headers('x-tenant-id') headerTenantId: string,
    @Param('platform') platform: string,
    @Query('tenantId') queryTenantId: string | undefined,
    @Body() body: { sku: string; price: number; requestKey?: string },
  ) {
    const tenantId = this.resolveTenantId(headerTenantId, queryTenantId);
    return this.marketplaceService.updateMarketplacePrice(
      tenantId,
      platform.toUpperCase() as Platform,
      body.sku,
      body.price,
      body.requestKey,
    );
  }

  @Get('contract-probe/:platform')
  async probeContract(
    @Headers('x-tenant-id') headerTenantId: string,
    @Param('platform') platform: string,
    @Query('tenantId') queryTenantId: string | undefined,
    @Query('includeOrders') includeOrders?: string,
    @Query('productLimit') productLimit?: string,
  ) {
    const tenantId = this.resolveTenantId(headerTenantId, queryTenantId);
    return this.marketplaceService.probeIntegrationContract(
      tenantId,
      platform.toUpperCase() as Platform,
      {
        includeOrders: includeOrders === '1' || includeOrders === 'true',
        productLimit: productLimit ? Number(productLimit) : undefined,
      },
    );
  }

  @Get('contract-probe-all')
  async probeAllContracts(
    @Headers('x-tenant-id') headerTenantId: string,
    @Query('tenantId') queryTenantId: string | undefined,
    @Query('includeOrders') includeOrders?: string,
    @Query('productLimit') productLimit?: string,
  ) {
    const tenantId = this.resolveTenantId(headerTenantId, queryTenantId);
    return this.marketplaceService.probeAllIntegrationsForTenant(tenantId, {
      includeOrders: includeOrders === '1' || includeOrders === 'true',
      productLimit: productLimit ? Number(productLimit) : undefined,
    });
  }

  /**
   * Mağaza analizi - Pazaryerinden gerçek veriler çek ve analiz et
   */
  @Public()
  @Get('analyze/:platform/:storeId')
  async analyzeStore(
    @Param('platform') platform: string,
    @Param('storeId') storeId: string,
    @Query('url') url?: string,
  ) {
    const platformUpper = platform.toUpperCase() as Platform;

    // Eğer URL verilmişse, URL'den store ID'sini çıkart
    let actualStoreId = storeId;
    if (url) {
      actualStoreId = this.extractStoreIdFromUrl(url, platformUpper);
    }

    return this.marketplaceService.analyzeStore(platformUpper, actualStoreId);
  }

  /**
   * Mağaza ürünlerini getir
   */
  @Public()
  @Get('store/:platform/:storeId/products')
  async getStoreProducts(
    @Param('platform') platform: string,
    @Param('storeId') storeId: string,
    @Query('limit') limit: number = 10,
  ) {
    const platformUpper = platform.toUpperCase() as Platform;
    return this.marketplaceService.getStoreProducts(
      platformUpper,
      storeId,
      limit,
    );
  }

  /**
   * Mağaza bilgilerini getir
   */
  @Public()
  @Get('store/:platform/:storeId/info')
  async getStoreInfo(
    @Param('platform') platform: string,
    @Param('storeId') storeId: string,
  ) {
    const platformUpper = platform.toUpperCase() as Platform;
    return this.marketplaceService.getStoreInfo(platformUpper, storeId);
  }

  // ==================== STORE MANAGEMENT ====================
  /**
   * Mağazaları listele
   * GET /marketplace/stores
   */
  @Get('stores')
  async getStores(@Query('tenantId') tenantId: string) {
    return this.marketplaceService.getStores(tenantId);
  }

  /**
   * Entegrasyonları listele
   * GET /marketplace/integrations
   */
  @Get('integrations')
  async getIntegrations(@Query('tenantId') tenantId: string) {
    return this.marketplaceService.getIntegrations(tenantId);
  }

  /**
   * Mağaza bağla
   * POST /marketplace/connect
   */
  @Post('connect')
  async connectStore(
    @Body() data: { tenantId: string; platform: string; credentials: any },
  ) {
    return this.marketplaceService.connectStore(
      data.tenantId,
      data.platform,
      data.credentials,
    );
  }

  /**
   * Mağaza bağlantısını kes
   * POST /marketplace/disconnect/:storeId
   */
  @Post('disconnect/:storeId')
  async disconnectStore(
    @Param('storeId') storeId: string,
    @Body() data: { tenantId: string },
  ) {
    return this.marketplaceService.disconnectStore(data.tenantId, storeId);
  }

  private extractStoreIdFromUrl(url: string, platform: Platform): string {
    try {
      const urlObj = new URL(url.startsWith('http') ? url : `https://${url}`);
      const pathname = urlObj.pathname;

      if (platform === Platform.TRENDYOL) {
        // https://www.trendyol.com/magaza/woys-m-203786
        const match = pathname.match(/\/magaza\/([^/]+)/);
        if (match) {
          const parts = match[1].split('-m-');
          if (parts.length > 1) return parts[1];
          return match[1].split('-').pop() || '203786';
        }
        return '203786';
      }

      if (platform === Platform.HEPSIBURADA) {
        // https://www.hepsiburada.com/magaza/happycomtr
        const match = pathname.match(/\/magaza\/([^/?]+)/);
        return match ? match[1] : 'hepsiburada';
      }

      if (platform === Platform.AMAZON) {
        // https://www.amazon.com.tr/sp?seller=A123456789
        const sellerParam =
          urlObj.searchParams.get('seller') ||
          urlObj.searchParams.get('merchant');
        if (sellerParam) return sellerParam;

        // https://www.amazon.com.tr/s?me=A123456789
        const meParam = urlObj.searchParams.get('me');
        if (meParam) return meParam;
      }

      // Global Fallback: return the last part of the path if no match
      const pathParts = pathname.split('/').filter((p) => p.length > 0);
      return pathParts[pathParts.length - 1] || '203786';
    } catch {
      return '203786'; // Default fallback
    }
  }
}

