  async probeIntegrationContract(
    tenantId: string,
    platform: Platform,
    options?: { includeOrders?: boolean; productLimit?: number },
  ) {
    if (!tenantId) {
      throw new BadRequestException('tenantId zorunludur');
    }

    const includeOrders = options?.includeOrders ?? false;
    const productLimit = Math.max(
      1,
      Math.min(20, Number(options?.productLimit ?? 5)),
    );

    const startedAt = Date.now();
    const bridge = await this.getBridgeForTenant(tenantId, platform);
    const bridgeAny = bridge as unknown as {
      getStoreInfo?: (storeId?: string) => Promise<unknown>;
      getStoreProducts?: (storeId?: string, limit?: number) => Promise<unknown>;
    };

    const checks: Array<{
      name: string;
      passed: boolean;
      detail: string;
      sample?: Prisma.InputJsonValue;
    }> = [];

    try {
      const info = bridgeAny.getStoreInfo
        ? await this.withRetry(() => bridgeAny.getStoreInfo!(), 2, 300)
        : null;
      const infoObj =
        info && typeof info === 'object'
          ? (info as Record<string, unknown>)
          : null;
      const infoPassed = Boolean(infoObj?.storeId && infoObj?.storeName);

      checks.push({
        name: 'storeInfoShape',
        passed: infoPassed,
        detail: infoPassed
          ? 'storeId/storeName alanlari mevcut'
          : 'storeInfo response shape eksik',
        sample: infoObj
          ? ({
              storeId: infoObj.storeId ?? null,
              storeName: infoObj.storeName ?? null,
              totalProducts: infoObj.totalProducts ?? null,
            } as Prisma.InputJsonValue)
          : undefined,
      });
    } catch (error) {
      checks.push({
        name: 'storeInfoShape',
        passed: false,
        detail: `storeInfo hatasi: ${(error as Error).message}`,
      });
    }

    try {
      const productsRaw = bridgeAny.getStoreProducts
        ? await this.withRetry(
            () => bridgeAny.getStoreProducts!(undefined, productLimit),
            2,
            300,
          )
        : [];

      const products = Array.isArray(productsRaw) ? productsRaw : [];
      const first =
        products[0] && typeof products[0] === 'object'
          ? (products[0] as Record<string, unknown>)
          : null;

      const firstHasShape = Boolean(
        first &&
        (first.title || first.name) &&
        (first.productId || first.id || first.sku),
      );
      const productShapeOk =
        Array.isArray(productsRaw) && (products.length === 0 || firstHasShape);

      checks.push({
        name: 'productsShape',
        passed: productShapeOk,
        detail: productShapeOk
          ? `${products.length} urun alindi, liste shape dogrulandi`
          : 'urun listesi bos veya beklenen alanlar eksik',
        sample: first
          ? ({
              productId: first.productId ?? first.id ?? first.sku ?? null,
              title: first.title ?? first.name ?? null,
              salePrice: first.salePrice ?? first.price ?? null,
            } as Prisma.InputJsonValue)
          : undefined,
      });
    } catch (error) {
      checks.push({
        name: 'productsShape',
        passed: false,
        detail: `products hatasi: ${(error as Error).message}`,
      });
    }

    if (includeOrders) {
      try {
        const ordersRaw = await this.withRetry(
          () => bridge.syncOrders(),
          2,
          400,
        );
        const orders = this.extractOrders(ordersRaw);
        const firstOrder = orders[0] || null;
        const orderShapeOk = Boolean(
          !firstOrder ||
          firstOrder.orderNumber ||
          firstOrder.orderId ||
          firstOrder.id ||
          firstOrder.packageNumber,
        );

        checks.push({
          name: 'ordersShape',
          passed: orderShapeOk,
          detail: `orders count: ${orders.length}`,
          sample: firstOrder
            ? ({
                orderNumber: firstOrder.orderNumber ?? null,
                orderId: firstOrder.orderId ?? firstOrder.id ?? null,
                status: firstOrder.status ?? firstOrder.orderStatus ?? null,
              } as Prisma.InputJsonValue)
            : undefined,
        });
      } catch (error) {
        checks.push({
          name: 'ordersShape',
          passed: false,
          detail: `orders hatasi: ${(error as Error).message}`,
        });
      }
    }

    const passedChecks = checks.filter((check) => check.passed).length;
    const success = passedChecks === checks.length && checks.length > 0;
    const durationMs = Date.now() - startedAt;

    const result = {
      success,
      tenantId,
      platform,
      checkedAt: new Date().toISOString(),
      durationMs,
      checks,
      score:
        checks.length > 0
          ? Math.round((passedChecks / checks.length) * 100)
          : 0,
    };

    await this.prisma.activityLog.create({
      data: {
        tenantId,
        action: 'marketplace.contract.probe',
        resource: 'integration',
        details: result as unknown as Prisma.InputJsonValue,
      },
    });

    return result;
  }

  /**
   * Pazaryerinden mağaza analizi yap
   */
  async analyzeStore(
    platform: Platform,
    storeId: string,
  ): Promise<MarketplaceAnalysisResponse> {
    const bridge = (await this.getTempBridge(platform)) as any;

    if (platform === Platform.TRENDYOL) {
      return bridge.analyzeStoreSEO(storeId);
    } else if (platform === Platform.HEPSIBURADA) {
      return bridge.analyzeStoreSEO(storeId);
    }

    // Universal Fallback for ANY other platform or direct URL
    if (storeId.startsWith('http')) {
      const scrapedData = await this.scrapingService.scrapeStore(storeId);
      if (scrapedData) {
        const metricSources = {
          storeName: 'scraped',
          rating: 'scraped',
          followers: 'scraped',
          productCount: 'scraped',
          totalProducts: 'scraped',
          responseTime: 'scraped_or_unknown',
          monthlyTraffic: 'not_available',
          monthlyTurnover: 'not_available',
        } as const;

        return {
          platform: scrapedData.platform || 'GENERIC',
          storeId: storeId,
          storeName: scrapedData.storeName,
          seoScore: Math.round(scrapedData.rating * 10), // Approx conversion
          dataSources: {
            overall: 'scraped+calculated',
            seoScore: 'calculated',
            products: 'not_available',
            metrics: metricSources,
            reasons: {
              monthlyTraffic:
                'Universal scrape akisi aylik trafik degeri saglamiyor.',
              monthlyTurnover:
                'Universal scrape akisi aylik ciro degeri saglamiyor.',
            },
            evidence: {
              adapter: 'marketplace.service.generic',
              inputUrl: storeId,
            },
          },
          confidence: computeConfidenceFromSources(metricSources),
          metrics: {
            storeName: scrapedData.storeName,
            rating: scrapedData.rating,
            followers: scrapedData.followerCount,
            totalProducts: scrapedData.productCount,
            productCount: scrapedData.productCount,
            responseTime: scrapedData.responseTime || 'Bilinmiyor',
          },
          products: [], // Generic scraper might not get full product list yet
          recommendations: ['Global pazar yeri analizi tamamlandı.'],
          timestamp: new Date(),
        };
      }
    }

    throw new Error(
      `${platform} için analiz henüz implementasyon edilmedi ve URL geçerli değil.`,
    );
  }

  /**
   * Mağaza ürünlerini getir
   */
  async getStoreProducts(
    platform: Platform,
    storeId: string,
    limit: number = 10,
  ) {
    const bridge = (await this.getTempBridge(platform)) as any;

    if (platform === Platform.TRENDYOL) {
      return bridge.getStoreProducts(storeId, limit);
    } else if (platform === Platform.HEPSIBURADA) {
      return bridge.getStoreProducts(storeId, limit);
    }

    throw new Error(
      `${platform} için ürün getirme henüz implementasyon edilmedi`,
    );
  }

  /**
   * Pazaryerinde ürün ara (auto-discovery için)
   */
  async searchProducts(
    platform: Platform,
    query: string,
    limit: number = 5,
  ): Promise<Array<Record<string, unknown>>> {
    try {
      const bridge = (await this.getTempBridge(platform)) as any;
      if (typeof bridge.searchProducts === 'function') {
        const results = await bridge.searchProducts(query, limit);
        return Array.isArray(results) ? results : [];
      }
    } catch {
      // Platform may not support search
    }
    return [];
  }

  /**
   * Mağaza bilgilerini getir
   */
  async getStoreInfo(platform: Platform, storeId: string) {
    const bridge = (await this.getTempBridge(platform)) as any;

    if (platform === Platform.TRENDYOL) {
      return bridge.getStoreInfo(storeId);
    } else if (platform === Platform.HEPSIBURADA) {
      return bridge.getStoreInfo(storeId);
    }

    throw new Error(
      `${platform} için mağaza bilgisi henüz implementasyon edilmedi`,
    );
  }

  /**
   * API Key olmadan geçici bridge oluştur (public store analizi için)
   */
  private async getTempBridge(platform: Platform): Promise<MarketplaceBridge> {
    switch (platform) {
      case Platform.TRENDYOL:
        // Trendyol public API'si kullanıyoruz
        return new TrendyolBridge('public', 'public', '', this.scrapingService);
      case Platform.AMAZON:
        return new AmazonBridge('public', 'public', this.scrapingService);
      case Platform.HEPSIBURADA:
        return new HepsiburadaBridge('public', 'public', this.scrapingService);
      case Platform.N11:
        return new N11Bridge('public', 'public', this.scrapingService);
      case Platform.CICEKSEPETI:
        return new CicekSepetiBridge('public', 'public', this.scrapingService);
      default:
        throw new Error(`${platform} köprüsü henüz hazır değil.`);
    }
  }

  // ==================== STORE MANAGEMENT ====================
  async getStores(tenantId: string) {
    if (!tenantId) {
      throw new BadRequestException('tenantId zorunludur');
    }

    try {
      const [integrations, productGroups, orderGroups] = await Promise.all([
        this.prisma.integration.findMany({
          where: { tenantId },
          orderBy: { createdAt: 'desc' },
        }),
        this.prisma.marketplaceProduct.groupBy({
          by: ['platform'],
          _count: { _all: true },
          where: {
            product: { tenantId },
          },
        }),
        this.prisma.order.groupBy({
          by: ['platform'],
          _count: { _all: true },
          _sum: { totalAmount: true },
          where: { tenantId },
        }),
      ]);

      const productCountByPlatform = new Map(
        productGroups.map((group) => [group.platform, group._count._all]),
      );
      const orderStatsByPlatform = new Map(
        orderGroups.map((group) => [
          group.platform,
          {
            orderCount: group._count._all,
            revenue: Number(group._sum.totalAmount ?? 0),
          },
        ]),
      );

      return integrations.map((integration) => {
        const orderStats = orderStatsByPlatform.get(integration.platform);
        const lastSync = integration.updatedAt?.toISOString() || null;
        const hoursSinceUpdate = integration.updatedAt
          ? (Date.now() - integration.updatedAt.getTime()) / (1000 * 60 * 60)
          : Number.POSITIVE_INFINITY;

        const health = !integration.isActive
          ? 0
          : hoursSinceUpdate <= 24
            ? 95
            : hoursSinceUpdate <= 24 * 7
              ? 85
              : 70;

        return {
          id: integration.id,
          platform: integration.platform,
          name: `${integration.platform} Mağazası`,
          status: integration.isActive ? 'connected' : 'disconnected',
          lastSync,
          productCount: productCountByPlatform.get(integration.platform) ?? 0,
          orderCount: orderStats?.orderCount ?? 0,
          revenue: orderStats?.revenue ?? 0,
          health,
          createdAt: integration.createdAt.toISOString(),
        };
      });
    } catch (error) {
      this.logger.error(
        `getStores failed for tenant ${tenantId}`,
        error as Error,
      );
      throw new InternalServerErrorException(
        'Mağaza entegrasyonları alınamadı',
      );
    }
  }

  async getIntegrations(tenantId: string) {
    if (!tenantId) {
      throw new BadRequestException('tenantId zorunludur');
    }

    try {
      const integrations = await this.prisma.integration.findMany({
        where: { tenantId },
        orderBy: { createdAt: 'desc' },
      });

      return integrations.map((integration) => ({
        id: integration.id,
        platform: integration.platform,
        isActive: integration.isActive,
        lastSyncAt: integration.updatedAt?.toISOString(),
        settings: integration.apiExtra,
        createdAt: integration.createdAt.toISOString(),
        status: integration.isActive ? 'active' : 'inactive',
      }));
    } catch (error) {
      this.logger.error(
        `getIntegrations failed for tenant ${tenantId}`,
        error as Error,
      );
      throw new InternalServerErrorException('Entegrasyonlar alınamadı');
    }
  }

  async connectStore(
    tenantId: string,
    platform: string,
    credentials: Record<string, unknown>,
  ) {
    if (!tenantId) {
      throw new BadRequestException('tenantId zorunludur');
    }
    if (!platform) {
      throw new BadRequestException('platform zorunludur');
    }

    const normalizedPlatform = platform.toUpperCase() as PrismaPlatform;
    if (!Object.values(PrismaPlatform).includes(normalizedPlatform)) {
      throw new BadRequestException(`Desteklenmeyen platform: ${platform}`);
    }

    const sanitizedCredentials = this.validateAndNormalizeCredentials(
      normalizedPlatform,
      credentials,
    );

    try {
      const existing = await this.prisma.integration.findFirst({
        where: {
          tenantId,
          platform: normalizedPlatform,
          isActive: true,
        },
        select: { id: true },
      });

      if (existing) {
        throw new ConflictException(
          `${normalizedPlatform} mağazası zaten bağlı`,
        );
      }

      const integration = await this.prisma.integration.create({
        data: {
          tenantId,
          platform: normalizedPlatform,
          isActive: true,
          apiKey: this.encryption.encrypt(sanitizedCredentials.apiKey),
          apiSecret: this.encryption.encrypt(sanitizedCredentials.apiSecret),
          apiExtra: sanitizedCredentials.apiExtra,
        },
      });
      return {
        success: true,
        integration,
        message: `${normalizedPlatform} mağazası başarıyla bağlandı`,
      };
    } catch (error) {
      if (
        error instanceof BadRequestException ||
        error instanceof ConflictException
      ) {
        throw error;
      }
      this.logger.error(
        `connectStore failed for tenant ${tenantId}`,
        error as Error,
      );
      throw new InternalServerErrorException('Mağaza bağlanamadı');
    }
  }

  async disconnectStore(tenantId: string, storeId: string) {
    if (!tenantId || !storeId) {
      throw new BadRequestException('tenantId ve storeId zorunludur');
    }

    try {
      const integration = await this.prisma.integration.findFirst({
        where: { id: storeId, tenantId },
        select: { id: true, isActive: true },
      });

      if (!integration) {
        throw new NotFoundException('Mağaza bağlantısı bulunamadı');
      }

      if (!integration.isActive) {
        return { success: true, message: 'Mağaza bağlantısı zaten pasif' };
      }

      await this.prisma.integration.update({
        where: { id: integration.id },
        data: { isActive: false },
      });
      return { success: true, message: 'Mağaza bağlantısı kesildi' };
    } catch (error) {
      if (
        error instanceof BadRequestException ||
        error instanceof NotFoundException
      ) {
        throw error;
      }
      this.logger.error(
        `disconnectStore failed for tenant ${tenantId}`,
        error as Error,
      );
      throw new InternalServerErrorException('Mağaza bağlantısı kesilemedi');
    }
  }

  private extractOrders(raw: any): Record<string, unknown>[] {
    if (!raw) return [];
    if (Array.isArray(raw)) return raw as Record<string, unknown>[];
    if (Array.isArray(raw.orders))
      return raw.orders as Record<string, unknown>[];
    if (Array.isArray(raw.content))
      return raw.content as Record<string, unknown>[];
    if (
      raw.data &&
      typeof raw.data === 'object' &&
      Array.isArray((raw.data as { items?: unknown }).items)
    ) {
      return (raw.data as { items: Record<string, unknown>[] }).items;
    }
    return [];
  }

  private normalizeOrderForPersistence(
    tenantId: string,
    platform: Platform,
    source: Record<string, unknown>,
  ) {
    const marketplaceOrderId = String(
      source.orderNumber ??
        source.orderId ??
        source.id ??
        source.packageNumber ??
        `ORD-${Date.now()}`,
    );

    const totalAmount = this.toNumber(
      source.totalAmount ?? source.totalPrice ?? source.amount,
    );
    const taxAmount = this.toNumber(source.taxAmount ?? source.tax ?? 0);

    const statusRaw = String(
      source.status ?? source.orderStatus ?? 'PENDING',
    ).toUpperCase();
    const status = (
      [
        'PENDING',
        'CONFIRMED',
        'SHIPPED',
        'DELIVERED',
        'CANCELLED',
        'RETURNED',
      ].includes(statusRaw)
        ? statusRaw
        : 'PENDING'
    ) as
      | 'PENDING'
      | 'CONFIRMED'
      | 'SHIPPED'
      | 'DELIVERED'
      | 'CANCELLED'
      | 'RETURNED';

    const paymentRaw = String(source.paymentStatus ?? 'UNPAID').toUpperCase();
    const paymentStatus = (
      ['UNPAID', 'PAID', 'REFUNDED', 'PARTIALLY_REFUNDED'].includes(paymentRaw)
        ? paymentRaw
        : 'UNPAID'
    ) as 'UNPAID' | 'PAID' | 'REFUNDED' | 'PARTIALLY_REFUNDED';

    const orderDate = source.orderDate
      ? new Date(String(source.orderDate))
      : new Date();

    return {
      platform,
      marketplaceOrderId,
      orderData: {
        tenantId,
        platform: platform as unknown as PrismaPlatform,
        marketplaceOrderId,
        status,
        paymentStatus,
        customerName: source.customerName ? String(source.customerName) : null,
        customerEmail: source.customerEmail
          ? String(source.customerEmail)
          : null,
        customerPhone: source.customerPhone
          ? String(source.customerPhone)
          : null,
        shippingAddress: source.shippingAddress
          ? String(source.shippingAddress)
          : null,
        billingAddress: source.billingAddress
          ? String(source.billingAddress)
          : null,
        totalAmount,
        taxAmount,
        shippingCost: this.toNumber(source.shippingCost ?? 0),
        commissionAmount: this.toNumber(source.commissionAmount ?? 0),
        netProfit: this.toNumber(source.netProfit ?? 0),
        currency: source.currency ? String(source.currency) : 'TRY',
        trackingNumber: source.trackingNumber
          ? String(source.trackingNumber)
          : null,
        shippingProvider: source.shippingProvider
          ? String(source.shippingProvider)
          : null,
        notes: source.notes ? String(source.notes) : null,
        orderDate,
      },
    };
  }

  private toNumber(value: unknown): number {
    const numeric = Number(value);
    return Number.isFinite(numeric) ? numeric : 0;
  }

  private async findRecentIdempotentLog(
    tenantId: string,
    action: string,
    requestKey: string,
  ) {
    const fiveMinutesAgo = new Date(Date.now() - 5 * 60 * 1000);
    const logs = await this.prisma.activityLog.findMany({
      where: {
        tenantId,
        action,
        createdAt: { gte: fiveMinutesAgo },
      },
      orderBy: { createdAt: 'desc' },
      take: 20,
    });

    return logs.find((log) => {
      const details = log.details as { requestKey?: string } | null;
      return details?.requestKey === requestKey;
    });
  }

  private async withRetry<T>(
    fn: () => Promise<T>,
    retries: number,
    delayMs: number,
  ): Promise<T> {
    let lastError: unknown;
    for (let attempt = 0; attempt < retries; attempt++) {
      try {
        return await fn();
      } catch (error) {
        lastError = error;
        if (attempt < retries - 1) {
          await new Promise((resolve) =>
            setTimeout(resolve, delayMs * (attempt + 1)),
          );
        }
      }
    }
    throw lastError;
  }

  private validateAndNormalizeCredentials(
    platform: PrismaPlatform,
    credentials: Record<string, unknown>,
  ) {
    const apiKey =
      typeof credentials.apiKey === 'string' ? credentials.apiKey.trim() : '';
    const apiSecret =
      typeof credentials.apiSecret === 'string'
        ? credentials.apiSecret.trim()
        : '';

    if (!apiKey) {
      throw new UnprocessableEntityException('apiKey zorunludur');
    }

    if (!apiSecret) {
      throw new UnprocessableEntityException('apiSecret zorunludur');
    }

    const apiExtraEntries = Object.entries(credentials).filter(
      ([key, value]) => {
        if (key === 'apiKey' || key === 'apiSecret') return false;
        return value !== undefined;
      },
    );
    const apiExtra: Record<string, unknown> =
      Object.fromEntries(apiExtraEntries);

    if (platform === PrismaPlatform.TRENDYOL) {
      const supplierId =
        typeof credentials.supplierId === 'string'
          ? credentials.supplierId.trim()
          : '';
      if (!supplierId) {
        throw new UnprocessableEntityException(
          'Trendyol için supplierId zorunludur',
        );
      }
      apiExtra.supplierId = supplierId;
    }

    if (platform === PrismaPlatform.HEPSIBURADA) {
      const merchantId =
        typeof credentials.merchantId === 'string'
          ? credentials.merchantId.trim()
          : '';
      if (!merchantId) {
        throw new UnprocessableEntityException(
          'Hepsiburada için merchantId zorunludur',
        );
      }
      apiExtra.merchantId = merchantId;
    }

    return {
      apiKey,
      apiSecret,
      apiExtra: apiExtra as Prisma.InputJsonValue,
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';

interface MercadoLibreProduct {
  productId: string;
  title: string;
  price: number;
  salePrice: number;
  stockCount: number;
  rating: number;
  reviewCount: number;
  url: string;
  images: string[];
  sellerName: string;
  sellerId: string;
  sellerReputation: string;
  shippingFree: boolean;
  condition: string;
  acceptsMercadoPago: boolean;
}

@Injectable()
export class MercadoLibreBridge implements MarketplaceBridge {
  private readonly logger = new Logger(MercadoLibreBridge.name);
  private readonly apiUrl = 'https://api.mercadolibre.com';

  constructor(
    private readonly appId: string,
    private readonly appSecret: string,
    private readonly accessToken: string,
    private readonly siteId: string = 'MLM',
    private readonly scrapingService: ScrapingService,
  ) {}

  private async getUserId(): Promise<string> {
    const response = await fetch(`${this.apiUrl}/users/me`, {
      headers: { Authorization: `Bearer ${this.accessToken}` },
    });
    const data = await response.json();
    return data.id?.toString() || '';
  }

  async syncProducts(): Promise<any> {
    try {
      const userId = await this.getUserId();
      const response = await fetch(
        `${this.apiUrl}/users/${userId}/items_search?status=active&limit=100`,
        { headers: { Authorization: `Bearer ${this.accessToken}` } },
      );

      if (!response.ok) {
        return {
          success: false,
          platform: 'MERCADOLIBRE',
          error: `HTTP ${response.status}`,
        };
      }

      const data = await response.json();
      return {
        success: true,
        platform: 'MERCADOLIBRE',
        count: data.results?.length || 0,
      };
    } catch (error) {
      return {
        success: false,
        platform: 'MERCADOLIBRE',
        error: (error as Error).message,
      };
    }
  }

  async syncOrders(): Promise<any> {
    try {
      const sellerId = await this.getUserId();
      const response = await fetch(
        `${this.apiUrl}/orders/search?seller=${sellerId}&limit=50`,
        { headers: { Authorization: `Bearer ${this.accessToken}` } },
      );
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();
      return {
        success: true,
        platform: 'MERCADOLIBRE',
        orders: data.results || [],
      };
    } catch (error) {
      return {
        success: false,
        platform: 'MERCADOLIBRE',
        error: (error as Error).message,
      };
    }
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    try {
      const response = await fetch(`${this.apiUrl}/items/${sku}`, {
        method: 'PUT',
        headers: {
          Authorization: `Bearer ${this.accessToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ available_quantity: stock }),
      });
      return { success: response.ok, sku, stock, platform: 'MERCADOLIBRE' };
    } catch (error) {
      throw error;
    }
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    try {
      const response = await fetch(`${this.apiUrl}/items/${sku}`, {
        method: 'PUT',
        headers: {
          Authorization: `Bearer ${this.accessToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ price }),
      });
      return { success: response.ok, sku, price, platform: 'MERCADOLIBRE' };
    } catch (error) {
      throw error;
    }
  }

  async getStoreInfo(storeId: string): Promise<any> {
    try {
      const response = await fetch(`${this.apiUrl}/users/${storeId}`, {
        headers: { Authorization: `Bearer ${this.accessToken}` },
      });
      if (response.ok) {
        const data = await response.json();
        return {
          storeId: data.id?.toString(),
          storeName: data.nickname,
          platform: 'MERCADOLIBRE',
          siteId: this.siteId,
          sellerReputation: data.seller_reputation?.level_id,
        };
      }
      throw new Error('Failed to get store info');
    } catch (error) {
      throw error;
    }
  }

  async getStoreProducts(
    storeId?: string,
    limit: number = 10,
  ): Promise<MercadoLibreProduct[]> {
    try {
      const response = await fetch(
        `${this.apiUrl}/sites/${this.siteId}/search?seller_id=${storeId}&limit=${limit}`,
      );
      const data = await response.json();
      return (data.results || []).map((item: any) => ({
        productId: item.id,
        title: item.title,
        price: item.price,
        salePrice: item.price,
        stockCount: item.available_quantity || 0,
        rating: 0,
        reviewCount: 0,
        url: item.permalink,
        images: [item.thumbnail],
        sellerName: item.seller?.nickname,
        sellerId: item.seller?.id?.toString(),
        sellerReputation: '',
        shippingFree: item.shipping?.free_shipping || false,
        condition: item.condition,
        acceptsMercadoPago: item.accepts_mercadopago || false,
      }));
    } catch (error) {
      throw error;
    }
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';
import {
  MarketplaceAnalysisResponse,
  computeConfidenceFromSources,
} from './analysis.types';

interface N11Product {
  productId: string;
  title: string;
  price: number;
  salePrice: number;
  stockCount: number;
  rating: number;
  reviewCount: number;
  url: string;
  images: string[];
  storeName?: string;
  storeUrl?: string;
}

@Injectable()
export class N11Bridge implements MarketplaceBridge {
  private readonly logger = new Logger(N11Bridge.name);
  private readonly baseUrl = 'https://api.n11.com/ws';

  constructor(
    private readonly apiKey: string,
    private readonly apiSecret: string,
    private readonly scrapingService: ScrapingService,
  ) {}

  async syncProducts(): Promise<any> {
    this.logger.log('Syncing products from N11');
    try {
      const url = `${this.baseUrl}/ProductService/`;
      const soapBody = this.buildSoapEnvelope(
        'GetProductList',
        `
                <pagingData>
                    <currentPage>0</currentPage>
                    <pageSize>100</pageSize>
                </pagingData>
            `,
      );

      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'text/xml; charset=utf-8', SOAPAction: '' },
        body: soapBody,
      });

      if (!response.ok) {
        this.logger.warn(`N11 syncProducts failed: ${response.status}`);
        return {
          success: false,
          platform: 'N11',
          error: `HTTP ${response.status}`,
        };
      }

      const text = await response.text();
      const products = this.parseProductListResponse(text);
      return {
        success: true,
        platform: 'N11',
        count: products.length,
        products,
      };
    } catch (error) {
      this.logger.warn(`N11 syncProducts error: ${(error as Error).message}`);
      return {
        success: false,
        platform: 'N11',
        error: (error as Error).message,
      };
    }
  }

  async syncOrders(): Promise<any> {
    try {
      const url = `${this.baseUrl}/OrderService/`;
      const soapBody = this.buildSoapEnvelope(
        'OrderList',
        `
                <searchData>
                    <buyerName />
                    <orderNumber />
                    <productSellerCode />
                    <recipient />
                    <period>
                        <startDate>${this.daysAgo(7)}</startDate>
                        <endDate>${this.now()}</endDate>
                    </period>
                    <sortForUpdateDate>true</sortForUpdateDate>
                </searchData>
                <pagingData>
                    <currentPage>0</currentPage>
                    <pageSize>50</pageSize>
                </pagingData>
            `,
      );

      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'text/xml; charset=utf-8' },
        body: soapBody,
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}`);
      }

      throw new Error(
        'N11 sipariş ayrıştırma henüz uygulanmadı; boş başarı çıktısı devre dışı bırakıldı',
      );
    } catch (error) {
      this.logger.warn(`N11 syncOrders error: ${(error as Error).message}`);
      return {
        success: false,
        platform: 'N11',
        error: (error as Error).message,
      };
    }
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    try {
      const url = `${this.baseUrl}/ProductStockService/`;
      const soapBody = this.buildSoapEnvelope(
        'IncreaseStockByStockSellerCode',
        `
                <stockItems>
                    <stockItem>
                        <sellerStockCode>${this.escapeXml(sku)}</sellerStockCode>
                        <quantity>${stock}</quantity>
                        <version>1</version>
                    </stockItem>
                </stockItems>
            `,
      );

      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'text/xml; charset=utf-8' },
        body: soapBody,
      });

      if (response.status === 429 || response.status >= 500) {
        throw new Error(`N11 stock update failed: HTTP ${response.status}`);
      }

      return { success: response.ok, sku, stock, platform: 'N11' };
    } catch (error) {
      this.logger.warn(`N11 updateStock error: ${(error as Error).message}`);
      throw error;
    }
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    try {
      const url = `${this.baseUrl}/ProductService/`;
      const soapBody = this.buildSoapEnvelope(
        'UpdateProductPriceBySellerCode',
        `
                <productSellerCode>${this.escapeXml(sku)}</productSellerCode>
                <price>${price}</price>
                <currencyType>1</currencyType>
            `,
      );

      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'text/xml; charset=utf-8' },
        body: soapBody,
      });

      if (response.status === 429 || response.status >= 500) {
        throw new Error(`N11 price update failed: HTTP ${response.status}`);
      }

      return { success: response.ok, sku, price, platform: 'N11' };
    } catch (error) {
      this.logger.warn(`N11 updatePrice error: ${(error as Error).message}`);
      throw error;
    }
  }

  async getStoreInfo(storeId: string): Promise<any> {
    try {
      const url = `https://www.n11.com/magaza/${storeId}`;
      const scraped = await this.scrapingService.scrapeStore(url, 'N11');
      if (scraped) {
        return {
          storeId,
          storeName: scraped.storeName || storeId,
          totalProducts: scraped.productCount ?? 0,
          averageRating: scraped.rating ?? 0,
          totalReviews: scraped.totalReviews ?? 0,
          followersCount: scraped.followerCount ?? 0,
          platform: 'N11',
        };
      }
    } catch (error) {
      this.logger.warn(
        `N11 getStoreInfo scraping failed: ${(error as Error).message}`,
      );
    }

    return {
      storeId,
      storeName: storeId,
      platform: 'N11',
    };
  }

  async getStoreProducts(
    storeId: string,
    limit: number = 10,
  ): Promise<N11Product[]> {
    try {
      const url = `https://www.n11.com/magaza/${storeId}`;
      const scraped = await this.scrapingService.scrapeStoreProducts(
        url,
        'N11',
        limit,
      );
      if (Array.isArray(scraped) && scraped.length > 0) {
        return (scraped as unknown as Array<Record<string, unknown>>).map(
          (item) => ({
            productId: String(item.productId || item.id || ''),
            title: String(item.title || ''),
            price: Number(item.price || 0),
            salePrice: Number(item.salePrice || item.price || 0),
            stockCount: Number(item.stock ?? item.stockCount ?? 0),
            rating: Number(item.rating || 0),
            reviewCount: Number(item.reviewCount || 0),
            url: String(item.url || ''),
            images: Array.isArray(item.images) ? (item.images as string[]) : [],
            storeName: item.storeName ? String(item.storeName) : undefined,
            storeUrl: item.storeUrl ? String(item.storeUrl) : undefined,
          }),
        );
      }
    } catch (error) {
      this.logger.warn(
        `N11 getStoreProducts scraping failed: ${(error as Error).message}`,
      );
    }

    return [];
  }

  /**
   * N11 mağaza SEO analizi yap
   */
  async analyzeStoreSEO(
    storeId?: string,
  ): Promise<MarketplaceAnalysisResponse> {
    try {
      const resolvedStoreId = storeId || 'default';
      const storeInfo = await this.getStoreInfo(resolvedStoreId);
      const products = await this.getStoreProducts(resolvedStoreId, 20);

      const seoScore = this.calculateSEOScore(storeInfo, products);

      const metricSources = {
        storeName: 'scraped',
        rating: 'scraped',
        followers: 'scraped',
        totalProducts: 'scraped',
        responseTime: 'not_available',
        monthlyTraffic: 'not_available',
        monthlyTurnover: 'not_available',
        titleOptimization: 'calculated',
        imageOptimization: 'calculated',
        priceCompetitiveness: 'calculated',
        stockHealth: 'calculated',
        ratingTrend: 'scraped',
        reviewCount: 'scraped',
      } as const;

      return {
        platform: 'N11',
        storeId: resolvedStoreId,
        storeName: storeInfo.storeName,
        seoScore,
        dataSources: {
          overall: 'scraped+calculated',
          seoScore: 'calculated',
          products: 'scraped',
          metrics: metricSources,
          reasons: {
            responseTime:
              'N11 public source yanit suresi bilgisini acik olarak saglamiyor.',
            monthlyTraffic:
              'Aylik trafik verisi platform public endpointlerinde bulunmuyor.',
            monthlyTurnover:
              'Aylik ciro verisi platform public endpointlerinde bulunmuyor.',
          },
          evidence: {
            adapter: 'n11.bridge',
            productSampleSize: products.length,
            hasCredentials: Boolean(this.apiKey && this.apiKey !== 'public'),
          },
        },
        confidence: computeConfidenceFromSources(metricSources),
        metrics: {
          storeName: storeInfo.storeName,
          rating: storeInfo.averageRating,
          followers: storeInfo.followersCount,
          totalProducts: storeInfo.totalProducts,
          titleOptimization: this.analyzeTitles(products),
          imageOptimization: this.analyzeImages(products),
          priceCompetitiveness: this.analyzePrices(products),
          stockHealth: this.analyzeStock(products),
          ratingTrend: storeInfo.averageRating,
          reviewCount: 0,
        },
        products: products.map((p) => ({
          name: p.title,
          price: p.salePrice,
          rating: p.rating,
          reviews: p.reviewCount,
          stock: p.stockCount,
        })),
        recommendations: this.generateRecommendations(storeInfo, products),
        timestamp: new Date(),
      };
    } catch (error) {
      this.logger.error(`N11 SEO analysis error: ${(error as Error).message}`);
      throw error;
    }
  }

  private calculateSEOScore(storeInfo: any, products: N11Product[]): number {
    let score = 48; // Base score

    // Rating (max +18) - N11 uses 10-scale
    score += (storeInfo.averageRating / 10) * 18;

    // Product count (max +12)
    const productBonus = Math.min(storeInfo.totalProducts / 50, 12);
    score += productBonus;

    // Stock health (max +15)
    const avgStock =
      products.length > 0
        ? products.reduce((sum, p) => sum + (p.stockCount > 0 ? 1 : 0), 0) /
          products.length
        : 0;
    score += avgStock * 15;

    // Followers (max +7)
    const followerBonus = Math.min(storeInfo.followersCount / 1000, 7);
    score += followerBonus;

    return Math.min(Math.round(score), 100);
  }

  private analyzeTitles(products: N11Product[]): number {
    if (!products.length) return 50;
    let validCount = 0;

    products.forEach((p) => {
      const title = p.title || '';
      // N11 title: 20-150 chars ideal
      if (title.length >= 20 && title.length <= 150) validCount++;
    });

    return Math.round((validCount / products.length) * 100);
  }

  private analyzeImages(products: N11Product[]): number {
    if (!products.length) return 50;
    let validCount = 0;
    products.forEach((p) => {
      if (p.images && p.images.length >= 1) validCount++;
    });
    return Math.round((validCount / products.length) * 100);
  }

  private analyzePrices(products: N11Product[]): number {
    if (!products.length) return 50;
    const avgPrice =
      products.reduce((sum, p) => sum + p.salePrice, 0) / products.length;
    const variance =
      products.reduce((sum, p) => sum + Math.abs(p.salePrice - avgPrice), 0) /
      products.length;
    const normalizedVariance = Math.min(
      25,
      (variance / Math.max(avgPrice, 1)) * 100,
    );
    return Math.round(
      Math.min(
        100,
        Math.max(50, (avgPrice > 150 ? 70 : 60) + (25 - normalizedVariance)),
      ),
    );
  }

  private analyzeStock(products: N11Product[]): number {
    if (!products.length) return 50;
    const stockedProducts = products.filter((p) => p.stockCount > 5).length;
    return Math.round((stockedProducts / products.length) * 100);
  }

  private generateRecommendations(
    storeInfo: any,
    products: N11Product[],
  ): string[] {
    const recommendations: string[] = [];

    if (storeInfo.averageRating < 8.0) {
      recommendations.push(
        'N11 mağaza puanını artırmak için kargolama sürelerini kısalt',
      );
    }

    if (storeInfo.totalProducts < 20) {
      recommendations.push(
        'N11 kataloğunu genişlet - minimum 20+ ürün önerilir',
      );
    }

    const lowStockProducts = products.filter((p) => p.stockCount < 10).length;
    if (lowStockProducts > 0) {
      recommendations.push(`${lowStockProducts} ürün kritik stok seviyesinde`);
    }

    if (storeInfo.followersCount < 100) {
      recommendations.push(
        'Mağaza takipçi sayısını artırmak için kampanyalar düzenle',
      );
    }

    return recommendations;
  }

  // SOAP helpers
  private buildSoapEnvelope(action: string, body: string): string {
    return `<?xml version="1.0" encoding="utf-8"?>
<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:sch="http://www.n11.com/ws/schemas">
    <soapenv:Header>
        <sch:Authentication>
            <appKey>${this.escapeXml(this.apiKey)}</appKey>
            <appSecret>${this.escapeXml(this.apiSecret)}</appSecret>
        </sch:Authentication>
    </soapenv:Header>
    <soapenv:Body>
        <sch:${action}Request>
            ${body}
        </sch:${action}Request>
    </soapenv:Body>
</soapenv:Envelope>`;
  }

  private escapeXml(str: string): string {
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  private parseProductListResponse(xml: string): N11Product[] {
    // Simple regex-based XML parsing for product data
    const products: N11Product[] = [];
    const productBlocks = xml.match(/<product>([\s\S]*?)<\/product>/g) || [];

    for (const block of productBlocks.slice(0, 100)) {
      const getValue = (tag: string): string => {
        const match = block.match(new RegExp(`<${tag}>([^<]*)</${tag}>`));
        return match ? match[1] : '';
      };

      products.push({
        productId: getValue('id') || getValue('productSellerCode'),
        title: getValue('title'),
        price: Number(getValue('displayPrice') || getValue('price') || 0),
        salePrice: Number(getValue('salePrice') || getValue('price') || 0),
        stockCount: Number(getValue('stockAmount') || 0),
        rating: 0,
        reviewCount: 0,
        url: getValue('url'),
        images: [],
      });
    }

    return products;
  }

  private daysAgo(days: number): string {
    const d = new Date(Date.now() - days * 86400000);
    return `${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear()}`;
  }

  private now(): string {
    const d = new Date();
    return `${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear()}`;
  }

  /**
   * N11'den ürün yorumlarını SOAP API ile çek
   */
  async getReviews(
    page: number = 0,
    size: number = 100,
  ): Promise<MarketplaceReview[]> {
    if (!this.apiKey || !this.apiSecret) {
      this.logger.warn('N11 getReviews: API kimlik bilgileri eksik');
      return [];
    }
    try {
      const url = `${this.baseUrl}/ProductService/`;
      const soapBody = this.buildSoapEnvelope(
        'GetProductQuestionList',
        `
                <pagingData>
                    <currentPage>${page}</currentPage>
                    <pageSize>${size}</pageSize>
                </pagingData>
            `,
      );
      const response = await fetch(url, {
        method: 'POST',
        headers: { 'Content-Type': 'text/xml; charset=utf-8', SOAPAction: '' },
        body: soapBody,
      });
      if (!response.ok) return [];
      const xml = await response.text();
      return this.parseReviewsFromXml(xml);
    } catch (error) {
      this.logger.warn(`N11 getReviews hatası: ${(error as Error).message}`);
      return [];
    }
  }

  private parseReviewsFromXml(xml: string): MarketplaceReview[] {
    const reviews: MarketplaceReview[] = [];
    const blocks =
      xml.match(/<review>([\ s\S]*?)<\/review>/g) ||
      xml.match(/<question>([\ s\S]*?)<\/question>/g) ||
      [];
    for (const block of blocks.slice(0, 100)) {
      const getValue = (tag: string): string => {
        const match = block.match(new RegExp(`<${tag}>([^<]*)</${tag}>`));
        return match ? match[1].trim() : '';
      };
      const id = getValue('id') || getValue('reviewId');
      const comment =
        getValue('review') || getValue('comment') || getValue('question');
      if (!id || !comment) continue;
      reviews.push({
        externalId: id,
        productName: getValue('productName') || 'N11 Ürün',
        customerName: getValue('reviewer') || getValue('userName') || 'Müşteri',
        rating: Number(getValue('rating') || getValue('rate') || 0),
        comment,
        reviewDate: getValue('createDate')
          ? new Date(getValue('createDate'))
          : new Date(),
        verified: getValue('approved') === 'true',
      });
    }
    return reviews;
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { MarketplaceBridge, MarketplaceReview } from './marketplace.service';
import { ScrapingService } from '../scraping/scraping.service';

interface OttoProduct {
  productId: string;
  title: string;
  price: number;
  salePrice: number;
  stockCount: number;
  rating: number;
  reviewCount: number;
  url: string;
  images: string[];
  brand: string;
  category: string;
  deliveryTime: string;
  freeReturns: boolean;
  isMarketplace: boolean;
}

@Injectable()
export class OttoBridge implements MarketplaceBridge {
  private readonly logger = new Logger(OttoBridge.name);
  private readonly apiUrl = 'https://api.otto.market';

  constructor(
    private readonly apiKey: string,
    private readonly apiSecret: string,
    private readonly partnerId: string,
    private readonly scrapingService: ScrapingService,
  ) {}

  private getAuthHeader(): string {
    return (
      'Bearer ' +
      Buffer.from(`${this.apiKey}:${this.apiSecret}`).toString('base64')
    );
  }

  async syncProducts(): Promise<any> {
    try {
      const response = await fetch(`${this.apiUrl}/v1/products`, {
        headers: {
          Authorization: this.getAuthHeader(),
          'Content-Type': 'application/json',
          'X-Partner-ID': this.partnerId,
        },
      });

      if (!response.ok) {
        return {
          success: false,
          platform: 'OTTO',
          error: `HTTP ${response.status}`,
        };
      }

      const data = await response.json();
      return {
        success: true,
        platform: 'OTTO',
        count: data.products?.length || 0,
      };
    } catch (error) {
      return {
        success: false,
        platform: 'OTTO',
        error: (error as Error).message,
      };
    }
  }

  async syncOrders(): Promise<any> {
    try {
      const response = await fetch(`${this.apiUrl}/v1/orders`, {
        headers: {
          Authorization: this.getAuthHeader(),
          'X-Partner-ID': this.partnerId,
        },
      });
      if (!response.ok) throw new Error(`HTTP ${response.status}`);
      const data = await response.json();
      return { success: true, platform: 'OTTO', orders: data.orders || [] };
    } catch (error) {
      return {
        success: false,
        platform: 'OTTO',
        error: (error as Error).message,
      };
    }
  }

  async updateStock(sku: string, stock: number): Promise<any> {
    try {
      const response = await fetch(`${this.apiUrl}/v1/products/${sku}/stock`, {
        method: 'PUT',
        headers: {
          Authorization: this.getAuthHeader(),
          'Content-Type': 'application/json',
          'X-Partner-ID': this.partnerId,
        },
        body: JSON.stringify({ stock }),
      });
      return { success: response.ok, sku, stock, platform: 'OTTO' };
    } catch (error) {
      throw error;
    }
  }

  async updatePrice(sku: string, price: number): Promise<any> {
    try {
      const response = await fetch(`${this.apiUrl}/v1/products/${sku}/price`, {
        method: 'PUT',
        headers: {
          Authorization: this.getAuthHeader(),
          'Content-Type': 'application/json',
          'X-Partner-ID': this.partnerId,
        },
        body: JSON.stringify({ price }),
      });
      return { success: response.ok, sku, price, platform: 'OTTO' };
    } catch (error) {
      throw error;
    }
  }

  async getStoreInfo(storeId: string): Promise<any> {
    try {
      const url = `https://www.otto.de/p/${storeId}`;
      const scraped = await this.scrapingService.scrapeStore(url, 'OTTO');
      return {
        storeId,
        storeName: scraped?.storeName || storeId,
        platform: 'OTTO',
        country: 'Germany',
        isMarketplace: true,
      };
    } catch (error) {
      throw error;
    }
  }

  async getStoreProducts(
    storeId?: string,
    limit: number = 10,
  ): Promise<OttoProduct[]> {
    try {
      const response = await fetch(
        `${this.apiUrl}/v1/products?partner_id=${storeId}&limit=${limit}`,
        {
          headers: {
            Authorization: this.getAuthHeader(),
            'X-Partner-ID': this.partnerId,
          },
        },
      );
      const data = await response.json();
      return (data.products || []).map((item: any) => ({
        productId: item.sku,
        title: item.name,
        price: item.price,
        salePrice: item.sale_price || item.price,
        stockCount: item.stock || 0,
        rating: item.rating || 0,
        reviewCount: item.review_count || 0,
        url: item.product_url,
        images: item.images || [],
        brand: item.brand,
        category: item.category,
        deliveryTime: item.delivery_time,
        freeReturns: item.free_returns || false,
        isMarketplace: item.is_marketplace || true,
      }));
    } catch (error) {
      throw error;
    }
  }
}

