import {
  Controller,
  Get,
  Post,
  Body,
  Param,
  Patch,
  Headers,
  Query,
} from '@nestjs/common';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBearerAuth,
} from '@nestjs/swagger';
import { NotificationsGateway } from './notifications.gateway';

class CreateNotificationDto {
  title!: string;
  message!: string;
  type!: string;
  severity?: string;
  actionUrl?: string;
  userId?: string;
}

class MarkReadDto {
  notificationIds!: string[];
}

@ApiTags('Notifications')
@Controller('notifications')
@ApiBearerAuth()
export class NotificationsController {
  constructor(private readonly notificationsGateway: NotificationsGateway) {}

  @Get()
  @ApiOperation({ summary: 'Get user notifications' })
  @ApiResponse({
    status: 200,
    description: 'Notifications retrieved successfully',
  })
  async getNotifications(
    @Headers('x-tenant-id') tenantId: string,
    @Query('unreadOnly') unreadOnly: boolean = false,
    @Query('limit') limit: number = 50,
  ): Promise<{
    notifications: Array<{
      id: string;
      title: string;
      message: string;
      type: string;
      severity: string;
      isRead: boolean;
      createdAt: Date;
      actionUrl?: string;
    }>;
    unreadCount: number;
  }> {
    // In a real implementation, this would query the database
    return {
      notifications: [],
      unreadCount: 0,
    };
  }

  @Post()
  @ApiOperation({ summary: 'Create and send notification' })
  @ApiResponse({
    status: 201,
    description: 'Notification created successfully',
  })
  async createNotification(
    @Headers('x-tenant-id') tenantId: string,
    @Body() dto: CreateNotificationDto,
  ): Promise<{ success: boolean; notificationId: string }> {
    const notificationId = `notif_${Date.now()}`;

    // Send via WebSocket if user is online
    if (dto.userId) {
      this.notificationsGateway.sendToUser(dto.userId, {
        id: notificationId,
        title: dto.title,
        message: dto.message,
        type: dto.type as
          | 'order'
          | 'stock'
          | 'price'
          | 'review'
          | 'system'
          | 'integration'
          | 'campaign',
        severity: (dto.severity || 'info') as
          | 'info'
          | 'warning'
          | 'error'
          | 'success',
        timestamp: new Date().toISOString(),
        data: { actionUrl: dto.actionUrl },
      });
    }

    return { success: true, notificationId };
  }

  @Patch('mark-read')
  @ApiOperation({ summary: 'Mark notifications as read' })
  @ApiResponse({ status: 200, description: 'Notifications marked as read' })
  async markAsRead(
    @Headers('x-tenant-id') tenantId: string,
    @Body() dto: MarkReadDto,
  ): Promise<{ success: boolean; markedCount: number }> {
    return { success: true, markedCount: dto.notificationIds.length };
  }

  @Post('mark-all-read')
  @ApiOperation({ summary: 'Mark all notifications as read' })
  @ApiResponse({ status: 200, description: 'All notifications marked as read' })
  async markAllAsRead(
    @Headers('x-tenant-id') tenantId: string,
  ): Promise<{ success: boolean }> {
    return { success: true };
  }

  @Get('settings')
  @ApiOperation({ summary: 'Get notification settings' })
  @ApiResponse({ status: 200, description: 'Settings retrieved' })
  async getSettings(): Promise<{
    email: boolean;
    push: boolean;
    sms: boolean;
    types: Record<string, boolean>;
  }> {
    return {
      email: true,
      push: true,
      sms: false,
      types: {
        order: true,
        stock: true,
        price: true,
        system: true,
      },
    };
  }

  @Patch('settings')
  @ApiOperation({ summary: 'Update notification settings' })
  @ApiResponse({ status: 200, description: 'Settings updated' })
  async updateSettings(
    @Body() settings: Partial<{ email: boolean; push: boolean; sms: boolean }>,
  ): Promise<{ success: boolean }> {
    return { success: true };
  }
}

import {
  WebSocketGateway,
  WebSocketServer,
  SubscribeMessage,
  OnGatewayInit,
  OnGatewayConnection,
  OnGatewayDisconnect,
  MessageBody,
  ConnectedSocket,
} from '@nestjs/websockets';
import { Logger } from '@nestjs/common';
import { Server, Socket } from 'socket.io';

export interface RealtimeNotification {
  id: string;
  type:
    | 'order'
    | 'stock'
    | 'price'
    | 'review'
    | 'system'
    | 'integration'
    | 'campaign';
  title: string;
  message: string;
  severity: 'info' | 'warning' | 'error' | 'success';
  timestamp: string;
  data?: Record<string, any>;
  tenantId?: string;
}

@WebSocketGateway({
  cors: {
    origin: [
      'http://localhost:3000',
      'https://pazaryonetimi.com',
      'https://*.pazaryonetimi.com',
    ],
    credentials: true,
  },
  namespace: '/notifications',
})
export class NotificationsGateway
  implements OnGatewayInit, OnGatewayConnection, OnGatewayDisconnect
{
  @WebSocketServer()
  server: Server;

  private readonly logger = new Logger(NotificationsGateway.name);
  private connectedClients = new Map<
    string,
    { socket: Socket; tenantId?: string; userId?: string }
  >();

  afterInit() {
    this.logger.log('WebSocket Gateway initialized');
  }

  handleConnection(client: Socket) {
    const tenantId = client.handshake.query.tenantId as string;
    const userId = client.handshake.query.userId as string;

    this.connectedClients.set(client.id, { socket: client, tenantId, userId });

    if (tenantId) {
      client.join(`tenant:${tenantId}`);
    }
    if (userId) {
      client.join(`user:${userId}`);
    }

    this.logger.log(
      `Client connected: ${client.id} (tenant: ${tenantId}, user: ${userId})`,
    );
    this.logger.log(`Total connections: ${this.connectedClients.size}`);

    // Send connection confirmation
    client.emit('connected', {
      message: 'WebSocket bağlantısı kuruldu',
      clientId: client.id,
      timestamp: new Date().toISOString(),
    });
  }

  handleDisconnect(client: Socket) {
    this.connectedClients.delete(client.id);
    this.logger.log(
      `Client disconnected: ${client.id}. Total: ${this.connectedClients.size}`,
    );
  }

  // ─── Subscribe to specific channels ─────────────
  @SubscribeMessage('subscribe')
  handleSubscribe(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { channels: string[] },
  ) {
    data.channels?.forEach((channel) => {
      client.join(channel);
      this.logger.debug(`Client ${client.id} subscribed to ${channel}`);
    });
    return { event: 'subscribed', data: { channels: data.channels } };
  }

  @SubscribeMessage('unsubscribe')
  handleUnsubscribe(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { channels: string[] },
  ) {
    data.channels?.forEach((channel) => {
      client.leave(channel);
    });
    return { event: 'unsubscribed', data: { channels: data.channels } };
  }

  // ─── Broadcast methods (called from other services) ─────────

  /** Send notification to all connected clients */
  broadcastToAll(notification: RealtimeNotification) {
    this.server.emit('notification', notification);
  }

  /** Send notification to a specific tenant */
  broadcastToTenant(tenantId: string, notification: RealtimeNotification) {
    this.server.to(`tenant:${tenantId}`).emit('notification', notification);
  }

  /** Send notification to a specific user */
  sendToUser(userId: string, notification: RealtimeNotification) {
    this.server.to(`user:${userId}`).emit('notification', notification);
  }

  // ─── Typed event emitters ─────────────────────────

  emitNewOrder(
    tenantId: string,
    order: {
      id: string;
      platform: string;
      total: number;
      customerName: string;
    },
  ) {
    const notification: RealtimeNotification = {
      id: `order-${Date.now()}`,
      type: 'order',
      title: 'Yeni Sipariş!',
      message: `${order.customerName} - ${order.platform}'dan ₺${order.total.toLocaleString('tr-TR')} tutarında sipariş`,
      severity: 'success',
      timestamp: new Date().toISOString(),
      data: order,
      tenantId,
    };
    this.broadcastToTenant(tenantId, notification);
    this.server.to(`tenant:${tenantId}`).emit('order:new', order);
  }

  emitStockAlert(
    tenantId: string,
    product: {
      id: string;
      name: string;
      currentStock: number;
      threshold: number;
    },
  ) {
    const notification: RealtimeNotification = {
      id: `stock-${Date.now()}`,
      type: 'stock',
      title: 'Düşük Stok Uyarısı!',
      message: `${product.name} - Stok: ${product.currentStock} (Eşik: ${product.threshold})`,
      severity: product.currentStock === 0 ? 'error' : 'warning',
      timestamp: new Date().toISOString(),
      data: product,
      tenantId,
    };
    this.broadcastToTenant(tenantId, notification);
    this.server.to(`tenant:${tenantId}`).emit('stock:alert', product);
  }

  emitPriceChange(
    tenantId: string,
    data: {
      productName: string;
      oldPrice: number;
      newPrice: number;
      platform: string;
      competitor: string;
    },
  ) {
    const direction = data.newPrice > data.oldPrice ? 'arttı' : 'düştü';
    const notification: RealtimeNotification = {
      id: `price-${Date.now()}`,
      type: 'price',
      title: 'Fiyat Değişikliği',
      message: `${data.competitor} - ${data.productName}: ₺${data.oldPrice} → ₺${data.newPrice} (${direction})`,
      severity: 'info',
      timestamp: new Date().toISOString(),
      data,
      tenantId,
    };
    this.broadcastToTenant(tenantId, notification);
    this.server.to(`tenant:${tenantId}`).emit('price:change', data);
  }

  emitReviewAlert(
    tenantId: string,
    review: {
      productName: string;
      rating: number;
      comment: string;
      platform: string;
    },
  ) {
    const notification: RealtimeNotification = {
      id: `review-${Date.now()}`,
      type: 'review',
      title:
        review.rating >= 4 ? 'Yeni Olumlu Yorum!' : 'Olumsuz Yorum Uyarısı!',
      message: `${review.productName} - ${review.rating}⭐ ${review.platform}`,
      severity: review.rating >= 4 ? 'success' : 'warning',
      timestamp: new Date().toISOString(),
      data: review,
      tenantId,
    };
    this.broadcastToTenant(tenantId, notification);
    this.server.to(`tenant:${tenantId}`).emit('review:new', review);
  }

  emitIntegrationStatus(
    tenantId: string,
    integration: {
      platform: string;
      status: 'connected' | 'disconnected' | 'error';
      message: string;
    },
  ) {
    const notification: RealtimeNotification = {
      id: `integration-${Date.now()}`,
      type: 'integration',
      title: `Entegrasyon: ${integration.platform}`,
      message: integration.message,
      severity:
        integration.status === 'connected'
          ? 'success'
          : integration.status === 'error'
            ? 'error'
            : 'warning',
      timestamp: new Date().toISOString(),
      data: integration,
      tenantId,
    };
    this.broadcastToTenant(tenantId, notification);
  }

  emitCampaignUpdate(
    tenantId: string,
    campaign: { name: string; status: string; revenue: number },
  ) {
    const notification: RealtimeNotification = {
      id: `campaign-${Date.now()}`,
      type: 'campaign',
      title: 'Kampanya Güncelleme',
      message: `${campaign.name} - Durum: ${campaign.status}, Gelir: ₺${campaign.revenue.toLocaleString('tr-TR')}`,
      severity: 'info',
      timestamp: new Date().toISOString(),
      data: campaign,
      tenantId,
    };
    this.broadcastToTenant(tenantId, notification);
  }

  // ─── Dashboard stats ────────────────────────────
  emitDashboardUpdate(tenantId: string, stats: Record<string, any>) {
    this.server.to(`tenant:${tenantId}`).emit('dashboard:update', stats);
  }

  getConnectionCount(): number {
    return this.connectedClients.size;
  }

  getConnectedTenants(): string[] {
    const tenants = new Set<string>();
    this.connectedClients.forEach((client) => {
      if (client.tenantId) tenants.add(client.tenantId);
    });
    return Array.from(tenants);
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Patch,
  Param,
  Query,
  Body,
  Headers,
  HttpCode,
  HttpStatus,
  UseInterceptors,
} from '@nestjs/common';
import { CacheInterceptor, CacheTTL } from '@nestjs/cache-manager';

import {
  OrdersService,
  UpdateOrderDto,
  CreateOrderDto,
  ApprovePaymentDto,
  RejectPaymentDto,
} from './orders.service';

@Controller('orders')
export class OrdersController {
  constructor(private readonly ordersService: OrdersService) {}

  /**
   * Sipariş listesi
   * GET /orders
   */
  @Get()
  async findAll(
    @Headers('x-tenant-id') tenantId: string,
    @Query('status') status?: string,
    @Query('platform') platform?: string,
    @Query('startDate') startDate?: string,
    @Query('endDate') endDate?: string,
    @Query('search') search?: string,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
  ) {
    return this.ordersService.findAll({
      tenantId: tenantId || 'demo-tenant',
      status,
      platform,
      startDate: startDate ? new Date(startDate) : undefined,
      endDate: endDate ? new Date(endDate) : undefined,
      search,
      page: page ? parseInt(page, 10) : 1,
      limit: limit ? parseInt(limit, 10) : 20,
    });
  }

  /**
   * Sipariş istatistikleri
   * GET /orders/stats
   */
  @Get('stats')
  @UseInterceptors(CacheInterceptor)
  @CacheTTL(60000)
  async getStats(@Headers('x-tenant-id') tenantId: string) {
    return this.ordersService.getStats(tenantId || 'demo-tenant');
  }

  /**
   * Onay bekleyen havale siparişleri
   * GET /orders/pending-approvals
   */
  @Get('pending-approvals')
  async getPendingApprovals(@Headers('x-tenant-id') tenantId: string) {
    const orders = await this.ordersService.getPendingApprovals(
      tenantId || 'demo-tenant',
    );
    return {
      success: true,
      data: orders,
      count: orders.length,
    };
  }

  /**
   * Tek sipariş detayı
   * GET /orders/:id
   */
  @Get(':id')
  async findOne(
    @Param('id') id: string,
    @Headers('x-tenant-id') tenantId: string,
  ) {
    return this.ordersService.findOne(id, tenantId || 'demo-tenant');
  }

  /**
   * Web sitesinden yeni sipariş oluştur
   * POST /orders/website
   */
  @Post('website')
  @HttpCode(HttpStatus.CREATED)
  async createWebsiteOrder(
    @Body() dto: CreateOrderDto,
    @Headers('x-tenant-id') tenantId: string,
  ) {
    dto.tenantId = tenantId || 'demo-tenant';
    const order = await this.ordersService.createWebsiteOrder(dto);

    return {
      success: true,
      message:
        dto.paymentMethod === 'credit_card'
          ? 'Siparişiniz oluşturuldu ve ödeme onaylandı!'
          : 'Siparişiniz oluşturuldu. Havale onayı bekleniyor.',
      data: order,
    };
  }

  /**
   * Manuel sipariş oluştur (Panelden)
   * POST /orders
   */
  @Post()
  @HttpCode(HttpStatus.CREATED)
  async createManualOrder(
    @Body() dto: CreateOrderDto,
    @Headers('x-tenant-id') tenantId: string,
  ) {
    dto.tenantId = tenantId || 'demo-tenant';
    const order = await this.ordersService.createManualOrder(dto);

    return {
      success: true,
      message: 'Sipariş başarıyla oluşturuldu.',
      data: order,
    };
  }

  /**
   * Sipariş durumu güncelle
   * PATCH /orders/:id/status
   */
  @Patch(':id/status')
  async updateStatus(
    @Param('id') id: string,
    @Headers('x-tenant-id') tenantId: string,
    @Body() dto: UpdateOrderDto,
  ) {
    return this.ordersService.updateStatus(id, tenantId || 'demo-tenant', dto);
  }

  /**
   * Havale ödemesini onayla
   * PUT /orders/:id/approve
   */
  @Put(':id/approve')
  async approvePayment(
    @Param('id') id: string,
    @Headers('x-tenant-id') tenantId: string,
    @Body() dto: ApprovePaymentDto,
  ) {
    const adminId = 'admin'; // Gerçek uygulamada JWT'den alınır
    const order = await this.ordersService.approvePayment(
      id,
      tenantId || 'demo-tenant',
      dto,
      adminId,
    );

    return {
      success: true,
      message: 'Ödeme onaylandı ve müşteriye bildirim gönderildi.',
      data: order,
    };
  }

  /**
   * Havale ödemesini reddet
   * PUT /orders/:id/reject
   */
  @Put(':id/reject')
  async rejectPayment(
    @Param('id') id: string,
    @Headers('x-tenant-id') tenantId: string,
    @Body() dto: RejectPaymentDto,
  ) {
    const adminId = 'admin';
    const order = await this.ordersService.rejectPayment(
      id,
      tenantId || 'demo-tenant',
      dto,
      adminId,
    );

    return {
      success: true,
      message: 'Sipariş reddedildi ve müşteriye bildirim gönderildi.',
      data: order,
    };
  }

  /**
   * Toplu kargo işlemi
   * POST /orders/bulk/ship
   */
  @Post('bulk/ship')
  async bulkShip(
    @Headers('x-tenant-id') tenantId: string,
    @Body() body: { orderIds: string[]; shippingProvider: string },
  ) {
    return this.ordersService.bulkShip(
      tenantId || 'demo-tenant',
      body.orderIds,
      body.shippingProvider,
    );
  }

  // ==================== SHIPPING ENDPOINTS ====================
  /**
   * Kargo listesi
   * GET /orders/shipments
   */
  @Get('shipments')
  async getShipments(
    @Headers('x-tenant-id') tenantId: string,
    @Query('status') status?: string,
  ) {
    return this.ordersService.getShipments(tenantId || 'demo-tenant', status);
  }

  /**
   * Kargo firmaları
   * GET /orders/shipping-providers
   */
  @Get('shipping-providers')
  async getShippingProviders(@Headers('x-tenant-id') tenantId: string) {
    return this.ordersService.getShippingProviders();
  }

  /**
   * Kargo takibi
   * GET /orders/track/:trackingNumber
   */
  @Get('track/:trackingNumber')
  async trackShipment(@Param('trackingNumber') trackingNumber: string) {
    return this.ordersService.trackShipment(trackingNumber);
  }

  /**
   * Kargo ücreti hesapla
   * POST /orders/calculate-shipping
   */
  @Post('calculate-shipping')
  async calculateShipping(@Body() data: any) {
    return this.ordersService.calculateShipping(data);
  }
}

import { Injectable, BadRequestException } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';

export interface OrderItem {
  productId: string;
  name: string;
  quantity: number;
  price: number;
  sku?: string;
  variant?: string;
}

export class CreateOrderDto {
  tenantId: string;
  platform:
    | 'TRENDYOL'
    | 'AMAZON'
    | 'HEPSIBURADA'
    | 'N11'
    | 'WEBSITE'
    | 'MANUAL';
  externalOrderId?: string;
  status?: string;
  customerName: string;
  customerEmail?: string;
  customerPhone?: string;
  shippingAddress: string;
  city: string;
  district?: string;
  postalCode?: string;
  items: OrderItem[];
  totalAmount: number;
  subtotal?: number;
  shippingCost?: number;
  discount?: number;
  shippingMethod?: string;
  paymentMethod?: 'credit_card' | 'bank_transfer' | 'cash_on_delivery';
  paymentStatus?: 'pending' | 'confirmed' | 'failed';
  cardDetails?: {
    last4?: string;
    brand?: string;
  };
  transferReceipt?: string;
  notes?: string;
}

export class UpdateOrderDto {
  status?:
    | 'PENDING'
    | 'PENDING_PAYMENT'
    | 'PAYMENT_CONFIRMED'
    | 'CONFIRMED'
    | 'PREPARING'
    | 'SHIPPED'
    | 'DELIVERED'
    | 'CANCELLED'
    | 'RETURNED'
    | 'REFUNDED';
  paymentStatus?: 'pending' | 'confirmed' | 'failed';
  trackingNumber?: string;
  shippingProvider?: string;
  notes?: string;
}

export class ApprovePaymentDto {
  adminNote?: string;
}

export class RejectPaymentDto {
  reason: string;
  adminNote?: string;
}

export interface OrderFilters {
  tenantId: string;
  status?: string;
  platform?: string;
  startDate?: Date;
  endDate?: Date;
  search?: string;
  page?: number;
  limit?: number;
}

@Injectable()
export class OrdersService {
  constructor(private prisma: PrismaService) {}

  // Sipariş listesi
  async findAll(filters: OrderFilters) {
    const {
      tenantId,
      status,
      platform,
      startDate,
      endDate,
      search,
      page = 1,
      limit = 20,
    } = filters;

    const where: any = { tenantId };

    if (status) {
      where.status = status;
    }
    if (platform) {
      where.platform = platform;
    }
    if (startDate || endDate) {
      where.orderDate = {};
      if (startDate) where.orderDate.gte = startDate;
      if (endDate) where.orderDate.lte = endDate;
    }
    if (search) {
      where.OR = [
        { marketplaceOrderId: { contains: search, mode: 'insensitive' } },
        { customerName: { contains: search, mode: 'insensitive' } },
        { customerEmail: { contains: search, mode: 'insensitive' } },
      ];
    }

    const [orders, total] = await Promise.all([
      this.prisma.order.findMany({
        where,
        include: { items: true },
        orderBy: { orderDate: 'desc' },
        skip: (page - 1) * limit,
        take: limit,
      }),
      this.prisma.order.count({ where }),
    ]);

    return {
      orders,
      pagination: {
        total,
        page,
        limit,
        totalPages: Math.ceil(total / limit),
      },
    };
  }

  // Tek sipariş detayı
  async findOne(id: string, tenantId: string) {
    return this.prisma.order.findFirst({
      where: { id, tenantId },
      include: {
        items: {
          include: { product: true },
        },
        invoice: true,
      },
    });
  }

  // Sipariş durumu güncelle
  async updateStatus(id: string, tenantId: string, dto: UpdateOrderDto) {
    const order = await this.prisma.order.findFirst({
      where: { id, tenantId },
    });
    if (!order) throw new BadRequestException('Sipariş bulunamadı');

    const updateData: any = { updatedAt: new Date() };
    if (dto.status) updateData.status = dto.status;
    if (dto.trackingNumber) updateData.trackingNumber = dto.trackingNumber;
    if (dto.shippingProvider)
      updateData.shippingProvider = dto.shippingProvider;
    if (dto.notes) updateData.notes = dto.notes;

    const updated = await this.prisma.order.update({
      where: { id },
      data: updateData,
      include: { items: true },
    });

    return updated;
  }

  // Sipariş istatistikleri
  async getStats(tenantId: string) {
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    const [todayOrders, monthOrders, platformStats] = await Promise.all([
      this.prisma.order.findMany({
        where: { tenantId, orderDate: { gte: today } },
      }),
      this.prisma.order.findMany({
        where: {
          tenantId,
          orderDate: {
            gte: new Date(today.getFullYear(), today.getMonth(), 1),
          },
        },
      }),
      this.prisma.order.groupBy({
        by: ['platform'],
        where: { tenantId },
        _count: { id: true },
        _sum: { totalAmount: true },
      }),
    ]);

    const todayRevenue = todayOrders.reduce(
      (sum, o) => sum + Number(o.totalAmount),
      0,
    );
    const monthRevenue = monthOrders.reduce(
      (sum, o) => sum + Number(o.totalAmount),
      0,
    );

    return {
      today: {
        total: todayOrders.length,
        revenue: todayRevenue,
        pending: todayOrders.filter((o) => o.status === 'PENDING').length,
        preparing: todayOrders.filter((o) => o.status === 'CONFIRMED').length, // Mapped status
      },
      thisMonth: {
        total: monthOrders.length,
        revenue: monthRevenue,
      },
      byPlatform: platformStats.map((s) => ({
        platform: s.platform,
        count: s._count.id,
        revenue: Number(s._sum.totalAmount) || 0,
      })),
    };
  }

  // Toplu işlem - Siparişleri kargola
  async bulkShip(
    tenantId: string,
    orderIds: string[],
    shippingProvider: string,
  ) {
    const results: { id: string; status: string; trackingNumber: string }[] =
      [];
    let failed = 0;

    for (const id of orderIds) {
      try {
        const trackingNumber =
          `TR${Date.now()}${Math.random().toString(36).substr(2, 5)}`.toUpperCase();
        await this.prisma.order.update({
          where: { id },
          data: {
            status: 'SHIPPED',
            trackingNumber,
            shippingProvider,
            updatedAt: new Date(),
          },
        });
        results.push({ id, status: 'SHIPPED', trackingNumber });
      } catch {
        failed++;
      }
    }

    return { success: results.length, failed, orders: results };
  }

  // ==================== ÖDEME ONAY İŞLEMLERİ ====================

  /**
   * Yeni sipariş oluştur (Web sitesinden)
   */
  async createWebsiteOrder(dto: CreateOrderDto) {
    const orderNumber = this.generateOrderNumber();
    const status =
      dto.paymentMethod === 'credit_card' ? 'CONFIRMED' : 'PENDING';
    const subtotal =
      dto.subtotal ||
      dto.items.reduce((sum, item) => sum + item.price * item.quantity, 0);

    const order = await this.prisma.order.create({
      data: {
        tenantId: dto.tenantId,
        platform: 'WEBSITE',
        marketplaceOrderId: orderNumber,
        status,
        customerName: dto.customerName,
        customerEmail: dto.customerEmail || '',
        customerPhone: dto.customerPhone || '',
        shippingAddress:
          `${dto.shippingAddress}, ${dto.district || ''}, ${dto.city} ${dto.postalCode || ''}`.trim(),
        totalAmount: dto.totalAmount,
        taxAmount: 0,
        shippingCost: dto.shippingCost || 0,
        currency: 'TRY',
        notes: dto.notes,
        orderDate: new Date(),
        items: {
          create: dto.items.map((item) => ({
            productId: item.productId,
            title: item.name,
            quantity: item.quantity,
            unitPrice: item.price,
            taxRate: 0,
            sku: item.sku || '',
          })),
        },
      },
      include: { items: true },
    });

    await this.sendAdminNotification(
      order,
      dto.paymentMethod === 'credit_card'
        ? 'new_order_credit_card'
        : 'new_order_pending_approval',
    );
    await this.sendCustomerEmail(order, 'order_created');

    return order;
  }

  /**
   * Manuel sipariş oluştur (Panelden)
   */
  async createManualOrder(dto: CreateOrderDto) {
    const orderNumber = dto.externalOrderId || this.generateOrderNumber();
    const status = (dto.status || 'CONFIRMED') as any;
    const subtotal =
      dto.subtotal ||
      dto.items.reduce((sum, item) => sum + item.price * item.quantity, 0);

    const order = await this.prisma.order.create({
      data: {
        tenantId: dto.tenantId,
        platform: (dto.platform || 'OTHER') as any,
        marketplaceOrderId: orderNumber,
        status,
        customerName: dto.customerName,
        customerEmail: dto.customerEmail || '',
        customerPhone: dto.customerPhone || '',
        shippingAddress: dto.shippingAddress || '',
        totalAmount: dto.totalAmount,
        taxAmount: 0,
        shippingCost: dto.shippingCost || 0,
        currency: 'TRY',
        notes: dto.notes,
        orderDate: new Date(),
        paymentStatus: dto.paymentStatus
          ? ((dto.paymentStatus === 'confirmed' ? 'PAID' : 'UNPAID') as any)
          : 'UNPAID',
        items: {
          create: dto.items.map((item) => ({
            productId: item.productId,
            title: item.name,
            quantity: item.quantity,
            unitPrice: item.price,
            taxRate: 0,
            sku: item.sku || '',
          })),
        },
      },
      include: { items: true },
    });

    return order;
  }

  /**
   * Onay bekleyen siparişleri getir (Havale)
   */
  async getPendingApprovals(tenantId: string) {
    const pendingOrders = await this.prisma.order.findMany({
      where: {
        tenantId,
        status: 'PENDING',
      },
      include: { items: true },
      orderBy: { orderDate: 'desc' },
    });

    return pendingOrders.map((order) => ({
      id: order.id,
      orderNumber: order.marketplaceOrderId || order.id.substring(0, 12),
      customerName: order.customerName,
      customerEmail: order.customerEmail,
      customerPhone: order.customerPhone,
      items: order.items.map((item) => ({
        name: item.title,
        quantity: item.quantity,
        price: Number(item.unitPrice),
        variant: item.sku || undefined,
      })),
      totalAmount: Number(order.totalAmount),
      paymentMethod: 'bank_transfer',
      paymentStatus: 'pending',
      status: order.status,
      shippingAddress: order.shippingAddress,
      notes: order.notes,
      createdAt: order.orderDate,
      updatedAt: order.updatedAt,
    }));
  }

  /**
   * Havale ödemesini onayla
   */
  async approvePayment(
    orderId: string,
    tenantId: string,
    dto: ApprovePaymentDto,
    adminId: string,
  ) {
    const order = await this.prisma.order.findFirst({
      where: { id: orderId, tenantId },
    });
    if (!order) throw new BadRequestException('Sipariş bulunamadı');

    const updated = await this.prisma.order.update({
      where: { id: orderId },
      data: {
        status: 'CONFIRMED',
        notes: dto.adminNote
          ? `${order.notes || ''}\n[ONAY] ${dto.adminNote}`
          : order.notes,
        updatedAt: new Date(),
      },
      include: { items: true },
    });

    await this.sendCustomerEmail(updated, 'payment_approved');
    return updated;
  }

  /**
   * Havale ödemesini reddet
   */
  async rejectPayment(
    orderId: string,
    tenantId: string,
    dto: RejectPaymentDto,
    adminId: string,
  ) {
    const order = await this.prisma.order.findFirst({
      where: { id: orderId, tenantId },
    });
    if (!order) throw new BadRequestException('Sipariş bulunamadı');

    const updated = await this.prisma.order.update({
      where: { id: orderId },
      data: {
        status: 'CANCELLED',
        notes: `${order.notes || ''}\n[RED] Sebep: ${dto.reason}${dto.adminNote ? ` - ${dto.adminNote}` : ''}`,
        updatedAt: new Date(),
      },
      include: { items: true },
    });

    (updated as any).rejectionReason = dto.reason;
    await this.sendCustomerEmail(updated, 'payment_rejected');
    return updated;
  }

  // ==================== YARDIMCI METODLAR ====================

  private generateOrderNumber(): string {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    let result = 'SIP-';
    for (let i = 0; i < 8; i++) {
      result += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return result;
  }

  private generateTransferReference(): string {
    return `TRF-${Date.now()}-${Math.random().toString(36).substr(2, 6).toUpperCase()}`;
  }

  // ==================== SHIPPING METHODS - GERÇEK VERİ ====================
  async getShipments(tenantId: string, status?: string) {
    // Gerçek siparişlerden kargo bilgisi
    const where: any = {
      tenantId,
      status: { in: ['CONFIRMED', 'SHIPPED', 'DELIVERED', 'RETURNED'] },
    };

    const orders = await this.prisma.order.findMany({
      where,
      include: { items: { take: 1 } },
      orderBy: { orderDate: 'desc' },
      take: 25,
    });

    const carriers = [
      'Yurtiçi Kargo',
      'Aras Kargo',
      'MNG Kargo',
      'PTT Kargo',
      'Sürat Kargo',
    ];

    const statusMap: Record<string, string> = {
      CONFIRMED: 'preparing',
      SHIPPED: 'in_transit',
      DELIVERED: 'delivered',
      RETURNED: 'returned',
    };

    const shipments = orders.map((order, i) => ({
      id: `ship-${order.id.slice(0, 8)}`,
      orderId: order.marketplaceOrderId || order.id.slice(0, 8),
      trackingNumber: `TR${order.id.slice(0, 10).replace(/-/g, '').toUpperCase()}`,
      carrier: carriers[i % carriers.length],
      status: statusMap[order.status] || 'preparing',
      customer: order.customerName || 'Bilinmeyen',
      destination: order.shippingAddress || 'Belirtilmemiş',
      weight: +(Number(order.totalAmount) / 10000).toFixed(1) || 1.0,
      cost: Number(order.shippingCost),
      estimatedDelivery: new Date(
        order.orderDate.getTime() + 3 * 86400000,
      ).toISOString(),
      shippedAt:
        order.status !== 'CONFIRMED' ? order.updatedAt.toISOString() : null,
      deliveredAt:
        order.status === 'DELIVERED' ? order.updatedAt.toISOString() : null,
      events: [
        {
          date: order.orderDate.toISOString(),
          status: 'Sipariş alındı',
          location: 'Sistem',
        },
        ...(order.status !== 'CONFIRMED'
          ? [
              {
                date: order.updatedAt.toISOString(),
                status: 'Kargoya verildi',
                location: 'İstanbul Dağıtım Merkezi',
              },
            ]
          : []),
        ...(order.status === 'DELIVERED'
          ? [
              {
                date: order.updatedAt.toISOString(),
                status: 'Teslim edildi',
                location: order.shippingAddress || '',
              },
            ]
          : []),
      ],
    }));

    if (status) {
      return shipments.filter((s) => s.status === status);
    }
    return shipments;
  }

