      'Maliyet',
      'Stok',
      'Kategori',
      'Marka',
      'Durum',
      'Etiketler',
      'Ağırlık (kg)',
    ];
    const csvRows = products.map((p: any) =>
      [
        p.sku,
        p.barcode || '',
        `"${(p.title || '').replace(/"/g, '""')}"`,
        `"${(p.description || '').replace(/"/g, '""')}"`,
