        (p.tags || []).join('|'),
        p.weight || '',
      ].join(';'),
    );

    const csv = '\uFEFF' + csvHeaders.join(';') + '\n' + csvRows.join('\n');
    res.setHeader('Content-Type', 'text/csv; charset=utf-8');
