import {
  Controller,
  Post,
  Get,
  Body,
  Param,
  Headers,
  Query,
} from '@nestjs/common';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBearerAuth,
} from '@nestjs/swagger';
import { SmsService } from './sms.service';

class SendSmsDto {
  phoneNumber!: string;
  message!: string;
}

class SendBulkSmsDto {
  phoneNumbers!: string[];
  message!: string;
}

@ApiTags('SMS')
@Controller('sms')
@ApiBearerAuth()
export class SmsController {
  constructor(private readonly smsService: SmsService) {}

  @Post('send')
  @ApiOperation({ summary: 'Send single SMS' })
  @ApiResponse({ status: 200, description: 'SMS sent successfully' })
  @ApiResponse({ status: 400, description: 'Invalid phone number or message' })
  async sendSms(
    @Body() dto: SendSmsDto,
  ): Promise<{ success: boolean; messageId?: string }> {
    const result = await this.smsService.sendSms(dto.phoneNumber, dto.message);
    return {
      success: result,
      messageId: result ? `sms_${Date.now()}` : undefined,
    };
  }

  @Post('send-bulk')
  @ApiOperation({ summary: 'Send bulk SMS to multiple recipients' })
  @ApiResponse({ status: 200, description: 'Bulk SMS sent successfully' })
  async sendBulkSms(@Body() dto: SendBulkSmsDto): Promise<{
    success: boolean;
    total: number;
    sent: number;
    failed: number;
    results: Array<{ phoneNumber: string; success: boolean; error?: string }>;
  }> {
    const results: Array<{
      phoneNumber: string;
      success: boolean;
      error?: string;
    }> = [];

    for (const phoneNumber of dto.phoneNumbers) {
      try {
        const success = await this.smsService.sendSms(phoneNumber, dto.message);
        results.push({ phoneNumber, success });
      } catch (error) {
        results.push({
          phoneNumber,
          success: false,
          error: (error as Error).message,
        });
      }
    }

    const sent = results.filter((r) => r.success).length;
    const failed = results.filter((r) => !r.success).length;

    return {
      success: failed === 0,
      total: dto.phoneNumbers.length,
      sent,
      failed,
      results,
    };
  }

  @Get('history')
  @ApiOperation({ summary: 'Get SMS sending history' })
  @ApiResponse({ status: 200, description: 'SMS history retrieved' })
  async getSmsHistory(
    @Query('limit') limit: number = 50,
    @Query('offset') offset: number = 0,
  ): Promise<{
    items: Array<{
      id: string;
      phoneNumber: string;
      message: string;
      status: string;
      sentAt: Date;
    }>;
    total: number;
  }> {
    // In a real implementation, this would query the database
    return {
      items: [],
      total: 0,
    };
  }

  @Get('balance')
  @ApiOperation({ summary: 'Get SMS provider balance' })
  @ApiResponse({ status: 200, description: 'Balance retrieved' })
  async getBalance(): Promise<{ balance: number; currency: string }> {
    return {
      balance: 1000,
      currency: 'TRY',
    };
  }
}

import { Injectable, Logger, BadRequestException } from '@nestjs/common';
import { ConfigService } from '@nestjs/config';
import axios from 'axios';

@Injectable()
export class SmsService {
  private readonly logger = new Logger(SmsService.name);

  constructor(private configService: ConfigService) {}

  async sendSms(phoneNumber: string, message: string): Promise<boolean> {
    const cleanPhone = phoneNumber.replace(/\s/g, '').replace(/^0/, '');

    if (!cleanPhone || cleanPhone.length < 10) {
      throw new BadRequestException('Geçersiz telefon numarası');
    }

    const smsProvider = this.configService.get('SMS_PROVIDER');

    if (smsProvider === 'netgsm') {
      return this.sendNetgsm(cleanPhone, message);
    }

    if (smsProvider === 'twilio') {
      return this.sendTwilio(cleanPhone, message);
    }

    // Default: Log only (development mode)
    this.logger.log(
      `[SMS] Development mode - SMS to ${cleanPhone}: ${message.substring(0, 50)}...`,
    );
    return true;
  }

  private async sendNetgsm(phone: string, message: string): Promise<boolean> {
    try {
      const username = this.configService.get('NETGSM_USERNAME');
      const password = this.configService.get('NETGSM_PASSWORD');
      const header = this.configService.get('NETGSM_HEADER', 'Pazaryonetimi');

      if (!username || !password) {
        this.logger.error('Netgsm credentials not configured');
        return false;
      }

      const response = await axios.post(
        'https://api.netgsm.com.tr/sms/send/get',
        {
          usercode: username,
          password: password,
          msgheader: header,
          gsmno: phone,
          message: message,
        },
        {
          headers: {
            'Content-Type': 'application/x-www-form-urlencoded',
          },
        },
      );

      const result = response.data;
      // Netgsm returns "00" for success
      const success = result.startsWith('00');

      if (!success) {
        this.logger.error(`Netgsm error: ${result}`);
      }

      return success;
    } catch (error) {
      this.logger.error(`Netgsm send failed: ${(error as Error).message}`);
      return false;
    }
  }

  private async sendTwilio(phone: string, message: string): Promise<boolean> {
    try {
      const accountSid = this.configService.get('TWILIO_ACCOUNT_SID');
      const authToken = this.configService.get('TWILIO_AUTH_TOKEN');
      const fromNumber = this.configService.get('TWILIO_PHONE_NUMBER');

      if (!accountSid || !authToken || !fromNumber) {
        this.logger.error('Twilio credentials not configured');
        return false;
      }

      const response = await axios.post(
        `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Messages.json`,
        {
          To: `+90${phone}`,
          From: fromNumber,
          Body: message,
        },
        {
          auth: {
            username: accountSid,
            password: authToken,
          },
        },
      );

      return response.status === 201;
    } catch (error) {
      this.logger.error(`Twilio send failed: ${(error as Error).message}`);
      return false;
    }
  }

  async getBalance(): Promise<{ provider: string; balance: number }> {
    const smsProvider = this.configService.get('SMS_PROVIDER');

    if (smsProvider === 'netgsm') {
      try {
        const username = this.configService.get('NETGSM_USERNAME');
        const password = this.configService.get('NETGSM_PASSWORD');

        const response = await axios.post(
          'https://api.netgsm.com.tr/balance/get',
          {
            usercode: username,
            password: password,
          },
        );

        return { provider: 'netgsm', balance: parseFloat(response.data) || 0 };
      } catch (error) {
        this.logger.error(
          `Netgsm balance check failed: ${(error as Error).message}`,
        );
        return { provider: 'netgsm', balance: 0 };
      }
    }

    return { provider: smsProvider || 'none', balance: 0 };
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Body,
  Param,
  Query,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import {
  SubscriptionsService,
  CreateSubscriptionDto,
  ApproveSubscriptionDto,
  RejectSubscriptionDto,
  SubscriptionFilters,
  SubscriptionStatus,
  PackageType,
  PaymentStatus,
} from './subscriptions.service';

@Controller('subscriptions')
export class SubscriptionsController {
  constructor(private readonly subscriptionsService: SubscriptionsService) {}

  /**
   * Yeni abonelik oluştur
   * POST /subscriptions
   */
  @Post()
  @HttpCode(HttpStatus.CREATED)
  async createSubscription(@Body() dto: CreateSubscriptionDto) {
    const subscription =
      await this.subscriptionsService.createSubscription(dto);
    return {
      success: true,
      message:
        dto.paymentMethod === 'credit_card'
          ? 'Aboneliğiniz başarıyla oluşturuldu ve aktif edildi!'
          : 'Abonelik talebiniz alındı. Havale onayı sonrası aktif olacaktır.',
      data: subscription,
    };
  }

  /**
   * Tüm abonelikleri listele
   * GET /subscriptions?status=pending&packageType=professional&search=ahmet&page=1&limit=20
   */
  @Get()
  async findAll(
    @Query('status') status?: string,
    @Query('packageType') packageType?: string,
    @Query('paymentStatus') paymentStatus?: string,
    @Query('search') search?: string,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
  ) {
    const filters: SubscriptionFilters = {
      status: status as SubscriptionStatus,
      packageType: packageType as PackageType,
      paymentStatus: paymentStatus as PaymentStatus,
      search,
      page: page ? parseInt(page, 10) : 1,
      limit: limit ? parseInt(limit, 10) : 20,
    };

    const result = await this.subscriptionsService.findAll(filters);
    return {
      success: true,
      ...result,
    };
  }

  /**
   * Onay bekleyen abonelikler
   * GET /subscriptions/pending
   */
  @Get('pending')
  async getPendingApprovals() {
    const subscriptions = await this.subscriptionsService.getPendingApprovals();
    return {
      success: true,
      count: subscriptions.length,
      data: subscriptions,
    };
  }

  /**
   * Abonelik istatistikleri
   * GET /subscriptions/stats
   */
  @Get('stats')
  async getStats() {
    const stats = await this.subscriptionsService.getStats();
    return {
      success: true,
      data: stats,
    };
  }

  /**
   * Tek abonelik detayı
   * GET /subscriptions/:id
   */
  @Get(':id')
  async findOne(@Param('id') id: string) {
    const subscription = await this.subscriptionsService.findOne(id);
    return {
      success: true,
      data: subscription,
    };
  }

  /**
   * Aboneliği onayla
   * PUT /subscriptions/:id/approve
   */
  @Put(':id/approve')
  async approveSubscription(
    @Param('id') id: string,
    @Body() dto: ApproveSubscriptionDto,
  ) {
    // Gerçek uygulamada adminId JWT'den alınır
    const adminId = 'admin-001';
    const subscription = await this.subscriptionsService.approveSubscription(
      id,
      dto,
      adminId,
    );
    return {
      success: true,
      message: 'Abonelik başarıyla onaylandı!',
      data: subscription,
    };
  }

  /**
   * Aboneliği reddet
   * PUT /subscriptions/:id/reject
   */
  @Put(':id/reject')
  async rejectSubscription(
    @Param('id') id: string,
    @Body() dto: RejectSubscriptionDto,
  ) {
    const adminId = 'admin-001';
    const subscription = await this.subscriptionsService.rejectSubscription(
      id,
      dto,
      adminId,
    );
    return {
      success: true,
      message: 'Abonelik reddedildi.',
      data: subscription,
    };
  }

  /**
   * Aboneliği askıya al
   * PUT /subscriptions/:id/suspend
   */
  @Put(':id/suspend')
  async suspendSubscription(
    @Param('id') id: string,
    @Body('reason') reason: string,
  ) {
    const adminId = 'admin-001';
    const subscription = await this.subscriptionsService.suspendSubscription(
      id,
      reason,
      adminId,
    );
    return {
      success: true,
      message: 'Abonelik askıya alındı.',
      data: subscription,
    };
  }

  /**
   * Aboneliği iptal et
   * PUT /subscriptions/:id/cancel
   */
  @Put(':id/cancel')
  async cancelSubscription(
    @Param('id') id: string,
    @Body('reason') reason: string,
  ) {
    const adminId = 'admin-001';
    const subscription = await this.subscriptionsService.cancelSubscription(
      id,
      reason,
      adminId,
    );
    return {
      success: true,
      message: 'Abonelik iptal edildi.',
      data: subscription,
    };
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';

// Types
export type SubscriptionStatus =
  | 'pending'
  | 'active'
  | 'cancelled'
  | 'expired'
  | 'suspended';
export type PaymentStatus = 'pending' | 'paid' | 'failed' | 'refunded';
export type PackageType = 'starter' | 'professional' | 'enterprise';
export type BillingPeriod = 'monthly' | 'yearly';

// DTOs
export class CreateSubscriptionDto {
  userId?: string;
  userName: string;
  userEmail: string;
  userPhone: string;
  companyName?: string;
  packageType: PackageType;
  billingPeriod: BillingPeriod;
  paymentMethod: 'credit_card' | 'bank_transfer';
  notes?: string;
}

export class UpdateSubscriptionDto {
  status?: SubscriptionStatus;
  paymentStatus?: PaymentStatus;
  notes?: string;
}

export class ApproveSubscriptionDto {
  adminNote?: string;
}

export class RejectSubscriptionDto {
  reason: string;
  adminNote?: string;
}

export interface SubscriptionFilters {
  status?: SubscriptionStatus;
  packageType?: PackageType;
  paymentStatus?: PaymentStatus;
  search?: string;
  page?: number;
  limit?: number;
}

// Package prices
const packagePrices: Record<PackageType, { monthly: number; yearly: number }> =
  {
    starter: { monthly: 299, yearly: 2990 },
    professional: { monthly: 599, yearly: 5990 },
    enterprise: { monthly: 1299, yearly: 12990 },
  };

@Injectable()
export class SubscriptionsService {
  constructor(private prisma: PrismaService) {}

  /**
   * Yeni abonelik oluştur (fiyatlandırma sayfasından)
   */
  async createSubscription(dto: CreateSubscriptionDto) {
    const subscriptionId = this.generateId();
    const amount = packagePrices[dto.packageType][dto.billingPeriod];

    // Ödeme yöntemine göre durum belirle
    const status: SubscriptionStatus =
      dto.paymentMethod === 'credit_card'
        ? 'active' // Kredi kartı - otomatik aktif
        : 'pending'; // Havale - admin onayı gerekli

    const paymentStatus: PaymentStatus =
      dto.paymentMethod === 'credit_card' ? 'paid' : 'pending';

    const startDate =
      dto.paymentMethod === 'credit_card' ? new Date() : undefined;
    const endDate = startDate
      ? new Date(
          startDate.getTime() +
            (dto.billingPeriod === 'yearly' ? 365 : 30) * 24 * 60 * 60 * 1000,
        )
      : undefined;

    const subscription = {
      id: subscriptionId,
      userId: dto.userId || this.generateId('user'),
      userName: dto.userName,
      userEmail: dto.userEmail,
      userPhone: dto.userPhone,
      companyName: dto.companyName,
      packageType: dto.packageType,
      billingPeriod: dto.billingPeriod,
      paymentMethod: dto.paymentMethod,
      paymentStatus,
      status,
      amount,
      startDate,
      endDate,
      notes: dto.notes,
      createdAt: new Date(),
      updatedAt: new Date(),
      approvedAt: dto.paymentMethod === 'credit_card' ? new Date() : undefined,
      approvedBy:
        dto.paymentMethod === 'credit_card' ? 'Sistem (Otomatik)' : undefined,
    };

    // Admin bildirimi gönder
    if (dto.paymentMethod === 'credit_card') {
      await this.sendAdminNotification(subscription, 'new_subscription_auto');
    } else {
      await this.sendAdminNotification(
        subscription,
        'new_subscription_pending',
      );
    }

    // Müşteriye e-posta gönder
    await this.sendCustomerEmail(subscription, 'subscription_created');

    return subscription;
  }

  /**
   * Abonelikleri listele
   */
  async findAll(filters: SubscriptionFilters) {
    // Demo data
    let subscriptions = this.getDemoSubscriptions();

    // Filtrele
    if (filters.status) {
      subscriptions = subscriptions.filter((s) => s.status === filters.status);
    }

    if (filters.packageType) {
      subscriptions = subscriptions.filter(
        (s) => s.packageType === filters.packageType,
      );
    }

    if (filters.paymentStatus) {
      subscriptions = subscriptions.filter(
        (s) => s.paymentStatus === filters.paymentStatus,
      );
    }

    if (filters.search) {
      const search = filters.search.toLowerCase();
      subscriptions = subscriptions.filter(
        (s) =>
          s.userName.toLowerCase().includes(search) ||
          s.userEmail.toLowerCase().includes(search) ||
          s.userPhone.includes(search) ||
          (s.companyName && s.companyName.toLowerCase().includes(search)),
      );
    }

    // Pagination
    const page = filters.page || 1;
    const limit = filters.limit || 20;
    const start = (page - 1) * limit;
    const paginatedData = subscriptions.slice(start, start + limit);

    return {
      data: paginatedData,
      total: subscriptions.length,
      page,
      limit,
      totalPages: Math.ceil(subscriptions.length / limit),
    };
  }

  /**
   * Tek abonelik detayı
   */
  async findOne(id: string) {
    const subscriptions = this.getDemoSubscriptions();
    const subscription = subscriptions.find((s) => s.id === id);

    if (!subscription) {
      throw new NotFoundException('Abonelik bulunamadı');
    }

    return subscription;
  }

  /**
   * Onay bekleyen abonelikler
   */
  async getPendingApprovals() {
    const subscriptions = this.getDemoSubscriptions();
    return subscriptions.filter((s) => s.status === 'pending');
  }

  /**
   * Aboneliği onayla
   */
  async approveSubscription(
    id: string,
    dto: ApproveSubscriptionDto,
    adminId: string,
  ) {
    const subscription = await this.findOne(id);

    if (subscription.status !== 'pending') {
      throw new BadRequestException(
        'Bu abonelik zaten onaylanmış veya iptal edilmiş',
      );
    }

    const startDate = new Date();
    const endDate = new Date(
      startDate.getTime() +
        (subscription.billingPeriod === 'yearly' ? 365 : 30) *
          24 *
          60 *
          60 *
          1000,
    );

    const updatedSubscription = {
      ...subscription,
      status: 'active' as SubscriptionStatus,
      paymentStatus: 'paid' as PaymentStatus,
      startDate,
      endDate,
      approvedAt: new Date(),
      approvedBy: adminId,
      adminNotes: dto.adminNote,
      updatedAt: new Date(),
    };

    // Müşteriye bildirim gönder
    await this.sendCustomerEmail(updatedSubscription, 'subscription_approved');

    return updatedSubscription;
  }

  /**
   * Aboneliği reddet
   */
  async rejectSubscription(
    id: string,
    dto: RejectSubscriptionDto,
    adminId: string,
  ) {
    const subscription = await this.findOne(id);

    if (subscription.status !== 'pending') {
      throw new BadRequestException('Bu abonelik zaten işlenmiş');
    }

    const updatedSubscription = {
      ...subscription,
      status: 'cancelled' as SubscriptionStatus,
      paymentStatus: 'refunded' as PaymentStatus,
      rejectedAt: new Date(),
      rejectedBy: adminId,
      rejectionReason: dto.reason,
      adminNotes: dto.adminNote,
      updatedAt: new Date(),
    };

    // Müşteriye red sebebiyle birlikte bildirim gönder
    await this.sendCustomerEmail(updatedSubscription, 'subscription_rejected');

    return updatedSubscription;
  }

  /**
   * Aboneliği askıya al
   */
  async suspendSubscription(id: string, reason: string, adminId: string) {
    const subscription = await this.findOne(id);

    if (subscription.status !== 'active') {
      throw new BadRequestException(
        'Sadece aktif abonelikler askıya alınabilir',
      );
    }

    const updatedSubscription = {
      ...subscription,
      status: 'suspended' as SubscriptionStatus,
      suspendedAt: new Date(),
      suspendedBy: adminId,
      suspensionReason: reason,
      updatedAt: new Date(),
    };

    await this.sendCustomerEmail(updatedSubscription, 'subscription_suspended');

    return updatedSubscription;
  }

  /**
   * Aboneliği iptal et
   */
  async cancelSubscription(id: string, reason: string, adminId: string) {
    const subscription = await this.findOne(id);

    const updatedSubscription = {
      ...subscription,
      status: 'cancelled' as SubscriptionStatus,
      cancelledAt: new Date(),
      cancelledBy: adminId,
      cancellationReason: reason,
      updatedAt: new Date(),
    };

    await this.sendCustomerEmail(updatedSubscription, 'subscription_cancelled');

    return updatedSubscription;
  }

  /**
   * Abonelik istatistikleri
   */
  async getStats() {
    const subscriptions = this.getDemoSubscriptions();

    const active = subscriptions.filter((s) => s.status === 'active');
    const pending = subscriptions.filter((s) => s.status === 'pending');

    const monthlyRevenue = active.reduce(
      (sum, s) =>
        sum + (s.billingPeriod === 'monthly' ? s.amount : s.amount / 12),
      0,
    );

    const byPackage = {
      starter: subscriptions.filter((s) => s.packageType === 'starter').length,
      professional: subscriptions.filter(
        (s) => s.packageType === 'professional',
      ).length,
      enterprise: subscriptions.filter((s) => s.packageType === 'enterprise')
        .length,
    };

    return {
      total: subscriptions.length,
      active: active.length,
      pending: pending.length,
      cancelled: subscriptions.filter((s) => s.status === 'cancelled').length,
      monthlyRevenue: Math.round(monthlyRevenue),
      yearlyRevenue: Math.round(monthlyRevenue * 12),
      byPackage,
      byBillingPeriod: {
        monthly: subscriptions.filter((s) => s.billingPeriod === 'monthly')
          .length,
        yearly: subscriptions.filter((s) => s.billingPeriod === 'yearly')
          .length,
      },
    };
  }

  // ========== Helper Methods ==========

  private generateId(prefix = 'sub'): string {
    return `${prefix}_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  private async sendAdminNotification(subscription: any, type: string) {
    const packageNames: Record<PackageType, string> = {
