  async getStats() {
    return this.announcementsService.getStats();
  }

  // Get announcements for a tenant
  @Get('tenant/:tenantId')
  async findForTenant(@Param('tenantId') tenantId: string) {
    return this.announcementsService.findForTenant(tenantId);
