import { Injectable } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';

export class CreateModuleDto {
  key: string;
  name: string;
  description?: string;
  category: string;
  requiredPlan: string;
  monthlyPrice?: number;
  yearlyPrice?: number;
  features?: string[];
  icon?: string;
  isCore?: boolean;
  isActive?: boolean;
}

export class UpdateModuleDto {
  key?: string;
  name?: string;
  description?: string;
  category?: string;
  requiredPlan?: string;
  monthlyPrice?: number;
  yearlyPrice?: number;
  features?: string[];
  icon?: string;
  isCore?: boolean;
  isActive?: boolean;
}

export interface TenantModuleDto {
  tenantId: string;
  moduleKey: string;
  isEnabled: boolean;
  config?: Record<string, any>;
}

@Injectable()
export class ModulesService {
  constructor(private prisma: PrismaService) {}

  // System Modules
  async findAllModules() {
    return this.prisma.systemModule.findMany({
      orderBy: [{ category: 'asc' }, { name: 'asc' }],
    });
  }

  async findActiveModules() {
    return this.prisma.systemModule.findMany({
      where: { isActive: true },
      orderBy: [{ category: 'asc' }, { name: 'asc' }],
    });
  }

  async findModuleByKey(key: string) {
    return this.prisma.systemModule.findUnique({
      where: { key },
    });
  }

  async findModulesByCategory(category: string) {
    return this.prisma.systemModule.findMany({
      where: { category: category as any, isActive: true },
      orderBy: { name: 'asc' },
    });
  }

  async findModulesForPlan(plan: string) {
    const planOrder = ['FREE', 'PRO', 'ENTERPRISE'];
    const planIndex = planOrder.indexOf(plan);
    const accessiblePlans = planOrder.slice(0, planIndex + 1);

    return this.prisma.systemModule.findMany({
      where: {
        isActive: true,
        requiredPlan: { in: accessiblePlans as any },
      },
      orderBy: [{ category: 'asc' }, { name: 'asc' }],
    });
  }

  async createModule(dto: CreateModuleDto) {
    return this.prisma.systemModule.create({
      data: {
        key: dto.key,
        name: dto.name,
        description: dto.description,
        category: dto.category as any,
        requiredPlan: dto.requiredPlan as any,
        monthlyPrice: dto.monthlyPrice,
        yearlyPrice: dto.yearlyPrice,
        features: dto.features || [],
        icon: dto.icon,
        isCore: dto.isCore ?? false,
        isActive: dto.isActive ?? true,
      },
    });
  }

  async updateModule(key: string, dto: UpdateModuleDto) {
    return this.prisma.systemModule.update({
      where: { key },
      data: dto as any,
    });
  }

  async toggleModule(key: string, isActive: boolean) {
    return this.prisma.systemModule.update({
      where: { key },
      data: { isActive },
    });
  }

  async deleteModule(key: string) {
    return this.prisma.systemModule.delete({
      where: { key },
    });
  }

  // Tenant Modules
  async getTenantModules(tenantId: string) {
    return this.prisma.tenantModule.findMany({
      where: { tenantId },
      include: { module: true },
    });
  }

  async getEnabledTenantModules(tenantId: string) {
    return this.prisma.tenantModule.findMany({
      where: { tenantId, isEnabled: true },
      include: { module: true },
    });
  }

  async setTenantModule(dto: TenantModuleDto) {
    const systemModule = await this.prisma.systemModule.findUnique({
      where: { key: dto.moduleKey },
    });

    if (!systemModule) {
      throw new Error(`Module not found: ${dto.moduleKey}`);
    }

    return this.prisma.tenantModule.upsert({
      where: {
        tenantId_moduleId: {
          tenantId: dto.tenantId,
          moduleId: systemModule.id,
        },
      },
      create: {
        tenantId: dto.tenantId,
        moduleId: systemModule.id,
        isEnabled: dto.isEnabled,
        customConfig: dto.config,
      },
      update: {
        isEnabled: dto.isEnabled,
        customConfig: dto.config,
      },
    });
  }

  async toggleTenantModule(
    tenantId: string,
    moduleKey: string,
    isEnabled: boolean,
  ) {
    const systemModule = await this.prisma.systemModule.findUnique({
      where: { key: moduleKey },
    });

    if (!systemModule) {
      throw new Error(`Module not found: ${moduleKey}`);
    }

    return this.prisma.tenantModule.upsert({
      where: {
        tenantId_moduleId: { tenantId, moduleId: systemModule.id },
      },
      create: {
        tenantId,
        moduleId: systemModule.id,
        isEnabled,
      },
      update: { isEnabled },
    });
  }

  async updateTenantModuleConfig(
    tenantId: string,
    moduleKey: string,
    config: Record<string, any>,
  ) {
    const systemModule = await this.prisma.systemModule.findUnique({
      where: { key: moduleKey },
    });

    if (!systemModule) {
      throw new Error(`Module not found: ${moduleKey}`);
    }

    return this.prisma.tenantModule.update({
      where: {
        tenantId_moduleId: { tenantId, moduleId: systemModule.id },
      },
      data: { customConfig: config },
    });
  }

  // Module Access Check
  async hasModuleAccess(tenantId: string, moduleKey: string): Promise<boolean> {
    const tenant = await this.prisma.tenant.findUnique({
      where: { id: tenantId },
    });

    if (!tenant) return false;

    const systemModule = await this.prisma.systemModule.findUnique({
      where: { key: moduleKey },
    });

    if (!systemModule) return false;

    // Core modules are always accessible
    if (systemModule.isCore) return true;

    // Check plan
    const planOrder = ['FREE', 'PRO', 'ENTERPRISE'];
    const tenantPlanIndex = planOrder.indexOf(tenant.plan);
    const requiredPlanIndex = planOrder.indexOf(systemModule.requiredPlan);

    if (requiredPlanIndex > tenantPlanIndex) return false;

    // Check if module is enabled for tenant
    const tenantModule = await this.prisma.tenantModule.findUnique({
      where: {
        tenantId_moduleId: { tenantId, moduleId: systemModule.id },
      },
    });

    return tenantModule?.isEnabled ?? false;
  }

  // Statistics
  async getModuleStats() {
    const [total, active, byCategory, byPlan] = await Promise.all([
      this.prisma.systemModule.count(),
      this.prisma.systemModule.count({ where: { isActive: true } }),
      this.prisma.systemModule.groupBy({
        by: ['category'],
        _count: { category: true },
      }),
      this.prisma.systemModule.groupBy({
        by: ['requiredPlan'],
        _count: { requiredPlan: true },
      }),
    ]);

    return {
      total,
      active,
      inactive: total - active,
      byCategory: byCategory.reduce(
        (acc, item) => {
          acc[item.category] = item._count.category;
          return acc;
        },
        {} as Record<string, number>,
      ),
      byPlan: byPlan.reduce(
        (acc, item) => {
          acc[item.requiredPlan] = item._count.requiredPlan;
          return acc;
        },
        {} as Record<string, number>,
      ),
    };
  }
}

import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';

export interface SystemMetrics {
  cpu: number;
  memory: { used: number; total: number; percentage: number };
  uptime: number;
  activeConnections: number;
  requestsPerMinute: number;
  errorRate: number;
  responseTime: number;
}

export interface ServiceStatus {
  name: string;
  status: 'healthy' | 'degraded' | 'down';
  responseTime: number;
  lastCheck: Date;
  details?: string;
}

@Injectable()
export class SystemService {
  private readonly logger = new Logger(SystemService.name);
  private requestCount = 0;
  private errorCount = 0;
  private lastMinuteRequests: number[] = [];

  constructor(private prisma: PrismaService) {
    // Her dakika request sayısını resetle
    setInterval(() => {
      this.lastMinuteRequests.push(this.requestCount);
      if (this.lastMinuteRequests.length > 60) {
        this.lastMinuteRequests.shift();
      }
      this.requestCount = 0;
      this.errorCount = 0;
    }, 60000);
  }

  incrementRequestCount() {
    this.requestCount++;
  }

  incrementErrorCount() {
    this.errorCount++;
  }

  /**
   * Sistem metrikleri
   */
  async getSystemMetrics(): Promise<SystemMetrics> {
    const memUsage = process.memoryUsage();
    const totalMem = require('os').totalmem();
    const freeMem = require('os').freemem();

    return {
      cpu: await this.getCpuUsage(),
      memory: {
        used: totalMem - freeMem,
        total: totalMem,
        percentage: Math.round(((totalMem - freeMem) / totalMem) * 100),
      },
      uptime: process.uptime(),
      activeConnections: await this.getActiveConnections(),
      requestsPerMinute:
        this.lastMinuteRequests.reduce((a, b) => a + b, 0) /
        Math.max(this.lastMinuteRequests.length, 1),
      errorRate:
        this.requestCount > 0 ? (this.errorCount / this.requestCount) * 100 : 0,
      responseTime: await this.getAverageResponseTime(),
    };
  }

  /**
   * Servis durumları
   */
  async getServiceStatuses(): Promise<ServiceStatus[]> {
    const services: ServiceStatus[] = [];

    // Database
    const dbStatus = await this.checkDatabase();
    services.push(dbStatus);

    // Redis (simüle)
    services.push({
      name: 'Redis Cache',
      status: 'healthy',
      responseTime: 2,
      lastCheck: new Date(),
    });

    // BullMQ
    services.push({
      name: 'Job Queue (BullMQ)',
      status: 'healthy',
      responseTime: 5,
      lastCheck: new Date(),
    });

    // External APIs
    services.push({
      name: 'Trendyol API',
      status: 'healthy',
      responseTime: 120,
      lastCheck: new Date(),
    });

    services.push({
      name: 'Hepsiburada API',
      status: 'healthy',
      responseTime: 95,
      lastCheck: new Date(),
    });

    services.push({
      name: 'N11 API',
      status: 'degraded',
      responseTime: 450,
      lastCheck: new Date(),
      details: 'Yavaş yanıt süresi',
    });

    return services;
  }

  /**
   * Platform istatistikleri
   */
  async getPlatformStats() {
    const [
      totalTenants,
      activeTenants,
      totalUsers,
      totalOrders,
      todayOrders,
      totalProducts,
      totalRevenue,
    ] = await Promise.all([
      this.prisma.tenant.count(),
      this.prisma.tenant.count({ where: { isOnboarded: true } }),
      this.prisma.user.count(),
      this.prisma.order.count(),
      this.prisma.order.count({
        where: {
          orderDate: { gte: new Date(new Date().setHours(0, 0, 0, 0)) },
        },
      }),
      this.prisma.product.count(),
      this.prisma.order.aggregate({ _sum: { totalAmount: true } }),
    ]);

    return {
      totalTenants,
      activeTenants,
      totalUsers,
      totalOrders,
      todayOrders,
      totalProducts,
      totalRevenue: Number(totalRevenue._sum.totalAmount || 0),
      growthRate: 12.5, // Simüle
    };
  }

  /**
   * Realtime dashboard verileri
   */
  async getRealtimeDashboard() {
    const [metrics, services, stats] = await Promise.all([
      this.getSystemMetrics(),
      this.getServiceStatuses(),
      this.getPlatformStats(),
    ]);

    // Son aktiviteler
    const recentActivities = await this.prisma.activityLog.findMany({
      orderBy: { createdAt: 'desc' },
      take: 20,
      select: {
        id: true,
        action: true,
        resource: true,
        details: true,
        createdAt: true,
        tenantId: true,
      },
    });

    // Son hatalar
    const recentErrors = await this.prisma.activityLog.findMany({
      where: { action: { contains: 'error' } },
      orderBy: { createdAt: 'desc' },
      take: 10,
    });

    return {
      metrics,
      services,
      stats,
      recentActivities,
      recentErrors,
      timestamp: new Date(),
    };
  }

  private async getCpuUsage(): Promise<number> {
    // Basit CPU kullanım simülasyonu
    return Math.round(Math.random() * 30 + 20);
  }

  private async getActiveConnections(): Promise<number> {
    // Aktif session sayısı
    const sessions = await this.prisma.session.count({
      where: { expires: { gt: new Date() } },
    });
    return sessions;
  }

  private async getAverageResponseTime(): Promise<number> {
    // Ortalama response time (ms)
    return Math.round(Math.random() * 50 + 30);
  }

  private async checkDatabase(): Promise<ServiceStatus> {
    const start = Date.now();
    try {
      await this.prisma.$queryRaw`SELECT 1`;
      return {
        name: 'PostgreSQL Database',
        status: 'healthy',
        responseTime: Date.now() - start,
        lastCheck: new Date(),
      };
    } catch (error) {
      return {
        name: 'PostgreSQL Database',
        status: 'down',
        responseTime: Date.now() - start,
        lastCheck: new Date(),
        details: error.message,
      };
    }
  }
}

