import { Injectable, Logger } from '@nestjs/common';
import { PrismaService } from '../../database/prisma.service';
import { GoogleGenerativeAI } from '@google/generative-ai';
import { ConfigService } from '@nestjs/config';
import { ReportsService } from '../reports/reports.service';

@Injectable()
export class WhatsappCommandService {
  private readonly logger = new Logger(WhatsappCommandService.name);
  private genAI: GoogleGenerativeAI;
  private model: any;

  constructor(
    private prisma: PrismaService,
    private configService: ConfigService,
    private reportsService: ReportsService,
  ) {
    const apiKey = this.configService.get<string>('GEMINI_API_KEY');
    if (apiKey) {
      this.genAI = new GoogleGenerativeAI(apiKey);
      this.model = this.genAI.getGenerativeModel({ model: 'gemini-1.5-flash' });
    }
  }

  /**
   * Processes an incoming WhatsApp message (text or voice)
   */
  async handleIncoming(
    tenantId: string,
    from: string,
    content: string,
    type: 'text' | 'voice',
  ): Promise<string> {
    this.logger.log(
      `Processing WhatsApp command from ${from}: ${content.substring(0, 50)}...`,
    );

    // 1. Interpret command using AI
    const interpretation = await this.interpretCommand(content, type);

    // 2. Execute action based on interpretation
    return await this.executeCommand(tenantId, interpretation);
  }

  private async interpretCommand(
    content: string,
    type: 'text' | 'voice',
  ): Promise<any> {
    const prompt = `
      Sen "Pazaryonetimi WhatsApp Asistanı"sın. Kullanıcının mesajını analiz et ve ne yapmak istediğini anla.
      
      MESAJ TİPİ: ${type}
      MESAJ İÇERİĞİ: "${content}"
      
      YETENEKLERİN:
      1. SALES_REPORT: Günlük, haftalık veya aylık satış raporu/ciro bilgisi verme.
      2. PRICE_UPDATE: Bir ürünün fiyatını güncelleme.
      3. STOCK_CHECK: Ürün stok durumunu sorgulama.
      4. GENERAL_QUERY: Genel sistem soruları.

      Lütfen şu JSON formatında cevap ver:
      {
        "action": "SALES_REPORT" | "PRICE_UPDATE" | "STOCK_CHECK" | "GENERAL_QUERY",
        "params": { 
          "period": "daily" | "weekly" | "monthly", 
          "sku": "...", 
          "newPrice": 100,
          "productName": "..."
        },
        "reason": "Kısa açıklama"
      }
    `;

    try {
      const result = await this.model.generateContent(prompt);
      const response = await result.response;
      const text = response
        .text()
        .replace(/```json|```/g, '')
        .trim();
      return JSON.parse(text);
    } catch (error) {
      this.logger.error(`Command Interpretation error: ${error.message}`);
      return { action: 'GENERAL_QUERY', params: {}, reason: 'Anlaşılamadı' };
    }
  }

  private async executeCommand(
    tenantId: string,
    interpretation: any,
  ): Promise<string> {
    const { action, params } = interpretation;

    try {
      switch (action) {
        case 'SALES_REPORT':
          const period =
            params.period === 'weekly'
              ? 'last_7_days'
              : params.period === 'monthly'
                ? 'last_30_days'
                : 'today';
          const report = await this.reportsService.generateReport(
            tenantId,
            period as any,
            'growth' as any,
          );
          return `📊 *Flaş Rapor (${params.period || 'günlük'})*:\n\nToplam Ciro: ₺${report.summary.totalRevenue}\nSipariş Adedi: ${report.summary.totalOrders}\nBüyüme: %${report.summary.revenueChange > 0 ? '+' : ''}${report.summary.revenueChange}\n\nBol satışlar dilerim! 🚀`;

        case 'PRICE_UPDATE':
          if (params.sku && params.newPrice) {
            const productToUpdate = await this.prisma.product.findFirst({
              where: { sku: params.sku, tenantId },
            });
            if (productToUpdate) {
              await this.prisma.product.update({
                where: { id: productToUpdate.id },
                data: { price: params.newPrice },
              });
              return `✅ *Fiyat Güncellendi!*\n\nÜrün: ${productToUpdate.title}\nYeni Fiyat: ₺${params.newPrice}\n\nTüm pazaryerlerinde senkronizasyon başlatıldı.`;
            }
          }
          return '❌ SKU veya fiyat bilgisi eksik ya da ürün bulunamadı. Örn: "ABC-123 fiyatını 500 TL yap"';

        case 'STOCK_CHECK':
          const product = await this.prisma.product.findFirst({
            where: {
              OR: [
                { sku: params.sku || '___' },
                { title: { contains: params.productName || '___' } },
              ],
              tenantId,
            },
          });
          if (product) {
            return `📦 *Stok Durumu*:\n\nÜrün: ${product.title}\nSKU: ${product.sku}\nMevcut Stok: ${product.stock} adet.\nStatu: ${product.stock > 0 ? '✅ Satışta' : '🛑 Tükendi'}`;
          }
          return '❌ Ürün bulunamadı.';

        default:
          return '🤖 Mesajınızı tam anlayamadım ama her zaman buradayım! Satış raporu isteyebilir veya fiyat güncelleyebilirsiniz.';
      }
    } catch (error) {
      this.logger.error(`Execution error: ${error.message}`);
      return '⚠️ Komut işlenirken bir hata oluştu. Lütfen tekrar deneyin.';
    }
  }
}

import {
  Controller,
  Get,
  Post,
  Put,
  Body,
  Headers,
  Query,
  HttpCode,
  HttpStatus,
} from '@nestjs/common';
import { WhatsappService } from './whatsapp.service';
import { WhatsappCommandService } from './whatsapp-command.service';

@Controller('whatsapp')
export class WhatsappController {
  constructor(
    private readonly whatsappService: WhatsappService,
    private readonly commandService: WhatsappCommandService,
  ) {}

  @Get('config')
  async getConfig(@Headers('x-tenant-id') tenantId: string) {
    return this.whatsappService.getConfig(tenantId);
  }

  @Put('config')
  async updateConfig(
    @Headers('x-tenant-id') tenantId: string,
    @Body() data: any,
  ) {
    return this.whatsappService.updateConfig(tenantId, data);
  }

  @Post('test')
  async sendTestMessage(
    @Headers('x-tenant-id') tenantId: string,
    @Body() data: { phone: string; message: string },
  ) {
    return this.whatsappService.sendTestMessage(
      tenantId,
      data.phone,
      data.message,
    );
  }

  @Post('send')
  async sendMessage(
    @Headers('x-tenant-id') tenantId: string,
    @Body()
    data: {
      phone: string;
      template: string;
      variables: Record<string, string>;
    },
  ) {
    return this.whatsappService.sendMessage(
      tenantId,
      data.phone,
      data.template,
      data.variables,
    );
  }

  @Get('templates')
  async getTemplates(@Headers('x-tenant-id') tenantId: string) {
    return this.whatsappService.getTemplates(tenantId);
  }

  @Get('logs')
  async getLogs(
    @Headers('x-tenant-id') tenantId: string,
    @Query('page') page?: string,
    @Query('limit') limit?: string,
  ) {
    return this.whatsappService.getLogs(
      tenantId,
      parseInt(page || '1'),
      parseInt(limit || '20'),
    );
  }

  @Post('webhook')
  @HttpCode(HttpStatus.OK)
  async handleWebhook(
    @Body() body: any,
    @Headers('x-tenant-id') tenantId: string,
  ) {
    // Meta/Twilio Webhook Logic
    const from =
      body.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.from || body.From;
    const text =
      body.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.text?.body ||
      body.Body;
    const type =
      body.entry?.[0]?.changes?.[0]?.value?.messages?.[0]?.type === 'audio'
        ? 'voice'
        : 'text';

    if (text) {
      const response = await this.commandService.handleIncoming(
        tenantId || 'default',
        from,
        text,
        type,
      );

      // Send response back to user
      await this.whatsappService.sendTestMessage(
        tenantId || 'default',
        from,
        response,
      );
    }

    return { success: true };
  }

  @Get('webhook')
  verifyWebhook(
    @Query('hub.verify_token') token: string,
    @Query('hub.challenge') challenge: string,
  ) {
    // Meta Webhook Verification
    return challenge;
  }
}

import { Injectable, Logger } from '@nestjs/common';

export interface WhatsappConfig {
  enabled: boolean;
  provider: 'meta' | 'twilio' | 'wati';
  apiKey: string;
  phoneNumberId: string;
  businessAccountId: string;
  webhookVerifyToken: string;
  notifications: {
    orderConfirmation: boolean;
    shippingUpdate: boolean;
    deliveryConfirmation: boolean;
    returnUpdate: boolean;
    lowStock: boolean;
    priceChange: boolean;
  };
}

export interface MessageTemplate {
  id: string;
  name: string;
  content: string;
  variables: string[];
  category: string;
}

@Injectable()
export class WhatsappService {
  private readonly logger = new Logger(WhatsappService.name);

  // In-memory config store (in production, use database)
  private configs: Map<string, WhatsappConfig> = new Map();
  private messageLogs: Map<string, any[]> = new Map();

  async getConfig(tenantId: string): Promise<WhatsappConfig> {
    return (
      this.configs.get(tenantId) || {
        enabled: false,
        provider: 'meta',
        apiKey: '',
        phoneNumberId: '',
        businessAccountId: '',
        webhookVerifyToken: '',
        notifications: {
          orderConfirmation: true,
          shippingUpdate: true,
          deliveryConfirmation: true,
          returnUpdate: true,
          lowStock: false,
          priceChange: false,
        },
      }
    );
  }

  async updateConfig(
    tenantId: string,
    data: Partial<WhatsappConfig>,
  ): Promise<WhatsappConfig> {
    const current = await this.getConfig(tenantId);
    const updated = { ...current, ...data };
    this.configs.set(tenantId, updated);
    this.logger.log(`WhatsApp config updated for tenant ${tenantId}`);
    return updated;
  }

  async sendTestMessage(tenantId: string, phone: string, message: string) {
    const config = await this.getConfig(tenantId);
    if (!config.enabled) {
      return { success: false, error: 'WhatsApp entegrasyonu aktif değil' };
    }

    // In production, this would call WhatsApp Business API
    this.logger.log(`Test message sent to ${phone}: ${message}`);
    this.addLog(tenantId, {
      type: 'test',
      phone,
      message,
      status: 'sent',
      sentAt: new Date().toISOString(),
    });

    return { success: true, messageId: `msg_${Date.now()}` };
  }

  async sendMessage(
    tenantId: string,
    phone: string,
    template: string,
    variables: Record<string, string>,
  ) {
    const config = await this.getConfig(tenantId);
    if (!config.enabled) {
      return { success: false, error: 'WhatsApp entegrasyonu aktif değil' };
    }

    const tmpl = (await this.getTemplates(tenantId)).find(
      (t) => t.id === template,
    );
    if (!tmpl) {
      return { success: false, error: 'Şablon bulunamadı' };
    }

    let messageBody = tmpl.content;
    Object.entries(variables).forEach(([key, value]) => {
      messageBody = messageBody.replace(`{{${key}}}`, value);
    });

    this.logger.log(
      `WhatsApp message sent via template "${template}" to ${phone}`,
    );
    this.addLog(tenantId, {
      type: template,
      phone,
      message: messageBody,
      status: 'sent',
      sentAt: new Date().toISOString(),
    });

    return { success: true, messageId: `msg_${Date.now()}` };
  }

  async getTemplates(_tenantId: string): Promise<MessageTemplate[]> {
    return [
      {
        id: 'order_confirmation',
        name: 'Sipariş Onayı',
        content:
          'Merhaba {{customerName}}, {{orderId}} numaralı siparişiniz onaylandı! Toplam: ₺{{totalAmount}}. Teşekkür ederiz! 🛒',
        variables: ['customerName', 'orderId', 'totalAmount'],
        category: 'Sipariş',
      },
      {
        id: 'shipping_update',
        name: 'Kargo Bilgisi',
        content:
          'Merhaba {{customerName}}, siparişiniz kargoya verildi! 📦 Takip No: {{trackingNumber}} Kargo: {{shippingProvider}}',
        variables: ['customerName', 'trackingNumber', 'shippingProvider'],
        category: 'Kargo',
      },
      {
        id: 'delivery_confirmation',
        name: 'Teslimat Onayı',
        content:
          'Merhaba {{customerName}}, siparişiniz teslim edildi! ✅ Memnun kaldıysanız değerlendirme bırakabilirsiniz: {{reviewLink}}',
        variables: ['customerName', 'reviewLink'],
        category: 'Teslimat',
      },
      {
        id: 'return_approved',
        name: 'İade Onayı',
        content:
          'Merhaba {{customerName}}, {{returnId}} numaralı iade talebiniz onaylandı. Ürünü kargoya verebilirsiniz. İade kargo kodu: {{returnCode}}',
        variables: ['customerName', 'returnId', 'returnCode'],
        category: 'İade',
      },
      {
        id: 'low_stock_alert',
        name: 'Düşük Stok Uyarısı',
        content:
          '⚠️ Dikkat: {{productName}} (SKU: {{sku}}) stoku {{currentStock}} adede düştü. Yeniden sipariş vermeniz önerilir.',
        variables: ['productName', 'sku', 'currentStock'],
        category: 'Stok',
      },
      {
        id: 'campaign_notification',
        name: 'Kampanya Bilgisi',
        content:
          '🎉 {{campaignName}} kampanyası başladı! {{discount}} indirim fırsatını kaçırmayın. Son tarih: {{endDate}}',
        variables: ['campaignName', 'discount', 'endDate'],
        category: 'Pazarlama',
      },
    ];
  }

  async getLogs(tenantId: string, page: number, limit: number) {
    const allLogs = this.messageLogs.get(tenantId) || this.getDefaultLogs();
    const start = (page - 1) * limit;
    return {
      data: allLogs.slice(start, start + limit),
      total: allLogs.length,
      page,
    };
  }

  private addLog(tenantId: string, log: any) {
    const logs = this.messageLogs.get(tenantId) || [];
    logs.unshift({ id: `log_${Date.now()}`, ...log });
    this.messageLogs.set(tenantId, logs);
  }

  private getDefaultLogs() {
    return [
      {
        id: 'log_1',
        type: 'order_confirmation',
        phone: '+905551234567',
        message: 'Sipariş onayı gönderildi',
